function getTechnicianFireSystemDefinition(systemKey) {
  return getTechnicianFireSystemDefinitions().find((item) => item.id === systemKey) || null;
}

function normalizeTechnicianSystemConfig(config) {
  if (!config) return { primarySystemId: "", secondarySystemIds: [] };
  if (typeof config === "string") return { primarySystemId: config, secondarySystemIds: [] };
  if (Array.isArray(config)) {
    return {
      primarySystemId: config[0] || "",
      secondarySystemIds: uniqueValues(config.slice(1).filter(Boolean))
    };
  }
  return {
    primarySystemId: config.primarySystemId || config.primarySystem || config.systemId || config.system || "",
    secondarySystemIds: uniqueValues([
      ...(config.secondarySystemIds || []),
      ...(config.secondarySystems || []),
      ...(config.alsoShowInSystems || [])
    ].filter(Boolean))
  };
}

function getTechnicianDeviceSystemConfig(device, schedule = null) {
  const id = device?.id || device?.tag || "";
  const tag = device?.tag || device?.id || "";
  const type = device?.type || "";
  const normalizedType = normalizeScopeText(type);
  const directConfig = normalizeTechnicianSystemConfig(device?.systemConfig || device?.fireSystemConfig || device?.technicianSystemConfig);
  if (directConfig.primarySystemId || directConfig.secondarySystemIds.length) return directConfig;

  const siteConfig = getCriticalDependencySiteConfig(schedule);
  const overrideMaps = [
    siteConfig.deviceSystemOverrides,
    siteConfig.deviceSystems,
    siteConfig.deviceSystemMap,
    siteConfig.deviceSystemRelationships
  ].filter(Boolean);
  const keys = uniqueValues([id, tag, type, normalizedType].filter(Boolean));
  for (const map of overrideMaps) {
    for (const key of keys) {
      const config = normalizeTechnicianSystemConfig(map[key]);
      if (config.primarySystemId || config.secondarySystemIds.length) return config;
    }
  }

  const typeMaps = [
    siteConfig.deviceTypeSystemOverrides,
    siteConfig.deviceTypeSystems,
    siteConfig.deviceTypeSystemMap
  ].filter(Boolean);
  for (const map of typeMaps) {
    for (const key of [type, normalizedType].filter(Boolean)) {
      const config = normalizeTechnicianSystemConfig(map[key]);
      if (config.primarySystemId || config.secondarySystemIds.length) return config;
    }
  }
  return { primarySystemId: "", secondarySystemIds: [] };
}

function deviceMatchesTechnicianDefinition(device, definition, schedule = null) {
  if (!device || !definition || definition.catchAll) return false;
  const configured = getTechnicianDeviceSystemConfig(device, schedule);
  const configuredIds = uniqueValues([configured.primarySystemId, ...(configured.secondarySystemIds || [])].filter(Boolean));
  if (configuredIds.length) return configuredIds.includes(definition.id);
  if (definition.scopeId && deviceMatchesScheduleScope(device, definition.scopeId)) return true;
  return deviceMatchesKeywords(device, definition.matchKeywords || []);
}

function getTechnicianFireSystemDefinitionsForDevice(device, definitions = getTechnicianFireSystemDefinitions(), schedule = null) {
  const normalDefinitions = definitions.filter((definition) => !definition.catchAll);
  const configured = getTechnicianDeviceSystemConfig(device, schedule);
  const configuredIds = uniqueValues([configured.primarySystemId, ...(configured.secondarySystemIds || [])].filter(Boolean));
  if (configuredIds.length) {
    const configuredDefinitions = normalDefinitions.filter((definition) => configuredIds.includes(definition.id));
    if (configuredDefinitions.length) return configuredDefinitions;
    if (configuredIds.includes("emergency-exit")) {
      const legacyLightingDefinition = normalDefinitions.find((definition) => {
        return ["emergency-light", "keluar-sign"].includes(definition.id)
          && deviceMatchesKeywords(device, definition.matchKeywords || []);
      });
      if (legacyLightingDefinition) return [legacyLightingDefinition];
    }
  }
  const matches = normalDefinitions.filter((definition) => deviceMatchesTechnicianDefinition(device, definition, schedule));
  if (matches.length) return [matches[0]];
  const catchAll = definitions.find((definition) => definition.catchAll);
  return catchAll ? [catchAll] : [];
}

function getPrimaryTechnicianFireSystemDefinition(device, definitions = getTechnicianFireSystemDefinitions(), schedule = null) {
  return getTechnicianFireSystemDefinitionsForDevice(device, definitions, schedule)[0] || null;
}

function deviceMatchesTechnicianFireSystem(device, systemKey, schedule = null) {
  if (!systemKey || systemKey === "all") return true;
  const definition = getTechnicianFireSystemDefinition(systemKey);
  if (!definition) return false;
  return getTechnicianFireSystemDefinitionsForDevice(device, getTechnicianFireSystemDefinitions(), schedule)
    .some((item) => item.id === definition.id);
}

function getTechnicianSystemDependencyDefinitions(definition, schedule = null) {
  const ids = new Set(getTechnicianSystemParentDependencyIds(schedule, definition));
  if (!ids.size) return [];
  return criticalDependencyDefinitions.filter((dependency) => ids.has(dependency.id));
}

function getTechnicianSystemParentSupplyConfig(schedule, definition) {
  const siteConfig = getCriticalDependencySiteConfig(schedule);
  const relationships = siteConfig.parentSupplyRelationships || siteConfig.systemRelationships || {};
  return relationships?.[definition?.id] || {};
}

function getTechnicianSystemParentDependencyIds(schedule, definition) {
  const relationship = getTechnicianSystemParentSupplyConfig(schedule, definition);
  return uniqueValues([
    ...(definition?.dependencyDefinitionIds || []),
    ...(relationship.dependencyDefinitionIds || []),
    ...(relationship.parentDependencyDefinitionIds || [])
  ].filter(Boolean));
}

function getTechnicianSystemConfiguredParentIds(schedule, definition) {
  const relationship = getTechnicianSystemParentSupplyConfig(schedule, definition);
  return uniqueValues([
    ...(relationship.parentDeviceIds || []),
    ...(relationship.parentDeviceTags || []),
    relationship.parentDeviceId,
    relationship.parentDeviceTag
  ].filter(Boolean));
}

function getTechnicianSystemMissingParentStatus(schedule, definition) {
  const relationship = getTechnicianSystemParentSupplyConfig(schedule, definition);
  if (relationship.status === "confirmed" || relationship.required === true) return "setup-incomplete";
  if (relationship.status === "not-required" || relationship.required === false) return "not-required";
  if (relationship.status === "unconfirmed") return "unconfirmed";
  return definition?.missingParentStatus || "not-required";
}

function isTechnicianSystemParentDevice(device, definition, schedule = null) {
  const parentDefinition = getCriticalDependencyDefinitionForParent(device);
  const parentIds = getTechnicianSystemParentDependencyIds(schedule, definition);
  return Boolean(parentDefinition && parentIds.includes(parentDefinition.id));
}

function getTechnicianSystemParentDevices(schedule, definition, devicesForSystem, assignedDevices) {
  const configuredParentIds = new Set(getTechnicianSystemConfiguredParentIds(schedule, definition));
  const candidates = [];
  [...(devicesForSystem || []), ...(assignedDevices || [])].forEach((device) => {
    const id = device?.id || device?.tag || "";
    if (!id || candidates.some((existing) => (existing.id || existing.tag) === id)) return;
    candidates.push(device);
  });
  return candidates.filter((device) => {
    const id = device?.id || device?.tag || "";
    return configuredParentIds.has(id) || isTechnicianSystemParentDevice(device, definition, schedule);
  });
}

function getTechnicianDeviceSummary(devicesForSystem, schedule) {
  const summary = {
    total: devicesForSystem.length,
    done: 0,
    pass: 0,
    fail: 0,
    partial: 0,
    pending: 0,
    blocked: 0,
    ready: false
  };
  devicesForSystem.forEach((device) => {
    const status = getAssignedDeviceCompletionStatus(device, schedule);
    if (status === "pass") summary.pass += 1;
    if (status === "fail") summary.fail += 1;
    if (status === "partial") summary.partial += 1;
    if (status === "locked") summary.blocked += 1;
    if (status === "pending") summary.pending += 1;
    if (status !== "pending" && status !== "partial" && status !== "locked") summary.done += 1;
  });
  summary.ready = summary.total > 0 && summary.done === summary.total && summary.partial === 0 && summary.pending === 0 && summary.blocked === 0;
  return summary;
}

function getTechnicianSystemWorkflowRuns(schedule, definition, parentDevices = []) {
  if (!schedule || !getTechnicianSystemParentDependencyIds(schedule, definition).length) return [];
  ensureActiveJobCriticalWorkflows(schedule);
  const parentDependencyIds = getTechnicianSystemParentDependencyIds(schedule, definition);
  const parentIds = new Set(parentDevices.map((device) => device.id || device.tag));
  return getCriticalWorkflowRunsForSchedule(schedule)
    .filter((run) => parentDependencyIds.includes(run.definitionId))
    .filter((run) => !parentIds.size || parentIds.has(run.parentDeviceId) || parentIds.has(run.parentDeviceTag));
}

function getTechnicianSystemStageModel(group, schedule) {
  const dependencyDefinitions = getTechnicianSystemDependencyDefinitions(group, schedule);
  const parentDevices = group.parentDevices || [];
  const fieldDevices = group.fieldDevices || [];
  const parentRuns = getTechnicianSystemWorkflowRuns(schedule, group, parentDevices);
  const parentStages = parentRuns.map((run) => ({
    run,
    stage: getCachedCriticalWorkflowRunState(run, schedule)
  }));
  const missingParentStatus = getTechnicianSystemMissingParentStatus(schedule, group);
  const hasExpectedParentRelationship = Boolean(dependencyDefinitions.length && fieldDevices.length);
  const setupIncomplete = Boolean(hasExpectedParentRelationship && !parentDevices.length && missingParentStatus === "setup-incomplete");
  const parentSupplyUnconfirmed = Boolean(hasExpectedParentRelationship && !parentDevices.length && missingParentStatus === "unconfirmed");
  const prerequisiteFailed = parentStages.some((item) => item.stage?.prerequisiteFailed);
  const prerequisitesComplete = parentStages.length > 0 && parentStages.every((item) => item.stage?.prerequisiteComplete && !item.stage?.prerequisiteFailed);
  const fieldSummary = getTechnicianDeviceSummary(fieldDevices, schedule);
  const firstParent = parentDevices[0] || null;
  const finalReadyRun = parentStages.find((item) => ["final_required", "checklist_complete"].includes(item.stage?.status))?.run || parentRuns[0] || null;

  let systemCheck;
  if (setupIncomplete) {
    systemCheck = {
      status: "setup-incomplete",
      title: `1. ${group.systemCheckLabel || "System Check"}`,
      note: "Setup incomplete: assigned field devices exist, but no approved parent/system prerequisite is configured.",
      actionLabel: "Ask admin to complete setup",
      disabled: true
    };
  } else if (parentSupplyUnconfirmed) {
    systemCheck = {
      status: "unconfirmed",
      title: `1. ${group.systemCheckLabel || "System Check"}`,
      note: "Parent/supply arrangement is unconfirmed. Do not assume a dedicated pump; admin must confirm dedicated, shared, or not-required relationship.",
      actionLabel: "Unconfirmed",
      disabled: true
    };
  } else if (parentDevices.length) {
    systemCheck = {
      status: prerequisiteFailed ? "blocked" : prerequisitesComplete ? "complete" : "active",
      title: `1. ${group.systemCheckLabel || "System Check"}`,
      note: prerequisiteFailed
        ? "Prerequisite has a failed/unsafe result. Correct it before field testing."
        : prerequisitesComplete
          ? `${parentRuns.length} system check(s) TEST READY. Remaining panel work continues concurrently.`
          : `Bring ${parentRuns.map((run) => run.parentDeviceTag).filter(Boolean).join(" / ") || parentDevices.map((device) => device.id || device.tag).filter(Boolean).join(" / ") || "system prerequisite"} to TEST READY before field testing.`,
      actionLabel: prerequisitesComplete ? "Review System Check" : "Open System Check",
      deviceId: firstParent?.id || firstParent?.tag || "",
      disabled: false
    };
  } else {
    systemCheck = {
      status: "complete",
      title: `1. ${group.systemCheckLabel || "System Check"}`,
      note: "No configured parent prerequisite for this system.",
      actionLabel: "No prerequisite",
      disabled: true
    };
  }

  const fieldLocked = setupIncomplete || prerequisiteFailed || (parentDevices.length > 0 && !prerequisitesComplete);
  const fieldDevicesComplete = fieldSummary.total === 0 || fieldSummary.ready;
  const fieldDevicesTitle = fieldSummary.total
    ? `${fieldSummary.done}/${fieldSummary.total} done`
    : "No separate field devices";
  const fieldStage = {
    status: fieldLocked ? "locked" : fieldDevicesComplete ? "complete" : "active",
    title: `2. ${group.fieldLabel || "Field Devices"}`,
    note: fieldLocked
      ? "Pins remain visible, but inspection is locked until the system check reaches TEST READY."
      : `${fieldDevicesTitle}. Use the mimic pins as the main workspace.`,
    actionLabel: fieldLocked ? "View Locked Mimic" : "Open Mimic",
    disabled: false
  };

  let completionStage;
  if (setupIncomplete) {
    completionStage = {
      status: "locked",
      title: `3. ${group.completionLabel || "Completion"}`,
      note: "Completion is locked until admin configures the required parent/system prerequisite.",
      actionLabel: "Locked",
      disabled: true
    };
  } else if (parentSupplyUnconfirmed) {
    completionStage = {
      status: "locked",
      title: `3. ${group.completionLabel || "Completion"}`,
      note: "System completion remains unconfirmed until admin verifies the actual parent/supply arrangement. Field device results can still be recorded.",
      actionLabel: "Unconfirmed",
      disabled: true
    };
  } else if (parentDevices.length) {
    const allComplete = parentStages.length > 0 && parentStages.every((item) => item.stage?.status === "final_restored");
    const finalReady = parentStages.some((item) => ["final_required", "checklist_complete"].includes(item.stage?.status));
    completionStage = {
      status: allComplete ? "complete" : finalReady ? "active" : "locked",
      title: `3. ${group.completionLabel || "Completion"}`,
      note: allComplete
        ? "Configured completion/restoration requirement is complete."
        : finalReady
          ? "Field devices are complete. Open the system check to finish final restoration."
          : "Locked until prerequisite and required field devices are completed.",
      actionLabel: allComplete ? "Review Completion" : finalReady ? "Open Completion" : "Locked",
      deviceId: finalReadyRun?.parentDeviceId || finalReadyRun?.parentDeviceTag || "",
      disabled: !(allComplete || finalReady)
    };
  } else {
    completionStage = {
      status: fieldSummary.ready ? "complete" : "locked",
      title: `3. ${group.completionLabel || "Completion"}`,
      note: fieldSummary.ready
        ? "Field devices complete. Job sign-off can be reviewed."
        : "Finish assigned field devices before completion.",
      actionLabel: fieldSummary.ready ? "Go Complete Job" : "Locked",
      disabled: !fieldSummary.ready,
      completion: true
    };
  }

  return {
    setupIncomplete,
    parentSupplyUnconfirmed,
    parentDevices,
    fieldDevices,
    fieldSummary,
    parentRuns,
    stages: [systemCheck, fieldStage, completionStage]
  };
}

function getTechnicianFireSystemGroups(schedule) {
  const cache = getRuntimeCaches();
  const cacheKey = `${getScheduleVersionKey(schedule)}::${getSharedRecordVersionKey(schedule)}::fire-system-groups`;
  if (cache.fireSystemGroups.has(cacheKey)) {
    return cache.fireSystemGroups.get(cacheKey);
  }
  const assignedDevices = getScheduledAssignedDevices(schedule);
  const definitions = getTechnicianFireSystemDefinitions();
  const groupedDevices = new Map(definitions.map((definition) => [definition.id, []]));
  assignedDevices.forEach((device) => {
    getTechnicianFireSystemDefinitionsForDevice(device, definitions, schedule).forEach((definition) => {
      groupedDevices.get(definition.id)?.push(device);
    });
  });
  const groups = definitions.map((definition) => {
    const devicesForSystem = groupedDevices.get(definition.id) || [];
    const parentDevices = getTechnicianSystemParentDevices(schedule, definition, devicesForSystem, assignedDevices);
    const fieldDevices = devicesForSystem.filter((device) => !isTechnicianSystemParentDevice(device, definition, schedule));
    const summary = getTechnicianDeviceSummary(devicesForSystem, schedule);
    const group = {
      ...definition,
      devices: devicesForSystem,
      parentDevices,
      fieldDevices,
      summary
    };
    group.stageModel = getTechnicianSystemStageModel(group, schedule);
    return {
      ...group
    };
  }).filter((group) => group.devices.length);
  cache.fireSystemGroups.set(cacheKey, groups);
  return groups;
}

function getActiveTechnicianSystemKey(schedule = getTechMarkerScopeSchedule()) {
  const groups = getTechnicianFireSystemGroups(schedule);
  if (!groups.length) return "";
  const valid = groups.some((group) => group.id === state.activeTechSystemKey);
  return valid ? state.activeTechSystemKey : "";
}

function getVisibleTechnicianDevicesForSystem(schedule) {
  const devicesForSchedule = getScheduledAssignedDevices(schedule);
  const systemKey = getActiveTechnicianSystemKey(schedule);
  if (!systemKey || systemKey === "all") return devicesForSchedule;
  return devicesForSchedule.filter((device) => deviceMatchesTechnicianFireSystem(device, systemKey, schedule));
}

function getVisibleTechnicianFieldDevicesForSystem(schedule) {
  const systemKey = getActiveTechnicianSystemKey(schedule);
  if (!systemKey) return getScheduledAssignedDevices(schedule);
  const group = getTechnicianFireSystemGroups(schedule).find((item) => item.id === systemKey);
  return group?.fieldDevices || [];
}

function isDeviceVisibleForTechnicianSystem(device, schedule = getTechMarkerScopeSchedule()) {
  if (getCurrentUserRole() !== "Technician") return true;
  const systemKey = getActiveTechnicianSystemKey(schedule);
  return deviceMatchesTechnicianFireSystem(device, systemKey, schedule);
}

function renderTechFireSystemButtons(schedule) {
  const groups = getTechnicianFireSystemGroups(schedule);
  const activeKey = getActiveTechnicianSystemKey(schedule);
  if (!groups.length) {
    return `<p class="hint">No fire-system scope is ready for this job. Ask admin to check the schedule/device master.</p>`;
  }
  return `
    <div class="tech-system-panel">
      <strong>Choose Fire System</strong>
      <span>Pick the system first. The app will show the matching mimic pins only.</span>
      <div class="tech-system-grid">
        ${groups.map((group) => {
          const stateClass = group.stageModel?.setupIncomplete
            ? "setup-incomplete"
            : group.stageModel?.parentSupplyUnconfirmed
              ? "unconfirmed"
              : "";
          const status = getTechnicianSystemStatus(group.summary);
          return `
          <button type="button" class="${activeKey === group.id ? "active" : ""} ${stateClass} status-${status.id}" data-tech-system="${escapeHtml(group.id)}" data-tech-system-schedule="${escapeHtml(schedule.scheduleId)}">
            ${getTechnicianSystemIcon(group.id)}
            <span class="tech-system-card-copy">
              <strong>${escapeHtml(group.label)}</strong>
              <span>${group.summary.done} / ${group.summary.total}</span>
              <small>${escapeHtml(group.stageModel?.setupIncomplete ? "Setup incomplete" : group.stageModel?.parentSupplyUnconfirmed ? "Parent/supply unconfirmed" : status.label)}</small>
            </span>
          </button>
        `;
        }).join("")}
      </div>
    </div>
  `;
}

function getTechStageStatusLabel(status) {
  if (status === "complete") return "Complete";
  if (status === "active") return "Ready";
  if (status === "setup-incomplete") return "Setup incomplete";
  if (status === "unconfirmed") return "Unconfirmed";
  if (status === "blocked") return "Blocked";
  return "Locked";
}

function renderTechSystemStageCard(stage, index, schedule, group) {
  const actionAttrs = stage.deviceId
    ? `data-tech-stage-device="${escapeHtml(stage.deviceId)}"`
    : stage.completion
      ? `data-tech-stage-complete="${escapeHtml(schedule.scheduleId)}"`
      : `data-tech-stage-mimic="${escapeHtml(group.id)}" data-tech-stage-schedule="${escapeHtml(schedule.scheduleId)}"`;
  return `
    <article class="tech-stage-card ${escapeHtml(stage.status || "locked")}">
      <div>
        <strong>${escapeHtml(stage.title || `Stage ${index + 1}`)}</strong>
        <span>${escapeHtml(stage.note || "")}</span>
      </div>
      <div class="tech-stage-actions">
        <small>${escapeHtml(getTechStageStatusLabel(stage.status))}</small>
        <button type="button" class="secondary" ${actionAttrs} ${stage.disabled ? "disabled" : ""}>
          ${escapeHtml(stage.actionLabel || "Open")}
        </button>
      </div>
    </article>
  `;
}

function renderTechSystemStagePanel(schedule = getTechMarkerScopeSchedule()) {
  if (!techSystemStagePanel) return;
  renderTechDesktopNavigation(schedule);
  const systemKey = getActiveTechnicianSystemKey(schedule);
  if (getCurrentUserRole() !== "Technician" || !schedule || !systemKey) {
    techSystemStagePanel.classList.add("hidden");
    techSystemStagePanel.innerHTML = "";
    delete techSystemStagePanel.dataset.stageSignature;
    return;
  }
  const groups = getTechnicianFireSystemGroups(schedule);
  const activeGroup = groups.find((group) => group.id === systemKey);
  if (!activeGroup) {
    techSystemStagePanel.classList.add("hidden");
    techSystemStagePanel.innerHTML = "";
    delete techSystemStagePanel.dataset.stageSignature;
    return;
  }
  techSystemStagePanel.classList.remove("hidden");
  const stageSignature = JSON.stringify({
    scheduleId: schedule.scheduleId || "",
    activeGroupId: activeGroup.id,
    groups: groups.map((group) => ({
      id: group.id,
      done: group.summary.done,
      total: group.summary.total,
      setupIncomplete: Boolean(group.stageModel?.setupIncomplete),
      parentSupplyUnconfirmed: Boolean(group.stageModel?.parentSupplyUnconfirmed)
    })),
    stages: (activeGroup.stageModel?.stages || []).map((stage) => ({
      status: stage.status || "",
      title: stage.title || "",
      note: stage.note || "",
      actionLabel: stage.actionLabel || "",
      deviceId: stage.deviceId || "",
      disabled: Boolean(stage.disabled),
      completion: Boolean(stage.completion)
    })),
    linkedVerifications: getTechnicianAssignedLinkedStates([schedule])
      .filter((linkedState) => linkedVerificationMatchesSystem(linkedState.definition, activeGroup.id))
      .map((linkedState) => ({
        id: linkedState.linkedVerificationId,
        status: linkedState.status,
        sideRevisions: (linkedState.sides || []).map((side) => Number(side.record?.revision || 0)),
        localDraftStates: linkedState.definition.requiredSides.map((side) => getLinkedVerificationDraft(schedule.scheduleId, linkedState.linkedVerificationId, side.sideId)?.syncStatus || "")
      })),
    jobAlerts: getSharedJobAlerts(schedule).map((alert) => ({ id: alert.alertId, status: alert.status, readings: alert.readings }))
  });
  if (techSystemStagePanel.dataset.stageSignature === stageSignature) return;
  techSystemStagePanel.dataset.stageSignature = stageSignature;
  techSystemStagePanel.innerHTML = `
    <div class="tech-system-tabs" role="tablist" aria-label="Assigned fire systems">
      ${groups.map((group) => {
        const stateClass = group.stageModel?.setupIncomplete
          ? "setup-incomplete"
          : group.stageModel?.parentSupplyUnconfirmed
            ? "unconfirmed"
            : "";
        return `
        <button type="button" class="${group.id === activeGroup.id ? "active" : ""} ${stateClass} status-${getTechnicianSystemStatus(group.summary).id}" data-tech-stage-system="${escapeHtml(group.id)}" data-tech-stage-schedule="${escapeHtml(schedule.scheduleId)}">
          ${getTechnicianSystemIcon(group.id)}
          <strong>${escapeHtml(group.label)}</strong>
          <span>${group.summary.done}/${group.summary.total}</span>
        </button>
      `;
      }).join("")}
    </div>
    <div class="tech-stage-heading">
      ${getTechnicianSystemIcon(activeGroup.id)}
      <div>
        <strong>${escapeHtml(activeGroup.label)}</strong>
        <span>System prerequisite -> field devices -> completion</span>
      </div>
      <span class="job-status-badge">${activeGroup.summary.done}/${activeGroup.summary.total}</span>
    </div>
    <div class="tech-system-stages">
      ${(activeGroup.stageModel?.stages || []).map((stage, index) => renderTechSystemStageCard(stage, index, schedule, activeGroup)).join("")}
    </div>
    ${renderTechnicianJobAlerts(schedule)}
  `;
  techSystemStagePanel.querySelectorAll("[data-tech-stage-system]").forEach((button) => {
    bindReliableTap(button, () => openTechnicianFireSystem(button.dataset.techStageSchedule, button.dataset.techStageSystem));
  });
  techSystemStagePanel.querySelectorAll("[data-tech-stage-device]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianAssignedDevice(button.dataset.techStageDevice, { openChecklist: true }));
  });
  techSystemStagePanel.querySelectorAll("[data-tech-stage-mimic]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianSystemMimic(button.dataset.techStageSchedule, button.dataset.techStageMimic));
  });
  techSystemStagePanel.querySelectorAll("[data-tech-stage-complete]").forEach((button) => {
    bindReliableTap(button, () => setTechScreen("complete", { scroll: true }));
  });
  techSystemStagePanel.querySelectorAll("[data-linked-save-side]").forEach((button) => {
    bindReliableTap(button, () => handleLinkedVerificationSideSave(button, schedule));
  });
}

function getTechnicianSystemStageRoute(schedule, systemKey = state.activeTechSystemKey) {
  if (!schedule || !systemKey) return null;
  const groups = getTechnicianFireSystemGroups(schedule);
  const group = groups.find((item) => item.id === systemKey);
  if (!group) return null;
  const stages = group.stageModel?.stages || [];
  const [systemCheckStage, fieldStage, completionStage] = stages;
  if (systemCheckStage?.deviceId && !systemCheckStage.disabled && systemCheckStage.status !== "complete") {
    return {
      stage: "system-check",
      screen: "inspection",
      group,
      deviceId: systemCheckStage.deviceId,
      message: `${group.label} Stage 1: complete ${systemCheckStage.deviceId} before field-device inspection.`
    };
  }
  if (completionStage?.status === "active" && !completionStage.disabled) {
    return {
      stage: "completion",
      screen: completionStage.deviceId ? "inspection" : "complete",
      group,
      deviceId: completionStage.deviceId || "",
      message: `${group.label} Stage 3: complete the configured final restoration / normal-status confirmation.`
    };
  }
  return {
    stage: "field-devices",
    screen: "mimic",
    group,
    message: `${group.label} Stage 2: use the mimic to inspect assigned field devices.`
  };
}

async function routeTechnicianSystemStage(schedule, systemKey = state.activeTechSystemKey, options = {}) {
  const route = getTechnicianSystemStageRoute(schedule, systemKey);
  if (!route) return null;
  state.activeTechPreviewScheduleId = schedule.scheduleId;
  state.activeTechSystemKey = route.group.id;
  persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
  renderTechSystemStagePanel(schedule);
  if (route.screen === "inspection" && route.deviceId) {
    await focusTechnicianAssignedDevice(route.deviceId, {
      openChecklist: true,
      scrollIntoView: options.scroll !== false
    });
    renderTechSystemStagePanel(schedule);
    document.querySelector("#syncState").textContent = route.message;
    return route;
  }
  if (route.screen === "complete") {
    setTechScreen("complete", { scroll: options.scroll !== false });
    document.querySelector("#syncState").textContent = route.message;
    return route;
  }
  await focusTechnicianSystemMimic(schedule.scheduleId, route.group.id, {
    scroll: options.scroll !== false,
    skipDirtyCheck: options.skipDirtyCheck === true
  });
  document.querySelector("#syncState").textContent = route.message;
  return route;
}

async function focusTechnicianSystemMimic(scheduleId, systemKey, options = {}) {
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (!schedule) return;
  if (options.skipDirtyCheck !== true && !confirmTechnicianNavigation()) return false;
  clearTechnicianInspectionDirty();
  state.activeTechSystemKey = systemKey || state.activeTechSystemKey || "";
  const group = getTechnicianFireSystemGroups(schedule).find((item) => item.id === state.activeTechSystemKey);
  const target = group?.fieldDevices?.[0] || group?.parentDevices?.[0] || group?.devices?.[0] || null;
  if (target?.floorId && floorExists(target.floorId)) {
    setTechnicianMapFloor(target.floorId, {
      companyName: schedule.companyName,
      siteName: schedule.siteName
    });
  }
  prepareTechnicianMimicWorkspace();
  persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
  renderTechSystemStagePanel(schedule);
  renderMarkers();
  updateTechnicianMimicBackAction(schedule, state.activeTechSystemKey);
  setTechScreen("mimic", { scroll: options.scroll !== false, renderMarkers: false });
  return true;
}

async function startOrResumeTechnicianSchedule(scheduleId) {
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (schedule) {
    await ensureTechnicianFieldDataLoaded(schedule);
  }
  state.activeTechSystemKey = "";
  state.activeTechPreviewScheduleId = scheduleId;
  state.activeTechFloorId = "";
  const started = await startScheduledJob(scheduleId, { stayOnJobSummary: true, skipFullJobSave: true, preserveTechSystem: false });
  if (started) {
    persistTechnicianActiveContext(scheduleId, "", floorSelect.value);
    renderTechWorkPanel();
    setTechScreen("jobs", { scroll: true });
    document.querySelector("#syncState").textContent = "Job opened. Choose a fire system to show the mimic pins.";
  }
}

async function openTechnicianFireSystem(scheduleId, systemKey) {
  if (systemKey !== state.activeTechSystemKey && !confirmTechnicianNavigation()) return false;
  clearTechnicianInspectionDirty();
  const requestId = (state.techSystemOpenRequestId || 0) + 1;
  state.techSystemOpenRequestId = requestId;
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (!schedule) return false;
  await ensureTechnicianFieldDataLoaded(schedule);
  if (isStaleTechnicianSystemOpenRequest({ techSystemOpenRequestId: requestId })) return false;
  const groups = getTechnicianFireSystemGroups(schedule);
  const requestedGroup = groups.find((group) => group.id === systemKey) || groups[0] || null;
  const targetSystemKey = requestedGroup?.id || "";
  state.activeTechSystemKey = targetSystemKey;
  state.activeTechPreviewScheduleId = scheduleId;
  const firstDevice = requestedGroup?.parentDevices?.[0] || requestedGroup?.fieldDevices?.[0] || requestedGroup?.devices?.[0];
  const targetFloorId = firstDevice?.floorId || getBestSchedulePreviewFloorId(schedule, {
    companyName: schedule.companyName,
    siteName: schedule.siteName
  });
  if (targetFloorId && floorExists(targetFloorId)) {
    setTechnicianMapFloor(targetFloorId, {
      companyName: schedule.companyName,
      siteName: schedule.siteName
    });
  }
  persistTechnicianActiveContext(scheduleId, targetSystemKey, floorSelect.value);
  const started = await startScheduledJob(scheduleId, {
    stayOnJobSummary: true,
    targetFloorId,
    skipFullJobSave: true,
    expectedTechSystemKey: targetSystemKey,
    techSystemOpenRequestId: requestId
  });
  if (isStaleTechnicianSystemOpenRequest({ techSystemOpenRequestId: requestId })) return false;
  if (!started) return false;
  state.activeTechPreviewScheduleId = scheduleId;
  state.activeTechSystemKey = targetSystemKey;
  persistTechnicianActiveContext(scheduleId, state.activeTechSystemKey, floorSelect.value);
  renderTechWorkPanel();
  await routeTechnicianSystemStage(schedule, targetSystemKey, { scroll: true, skipDirtyCheck: true });
  return true;
}

function renderTechWorkPanel() {
  const panel = document.querySelector("#techWorkPanel");
  if (!panel) return;
  const jobs = getTechnicianMaintenanceSchedules(6);
  const activeSchedule = getActiveTechnicianMaintenanceSchedule();
  const badge = document.querySelector("#techContractBadge");
  if (badge) {
    const badgeSchedule = activeSchedule || jobs[0] || null;
    const assignedCount = badgeSchedule?.plannedDeviceIds?.length || badgeSchedule?.deviceCount || 0;
    badge.textContent = badgeSchedule ? `${assignedCount} assigned items` : "No assigned job";
  }
  renderTechnicianFrontDeskStats(jobs, activeSchedule);

  const activeSummary = document.querySelector("#techActiveJobSummary");
  const activeJob = state.activeJob && state.activeJob.status !== "Completed" ? state.activeJob : null;
  clearActiveJobBtn?.classList.add("hidden");
  if (activeSummary) {
    if (activeSchedule) {
      ensureSchedulePlannedScope(activeSchedule);
      const summary = getAssignedCompletionSummary(activeSchedule);
      const status = getTechnicianScheduleStatus(activeSchedule);
      const floorBreakdown = formatScheduleFloorBreakdown(activeSchedule.plannedFloorCounts || [], 4);
      activeSummary.innerHTML = `
          <div class="tech-current-job">
            <div>
              <strong>${escapeHtml(activeSchedule.companyName)} / ${escapeHtml(activeSchedule.siteName)}</strong>
              <span>${escapeHtml(getTechnicianServiceDisplayLabel(activeSchedule))} - ${escapeHtml(activeSchedule.date || "No date")} ${escapeHtml(activeSchedule.time || "")}</span>
              <span>Frozen service scope: ${activeSchedule.plannedDeviceIds?.length || activeSchedule.deviceCount || 0} assigned items</span>
              <span>Starting floor: ${escapeHtml(getTechnicianScheduleStartFloor(activeSchedule))}${floorBreakdown ? ` | ${escapeHtml(floorBreakdown)}` : ""}</span>
            </div>
            ${renderTechProgressGrid(summary)}
            ${renderTechFireSystemButtons(activeSchedule)}
            <div class="tech-job-actions">
              <button type="button" class="secondary" data-tech-summary-mimic="${escapeHtml(activeSchedule.scheduleId)}">All Mimic</button>
              <button type="button" class="secondary" data-tech-screen-link="faults">Outstanding Faults</button>
              <button type="button" class="secondary" data-tech-screen-link="complete">Complete Job</button>
            </div>
            <span class="job-status-badge ${status === "In Progress" ? "active" : ""}">${escapeHtml(status)}</span>
          </div>
        `;
      } else {
        activeSummary.innerHTML = `
        <div class="tech-current-job muted">
          <strong>Today's assigned jobs</strong>
          <span>Open a job below. Then choose the fire system and use the mimic pins as the main working screen.</span>
        </div>
      `;
      }
  }

  renderTechSystemStagePanel(activeSchedule);
  renderTechExtinguisherAssignedJobs();
  if (activeSchedule || state.activeTechPreviewScheduleId) {
    renderTechAssignedItemList();
  } else if (techAssignedItemPanel && techAssignedItemList) {
    if (techItemProgress) techItemProgress.textContent = "Open a job";
    techAssignedItemList.innerHTML = `<p class="hint">Open an assigned job first. The checklist and mimic pins load after that.</p>`;
    renderTechCompletionPanel(null, [], false);
    renderTechSystemStagePanel(null);
  }

  const list = document.querySelector("#techAssignedJobs");
  if (!list) return;
  const today = formatDateValue(new Date());

  if (!jobs.length) {
    list.innerHTML = `<p class="hint">No assigned maintenance job. Admin must schedule the client, date, time, and checklist before technician starts.</p>`;
    return;
  }

  list.innerHTML = jobs.map((schedule) => {
    ensureSchedulePlannedScope(schedule);
    const isToday = schedule.date === today;
    const plannedCount = schedule.plannedDeviceIds?.length || schedule.deviceCount || 0;
    const summary = getLightTechnicianScheduleSummary(schedule);
    const status = getTechnicianScheduleStatus(schedule);
    const progressPercent = summary.total ? Math.round((summary.done / summary.total) * 100) : 0;
    return `
      <article class="tech-job-card ${isToday ? "today" : ""}">
        <div>
          <strong>${escapeHtml(schedule.companyName)} / ${escapeHtml(schedule.siteName)}</strong>
          <span>${escapeHtml(getTechnicianServiceDisplayLabel(schedule))} - ${escapeHtml(schedule.date || "No date")} ${escapeHtml(schedule.time || "")}</span>
        </div>
        <div class="tech-job-meta-grid">
          <span><strong>${escapeHtml(schedule.companyName || "-")}</strong>Client</span>
          <span><strong>${escapeHtml(schedule.siteName || "-")}</strong>Site</span>
          <span><strong>${escapeHtml(getTechnicianServiceDisplayLabel(schedule))}</strong>Job type</span>
          <span><strong>${escapeHtml(schedule.date || "No date")} ${escapeHtml(schedule.time || "")}</strong>Date / time</span>
          <span><strong>${escapeHtml(getTechnicianScheduleStartFloor(schedule))}</strong>Starting floor</span>
          <span><strong>${plannedCount}</strong>Assigned items</span>
        </div>
        ${renderTechProgressGrid(summary)}
        <div class="tech-job-actions">
          <button type="button" class="primary-wide" data-tech-start-schedule="${escapeHtml(schedule.scheduleId)}">${escapeHtml(getTechnicianScheduleActionLabel(schedule))}</button>
        </div>
        <span class="job-status-badge ${status === "In Progress" ? "active" : ""}">${escapeHtml(status)} - ${progressPercent}%</span>
      </article>
    `;
  }).join("");

  activeSummary?.querySelectorAll("[data-tech-start-schedule]").forEach((button) => {
    bindReliableTap(button, () => startOrResumeTechnicianSchedule(button.dataset.techStartSchedule));
  });
  activeSummary?.querySelectorAll("[data-tech-summary-mimic]").forEach((button) => {
    bindReliableTap(button, () => openCurrentTechnicianMimic({ scroll: true }));
  });
  activeSummary?.querySelectorAll("[data-tech-system]").forEach((button) => {
    bindReliableTap(button, () => openTechnicianFireSystem(button.dataset.techSystemSchedule, button.dataset.techSystem));
  });
  activeSummary?.querySelectorAll("[data-tech-screen-link]").forEach((button) => {
    bindReliableTap(button, () => setTechScreen(button.dataset.techScreenLink, { scroll: true }));
  });
  list.querySelectorAll("[data-tech-start-schedule]").forEach((button) => {
    bindReliableTap(button, () => startOrResumeTechnicianSchedule(button.dataset.techStartSchedule));
  });
  renderTechWorkflowNav();
}

function getCurrentFloorAssignedCount(schedule) {
  const ids = new Set(schedule?.plannedDeviceIds || []);
  if (!ids.size) return 0;
  return getInspectionDevices().filter((device) => ids.has(device.id)).length;
}

function getScheduledAssignedDevices(schedule) {
  if (!schedule) return [];
  ensureSchedulePlannedScope(schedule);
  const cache = getRuntimeCaches();
  const cacheKey = `${getScheduleVersionKey(schedule)}::scheduled-devices`;
  if (cache.scheduledDevices.has(cacheKey)) {
    return cache.scheduledDevices.get(cacheKey);
  }
  const ids = getSchedulePlannedIdSet(schedule);
  if (!ids.size) return [];
  const deviceMap = new Map();
  getDevicesForScheduleRecord(schedule)
    .filter((device) => ids.has(device.id))
    .forEach((device) => deviceMap.set(device.id, device));
  state.setupDevices
    .filter((device) => ids.has(device.tag))
    .forEach((device) => {
      if (deviceMap.has(device.tag)) return;
      const floorId = device.floorId || schedule.floorId || floorSelect.value;
      const floorAsset = getFloorAsset(floorId);
      deviceMap.set(device.tag, getScheduleDeviceFromSetupDevice(device, floorId, floorAsset));
    });
  const resolvedDevices = [...ids]
    .map((id) => deviceMap.get(id))
    .filter(Boolean)
    .map((device) => ({
      ...device,
      tag: device.tag || device.id,
      id: device.id || device.tag,
      floorTitle: device.floorTitle || device.floor || "Unknown floor",
      questions: device.questions || getChecklistQuestions(device.type)
    }))
    .sort(compareAssignedDevicesForTech);
  cache.scheduledDevices.set(cacheKey, resolvedDevices);
  return resolvedDevices;
}

function compareAssignedDevicesForTech(a, b) {
  const floorA = `${a.floorCode || ""} ${a.floorTitle || ""}`;
  const floorB = `${b.floorCode || ""} ${b.floorTitle || ""}`;
  const floorCompare = floorA.localeCompare(floorB, undefined, { numeric: true, sensitivity: "base" });
  if (floorCompare) return floorCompare;
  return `${a.id || ""}`.localeCompare(`${b.id || ""}`, undefined, { numeric: true, sensitivity: "base" });
}

function getAssignedDeviceCompletionStatus(device, schedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule()) {
  if (isCriticalSopDevice(device)) {
    const templateId = getCriticalSopTemplateIdForDevice(device);
    const deviceTag = device.id || device.tag || "";
    const saved = getSharedCriticalSopRecordByDevice(deviceTag, templateId, schedule)
      || state.criticalSops[deviceTag ? `${templateId}::${deviceTag}` : templateId]
      || state.criticalSops[templateId]
      || { steps: {} };
    const template = criticalSopTemplates.find((item) => item.id === templateId);
    if (!template) return "pending";
    const completed = getCriticalSopCompleteCount(template, saved);
    const workflow = getCriticalWorkflowRunForParentDevice(device, schedule);
    const workflowState = workflow ? getCachedCriticalWorkflowRunState(workflow, schedule) : null;
    if (workflowState?.status === "final_restored" || (!workflow && isCriticalSopRecordComplete(template, saved))) return "pass";
    return completed > 0 ? "partial" : "pending";
  }
  const access = getDeviceCriticalAccessState(device, schedule);
  if (!access.allowed) return "locked";
  return deviceStatus(device.id);
}

function isAssignedDeviceStillOpen(device, schedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule()) {
  const status = getAssignedDeviceCompletionStatus(device, schedule);
  return status === "pending" || status === "partial";
}

function getNextAssignedDeviceAfter(currentDeviceId) {
  const schedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule();
  const activeSystemKey = getActiveTechnicianSystemKey(schedule);
  const assignedDevices = activeSystemKey
    ? getVisibleTechnicianFieldDevicesForSystem(schedule)
    : getScheduledAssignedDevices(schedule);
  if (!assignedDevices.length) return null;
  const currentIndex = assignedDevices.findIndex((device) => (device.id || device.tag) === currentDeviceId);
  const searchOrder = currentIndex >= 0
    ? [...assignedDevices.slice(currentIndex + 1), ...assignedDevices.slice(0, currentIndex)]
    : assignedDevices;
  return searchOrder.find((device) => isAssignedDeviceStillOpen(device, schedule)) || null;
}

function getResumeTargetAssignedDevice(schedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule()) {
  const assignedDevices = getScheduledAssignedDevices(schedule);
  if (!assignedDevices.length) return null;
  const lastDeviceId = state.activeJob?.lastDeviceId || state.activeJob?.lastCompletedDeviceId || "";
  const lastDevice = assignedDevices.find((device) => (device.id || device.tag) === lastDeviceId);
  if (lastDevice && isAssignedDeviceStillOpen(lastDevice)) return lastDevice;
  return assignedDevices.find(isAssignedDeviceStillOpen) || assignedDevices[0];
}

function scrollAssignedItemListIntoView() {
  const target = techAssignedItemPanel || document.querySelector("#techAssignedItemPanel");
  if (!target) return;
  target.scrollIntoView({ behavior: "smooth", block: "start" });
}

function scrollTechCompletionPanelIntoView() {
  const target = techCompletionPanel || document.querySelector("#techCompletionPanel");
  if (!target || target.classList.contains("hidden")) {
    scrollAssignedItemListIntoView();
    return;
  }
  target.scrollIntoView({ behavior: "smooth", block: "start" });
}

async function openNextAssignedItemAfter(currentDeviceId) {
  const nextDevice = getNextAssignedDeviceAfter(currentDeviceId);
  renderTechAssignedItemList();
  if (!nextDevice) {
    setTechScreen("complete", { scroll: true });
    scrollTechCompletionPanelIntoView();
    document.querySelector("#syncState").textContent = "Saved. All assigned items are completed. Sign off and complete the job.";
    return false;
  }
  setTechScreen("inspection");
  await focusTechnicianAssignedDevice(nextDevice.id || nextDevice.tag, { openChecklist: true });
  document.querySelector("#syncState").textContent = `Saved. Next item opened: ${nextDevice.id || nextDevice.tag}`;
  return true;
}

function getAssignedDeviceStatusLabel(status) {
  if (status === "pass") return "Done";
  if (status === "fail") return "Fail";
  if (status === "partial") return "SOP Started";
  if (status === "locked") return "Locked";
  if (status === "na" || status === "n/a") return "N/A";
  return "Pending";
}

function getAssignedCompletionSummary(schedule) {
  const cache = getRuntimeCaches();
  const cacheKey = `${getScheduleVersionKey(schedule)}::${getSharedRecordVersionKey(schedule)}::completion-summary`;
  if (cache.completionSummaries.has(cacheKey)) {
    return cache.completionSummaries.get(cacheKey);
  }
  const assignedDevices = getScheduledAssignedDevices(schedule);
  const summary = {
    total: assignedDevices.length,
    done: 0,
    pass: 0,
    fail: 0,
    partial: 0,
    pending: 0,
    blocked: 0
  };
  assignedDevices.forEach((device) => {
    const status = getAssignedDeviceCompletionStatus(device, schedule);
    if (status === "pass") summary.pass += 1;
    if (status === "fail") summary.fail += 1;
    if (status === "partial") summary.partial += 1;
    if (status === "locked") summary.blocked += 1;
    if (status === "pending") summary.pending += 1;
    if (status !== "pending" && status !== "partial") summary.done += 1;
  });
  summary.done = Math.max(0, summary.done - summary.blocked);
  summary.ready = summary.total > 0 && summary.done === summary.total && summary.partial === 0 && summary.pending === 0 && summary.blocked === 0;
  cache.completionSummaries.set(cacheKey, summary);
  return summary;
}

function getStoredInspectionForDevice(device, schedule = null) {
  const key = device?.id || device?.tag || "";
  return getSharedInspectionRecord(key, schedule) || schedule?.jobProgress?.inspections?.[key] || state.inspections[key] || null;
}

function getAssignedDeviceFaultInfo(device, schedule = null) {
  if (!device) return null;
  if (isCriticalSopDevice(device)) {
    const record = getCriticalSopRecordForDevice(device, schedule);
    if (!record) return null;
    const template = criticalSopTemplates.find((item) => item.id === record.templateId || item.id === getCriticalSopTemplateIdForDevice(device));
    const steps = template?.steps || [];
    const failedSteps = Object.values(record.steps || {}).filter((step) => {
      return String(step.choice || "").toLowerCase().includes("fail")
        || String(step.remark || "").toLowerCase().includes("fault");
    });
    const missingEvidence = template ? getMissingCriticalSopEvidence(template, record) : [];
    const complete = template ? isCriticalSopRecordComplete(template, record) : false;
    if (!failedSteps.length && !missingEvidence.length && complete) return null;
    return {
      device,
      title: `${device.id || device.tag} - ${record.title || template?.title || "Critical SOP"}`,
      description: failedSteps.length
        ? `${failedSteps.length} SOP step(s) marked fail / fault.`
        : complete
          ? "Critical SOP completed with evidence."
          : `Critical SOP incomplete${steps.length ? ` (${getCriticalSopCompleteCount(template, record)}/${steps.length})` : ""}.`,
      photoStatus: missingEvidence.length ? `Missing ${missingEvidence.join(", ")}` : "Photo evidence recorded",
      critical: true
    };
  }

  const inspection = getStoredInspectionForDevice(device, schedule);
  if (!inspection || inspection.status !== "fail") return null;
  const failedQuestions = (inspection.answers || [])
    .map((answer, index) => answer === "Fail" ? `Q${index + 1}` : "")
    .filter(Boolean);
  const hasPhoto = Boolean(inspection.beforePhoto || inspection.beforePhotoData || inspection.beforePhotoEvidence || inspection.afterPhoto || inspection.afterPhotoData || inspection.afterPhotoEvidence);
  return {
    device,
    title: `${device.id || device.tag} - ${device.type || "Device"}`,
    description: inspection.notes || (failedQuestions.length ? `Failed ${failedQuestions.join(", ")}` : "Fault marked, description not recorded."),
    photoStatus: hasPhoto ? "Photo evidence recorded" : "No photo evidence recorded",
    critical: false
  };
}

function renderTechFaultPanel() {
  if (!techFaultPanel || getCurrentUserRole() !== "Technician") return;
  const schedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule();
  if (!schedule) {
    techFaultPanel.innerHTML = `
      <div class="section-header compact">
        <div>
          <p class="eyebrow">Outstanding Faults</p>
          <h3>No Active Job</h3>
        </div>
      </div>
      <p class="hint">Start an assigned job first, then saved faults will appear here.</p>
    `;
    return;
  }
  const assignedDevices = getScheduledAssignedDevices(schedule);
  const faults = assignedDevices
    .map((device) => getAssignedDeviceFaultInfo(device, schedule))
    .filter(Boolean);
  techFaultPanel.innerHTML = `
    <div class="section-header compact">
      <div>
        <p class="eyebrow">Outstanding Faults</p>
        <h3>${escapeHtml(schedule.companyName)} / ${escapeHtml(schedule.siteName)}</h3>
      </div>
      <span class="job-status-badge ${faults.length ? "active" : "complete"}">${faults.length} fault(s)</span>
    </div>
    ${faults.length ? `
      <div class="tech-fault-list">
        ${faults.map((fault) => `
          <article class="tech-fault-card">
            <strong>${escapeHtml(fault.title)}</strong>
            <span>${escapeHtml(fault.device.floorTitle || fault.device.floor || "-")} | ${escapeHtml(displayDeviceLocation(fault.device.location || ""))}</span>
            <small>${escapeHtml(fault.description)}</small>
            <small>${escapeHtml(fault.photoStatus)}</small>
            <div class="tech-fault-actions">
              <button type="button" data-tech-open-fault="${escapeHtml(fault.device.id || fault.device.tag)}">Open Checklist</button>
              <button type="button" class="secondary" data-tech-map-fault="${escapeHtml(fault.device.id || fault.device.tag)}">Map</button>
            </div>
          </article>
        `).join("")}
      </div>
    ` : `<p class="hint">No saved fault yet for this assigned job.</p>`}
  `;
  techFaultPanel.querySelectorAll("[data-tech-open-fault]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianAssignedDevice(button.dataset.techOpenFault, { openChecklist: true }));
  });
  techFaultPanel.querySelectorAll("[data-tech-map-fault]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianAssignedDevice(button.dataset.techMapFault, { openChecklist: false, scrollToMap: true }));
  });
}

function readTechSignOffDraft() {
  const signatureData = document.querySelector("#techSignatureData")?.value || state.techSignOffSignatureData || "";
  return {
    technicianName: document.querySelector("#techSignTechnician")?.value.trim() || getCurrentUserName(),
    supervisorName: document.querySelector("#techSignSupervisor")?.value.trim() || "",
    clientName: document.querySelector("#techSignClient")?.value.trim() || "",
    remarks: document.querySelector("#techSignRemarks")?.value.trim() || "",
    signatureData,
    confirmed: Boolean(document.querySelector("#techSignConfirm")?.checked)
  };
}

function setupSignaturePad(enabled = true) {
  const canvas = document.querySelector("#techSignatureCanvas");
  const hiddenInput = document.querySelector("#techSignatureData");
  const clearButton = document.querySelector("#clearTechSignatureBtn");
  const status = document.querySelector("#techSignatureStatus");
  if (!canvas || !hiddenInput) return;

  const ctx = canvas.getContext("2d");
  const ratio = Math.max(1, window.devicePixelRatio || 1);
  const cssWidth = Math.max(280, canvas.clientWidth || canvas.parentElement?.clientWidth || 320);
  const cssHeight = 150;
  canvas.width = Math.round(cssWidth * ratio);
  canvas.height = Math.round(cssHeight * ratio);
  canvas.style.height = `${cssHeight}px`;
  ctx.scale(ratio, ratio);
  ctx.lineWidth = 3;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = "#111827";
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, cssWidth, cssHeight);

  const savedSignature = hiddenInput.value || state.techSignOffSignatureData || "";
  if (savedSignature) {
    const image = new Image();
    image.onload = () => {
      ctx.drawImage(image, 0, 0, cssWidth, cssHeight);
    };
    image.src = savedSignature;
  }

  let drawing = false;
  let hasInk = Boolean(savedSignature);
  let lastPointerEventAt = 0;
  const setStatus = () => {
    if (status) status.textContent = hasInk ? "Signature captured" : "Please sign inside the box";
  };
  const pointFromEvent = (event) => {
    const rect = canvas.getBoundingClientRect();
    return {
      x: event.clientX - rect.left,
      y: event.clientY - rect.top
    };
  };
  const saveSignature = () => {
    if (!hasInk) return;
    const dataUrl = canvas.toDataURL("image/png");
    hiddenInput.value = dataUrl;
    state.techSignOffSignatureData = dataUrl;
    setStatus();
  };
  const startDrawingAt = (clientX, clientY) => {
    if (!enabled) return;
    const point = pointFromEvent({ clientX, clientY });
    drawing = true;
    hasInk = true;
    ctx.beginPath();
    ctx.moveTo(point.x, point.y);
  };
  const continueDrawingAt = (clientX, clientY) => {
    if (!enabled || !drawing) return;
    const point = pointFromEvent({ clientX, clientY });
    ctx.lineTo(point.x, point.y);
    ctx.stroke();
    saveSignature();
  };
  const stopDrawing = () => {
    if (!drawing) return;
    drawing = false;
    saveSignature();
  };

  canvas.addEventListener("pointerdown", (event) => {
    if (!enabled) return;
    event.preventDefault();
    lastPointerEventAt = Date.now();
    canvas.setPointerCapture?.(event.pointerId);
    startDrawingAt(event.clientX, event.clientY);
  });
  canvas.addEventListener("pointermove", (event) => {
    if (!enabled || !drawing) return;
    event.preventDefault();
    lastPointerEventAt = Date.now();
    continueDrawingAt(event.clientX, event.clientY);
  });
  ["pointerup", "pointercancel", "pointerleave"].forEach((eventName) => {
    canvas.addEventListener(eventName, (event) => {
      if (!drawing) return;
      event.preventDefault();
      lastPointerEventAt = Date.now();
      try {
        canvas.releasePointerCapture?.(event.pointerId);
      } catch {
        // Pointer capture may already be released by the browser.
      }
      stopDrawing();
    });
  });
  canvas.addEventListener("mousedown", (event) => {
    if (Date.now() - lastPointerEventAt < 500) return;
    event.preventDefault();
    startDrawingAt(event.clientX, event.clientY);
  });
  canvas.addEventListener("mousemove", (event) => {
    if (Date.now() - lastPointerEventAt < 500) return;
    event.preventDefault();
    continueDrawingAt(event.clientX, event.clientY);
  });
  ["mouseup", "mouseleave"].forEach((eventName) => {
    canvas.addEventListener(eventName, (event) => {
      if (Date.now() - lastPointerEventAt < 500) return;
      event.preventDefault();
      stopDrawing();
    });
  });
  canvas.addEventListener("touchstart", (event) => {
    if (!enabled) return;
    event.preventDefault();
    const touch = event.touches?.[0];
    if (touch) startDrawingAt(touch.clientX, touch.clientY);
  }, { passive: false });
  canvas.addEventListener("touchmove", (event) => {
    if (!enabled || !drawing) return;
    event.preventDefault();
    const touch = event.touches?.[0];
    if (touch) continueDrawingAt(touch.clientX, touch.clientY);
  }, { passive: false });
  canvas.addEventListener("touchend", (event) => {
    if (!drawing) return;
    event.preventDefault();
    stopDrawing();
  }, { passive: false });

  clearButton?.addEventListener("click", () => {
    if (!enabled) return;
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, cssWidth, cssHeight);
    hiddenInput.value = "";
    state.techSignOffSignatureData = "";
    hasInk = false;
    setStatus();
  });

  setStatus();
}

function renderTechCompletionPanel(schedule, assignedDevices, isActiveSchedule) {
  if (!techCompletionPanel) return;
  if (!schedule || !assignedDevices.length || getCurrentUserRole() !== "Technician") {
    techCompletionPanel.classList.add("hidden");
    techCompletionPanel.innerHTML = "";
    return;
  }

  const summary = getAssignedCompletionSummary(schedule);
  const draft = readTechSignOffDraft();
  const awaitingReview = isScheduleAwaitingAdminReview(schedule);
  const approved = isScheduleAdminApproved(schedule);
  const returned = isScheduleReturnedForCorrection(schedule);
  const readOnly = awaitingReview || approved;
  const canComplete = Boolean(isActiveSchedule && summary.ready && !readOnly);
  const disabledReason = !isActiveSchedule
    ? "Start this assigned job before sign-off."
    : awaitingReview
      ? "Submitted. Awaiting Admin Review. Technician can view but cannot edit unless Admin returns it."
      : approved
        ? "Admin approved. This job is read-only."
    : summary.ready
      ? "All assigned items are completed. Sign and submit the report to Admin Review."
      : summary.blocked
        ? `${summary.blocked} item(s) locked by critical prerequisites / final restoration.`
      : `${summary.pending + summary.partial} item(s) still pending / SOP started.`;
  const statusLabel = awaitingReview
    ? "Awaiting Admin Review"
    : approved
      ? "Admin Approved"
      : returned
        ? "Returned For Correction"
        : canComplete
          ? "Ready to Submit"
          : "Not Ready";

  techCompletionPanel.classList.remove("hidden");
  techCompletionPanel.innerHTML = `
    <div class="tech-completion-head">
      <div>
        <p class="eyebrow">Final Step</p>
        <h3>Sign-Off & Submit Report</h3>
      </div>
      <span class="job-status-badge ${canComplete ? "complete" : ""}">${summary.done}/${summary.total} done - ${escapeHtml(statusLabel)}</span>
    </div>
    <div class="tech-completion-stats">
      <span><strong>${summary.pass}</strong>Done</span>
      <span><strong>${summary.fail}</strong>Fail</span>
      <span><strong>${summary.pending}</strong>Pending</span>
      <span><strong>${summary.partial}</strong>SOP Started</span>
      <span><strong>${summary.blocked || 0}</strong>Locked</span>
    </div>
    <p class="hint">${escapeHtml(disabledReason)}</p>
    ${readOnly ? `<div class="submission-review-status"><strong>${escapeHtml(statusLabel)}</strong><span>Admin must return this job before technician edits are allowed.</span></div>` : ""}
    <div class="tech-sign-grid ${canComplete ? "" : "locked"}">
      <label>
        Technician Sign-Off Name
        <input id="techSignTechnician" value="${escapeHtml(draft.technicianName)}" ${canComplete ? "" : "disabled"}>
      </label>
      <label>
        Client / Supervisor Witness
        <input id="techSignSupervisor" value="${escapeHtml(draft.supervisorName)}" placeholder="Example: Mr Young / Facilities Manager" ${canComplete ? "" : "disabled"}>
      </label>
      <label>
        Client Name
        <input id="techSignClient" value="${escapeHtml(draft.clientName)}" placeholder="Optional: UOB / WETEX / MTB" ${canComplete ? "" : "disabled"}>
      </label>
      <label class="tech-sign-wide">
        Completion Remarks
        <textarea id="techSignRemarks" rows="3" placeholder="Example: All assigned monthly points completed. Defects listed in report." ${canComplete ? "" : "disabled"}>${escapeHtml(draft.remarks)}</textarea>
      </label>
      <div class="tech-signature-card tech-sign-wide">
        <div class="tech-signature-head">
          <strong>Client / Supervisor Signature</strong>
          <button id="clearTechSignatureBtn" type="button" class="secondary" ${canComplete ? "" : "disabled"}>Clear</button>
        </div>
        <canvas id="techSignatureCanvas" aria-label="Client or supervisor signature" ${canComplete ? "" : "data-disabled=\"true\""}></canvas>
        <input id="techSignatureData" type="hidden" value="${escapeHtml(draft.signatureData)}">
        <span id="techSignatureStatus" class="signature-status">Please sign inside the box</span>
      </div>
      <label class="tech-sign-confirm tech-sign-wide">
        <input id="techSignConfirm" type="checkbox" ${draft.confirmed ? "checked" : ""} ${canComplete ? "" : "disabled"}>
        I confirm all assigned checklist items and critical SOP steps are completed for this scheduled job.
      </label>
    </div>
    <button id="techCompleteJobBtn" type="button" ${canComplete ? "" : "disabled"}>Submit Report for Review</button>
  `;

  setupSignaturePad(canComplete);
  const confirmRow = document.querySelector(".tech-sign-confirm");
  const confirmInput = document.querySelector("#techSignConfirm");
  const toggleConfirm = (event) => {
    if (!canComplete || !confirmInput) return;
    event.preventDefault();
    confirmInput.checked = !confirmInput.checked;
    confirmInput.dispatchEvent(new Event("change", { bubbles: true }));
    confirmRow.dataset.toggledAt = String(Date.now());
  };
  confirmRow?.addEventListener("pointerup", (event) => {
    if (event.pointerType === "mouse") return;
    toggleConfirm(event);
  });
  confirmRow?.addEventListener("touchend", (event) => {
    const lastToggle = Number(confirmRow.dataset.toggledAt || 0);
    if (Date.now() - lastToggle < 700) {
      event.preventDefault();
      return;
    }
    toggleConfirm(event);
  }, { passive: false });
  confirmRow?.addEventListener("click", (event) => {
    if (event.target === confirmInput) return;
    const lastToggle = Number(confirmRow.dataset.toggledAt || 0);
    if (Date.now() - lastToggle < 700) {
      event.preventDefault();
      return;
    }
    toggleConfirm(event);
  });
  document.querySelector("#techCompleteJobBtn")?.addEventListener("click", completeTechnicianAssignedJob);
}

async function completeTechnicianAssignedJob() {
  const schedule = getActiveTechnicianMaintenanceSchedule();
  if (!schedule) {
    document.querySelector("#syncState").textContent = "Start the assigned job before completing it.";
    return;
  }
  if (isTechnicianReportReadOnly(schedule)) {
    document.querySelector("#syncState").textContent = "This report is already submitted for Admin Review. Admin must return it before edits are allowed.";
    return;
  }
  const summary = getAssignedCompletionSummary(schedule);
  if (!summary.ready) {
    document.querySelector("#syncState").textContent = summary.blocked
      ? `${summary.blocked} assigned item(s) are locked by critical prerequisites or final restoration.`
      : `${summary.pending + summary.partial} assigned item(s) still not complete.`;
    renderTechAssignedItemList();
    return;
  }
  const signOff = readTechSignOffDraft();
  if (!signOff.technicianName || !signOff.supervisorName || !signOff.signatureData || !signOff.confirmed) {
    document.querySelector("#syncState").textContent = "Fill technician name, witness name, signature, and final confirmation.";
    return;
  }
  const confirmed = window.confirm("Submit this completed inspection to Admin Review? Technician editing will be locked unless Admin returns it for correction.");
  if (!confirmed) return;
  const signedAt = new Date().toISOString();
  const sharedSignOff = await submitSharedJobSignOff({
    ...signOff,
    signedAt
  }, schedule);
  if (!sharedSignOff.ok) {
    if (sharedSignOff.offline) {
      document.querySelector("#syncState").textContent = "Cannot submit report: shared server is unavailable. Local draft remains, but completion is blocked.";
    } else if (sharedSignOff.blocked) {
      const progress = sharedSignOff.payload?.progress;
      document.querySelector("#syncState").textContent = `Cannot submit report: server still sees ${progress?.pending || 0} pending, ${progress?.partial || 0} SOP started, ${progress?.blocked || 0} locked.`;
    } else if (sharedSignOff.conflict) {
      document.querySelector("#syncState").textContent = "Cannot submit report: sign-off was updated elsewhere. Reload before signing.";
    } else {
      document.querySelector("#syncState").textContent = "Cannot submit report: shared sign-off validation failed.";
    }
    renderTechAssignedItemList();
    return;
  }
  const submission = buildReportSubmissionRecord(schedule, { ...signOff, signedAt }, summary);
  const submitResult = await submitSharedReportSubmission(schedule, submission);
  if (!submitResult.ok) {
    if (submitResult.offline) {
      document.querySelector("#syncState").textContent = "Cannot submit report: shared server is unavailable. Your work remains saved but not submitted.";
    } else if (submitResult.blocked) {
      const progress = submitResult.payload?.progress;
      document.querySelector("#syncState").textContent = `Cannot submit report: server still sees ${progress?.pending || 0} pending, ${progress?.partial || 0} SOP started, ${progress?.blocked || 0} locked.`;
    } else if (submitResult.conflict) {
      document.querySelector("#syncState").textContent = "Cannot submit report: review record changed elsewhere. Reload and try again.";
    } else {
      document.querySelector("#syncState").textContent = "Cannot submit report for review.";
    }
    return;
  }
  state.activeJob.status = "AWAITING_ADMIN_REVIEW";
  state.activeJob.reportSubmission = submitResult.submission;
  state.activeJob.signOff = sharedSignOff.signOff || {
    ...signOff,
    signedAt,
    signedBy: getCurrentUserName(),
    signedById: getCurrentUserId(),
    signedRole: getCurrentUserRole()
  };
  schedule.status = "AWAITING_ADMIN_REVIEW";
  schedule.reportSubmissionStatus = "AWAITING_ADMIN_REVIEW";
  schedule.reportSubmission = submitResult.submission;
  schedule.reportSubmittedAt = submitResult.submission?.submittedAt || signedAt;
  schedule.reportSubmittedBy = getCurrentUserName();
  schedule.signOff = state.activeJob.signOff;
  addJobEvent("Report submitted", `${getCurrentUserName()} submitted ${schedule.scheduleId} for Admin Review`);
  syncActiveJobProgressToSchedule();
  persistActiveJob();
  persistSchedules();
  await saveSchedulesToPc(false);
  checklistForm?.classList.add("hidden");
  emptyState?.classList.remove("hidden");
  renderTechWorkPanel();
  renderMarkers();
  setTechScreen("complete", { scroll: true });
  document.querySelector("#syncState").textContent = `${schedule.scheduleId} submitted. Awaiting Admin Review.`;
}

function renderTechAssignedItemList() {
  if (!techAssignedItemPanel || !techAssignedItemList || getCurrentUserRole() !== "Technician") return;
  const schedule = getTechMarkerScopeSchedule();
  if (!schedule) {
    if (techItemProgress) techItemProgress.textContent = "No item loaded";
    techAssignedItemList.innerHTML = `<p class="hint">No assigned maintenance checklist yet. Admin must schedule the job first.</p>`;
    renderTechCompletionPanel(null, [], false);
    return;
  }

  ensureSchedulePlannedScope(schedule);
  ensureActiveJobCriticalWorkflows(schedule);
  const assignedDevices = getScheduledAssignedDevices(schedule);
  const currentFloor = getFloorAsset(floorSelect.value);
  const activeSchedule = getActiveTechnicianMaintenanceSchedule();
  const isActiveSchedule = activeSchedule?.scheduleId === schedule.scheduleId;
  const doneCount = assignedDevices.filter((device) => {
    const status = getAssignedDeviceCompletionStatus(device, schedule);
    return status !== "pending" && status !== "partial";
  }).length;
  if (techItemProgress) {
    techItemProgress.textContent = `${doneCount}/${assignedDevices.length} done`;
  }

  if (!assignedDevices.length) {
    techAssignedItemList.innerHTML = `<p class="hint">${escapeHtml(schedule.companyName)} has no assigned device scope. Ask admin to regenerate the schedule.</p>`;
    renderTechCompletionPanel(schedule, assignedDevices, isActiveSchedule);
    return;
  }

  renderTechSystemStagePanel(schedule);
  const visibleSystemDevices = getVisibleTechnicianFieldDevicesForSystem(schedule);
  const floorGroups = getAssignedFloorGroups(assignedDevices, schedule);
  const visibleFloorGroups = getAssignedFloorGroups(visibleSystemDevices, schedule);
  const selectedFloorHasItems = visibleSystemDevices.some((device) => device.floorId === floorSelect.value);
  const visibleFloorId = selectedFloorHasItems ? floorSelect.value : visibleFloorGroups[0]?.floorId || floorGroups[0]?.floorId;
  const visibleFloor = getFloorAsset(visibleFloorId);
  const visibleDevices = visibleSystemDevices.filter((device) => device.floorId === visibleFloorId);
  const floorButtons = (visibleFloorGroups.length ? visibleFloorGroups : floorGroups).map((floor) => `
    <button type="button" class="${floor.floorId === visibleFloorId ? "active" : ""}" data-tech-item-floor="${escapeHtml(floor.floorId)}">
      ${escapeHtml(floor.floorCode || floor.floorTitle)}
      <span>${floor.done}/${floor.count}</span>
    </button>
  `).join("");
  const summary = getAssignedCompletionSummary(schedule);
  const activeSystemLabel = getTechnicianFireSystemDefinition(getActiveTechnicianSystemKey(schedule))?.label || "All Assigned";

  techAssignedItemList.innerHTML = `
    <div class="tech-item-job-summary">
      <strong>${escapeHtml(schedule.companyName)} / ${escapeHtml(schedule.siteName)}</strong>
      <span>${escapeHtml(activeSystemLabel)} | ${assignedDevices.length} frozen assigned item(s) | ${escapeHtml(schedule.date || "")} ${escapeHtml(schedule.time || "")}</span>
      ${!isActiveSchedule ? `<span class="tech-item-warning">Press Open Checklist on any item to start this scheduled job.</span>` : ""}
    </div>
    ${renderTechProgressGrid(summary)}
    <div class="tech-floor-chip-row">
      ${floorButtons}
    </div>
    <div class="tech-current-floor-note">
      Showing ${visibleDevices.length} ${escapeHtml(activeSystemLabel)} item(s) on ${escapeHtml(visibleFloor?.title || currentFloor.title)}.
      ${visibleSystemDevices.length ? "" : `<span>Use the system stage cards above for this configured prerequisite/SOP.</span>`}
    </div>
    <div class="tech-item-cards">
      ${visibleDevices.map((device) => renderTechAssignedItemCard(device, schedule)).join("")}
    </div>
  `;
  renderTechCompletionPanel(schedule, assignedDevices, isActiveSchedule);

  techAssignedItemList.querySelectorAll("[data-tech-item-floor]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianFloor(button.dataset.techItemFloor));
  });
  techAssignedItemList.querySelectorAll("[data-tech-open-device]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianAssignedDevice(button.dataset.techOpenDevice, { openChecklist: true }));
  });
  techAssignedItemList.querySelectorAll("[data-tech-map-device]").forEach((button) => {
    bindReliableTap(button, () => focusTechnicianAssignedDevice(button.dataset.techMapDevice, { openChecklist: false, scrollToMap: true }));
  });
  techAssignedItemList.querySelectorAll("[data-tech-item-card]").forEach((card) => {
    bindReliableTap(card, (event) => {
      if (event.target.closest("button")) return;
      focusTechnicianAssignedDevice(card.dataset.techItemCard, { openChecklist: true });
    });
  });
}

function getAssignedFloorGroups(devicesForSchedule, schedule = null) {
  const groups = new Map();
  devicesForSchedule.forEach((device) => {
    const floorId = device.floorId || "unknown-floor";
    const group = groups.get(floorId) || {
      floorId,
      floorTitle: device.floorTitle || device.floor || floorId,
      floorCode: device.floorCode || getFloorCode(floorId),
      count: 0,
      done: 0
    };
    group.count += 1;
    const status = getAssignedDeviceCompletionStatus(device, schedule);
    if (status !== "pending" && status !== "partial" && status !== "locked") group.done += 1;
    groups.set(floorId, group);
  });
  return [...groups.values()].sort((a, b) => {
    return `${a.floorCode || ""} ${a.floorTitle || ""}`.localeCompare(`${b.floorCode || ""} ${b.floorTitle || ""}`, undefined, {
      numeric: true,
      sensitivity: "base"
    });
  });
}

function renderTechAssignedItemCard(device, schedule = null) {
  const access = getDeviceCriticalAccessState(device, schedule);
  const status = getAssignedDeviceCompletionStatus(device, schedule);
  const isActive = state.selectedId === device.id || state.activeCriticalDevice?.tag === device.id;
  const location = displayDeviceLocation(device.location || device.floorTitle || "");
  const auditLine = renderTechAssignedItemAudit(device, schedule);
  const claim = getActiveSharedClaim(device.id, schedule);
  const claimLine = claim
    ? `<small class="tech-item-warning">Opened by ${escapeHtml(claim.claimedByName || claim.claimedBy || "another technician")} - saving stale changes will be rejected.</small>`
    : "";
  const lockLine = !access.allowed
    ? `<small class="tech-dependency-lock">${escapeHtml(access.reason || "Critical prerequisite required before opening this checklist.")}</small>`
    : access.dependencyLabel
      ? `<small class="tech-dependency-ok">Prerequisite cleared: ${escapeHtml(access.dependencyLabel)}</small>`
      : "";
  const buttonLabel = !access.allowed && access.parentDeviceId ? "Open Prerequisite" : "Open Checklist";
  return `
    <article class="tech-assigned-item-card ${escapeHtml(status)} ${isActive ? "active" : ""}" data-tech-item-card="${escapeHtml(device.id)}" tabindex="0" role="button" aria-label="Open checklist for ${escapeHtml(device.id)}">
      <div class="tech-item-main">
        <span class="tech-item-type ${escapeHtml(getDeviceTypeClass(device.type))}">${escapeHtml(device.short || getShortCode(device))}</span>
        <div>
          <strong>${escapeHtml(device.id)}</strong>
          <span>${escapeHtml(device.type || "Device")}</span>
          <small>${escapeHtml(device.floorTitle || device.floor || "")} | ${escapeHtml(location)}</small>
          ${auditLine}
          ${claimLine}
          ${lockLine}
        </div>
      </div>
      <span class="tech-item-status ${escapeHtml(status)}">${escapeHtml(getAssignedDeviceStatusLabel(status))}</span>
      <div class="tech-item-actions">
        <button type="button" data-tech-open-device="${escapeHtml(device.id)}">${escapeHtml(buttonLabel)}</button>
        <button type="button" class="secondary" data-tech-map-device="${escapeHtml(device.id)}">Map</button>
      </div>
    </article>
  `;
}

function renderTechAssignedItemAudit(device, schedule = null) {
  const session = getItemSessionForDevice(device, schedule);
  const critical = isCriticalSopDevice(device);
  const sop = critical ? getCriticalSopRecordForDevice(device, schedule) : null;
  const pieces = [];

  if (critical) {
    const templateId = getCriticalSopTemplateIdForDevice(device);
    const template = criticalSopTemplates.find((item) => item.id === templateId);
    const savedCount = sop && template ? getCriticalSopCompleteCount(template, sop) : 0;
    const total = template?.steps?.length || 0;
    const workflow = getCriticalWorkflowRunForParentDevice(device, schedule);
    const workflowState = workflow ? getCachedCriticalWorkflowRunState(workflow, schedule) : null;
    pieces.push(`Critical SOP${total ? ` ${savedCount}/${total}` : ""}`);
    if (workflowState?.stageLabel) pieces.push(workflowState.stageLabel);
  } else {
    const access = getDeviceCriticalAccessState(device, schedule);
    if (access.dependencies?.length) {
      const dependencyText = access.allowed
        ? `Prerequisite cleared: ${access.dependencies.map((dependency) => dependency.run.parentDeviceTag).join(" + ")}`
        : `Locked by ${access.parentDeviceTag || access.parentDeviceId || "critical prerequisite"}`;
      pieces.push(dependencyText);
    }
  }

  if (session?.lastSavedAt) {
    pieces.push(`Filled by ${session.savedBy || "-"}`);
    pieces.push(`Saved ${formatShortDateTime(session.lastSavedAt)}`);
    pieces.push(`Time ${formatDurationMs(session.durationMs)}`);
  } else if (session?.lastOpenedAt) {
    pieces.push(`Opened by ${session.lastOpenedBy || session.firstOpenedBy || "-"}`);
    pieces.push(`Started ${formatShortDateTime(session.lastOpenedAt)}`);
  } else {
    pieces.push(`Assigned to ${schedule?.technician || "technician"}`);
  }

  return `<small class="tech-item-audit">${pieces.map(escapeHtml).join(" | ")}</small>`;
}

function focusTechnicianFloor(floorId) {
  if (!floorExists(floorId)) return;
  if (getCurrentUserRole() === "Technician") {
    const schedule = getTechMarkerScopeSchedule();
    setTechnicianMapFloor(floorId, schedule ? {
      companyName: schedule.companyName,
      siteName: schedule.siteName
    } : state.siteProfile);
    persistTechnicianActiveContext(state.activeTechPreviewScheduleId || schedule?.scheduleId || "", state.activeTechSystemKey, floorSelect.value);
    renderMarkers();
    renderTechAssignedItemList();
  } else {
    floorSelect.value = floorId;
    floorSelect.dispatchEvent(new Event("change"));
  }
  requestAnimationFrame(scrollInspectionPanelIntoView);
}

async function focusTechnicianAssignedDevice(deviceId, { openChecklist = false, scrollToMap = false, dependencyBlockedMessage = "", scrollIntoView = true } = {}) {
  const schedule = getTechMarkerScopeSchedule();
  const device = getScheduledAssignedDevices(schedule).find((item) => item.id === deviceId);
  if (!device) return;
  state.activeTechPreviewScheduleId = schedule.scheduleId;
  if (openChecklist) {
    setTechScreen("inspection");
  } else if (scrollToMap) {
    setTechScreen("mimic");
  }
  if (device.floorId && floorExists(device.floorId) && floorSelect.value !== device.floorId) {
    if (getCurrentUserRole() === "Technician") {
      setTechnicianMapFloor(device.floorId, {
        companyName: schedule.companyName,
        siteName: schedule.siteName
      });
      persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
      renderMarkers();
      renderTechAssignedItemList();
    } else {
      floorSelect.value = device.floorId;
      floorSelect.dispatchEvent(new Event("change"));
    }
  } else {
    renderMarkers();
    renderTechAssignedItemList();
  }
  state.selectedSetupTag = device.id;
  state.focusedMapTag = scrollToMap ? device.id : null;
  renderMarkers();
  if (openChecklist) {
    await selectDevice(device.id, { dependencyBlockedMessage, scrollIntoView });
    renderTechAssignedItemList();
    return;
  }
  document.querySelector("#syncState").textContent = `${device.id} highlighted on mimic`;
  if (scrollToMap) {
    requestAnimationFrame(() => {
      scrollMapIntoView();
      centerMapOnDeviceMarker(device.id);
    });
  }
}

async function showTechnicianScheduleOnMap(scheduleId, { scrollToMap = true } = {}) {
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (!schedule) return;
  if (!isScheduleAssignedToCurrentTechnician(schedule)) {
    document.querySelector("#syncState").textContent = `${schedule.scheduleId} is not assigned to ${getCurrentUserName()}`;
    return;
  }
  await ensureTechnicianFieldDataLoaded(schedule);
  ensureSchedulePlannedScope(schedule);
  state.activeTechPreviewScheduleId = schedule.scheduleId;
  const profile = {
    companyName: schedule.companyName,
    siteName: schedule.siteName
  };
  const targetFloorId = getBestSchedulePreviewFloorId(schedule, profile);
  setTechnicianMapFloor(targetFloorId, profile);
  state.activeTechPreviewScheduleId = schedule.scheduleId;
  persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
  renderMarkers();
  renderTechAssignedItemList();
  if (scrollToMap) {
    setTechScreen("mimic", { scroll: true, renderMarkers: false });
  } else {
    renderTechWorkflowNav();
  }
  document.querySelector("#syncState").textContent = `${schedule.companyName} assigned item list loaded`;
}

function getBestSchedulePreviewFloorId(schedule, profile) {
  const currentFloorId = floorSelect.value;
  const currentHasAssignedPins = (schedule.plannedFloorCounts || [])
    .some((floor) => floor.floorId === currentFloorId && floor.count > 0);
  if (currentHasAssignedPins && floorExists(currentFloorId)) return currentFloorId;

  const firstAssignedFloor = (schedule.plannedFloorCounts || [])
    .find((floor) => floor.count > 0 && floorExists(floor.floorId));
  if (firstAssignedFloor?.floorId) return firstAssignedFloor.floorId;

  const fallbackFloorId = schedule.startFloorId || schedule.floorId;
  if (floorExists(fallbackFloorId)) return fallbackFloorId;
  return getFirstFloorIdForProfile(profile);
}

function updateFrozenScheduleScopeMetadata(schedule, devicePool, scopeInfo, profile) {
  const plannedIds = uniqueValues(Array.isArray(schedule.plannedDeviceIds) ? schedule.plannedDeviceIds : []);
  const plannedSet = new Set(plannedIds);
  const plannedDevices = getUniqueScheduleDevices(devicePool).filter((device) => plannedSet.has(device.id));
  const activeDevices = plannedDevices.filter((device) => isActiveSystem(device.type));
  const passiveDevices = plannedDevices.filter((device) => isPassiveScopeDevice(device));
  const frequencyPercent = normalizeMaintenanceFrequency(schedule.contractFrequencyPercent || getContractFrequencyForProfile(profile));
  const annualCycleId = schedule.annualCycleId || schedule.contractCycleId || getContractCycleIdForDate(schedule.date || schedule.createdAt);
  const scopeSelectionMode = schedule.scopeSelectionMode || getScheduleScopeSelectionMode(scopeInfo, schedule.serviceType || "");
  const rotationScopeKey = getScheduleRotationScopeKey(scopeInfo, scopeSelectionMode, schedule.floorId || schedule.startFloorId || floorSelect.value);
  const totalPassivePool = getUniqueScheduleDevices(devicePool).filter((device) => isPassiveScopeDevice(device)).length;
  const savedMandatoryIds = uniqueValues(schedule.mandatoryRecheckDeviceIds || []).filter((id) => plannedSet.has(id));
  const mandatoryIds = new Set(savedMandatoryIds);

  schedule.contractFrequencyPercent = frequencyPercent;
  schedule.annualCycleId = annualCycleId;
  schedule.contractCycleId = schedule.contractCycleId || annualCycleId;
  schedule.scopeSelectionMode = scopeSelectionMode;
  schedule.scopeFrozen = true;
  schedule.rotationHistoryKey = scopeSelectionMode === "site-wide"
    ? schedule.rotationHistoryKey || getScopeHistoryKey(frequencyPercent, profile, rotationScopeKey, annualCycleId)
    : schedule.rotationHistoryKey || "";
  schedule.deviceCount = plannedIds.length;
  schedule.totalFloorDeviceCount = Number(schedule.totalFloorDeviceCount || devicePool.length || 0);
  schedule.totalSiteDeviceCount = scopeSelectionMode === "site-wide" ? Number(schedule.totalSiteDeviceCount || devicePool.length || 0) : schedule.totalSiteDeviceCount;
  schedule.passiveCount = passiveDevices.length;
  schedule.activeCount = activeDevices.length;
  schedule.criticalDeviceIds = Array.isArray(schedule.criticalDeviceIds) && schedule.criticalDeviceIds.length
    ? uniqueValues(schedule.criticalDeviceIds)
    : activeDevices.map((device) => device.id);
  schedule.mandatoryRecheckDeviceIds = savedMandatoryIds;
  schedule.adminForcedDeviceIds = Array.isArray(schedule.adminForcedDeviceIds) && schedule.adminForcedDeviceIds.length
    ? uniqueValues(schedule.adminForcedDeviceIds)
    : plannedDevices.filter((device) => device.forceRecheck || device.adminForcedRecheck).map((device) => device.id);
  schedule.sampledDeviceIds = Array.isArray(schedule.sampledDeviceIds) && schedule.sampledDeviceIds.length
    ? uniqueValues(schedule.sampledDeviceIds)
    : passiveDevices.filter((device) => !mandatoryIds.has(device.id)).map((device) => device.id);
  schedule.passiveTargetCount = Number(schedule.passiveTargetCount || Math.max(1, Math.ceil(totalPassivePool * (frequencyPercent / 100))) || passiveDevices.length || 0);
  if (plannedDevices.length) schedule.plannedFloorCounts = getScheduleFloorCounts(plannedDevices);
  return plannedDevices;
}

function ensureSchedulePlannedScope(schedule) {
  if (!schedule || isExtinguisherJobSchedule(schedule)) return schedule;
  const cache = getRuntimeCaches();
  const cacheKey = getScheduleVersionKey(schedule);
  if (cache.scopeEnsured.get(getScheduleKey(schedule)) === cacheKey) return schedule;
  const normalizedScope = normalizeScheduleScopeForService(schedule.scope || "full-maintenance", schedule.serviceType || "");
  const scopeInfo = getScheduleScopeInfo(normalizedScope);
  schedule.scope = normalizedScope;
  schedule.scopeLabel = scopeInfo.label;
  if (scopeInfo.jobOnly) {
    cache.scopeEnsured.set(getScheduleKey(schedule), getScheduleVersionKey(schedule));
    return schedule;
  }
  const profile = {
    companyName: schedule.companyName,
    siteName: schedule.siteName
  };
  const scheduleServiceType = schedule.serviceType || "";
  const existingScopeSelectionMode = schedule.scopeSelectionMode || getScheduleScopeSelectionMode(scopeInfo, scheduleServiceType);
  const devicePool = getScheduleDevicePoolForScope(scopeInfo, profile, schedule.floorId || schedule.startFloorId || floorSelect.value, {
    serviceType: scheduleServiceType,
    scopeSelectionMode: existingScopeSelectionMode
  });
  const plannedIds = Array.isArray(schedule.plannedDeviceIds) ? schedule.plannedDeviceIds : [];
  if (schedule.scopeFrozen === true && plannedIds.length) {
    updateFrozenScheduleScopeMetadata(schedule, devicePool, scopeInfo, profile);
    cache.scopeEnsured.set(getScheduleKey(schedule), getScheduleVersionKey(schedule));
    return schedule;
  }
  const availableIds = new Set(devicePool.map((device) => device.id).filter(Boolean));
  const validPlannedCount = plannedIds.filter((id) => availableIds.has(id)).length;
  const stalePlannedIds = plannedIds.length > 0 && devicePool.length > 0 && validPlannedCount === 0;
  const knownPoolCount = Number(schedule.totalSiteDeviceCount || schedule.totalFloorDeviceCount || 0);
  const poolExpandedAfterSave = plannedIds.length > 0
    && devicePool.length > 0
    && knownPoolCount > 0
    && devicePool.length > knownPoolCount * 2
    && validPlannedCount < Math.ceil(plannedIds.length / 2);
  const hasUsableExistingPlannedScope = plannedIds.length > 0 && !stalePlannedIds && !poolExpandedAfterSave;
  if (hasUsableExistingPlannedScope) {
    schedule.scopeFrozen = true;
    updateFrozenScheduleScopeMetadata(schedule, devicePool, scopeInfo, profile);
    cache.scopeEnsured.set(getScheduleKey(schedule), getScheduleVersionKey(schedule));
    return schedule;
  }
  const shouldRefreshScope = !plannedIds.length
    || stalePlannedIds
    || poolExpandedAfterSave;
  if (!shouldRefreshScope) {
    cache.scopeEnsured.set(getScheduleKey(schedule), getScheduleVersionKey(schedule));
    return schedule;
  }
  const frequencyPercent = normalizeMaintenanceFrequency(schedule.contractFrequencyPercent || getContractFrequencyForProfile(profile));
  const scopeSelectionMode = getScheduleScopeSelectionMode(scopeInfo, scheduleServiceType);
  const annualCycleId = schedule.annualCycleId || schedule.contractCycleId || getContractCycleIdForDate(schedule.date || schedule.createdAt);
  const rotationScopeKey = getScheduleRotationScopeKey(scopeInfo, scopeSelectionMode, schedule.floorId || schedule.startFloorId || floorSelect.value);
  const rotationHistoryKey = scopeSelectionMode === "site-wide"
    ? getScopeHistoryKey(frequencyPercent, profile, rotationScopeKey, annualCycleId)
    : "";
  const plannedDevices = getScheduleDevicesForScope(devicePool, scopeInfo, {
    profile,
    floorId: scopeSelectionMode === "site-wide" ? rotationScopeKey : schedule.floorId,
    frequencyPercent,
    annualCycleId,
    rotationHistoryKey,
    date: schedule.date || "",
    useMaintenanceSampling: shouldApplyMaintenanceSampling(scopeInfo, scheduleServiceType),
    commitHistory: false
  });
  const startFloor = getFloorAsset(schedule.floorId || schedule.startFloorId || floorSelect.value);
  schedule.contractFrequencyPercent = frequencyPercent;
  schedule.plannedDeviceIds = plannedDevices.map((device) => device.id);
  schedule.deviceCount = plannedDevices.length;
  schedule.totalFloorDeviceCount = devicePool.length;
  schedule.totalSiteDeviceCount = scopeSelectionMode === "site-wide" ? devicePool.length : undefined;
  schedule.passiveCount = plannedDevices.filter((device) => isPassiveScopeDevice(device)).length;
  schedule.activeCount = plannedDevices.filter((device) => isActiveSystem(device.type)).length;
  schedule.scopeSelectionMode = scopeSelectionMode;
  schedule.annualCycleId = annualCycleId;
  schedule.contractCycleId = schedule.contractCycleId || annualCycleId;
  schedule.rotationHistoryKey = rotationHistoryKey;
  schedule.scopeFrozen = true;
  schedule.startFloorId = schedule.startFloorId || schedule.floorId;
  schedule.startFloorTitle = schedule.startFloorTitle || startFloor.title;
  schedule.floorTitle = scopeSelectionMode === "site-wide" ? `Whole site (start: ${startFloor.title})` : startFloor.title;
  schedule.plannedFloorCounts = getScheduleFloorCounts(plannedDevices);
  schedule.criticalDeviceIds = plannedDevices.filter((device) => isActiveSystem(device.type)).map((device) => device.id);
  schedule.mandatoryRecheckDeviceIds = plannedDevices.filter((device) => device.recheckPriority > 0).map((device) => device.id);
  schedule.sampledDeviceIds = plannedDevices
    .filter((device) => isPassiveScopeDevice(device) && !device.recheckPriority)
    .map((device) => device.id);
  schedule.passiveTargetCount = schedule.sampledDeviceIds.length || schedule.passiveCount;
  cache.scopeEnsured.set(getScheduleKey(schedule), getScheduleVersionKey(schedule));
  return schedule;
}

async function resumeScheduledJob(schedule, options = {}) {
  const isTechnician = getCurrentUserRole() === "Technician";
  if (isTechnician) {
    loadStoredRunState();
    await ensureTechnicianFieldDataLoaded(schedule);
    if (isStaleTechnicianSystemOpenRequest(options)) return false;
  }
  const sharedCache = options.sharedCache || await requestSharedJobState(schedule);
  if (isStaleTechnicianSystemOpenRequest(options)) return false;
  if (sharedCache) {
    applySharedRecordsToLocalState(sharedCache.store, schedule);
  } else {
    loadScheduleProgressSnapshot(schedule);
  }
  const savedJob = schedule.jobProgress?.activeJob || {};
  const profile = {
    companyName: schedule.companyName,
    siteName: schedule.siteName
  };
  const targetFloorId = options.targetFloorId || schedule.floorId || schedule.startFloorId;
  if (isTechnician) {
    state.siteProfile = normalizeClientProfile(profile);
    writeStoredJson("rmtSiteProfile", state.siteProfile);
    if (floorExists(targetFloorId)) {
      setTechnicianMapFloor(targetFloorId, profile);
    }
    if (schedule.mimicViewMode === "original") {
      setMimicViewMode("original");
    }
  } else {
    selectClientProfile(profile);
    if (floorExists(targetFloorId)) {
      floorSelect.value = targetFloorId;
      floorSelect.dispatchEvent(new Event("change"));
    }
  }
  const scheduleFrequencyPercent = Number(schedule.contractFrequencyPercent || savedJob.serviceFrequencyPercent || getFrequencyFromScheduleScope(schedule.scope, schedule.serviceType));
  const techSystemKey = isTechnician
    ? options.preserveTechSystem === false
      ? ""
      : options.expectedTechSystemKey || state.activeTechSystemKey || savedJob.activeTechSystemKey || ""
    : savedJob.activeTechSystemKey || "";
  state.activeJob = {
    ...savedJob,
    jobId: savedJob.jobId || `JOB-${formatRunStamp(new Date())}`,
    scheduleId: schedule.scheduleId,
    companyName: schedule.companyName,
    siteName: schedule.siteName,
    clientSource: schedule.clientSource,
    address: schedule.address,
    inspector: savedJob.inspector || getCurrentUserName(),
    serviceType: schedule.serviceType,
    reference: schedule.scheduleId,
    status: savedJob.status || "In Progress",
    startedAt: savedJob.startedAt || schedule.startedAt || new Date().toISOString(),
    createdAt: savedJob.createdAt || schedule.createdAt || new Date().toISOString(),
    serviceFrequencyPercent: scheduleFrequencyPercent,
    schedule,
    activeTechSystemKey: techSystemKey,
    activeFloorId: floorSelect.value,
    events: savedJob.events || [],
    itemSessions: savedJob.itemSessions || {},
    criticalWorkflowRuns: savedJob.criticalWorkflowRuns || {}
  };
  ensureActiveJobCriticalWorkflows(schedule);
  state.activeTechPreviewScheduleId = schedule.scheduleId;
  state.activeTechSystemKey = techSystemKey;
  state.activeTechFloorId = floorSelect.value;
  ensureActiveJobTeamMember();
  jobInspector.value = state.activeJob.inspector || getCurrentUserName();
  setSelectValue(jobServiceType, schedule.serviceType || "Maintenance / Inspection", "Maintenance / Inspection");
  jobReference.value = schedule.scheduleId;
  const serviceFrequency = document.querySelector("#serviceFrequency");
  if ([...serviceFrequency.options].some((option) => option.value === String(scheduleFrequencyPercent))) {
    serviceFrequency.value = String(scheduleFrequencyPercent);
  }
  addJobEvent("Job resumed", `${getCurrentUserName()} resumed shared schedule`);
  syncActiveJobProgressToSchedule();
  if (isTechnician) {
    persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
    renderTechWorkPanel();
  } else {
    persistActiveJob();
    saveSchedulesToPc(false);
    renderSchedulePanel();
    renderJobPanel();
    renderTechWorkPanel();
    renderMarkers();
    updateSummary();
  }
  if (options.openDeviceId) {
    await focusTechnicianAssignedDevice(options.openDeviceId, { openChecklist: true });
  } else if (options.openFirstUnfinished && getCurrentUserRole() === "Technician") {
    const target = getResumeTargetAssignedDevice(schedule);
    if (target) {
      await focusTechnicianAssignedDevice(target.id || target.tag, { openChecklist: true });
    } else {
      setTechScreen("inspection", { scroll: true });
    }
  } else if (getCurrentUserRole() === "Technician" && !options.stayOnJobSummary) {
    setTechScreen("inspection", { scroll: true });
  } else if (isTechnician) {
    setTechScreen("jobs");
  }
  document.querySelector("#syncState").textContent = `${schedule.scheduleId} resumed from saved progress`;
  return true;
}

async function startScheduledJob(scheduleId, options = {}) {
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (!schedule) return false;
  const isTechnician = getCurrentUserRole() === "Technician";
  if (!isScheduleAssignedToCurrentTechnician(schedule)) {
    document.querySelector("#syncState").textContent = `${schedule.scheduleId} is not assigned to ${getCurrentUserName()}`;
    return false;
  }
  if (isTechnician) {
    loadStoredRunState();
    await ensureTechnicianFieldDataLoaded(schedule);
    if (isStaleTechnicianSystemOpenRequest(options)) return false;
  }
  ensureSchedulePlannedScope(schedule);
  const sharedCache = await requestSharedJobState(schedule);
  if (isStaleTechnicianSystemOpenRequest(options)) return false;
  if ((!state.activeJob || state.activeJob.status === "Completed") && isScheduleResumeAvailable(schedule)) {
    return resumeScheduledJob(schedule, { ...options, sharedCache });
  }
  if (state.activeJob && state.activeJob.status !== "Completed") {
    const currentScheduleId = state.activeJob.scheduleId || state.activeJob.schedule?.scheduleId;
    if (currentScheduleId === schedule.scheduleId) {
      state.activeTechPreviewScheduleId = schedule.scheduleId;
      if (isTechnician) {
        if (options.expectedTechSystemKey) state.activeTechSystemKey = options.expectedTechSystemKey;
        persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
        renderTechWorkPanel();
        if (state.techScreen === "mimic") renderMarkers();
      } else {
        renderJobPanel();
        renderTechWorkPanel();
        renderMarkers();
      }
      if (options.openDeviceId) {
        await focusTechnicianAssignedDevice(options.openDeviceId, { openChecklist: true });
      } else if (options.openFirstUnfinished && getCurrentUserRole() === "Technician") {
        const target = getResumeTargetAssignedDevice(schedule);
        if (target) await focusTechnicianAssignedDevice(target.id || target.tag, { openChecklist: true });
      } else if (isTechnician && !options.stayOnJobSummary) {
        setTechScreen("inspection", { scroll: true });
      } else if (isTechnician) {
        setTechScreen("jobs");
      } else {
        requestAnimationFrame(scrollInspectionPanelIntoView);
      }
      document.querySelector("#syncState").textContent = `${schedule.scheduleId} is already active.`;
      return true;
    }
    const activeJobIsStale = isTechnician && !isActiveTechnicianJobResolvable();
    const canSwitchFromTechOpen = isTechnician && (options.openDeviceId || options.openFirstUnfinished || options.stayOnJobSummary || options.forceSwitch || activeJobIsStale);
    if (!canSwitchFromTechOpen) {
      document.querySelector("#syncState").textContent = "Finish or check out the current job before starting this schedule";
      return false;
    }
    if (!activeJobIsStale && !options.forceSwitch) {
      const switchTarget = options.openDeviceId ? ` and open ${options.openDeviceId}` : "";
      const confirmed = window.confirm(`Switch to ${schedule.companyName || "this assigned job"}${switchTarget}? Unsaved answers from the previous phone job will be cleared.`);
      if (!confirmed) {
        document.querySelector("#syncState").textContent = "Checklist not opened because the previous active job is still active.";
        return false;
      }
    }
    clearCurrentRunData();
    clearActiveJobForSwitch();
  }
  if (hasCurrentRunData()) {
    if (isTechnician) {
      keepRunDataForSchedule(schedule);
    } else {
      const confirmed = window.confirm("Start this scheduled job and clear current inspection answers/SOP results? Device pins and master data will remain.");
      if (!confirmed) return false;
      clearCurrentRunData();
    }
  }

  const profile = {
    companyName: schedule.companyName,
    siteName: schedule.siteName
  };
  const targetFloorId = options.targetFloorId || schedule.floorId;
  if (isTechnician) {
    state.siteProfile = normalizeClientProfile(profile);
    writeStoredJson("rmtSiteProfile", state.siteProfile);
    if (floorExists(targetFloorId)) {
      setTechnicianMapFloor(targetFloorId, profile);
    }
  } else {
    selectClientProfile(profile);
    if (floorExists(targetFloorId)) {
      floorSelect.value = targetFloorId;
      floorSelect.dispatchEvent(new Event("change"));
    }
  }
  jobInspector.value = isTechnician ? getCurrentUserName() : schedule.technician || "Demo Inspector";
  setSelectValue(jobServiceType, schedule.serviceType || "Maintenance / Inspection", "Maintenance / Inspection");
  jobReference.value = schedule.scheduleId;
  const scheduleFrequencyPercent = Number(schedule.contractFrequencyPercent || getFrequencyFromScheduleScope(schedule.scope, schedule.serviceType));
  const serviceFrequency = document.querySelector("#serviceFrequency");
  if ([...serviceFrequency.options].some((option) => option.value === String(scheduleFrequencyPercent))) {
    serviceFrequency.value = String(scheduleFrequencyPercent);
  }

  const now = new Date();
  state.activeJob = {
    jobId: `JOB-${formatRunStamp(now)}`,
    scheduleId: schedule.scheduleId,
    companyName: schedule.companyName,
    siteName: schedule.siteName,
    clientSource: schedule.clientSource,
    address: schedule.address,
    extinguisherDetails: schedule.extinguisherDetails,
    extinguisherUnitDetails: schedule.extinguisherUnitDetails,
    inspector: isTechnician ? getCurrentUserName() : schedule.technician,
    serviceType: schedule.serviceType,
    reference: schedule.scheduleId,
    status: "Scheduled Job Started",
    createdAt: now.toISOString(),
    startedAt: now.toISOString(),
    serviceFrequencyPercent: scheduleFrequencyPercent,
    schedule,
    activeTechSystemKey: isTechnician ? options.expectedTechSystemKey || state.activeTechSystemKey || "" : "",
    activeFloorId: floorSelect.value,
    events: [],
    itemSessions: {},
    criticalWorkflowRuns: {}
  };
  ensureActiveJobCriticalWorkflows(schedule);
  state.activeTechPreviewScheduleId = schedule.scheduleId;
  if (isTechnician && options.expectedTechSystemKey) state.activeTechSystemKey = options.expectedTechSystemKey;
  state.activeTechFloorId = floorSelect.value;
  schedule.status = "In Progress";
  schedule.startedAt = now.toISOString();
  addJobEvent("Scheduled job started", schedule.floorTitle);
  ensureActiveJobTeamMember();
  syncActiveJobProgressToSchedule();
  persistSchedules();
  if (isTechnician) {
    persistTechnicianActiveContext(schedule.scheduleId, state.activeTechSystemKey, floorSelect.value);
    renderTechWorkPanel();
    if (state.techScreen === "mimic") renderMarkers();
  } else {
    persistActiveJob();
    renderSchedulePanel();
    renderJobPanel();
    renderTechWorkPanel();
    renderMarkers();
  }
  if (!options.skipFullJobSave && !isTechnician) {
    await saveJobProgress(false);
  }
  document.querySelector("#syncState").textContent = options.openDeviceId
    ? `${schedule.scheduleId} started from ${options.openDeviceId}`
    : `${schedule.scheduleId} loaded into active job`;
  if (!options.openDeviceId && options.openFirstUnfinished && isTechnician) {
    const target = getResumeTargetAssignedDevice(schedule);
    if (target) {
      await focusTechnicianAssignedDevice(target.id || target.tag, { openChecklist: true });
    } else {
      setTechScreen("inspection", { scroll: true });
    }
  } else if (isTechnician && !options.stayOnJobSummary) {
    setTechScreen("inspection", { scroll: true });
  } else if (isTechnician) {
    setTechScreen("jobs");
  }
  return true;
}

function getFrequencyFromScheduleScope(scope, serviceType = "") {
  const service = String(serviceType || "").toLowerCase();
  if (service.includes("yearly")) return "100";
  if (service.includes("50%")) return "50";
  if (service.includes("tri")) return "30";
  if (service.includes("bi")) return "20";
  if (scope === "bimonthly-20") return "20";
  if (scope === "trimonthly-30") return "30";
  if (scope === "special-50") return "50";
  if (scope === "yearly-100") return "100";
  return "10";
}

function deleteSchedule(scheduleId) {
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  releaseScheduleScopeReservation(schedule);
  state.schedules = state.schedules.filter((item) => item.scheduleId !== scheduleId);
  persistSchedules();
  renderSchedulePanel();
  saveSchedulesToPc(false);
  document.querySelector("#syncState").textContent = `${scheduleId} deleted`;
}

function reserveScheduleScope(schedule) {
  if (!schedule?.rotationHistoryKey || schedule.status === "Completed" || schedule.status === "Cancelled") return;
  const passiveDevices = getPassiveDevicesForScheduleCycle(schedule);
  if (!passiveDevices.length) return;
  const selectedIds = new Set(uniqueValues(schedule.plannedDeviceIds || []));
  const selectedDevices = passiveDevices.filter((device) => selectedIds.has(device.id));
  const mandatoryIds = new Set(schedule.mandatoryRecheckDeviceIds || []);
  const mandatoryRecheckDevices = passiveDevices.filter((device) => mandatoryIds.has(device.id));
  const cycle = getScopeCycleRecord(schedule.rotationHistoryKey, passiveDevices, {
    annualCycleId: schedule.annualCycleId || schedule.contractCycleId,
    excludeScheduleId: schedule.scheduleId
  });
  reserveScopeCycleSelection(schedule.rotationHistoryKey, passiveDevices, cycle, selectedDevices, {
    scheduleId: schedule.scheduleId,
    annualCycleId: schedule.annualCycleId || schedule.contractCycleId,
    mandatoryRecheckDevices,
    date: schedule.date || ""
  });
}

function getPassiveDevicesForScheduleCycle(schedule) {
  if (!schedule?.rotationHistoryKey) return [];
  const profile = {
    companyName: schedule.companyName,
    siteName: schedule.siteName
  };
  const normalizedScope = normalizeScheduleScopeForService(schedule.scope || "full-maintenance", schedule.serviceType || "");
  const scopeInfo = getScheduleScopeInfo(normalizedScope);
  const pool = getScheduleDevicePoolForScope(scopeInfo, profile, schedule.floorId || schedule.startFloorId || floorSelect.value, {
    serviceType: schedule.serviceType || "",
    scopeSelectionMode: schedule.scopeSelectionMode
  });
  return getUniqueScheduleDevices(pool).filter((device) => isPassiveScopeDevice(device));
}

function completeScopeCycleSchedule(schedule) {
  if (!schedule?.rotationHistoryKey) return;
  const passiveDevices = getPassiveDevicesForScheduleCycle(schedule);
  if (!passiveDevices.length) return;
  const validIds = new Set(passiveDevices.map((device) => device.id));
  const cycle = getScopeCycleRecord(schedule.rotationHistoryKey, passiveDevices, {
    annualCycleId: schedule.annualCycleId || schedule.contractCycleId,
    excludeScheduleId: schedule.scheduleId
  });
  const plannedPassiveIds = uniqueValues(schedule.plannedDeviceIds || []).filter((id) => validIds.has(id));
  if (!plannedPassiveIds.length) return;
  const completedPassiveIds = getCompletedAnnualCoverageDeviceIds(schedule, plannedPassiveIds);
  const coveredBefore = new Set(cycle.coveredIds || []);
  const newCoveredIds = completedPassiveIds.filter((id) => !coveredBefore.has(id));
  const repeatIds = completedPassiveIds.filter((id) => coveredBefore.has(id));
  completedPassiveIds.forEach((id) => coveredBefore.add(id));
  const coveredIds = [...coveredBefore].filter((id) => validIds.has(id));
  const completionRecords = { ...(cycle.completionRecords || {}) };
  if (completedPassiveIds.length) {
    completionRecords[schedule.scheduleId] = {
      scheduleId: schedule.scheduleId,
      deviceIds: completedPassiveIds,
      newCoveredIds,
      repeatIds,
      recheckIds: uniqueValues(schedule.mandatoryRecheckDeviceIds || []).filter((id) => completedPassiveIds.includes(id)),
      completedAt: state.activeJob?.checkedOutAt || new Date().toISOString(),
      completedBy: getCurrentUserName()
    };
  } else {
    delete completionRecords[schedule.scheduleId];
  }
  const reservations = sanitizeScopeReservations(cycle.reservations || {}, validIds, schedule.scheduleId);
  const reservedIds = uniqueValues(Object.values(reservations).flatMap((reservation) => reservation.deviceIds || [])).filter((id) => validIds.has(id));
  const completedInspectionCount = Object.values(completionRecords).reduce((sum, record) => sum + (record.deviceIds || []).length, 0);
  const repeatInspectionCount = Object.values(completionRecords).reduce((sum, record) => sum + (record.repeatIds || []).length, 0);
  const faultRecheckRepeatCount = Object.values(completionRecords).reduce((sum, record) => sum + (record.recheckIds || []).length, 0);
  const now = new Date().toISOString();
  state.scopeCycle[schedule.rotationHistoryKey] = {
    schemaVersion: "scope-cycle-v2",
    annualCycleId: schedule.annualCycleId || schedule.contractCycleId || cycle.annualCycleId,
    contractCycleId: schedule.contractCycleId || schedule.annualCycleId || cycle.contractCycleId,
    eligibleIds: [...validIds],
    coveredIds,
    reservations,
    reservedIds,
    completionRecords,
    completedInspectionCount,
    repeatInspectionCount,
    faultRecheckRepeatCount,
    lastSelectedIds: uniqueValues(schedule.sampledDeviceIds || completedPassiveIds).filter((id) => completedPassiveIds.includes(id) && validIds.has(id)),
    cycleStartedAt: cycle.cycleStartedAt || schedule.createdAt || now,
    completedAt: coveredIds.length >= validIds.size ? cycle.completedAt || now : "",
    updatedAt: now
  };
  state.scopeHistory[schedule.rotationHistoryKey] = coveredIds;
  writeStoredJson("rmtScopeCycle", state.scopeCycle);
  writeStoredJson("tmFireScopeHistory", state.scopeHistory);
}

function getCompletedAnnualCoverageDeviceIds(schedule, plannedPassiveIds = []) {
  const scheduleId = getScheduleKey(schedule);
  return uniqueValues(plannedPassiveIds).filter((deviceId) => {
    const sharedRecord = scheduleId ? getSharedInspectionRecord(deviceId, schedule) : null;
    const localRecord = state.inspections?.[deviceId] || null;
    return isAnnualCoverageInspectionComplete(sharedRecord)
      || isAnnualCoverageInspectionCompleteForSchedule(localRecord, schedule);
  });
}

function isAnnualCoverageInspectionCompleteForSchedule(record = null, schedule = null) {
  if (!isAnnualCoverageInspectionComplete(record)) return false;
  const scheduleId = getScheduleKey(schedule);
  if (record?.scheduleId && scheduleId && record.scheduleId !== scheduleId) return false;
  return true;
}

function isAnnualCoverageInspectionComplete(record = null) {
  if (!record) return false;
  const status = normalizeScopeText(record.status || record.result || "");
  if (!status) return false;
  return status === "pass"
    || status === "passed"
    || status === "fail"
    || status === "failed"
    || status === "fault"
    || status === "n/a"
    || status === "na"
    || status === "done"
    || status === "completed";
}

function releaseScheduleScopeReservation(schedule) {
  if (!schedule?.rotationHistoryKey || schedule.status === "Completed") return;
  const passiveDevices = getPassiveDevicesForScheduleCycle(schedule);
  const validIds = new Set(passiveDevices.map((device) => device.id));
  const cycle = state.scopeCycle[schedule.rotationHistoryKey];
  if (!cycle) return;
  const reservations = sanitizeScopeReservations(cycle.reservations || {}, validIds, schedule.scheduleId);
  cycle.reservations = reservations;
  cycle.reservedIds = uniqueValues(Object.values(reservations).flatMap((reservation) => reservation.deviceIds || [])).filter((id) => validIds.has(id));
  cycle.updatedAt = new Date().toISOString();
  state.scopeCycle[schedule.rotationHistoryKey] = cycle;
  state.scopeHistory[schedule.rotationHistoryKey] = cycle.coveredIds || [];
  writeStoredJson("rmtScopeCycle", state.scopeCycle);
  writeStoredJson("tmFireScopeHistory", state.scopeHistory);
}

function persistSchedules() {
  writeStoredJson("rmtSchedules", stripSchedulePhotoDataForLocalStorage(state.schedules));
  invalidateRuntimeCaches();
}

function stripSchedulePhotoDataForLocalStorage(schedules = []) {
  return schedules.map((schedule) => ({
    ...schedule,
    photoProof: Object.fromEntries(Object.entries(schedule.photoProof || {}).map(([category, photos]) => [
      category,
      (Array.isArray(photos) ? photos : []).map((photo) => {
        const next = { ...photo };
        delete next.dataUrl;
        return next;
      })
    ]))
  }));
}

async function saveSchedulesToPc(showMessage = true) {
  try {
    const response = await fetch("/api/save-schedules", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ schedules: state.schedules })
    });
    const result = await response.json();
    if (!response.ok || !result.ok) throw new Error(result.error || "Unable to save schedules");
    if (showMessage) {
      document.querySelector("#syncState").textContent = `${state.schedules.length} schedule(s) saved to PC folder`;
    }
    return result;
  } catch (error) {
    console.warn("Unable to save schedules to PC folder", error);
    if (showMessage) {
      document.querySelector("#syncState").textContent = "Unable to save schedules to PC folder";
    }
    return { ok: false, error: error.message };
  }
}

