document.querySelector("#requestForm").addEventListener("submit", async (event) => {
  event.preventDefault();
  const role = getCurrentUserRole();
  const existingRequest = state.editingRequestId
    ? state.requests.find((request) => request.id === state.editingRequestId)
    : null;
  if (role === "Technician" && !state.pendingRequestPin && !existingRequest) {
    startMissingDevicePinMode();
    return;
  }
  const pin = state.pendingRequestPin || existingRequest || {};
  const profile = getCurrentSiteIdentity();
  const activeSchedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule();
  const now = new Date().toISOString();
  const activeSystem = getTechnicianFireSystemDefinition(state.activeTechSystemKey);
  const id = existingRequest?.id || `REQ-${Date.now()}`;
  const photoInput = document.querySelector("#requestPhoto");
  const photoEvidence = await readPhotoAttachmentFiles(photoInput, "missing-device", {
    jobId: state.activeJob?.jobId || "",
    scheduleId: activeSchedule?.scheduleId || state.activeJob?.scheduleId || "",
    clientId: activeSchedule?.clientId || pin.companyName || profile.companyName,
    clientName: pin.companyName || profile.companyName,
    siteId: activeSchedule?.siteId || pin.siteName || profile.siteName,
    siteName: pin.siteName || profile.siteName,
    floorId: pin.floorId || floorSelect.value,
    floorLabel: pin.floor || getFloorAsset(floorSelect.value).title,
    deviceId: document.querySelector("#requestLabel").value.trim(),
    locationLabel: document.querySelector("#requestLocation").value.trim()
  });
  if (role === "Technician" && !existingRequest && !photoEvidence.length) {
    document.querySelector("#syncState").textContent = "Missing device request needs at least one photo before sending to Admin.";
    photoInput?.focus();
    return;
  }
  const request = {
    ...(existingRequest || {}),
    id,
    requestId: existingRequest?.requestId || id,
    schemaVersion: "missing-device-request-v1",
    type: document.querySelector("#requestType").value,
    label: document.querySelector("#requestLabel").value.trim() || "Admin to assign",
    location: document.querySelector("#requestLocation").value.trim(),
    note: document.querySelector("#requestReason").value.trim(),
    reason: document.querySelector("#requestReason").value.trim(),
    photo: photoEvidence[0]?.name || existingRequest?.photo || "",
    photoEvidence: photoEvidence.length ? photoEvidence : existingRequest?.photoEvidence || [],
    floor: pin.floor || getFloorAsset(floorSelect.value).title,
    floorId: pin.floorId || floorSelect.value,
    companyName: pin.companyName || profile.companyName,
    siteName: pin.siteName || profile.siteName,
    jobId: state.activeJob?.jobId || "",
    scheduleId: activeSchedule?.scheduleId || state.activeJob?.scheduleId || "",
    system: activeSystem?.label || state.activeTechSystemKey || "",
    systemKey: state.activeTechSystemKey || "",
    xPercent: Number.isFinite(Number(pin.xPercent)) ? Number(pin.xPercent) : null,
    yPercent: Number.isFinite(Number(pin.yPercent)) ? Number(pin.yPercent) : null,
    pinText: formatRequestPin(pin),
    status: existingRequest?.status && !isRequestApproved(existingRequest) && !isRequestRejected(existingRequest)
      ? existingRequest.status
      : "PENDING_ADMIN_REVIEW",
    requestedBy: existingRequest?.requestedBy || getCurrentUserName(),
    requestedRole: existingRequest?.requestedRole || getCurrentUserRole(),
    technicianId: existingRequest?.technicianId || getCurrentUserId(),
    technicianName: existingRequest?.technicianName || getCurrentUserName(),
    requestedAt: existingRequest?.requestedAt || now,
    plannedDeviceCountAtRequest: activeSchedule?.plannedDeviceIds?.length || existingRequest?.plannedDeviceCountAtRequest || 0,
    scopeUnchanged: true
  };
  if (existingRequest && canEditMasterData()) {
    request.status = "PENDING_ADMIN_REVIEW";
    request.adjustedAt = now;
    request.adjustedBy = getCurrentUserName();
    request.reviewHistory = [
      ...(existingRequest.reviewHistory || []),
      { action: "ADJUSTED", by: getCurrentUserName(), at: now }
    ];
  }
  const saveResult = await saveMissingDeviceRequestRecord(request);
  if (saveResult.conflict) {
    document.querySelector("#syncState").textContent = "Request was updated elsewhere. Reloading Admin requests.";
    await loadSavedRequests({ render: true });
    return;
  }
  if (saveResult.offline) {
    request.syncStatus = "draft";
    request.unsynced = true;
    upsertMissingDeviceRequest(request);
  }
  event.target.reset();
  clearMissingDevicePinMode();
  closeRequestModal();
  renderRequests();
  renderMarkers();
  updateSummary();
  document.querySelector("#syncState").textContent = saveResult.offline
    ? "Missing point saved as local draft only. Send again when server is available."
    : `Missing point sent to Admin Review. Scope remains ${request.plannedDeviceCountAtRequest} planned item(s).`;
});

function stripRequestPhotoDataForStorage(request = {}) {
  const clean = { ...request };
  clean.photoEvidence = (Array.isArray(request.photoEvidence) ? request.photoEvidence : []).map((photo) => {
    return stripEvidenceBinaryData(photo);
  });
  return clean;
}

function persistMissingDeviceRequests() {
  writeStoredJson("tmFireRequests", state.requests.map(stripRequestPhotoDataForStorage));
}

function upsertMissingDeviceRequest(request) {
  const index = state.requests.findIndex((item) => item.id === request.id);
  if (index >= 0) {
    state.requests[index] = request;
  } else {
    state.requests.unshift(request);
  }
  persistMissingDeviceRequests();
}

async function loadSavedRequests(options = {}) {
  const { render = true } = options;
  loadStoredPlanningState();
  try {
    const response = await fetch("/api/missing-device-requests", { cache: "no-store" });
    if (!response.ok) return state.requests;
    const payload = await response.json();
    if (Array.isArray(payload.requests)) {
      state.requests = payload.requests;
      persistMissingDeviceRequests();
      if (render) {
        renderRequests();
        renderMarkers();
        updateSummary();
      }
    }
  } catch (error) {
    console.warn("Unable to load missing device requests", error);
  }
  return state.requests;
}

async function saveMissingDeviceRequestRecord(request) {
  const expectedRevision = Number(request.revision || 0);
  try {
    const response = await fetch("/api/missing-device-requests", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        expectedRevision,
        request
      })
    });
    const payload = await response.json();
    if (response.status === 409 && payload.conflict) {
      if (payload.current) upsertMissingDeviceRequest(payload.current);
      return { ok: false, conflict: true, payload };
    }
    if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to save missing device request");
    upsertMissingDeviceRequest(payload.request);
    return { ok: true, request: payload.request };
  } catch (error) {
    console.warn("Missing device request server unavailable", error);
    return { ok: false, offline: true, error };
  }
}

function getLinkedVerificationSideRecordId(scheduleId, linkedVerificationId, sideId) {
  return `linked-side::${scheduleId}::${linkedVerificationId}::${sideId}`;
}

function normalizeLinkedVerificationClientSide(side = {}) {
  const sideId = String(side.sideId || side.id || "").trim();
  return {
    ...side,
    sideId,
    sideName: String(side.sideName || side.name || sideId).trim(),
    location: String(side.location || side.sideName || side.name || sideId).trim(),
    assignedTechnicianId: String(side.assignedTechnicianId || side.technicianId || "").trim(),
    assignedTechnicianName: String(side.assignedTechnicianName || side.technicianName || "").trim(),
    evidenceRequired: Boolean(side.evidenceRequired)
  };
}

function normalizeLinkedVerificationClientDefinition(schedule, definition = {}) {
  const linkedVerificationId = String(definition.linkedVerificationId || definition.id || "").trim();
  const requiredSides = (Array.isArray(definition.requiredSides) ? definition.requiredSides : [])
    .map(normalizeLinkedVerificationClientSide)
    .filter((side) => side.sideId);
  return {
    ...definition,
    linkedVerificationId,
    scheduleId: definition.scheduleId || getScheduleKey(schedule),
    jobId: definition.jobId || schedule?.jobId || `JOB-${getScheduleKey(schedule)}`,
    clientId: definition.clientId || schedule?.clientId || schedule?.companyName || "",
    siteId: definition.siteId || schedule?.siteId || schedule?.siteName || "",
    companyName: definition.companyName || schedule?.companyName || "",
    siteName: definition.siteName || schedule?.siteName || "",
    systemId: String(definition.systemId || definition.system || "").trim(),
    verificationType: String(definition.verificationType || "GENERIC_LINKED_VERIFICATION").trim(),
    title: String(definition.title || LINKED_VERIFICATION_TYPES[definition.verificationType]?.label || "Linked Verification").trim(),
    requiredSides,
    requiredSideIds: requiredSides.map((side) => side.sideId),
    definitionVersion: String(definition.definitionVersion || definition.version || "1"),
    reconciliationMode: definition.reconciliationMode === "ADMIN_REVIEW" ? "ADMIN_REVIEW" : "MATCHING_RESULTS",
    evidenceRequired: Boolean(definition.evidenceRequired)
  };
}

function getScheduleTechnicianIdentity(schedule, deviceId, fallbackIndex = 0) {
  const assignment = schedule?.deviceAssignments?.[deviceId] || {};
  const technicians = Array.isArray(schedule?.technicians) ? schedule.technicians : [];
  const fallback = technicians[fallbackIndex] || technicians[0] || {};
  return {
    technicianId: String(assignment.technicianId || assignment.assignedTechnicianId || fallback.technicianId || fallback.id || "").trim(),
    technicianName: String(assignment.technicianName || assignment.assignedTechnicianName || fallback.technicianName || fallback.name || "").trim()
  };
}

function linkedVerificationTechniciansDiffer(first = {}, second = {}) {
  const firstId = String(first.technicianId || "").trim().toLowerCase();
  const secondId = String(second.technicianId || "").trim().toLowerCase();
  if (firstId && secondId) return firstId !== secondId;
  const firstName = String(first.technicianName || "").trim().toLowerCase();
  const secondName = String(second.technicianName || "").trim().toLowerCase();
  return Boolean(firstName && secondName && firstName !== secondName);
}

function getPumpLinkedVerificationDefinitions(schedule) {
  if (!schedule) return [];
  const devices = getScheduledAssignedDevices(schedule);
  const mfap = devices.find((device) => getCriticalSopTemplateIdForDevice(device) === "fire-alarm-tripping-sop");
  const pumps = devices.filter((device) => getCriticalSopTemplateIdForDevice(device) === "sprinkler-hydrant-pump-sop");
  if (!mfap || !pumps.length) return [];
  const mfapId = mfap.id || mfap.tag;
  const mfapTech = getScheduleTechnicianIdentity(schedule, mfapId, 1);
  const tests = [
    { key: "JOCKEY_MANUAL", label: "Jockey Pump Manual" },
    { key: "DUTY_MANUAL", label: "Duty Pump Manual" },
    { key: "STANDBY_MANUAL", label: "Standby Pump Manual" }
  ];
  return pumps.flatMap((pump) => {
    const pumpId = pump.id || pump.tag;
    const pumpTech = getScheduleTechnicianIdentity(schedule, pumpId, 0);
    if (!linkedVerificationTechniciansDiffer(pumpTech, mfapTech)) return [];
    return tests.map((test) => ({
      linkedVerificationId: `${getScheduleKey(schedule)}::PUMP_MFAP::${pumpId}::${test.key}`,
      verificationType: "FIRE_PUMP_INDICATION",
      pumpTestKey: test.key,
      pumpDeviceId: pumpId,
      title: `Linked Test - ${test.label}`,
      systemId: "pump-system",
      systemIds: ["pump-system", "fire-alarm"],
      definitionVersion: "pump-mfap-v1",
      reconciliationMode: "MATCHING_RESULTS",
      requiredSides: [
        {
          sideId: "PUMP_ROOM",
          sideName: "Pump Room",
          location: pump.location || pump.floor || "Pump Room",
          assignedTechnicianId: pumpTech.technicianId,
          assignedTechnicianName: pumpTech.technicianName
        },
        {
          sideId: "MFAP",
          sideName: "MFAP",
          location: mfap.location || mfap.floor || "Main Fire Alarm Panel",
          assignedTechnicianId: mfapTech.technicianId,
          assignedTechnicianName: mfapTech.technicianName
        }
      ]
    }));
  });
}

function getGasReleaseLinkedVerificationDefinitions(schedule) {
  if (!schedule) return [];
  const devices = getScheduledAssignedDevices(schedule);
  const mfap = devices.find((device) => getCriticalSopTemplateIdForDevice(device) === "fire-alarm-tripping-sop");
  const gasDevices = devices.filter((device) => getCriticalSopTemplateIdForDevice(device) === "gas-discharge-sop");
  if (!mfap || !gasDevices.length) return [];
  const mfapId = mfap.id || mfap.tag;
  const mfapTech = getScheduleTechnicianIdentity(schedule, mfapId, 1);
  return gasDevices.flatMap((device) => {
    const gasDeviceId = device.id || device.tag;
    const gasTech = getScheduleTechnicianIdentity(schedule, gasDeviceId, 0);
    if (!linkedVerificationTechniciansDiffer(gasTech, mfapTech)) return [];
    return [{
      linkedVerificationId: `${getScheduleKey(schedule)}::CO2_MFAP::${gasDeviceId}::INDICATION`,
      verificationType: "CO2_GAS_RELEASE_INDICATION",
      gasTestKey: "INDICATION",
      gasDeviceId,
      title: `Linked Test - ${gasDeviceId} Gas/CO2 Indication`,
      systemId: "gas-release",
      systemIds: ["gas-release", "fire-alarm"],
      definitionVersion: "co2-mfap-v1",
      reconciliationMode: "MATCHING_RESULTS",
      requiredSides: [
        {
          sideId: "SUPPRESSION_SYSTEM_LOCATION",
          sideName: "Suppression System Location",
          location: device.location || device.floor || "Suppression System Location",
          assignedTechnicianId: gasTech.technicianId,
          assignedTechnicianName: gasTech.technicianName
        },
        {
          sideId: "REMOTE_PANEL_OR_MFAP",
          sideName: "Remote Panel / MFAP",
          location: mfap.location || mfap.floor || "Main Fire Alarm Panel",
          assignedTechnicianId: mfapTech.technicianId,
          assignedTechnicianName: mfapTech.technicianName
        }
      ]
    }];
  });
}

function getScheduleLinkedVerificationDefinitions(schedule) {
  if (!schedule) return [];
  const store = getSharedStore(schedule);
  const sharedDefinitions = Object.values(store?.linkedVerificationDefinitions || {});
  const configured = Array.isArray(schedule.linkedVerifications) ? schedule.linkedVerifications : [];
  const definitions = [
    ...sharedDefinitions,
    ...configured,
    ...getPumpLinkedVerificationDefinitions(schedule),
    ...getGasReleaseLinkedVerificationDefinitions(schedule)
  ];
  const seen = new Set();
  return definitions
    .map((definition) => normalizeLinkedVerificationClientDefinition(schedule, definition))
    .filter((definition) => {
      if (!definition.linkedVerificationId || definition.requiredSides.length < 2 || seen.has(definition.linkedVerificationId)) return false;
      seen.add(definition.linkedVerificationId);
      return true;
    });
}

function linkedVerificationTechnicianMatches(side, userId = getCurrentUserId(), userName = getCurrentUserName()) {
  const assignedId = String(side?.assignedTechnicianId || "").trim().toLowerCase();
  const assignedName = String(side?.assignedTechnicianName || "").trim().toLowerCase();
  const actualId = String(userId || "").trim().toLowerCase();
  const actualName = String(userName || "").trim().toLowerCase();
  return Boolean((assignedId && assignedId === actualId) || (assignedName && assignedName === actualName));
}

function getLinkedVerificationDraftKey(scheduleId, linkedVerificationId, sideId) {
  return `${scheduleId}::${linkedVerificationId}::${sideId}`;
}

function persistLinkedVerificationDrafts() {
  writeStoredJson("rmtLinkedVerificationDrafts", state.linkedVerificationDrafts || {});
  renderDiagnosticsPanel();
}

function getLinkedVerificationDraft(scheduleId, linkedVerificationId, sideId) {
  return state.linkedVerificationDrafts?.[getLinkedVerificationDraftKey(scheduleId, linkedVerificationId, sideId)] || null;
}

function getLinkedVerificationSideRecord(schedule, linkedVerificationId, sideId) {
  const store = getSharedStore(schedule);
  const recordId = getLinkedVerificationSideRecordId(getScheduleKey(schedule), linkedVerificationId, sideId);
  return store?.linkedVerificationSideRecords?.[recordId]
    || Object.values(store?.linkedVerificationSideRecords || {}).find((record) => record.linkedVerificationId === linkedVerificationId && record.sideId === sideId)
    || null;
}

function linkedVerificationRecordsEquivalent(left, right) {
  if (!left || !right) return false;
  const evidenceSignature = (items) => JSON.stringify((Array.isArray(items) ? items : []).map((item) => ({
    evidenceId: item?.evidenceId || "",
    photoUrl: item?.photoUrl || item?.stampedPhotoUrl || item?.originalPhotoUrl || "",
    name: item?.name || ""
  })));
  return String(left.result || "").trim().toUpperCase() === String(right.result || "").trim().toUpperCase()
    && String(left.technicianId || "").trim().toLowerCase() === String(right.technicianId || "").trim().toLowerCase()
    && String(left.notes || "").trim() === String(right.notes || "").trim()
    && evidenceSignature(left.evidenceRefs) === evidenceSignature(right.evidenceRefs);
}

function reconcileLinkedVerificationConflictDrafts(scheduleId, store = {}) {
  let changed = false;
  Object.entries(state.linkedVerificationDrafts || {}).forEach(([key, draft]) => {
    if (draft.scheduleId !== scheduleId || draft.syncStatus !== "CONFLICT") return;
    const recordId = getLinkedVerificationSideRecordId(scheduleId, draft.linkedVerificationId, draft.sideId);
    const current = store.linkedVerificationSideRecords?.[recordId];
    if (!linkedVerificationRecordsEquivalent(draft, current)) return;
    delete state.linkedVerificationDrafts[key];
    changed = true;
  });
  if (changed) persistLinkedVerificationDrafts();
}

function getLinkedVerificationLiveState(schedule, linkedVerificationId) {
  const store = getSharedStore(schedule) || {};
  const recordId = `linked-live::${linkedVerificationId}`;
  return store.linkedVerificationLiveStates?.[recordId]
    || Object.values(store.linkedVerificationLiveStates || {}).find((record) => record.linkedVerificationId === linkedVerificationId)
    || null;
}

function getLiveCoordinationEvents(schedule = getActiveTechnicianMaintenanceSchedule(), options = {}) {
  const store = getSharedStore(schedule) || {};
  const events = new Map();
  Object.values(store.liveCoordinationEvents || {}).forEach((event) => {
    if (event?.eventId) events.set(event.eventId, event);
  });
  Object.values(store.linkedVerificationLiveStates || {}).forEach((record) => {
    if (!record?.linkedVerificationId) return;
    const eventId = `live-event::linked::${record.linkedVerificationId}`;
    if (events.has(eventId)) return;
    const definition = getScheduleLinkedVerificationDefinitions(schedule).find((item) => item.linkedVerificationId === record.linkedVerificationId);
    const sourceSide = definition?.requiredSides?.find((side) => side.sideId === record.sideId);
    const observerSide = definition?.requiredSides?.find((side) => side.sideId !== record.sideId);
    events.set(eventId, {
      eventId,
      scheduleId: getScheduleKey(schedule),
      sourceType: "LINKED_VERIFICATION",
      linkedVerificationId: record.linkedVerificationId,
      linkedInspectionId: record.linkedVerificationId,
      systemId: definition?.systemId || "",
      deviceId: definition?.pumpDeviceId || definition?.gasDeviceId || "",
      deviceLabel: record.equipmentLabel || definition?.title || "Linked test",
      equipmentLabel: record.equipmentLabel || definition?.title || "Linked test",
      location: sourceSide?.location || sourceSide?.sideName || "",
      sourceTechnicianId: record.technicianId || "",
      sourceTechnicianName: record.technicianName || "",
      observerTechnicianId: observerSide?.assignedTechnicianId || "",
      observerTechnicianName: observerSide?.assignedTechnicianName || "",
      testType: record.testMode || "MANUAL",
      currentState: record.currentState || "OBSERVATION_REQUIRED",
      priority: record.priority || "MEDIUM",
      status: record.status,
      startedAt: record.startedAt,
      lastUpdated: record.updatedAt,
      endedAt: record.endedAt,
      expiresAt: record.expiresAt,
      revision: record.revision || 0
    });
  });
  const priorityRank = { HIGH: 3, MEDIUM: 2, LOW: 1 };
  return [...events.values()]
    .filter((event) => !options.activeOnly || isLiveCoordinationEventActive(event))
    .filter((event) => !options.assignedToCurrent || liveEventObserverMatches(event))
    .sort((left, right) => (priorityRank[String(right.priority || "LOW").toUpperCase()] || 0) - (priorityRank[String(left.priority || "LOW").toUpperCase()] || 0)
      || Date.parse(right.lastUpdated || right.startedAt || 0) - Date.parse(left.lastUpdated || left.startedAt || 0));
}

function isLiveCoordinationEventActive(event) {
  if (String(event?.status || "").toUpperCase() !== "ACTIVE") return false;
  const expiresAt = Date.parse(event.expiresAt || "");
  return !Number.isFinite(expiresAt) || expiresAt > Date.now();
}

function liveEventObserverMatches(event, userId = getCurrentUserId(), userName = getCurrentUserName()) {
  const observerId = normalizeScopeText(event?.observerTechnicianId || "");
  const observerName = normalizeScopeText(event?.observerTechnicianName || "");
  if (!observerId && !observerName) return false;
  return observerId === normalizeScopeText(userId) || observerName === normalizeScopeText(userName);
}

async function postLiveCoordinationEvent(schedule, record, expectedRevision = 0) {
  const response = await fetch(`/api/jobs/${encodeURIComponent(getScheduleKey(schedule))}/live-events`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      expectedRevision,
      schedule: getScheduleSnapshotForSharedApi(schedule),
      record
    })
  });
  const payload = await response.json();
  if (response.status === 409 && payload.conflict) return { ok: false, conflict: true, payload };
  if (!response.ok || !payload.ok) return { ok: false, forbidden: response.status === 403, reason: payload.reason || payload.error || "Unable to update live event.", payload };
  const scheduleId = getScheduleKey(schedule);
  const cache = ensureSharedCacheForSchedule(schedule);
  const store = {
    ...cache.store,
    liveCoordinationEvents: {
      ...(cache.store?.liveCoordinationEvents || {}),
      [payload.record.eventId]: payload.record
    }
  };
  setSharedJobCache(scheduleId, { store, progress: cache.progress }, { online: true });
  return payload;
}

function getMfapObserverIdentity(schedule) {
  const mfap = getScheduledAssignedDevices(schedule).find((device) => getCriticalSopTemplateIdForDevice(device) === "fire-alarm-tripping-sop");
  if (!mfap) return null;
  const identity = getScheduleTechnicianIdentity(schedule, mfap.id || mfap.tag, 0);
  return { ...identity, device: mfap };
}

function isFireAlarmFieldDevice(device, schedule) {
  return Boolean(device && !isCriticalSopDevice(device) && getPrimaryTechnicianFireSystemDefinition(device, getTechnicianFireSystemDefinitions(), schedule)?.id === "fire-alarm");
}

function getFieldDeviceLiveEventId(schedule, device) {
  return `live-event::field::${getScheduleKey(schedule)}::${device?.id || device?.tag || ""}`;
}

async function updateFieldDeviceLiveEvent(schedule, device, status = "ACTIVE") {
  if (!schedule || !isFireAlarmFieldDevice(device, schedule)) return { ok: true, skipped: true };
  const observer = getMfapObserverIdentity(schedule);
  const source = getScheduleTechnicianIdentity(schedule, device.id || device.tag, 0);
  if (!observer || !linkedVerificationTechniciansDiffer(source, observer)) return { ok: true, skipped: true };
  const eventId = getFieldDeviceLiveEventId(schedule, device);
  const current = getLiveCoordinationEvents(schedule).find((event) => event.eventId === eventId);
  if (status === "ACTIVE" && isLiveCoordinationEventActive(current)) return { ok: true, skipped: true };
  if (status === "ACTIVE" && current?.status === "ENDED" && isChildInspectionComplete(device.id || device.tag, schedule)) return { ok: true, skipped: true };
  try {
    return await postLiveCoordinationEvent(schedule, {
      eventId,
      sourceType: "FIELD_DEVICE",
      systemId: "fire-alarm",
      deviceId: device.id || device.tag,
      deviceLabel: device.id || device.tag,
      equipmentLabel: device.type || "Fire alarm field device",
      location: displayDeviceLocation(device.location || device.floor || ""),
      floorId: device.floorId || "",
      floorLabel: device.floorTitle || device.floor || "",
      sourceTechnicianId: getCurrentUserId(),
      sourceTechnicianName: getCurrentUserName(),
      observerTechnicianId: observer.technicianId,
      observerTechnicianName: observer.technicianName,
      testType: device.type || "FIELD DEVICE",
      currentState: status === "ACTIVE" ? "OBSERVATION_REQUIRED" : "CLOSED",
      priority: "MEDIUM",
      status
    }, Number(current?.revision || 0));
  } catch (error) {
    return { ok: false, offline: true, reason: "Live coordination unavailable while offline.", error };
  }
}

function isLinkedVerificationLiveActive(record) {
  if (String(record?.status || "").toUpperCase() !== "ACTIVE") return false;
  const expiresAt = Date.parse(record.expiresAt || "");
  return !Number.isFinite(expiresAt) || expiresAt > Date.now();
}

function calculateClientLinkedVerificationState(schedule, definition) {
  const store = getSharedStore(schedule) || {};
  const indexed = state.linkedVerificationIndex.find((item) => item.linkedVerificationId === definition.linkedVerificationId && item.definition?.scheduleId === getScheduleKey(schedule));
  const sides = definition.requiredSides.map((side) => {
    const indexedSide = indexed?.sides?.find((item) => item.sideId === side.sideId);
    const record = getLinkedVerificationSideRecord(schedule, definition.linkedVerificationId, side.sideId) || indexedSide?.record || null;
    const draft = getLinkedVerificationDraft(getScheduleKey(schedule), definition.linkedVerificationId, side.sideId);
    return { ...side, record, draft };
  });
  const syncedComplete = sides.filter((side) => String(side.record?.status || "").toUpperCase() === "COMPLETE" && side.record?.result);
  const anyLocal = sides.some((side) => side.draft);
  const conflict = store.linkedVerificationConflicts?.[definition.linkedVerificationId];
  let status = "NOT_STARTED";
  const unresolvedLocalConflict = sides.some((side) => side.draft?.syncStatus === "CONFLICT" && !linkedVerificationRecordsEquivalent(side.draft, side.record));
  if (conflict?.unresolved || indexed?.status === "MISMATCH_REVIEW_REQUIRED" || unresolvedLocalConflict) {
    status = "MISMATCH_REVIEW_REQUIRED";
  } else if (syncedComplete.length === sides.length) {
    const results = new Set(syncedComplete.map((side) => String(side.record.result).trim().toUpperCase()));
    status = results.size > 1
      ? "MISMATCH_REVIEW_REQUIRED"
      : definition.reconciliationMode === "ADMIN_REVIEW" ? "READY_FOR_RECONCILIATION" : "VERIFIED";
  } else if (anyLocal) {
    status = "LOCAL_COMPLETE_AWAITING_SYNC";
  } else if (syncedComplete.length) {
    status = "AWAITING_COUNTERPART";
  }
  return {
    linkedVerificationId: definition.linkedVerificationId,
    status,
    definition,
    sides,
    completedSideCount: syncedComplete.length,
    requiredSideCount: sides.length
  };
}

function replaceLinkedVerificationIndexForSchedule(scheduleId, entries = []) {
  state.linkedVerificationIndex = [
    ...state.linkedVerificationIndex.filter((item) => item.definition?.scheduleId !== scheduleId && item.scheduleId !== scheduleId),
    ...entries
  ];
}

function getTechnicianSystemIcon(systemKey) {
  const paths = {
    "fire-alarm": '<rect x="4" y="3" width="16" height="18" rx="2"></rect><circle cx="9" cy="9" r="1.5"></circle><circle cx="15" cy="9" r="1.5"></circle><path d="M8 15h8M8 18h5"></path>',
    pump: '<path d="M3 12h4m10 0h4M7 8v8m10-8v8"></path><circle cx="12" cy="12" r="5"></circle><path d="M10 9.5 15 12l-5 2.5z"></path>',
    "hose-reel": '<circle cx="12" cy="12" r="8"></circle><circle cx="12" cy="12" r="4"></circle><path d="M12 8v8m-4-4h8M18 17l3 3"></path>',
    "pump-system": '<path d="M5 4v7h14V4M8 11v4m8-4v4M4 18h16"></path><path d="M9 7h6m-3-3v6"></path>',
    "gas-release": '<path d="M9 3h6v3l2 2v12H7V8l2-2z"></path><path d="M9 10h6m-3 3v4"></path>',
    "wet-chemical": '<path d="M8 3h8v4l2 3v10H6V10l2-3z"></path><path d="M9 14h6m-3-3v6"></path>',
    extinguisher: '<path d="M9 5h6l2 3v12H7V8z"></path><path d="M10 5V3h5m0 0 3 2m-1 2c3 0 4 2 4 4"></path>',
    "emergency-light": '<path d="M7 18h10M9 18v-5h6v5M8 10h8l-2-5h-4z"></path><path d="M4 5 2 3m18 2 2-2M3 11H1m22 0h-2"></path>',
    "keluar-sign": '<path d="M4 4h10v16H4zM14 12h7m-3-3 3 3-3 3"></path><circle cx="9" cy="8" r="1"></circle><path d="m9 9-2 4m2-4 3 3m-5 1-1 4m6-5 2 4"></path>',
    "fire-door": '<path d="M5 3h14v18H5zM8 6h8v15H8z"></path><circle cx="14" cy="13" r="1"></circle>',
    "other-configured": '<rect x="4" y="4" width="6" height="6" rx="1"></rect><rect x="14" y="4" width="6" height="6" rx="1"></rect><rect x="4" y="14" width="6" height="6" rx="1"></rect><rect x="14" y="14" width="6" height="6" rx="1"></rect>'
  };
  const body = paths[systemKey] || paths["other-configured"];
  return `<span class="tech-system-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${body}</svg></span>`;
}

function getTechnicianSystemStatus(summary = {}) {
  const total = Number(summary.total || 0);
  const done = Number(summary.done || 0);
  const fail = Number(summary.fail || 0);
  if (fail > 0) return { id: "fault", label: `${fail} fault${fail === 1 ? "" : "s"}` };
  if (total > 0 && done >= total) return { id: "complete", label: "Complete" };
  if (done > 0) return { id: "pending", label: "In progress" };
  return { id: "not-started", label: "Not started" };
}

async function loadLinkedVerificationIndex({ render = false } = {}) {
  try {
    const scheduleIds = state.schedules.map((schedule) => schedule.scheduleId).filter(Boolean);
    const query = scheduleIds.length ? `?scheduleIds=${encodeURIComponent(scheduleIds.join(","))}` : "";
    const response = await fetch(`/api/linked-verifications${query}`, { cache: "no-store" });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to load linked verifications");
    state.linkedVerificationIndex = Array.isArray(payload.linkedVerifications) ? payload.linkedVerifications : [];
    state.linkedVerificationIndexOnline = true;
  } catch (error) {
    state.linkedVerificationIndexOnline = false;
    console.warn("Linked verification index unavailable", error);
  }
  if (render) {
    renderAdminLinkedVerificationPanel();
    renderTechWorkPanel();
  }
  return state.linkedVerificationIndex;
}

function updateLinkedVerificationCache(schedule, payload) {
  const linkedState = payload?.linkedVerification;
  const record = payload?.record;
  if (!schedule || !linkedState || !record) return;
  const scheduleId = getScheduleKey(schedule);
  const cache = ensureSharedCacheForSchedule(schedule);
  const store = {
    ...cache.store,
    linkedVerificationDefinitions: {
      ...(cache.store?.linkedVerificationDefinitions || {}),
      [linkedState.definition.linkedVerificationId]: linkedState.definition
    },
    linkedVerificationSideRecords: {
      ...(cache.store?.linkedVerificationSideRecords || {}),
      [record.recordId]: record
    }
  };
  setSharedJobCache(scheduleId, { store, progress: cache.progress }, { online: true });
  replaceLinkedVerificationIndexForSchedule(scheduleId, [linkedState]);
}

function storeLinkedVerificationDraft(record) {
  const key = getLinkedVerificationDraftKey(record.scheduleId, record.linkedVerificationId, record.sideId);
  state.linkedVerificationDrafts = {
    ...(state.linkedVerificationDrafts || {}),
    [key]: {
      ...record,
      status: "COMPLETE",
      syncStatus: "LOCAL_COMPLETE_AWAITING_SYNC",
      savedLocallyAt: new Date().toISOString()
    }
  };
  persistLinkedVerificationDrafts();
  return state.linkedVerificationDrafts[key];
}

function removeLinkedVerificationDraft(record) {
  const key = getLinkedVerificationDraftKey(record.scheduleId, record.linkedVerificationId, record.sideId);
  if (!state.linkedVerificationDrafts?.[key]) return;
  delete state.linkedVerificationDrafts[key];
  persistLinkedVerificationDrafts();
}

async function postLinkedVerificationSide(schedule, record, expectedRevision) {
  const response = await fetch(`/api/jobs/${encodeURIComponent(getScheduleKey(schedule))}/linked-verification-sides`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      expectedRevision,
      schedule: getScheduleSnapshotForSharedApi(schedule),
      record
    })
  });
  const payload = await response.json();
  if (response.status === 409 && payload.conflict) return { ok: false, conflict: true, payload };
  if (!response.ok || !payload.ok) {
    return {
      ok: false,
      forbidden: response.status === 403,
      invalid: response.status === 400,
      reason: payload.reason || payload.error || "Unable to save linked verification",
      payload
    };
  }
  return payload;
}

async function postLinkedVerificationLiveState(schedule, record, expectedRevision) {
  const response = await fetch(`/api/jobs/${encodeURIComponent(getScheduleKey(schedule))}/linked-verification-live`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      expectedRevision,
      schedule: getScheduleSnapshotForSharedApi(schedule),
      record
    })
  });
  const payload = await response.json();
  if (response.status === 409 && payload.conflict) return { ok: false, conflict: true, payload };
  if (!response.ok || !payload.ok) {
    return {
      ok: false,
      forbidden: response.status === 403,
      reason: payload.reason || payload.error || "Unable to update the linked live test.",
      payload
    };
  }
  return payload;
}

async function saveLinkedVerificationLiveState(schedule, definition, side, status, options = {}) {
  if (!schedule || !definition || !side || !linkedVerificationTechnicianMatches(side)) {
    return { ok: false, forbidden: true, reason: "This live test side is assigned to another technician." };
  }
  const current = getLinkedVerificationLiveState(schedule, definition.linkedVerificationId);
  try {
    const payload = await postLinkedVerificationLiveState(schedule, {
      linkedVerificationId: definition.linkedVerificationId,
      sideId: side.sideId,
      technicianId: getCurrentUserId(),
      technicianName: getCurrentUserName(),
      equipmentLabel: definition.title,
      testMode: definition.pumpTestKey || definition.gasTestKey || "MANUAL",
      priority: options.priority || (definition.gasTestKey ? "LOW" : "MEDIUM"),
      currentState: options.currentState || (status === "ACTIVE" ? "OBSERVATION_REQUIRED" : "CLOSED"),
      status
    }, Number(current?.revision || 0));
    if (!payload.ok) return payload;
    const scheduleId = getScheduleKey(schedule);
    const cache = ensureSharedCacheForSchedule(schedule);
    const store = {
      ...cache.store,
      linkedVerificationLiveStates: {
        ...(cache.store?.linkedVerificationLiveStates || {}),
        [payload.record.recordId]: payload.record
      }
    };
    setSharedJobCache(scheduleId, { store, progress: cache.progress }, { online: true });
    return payload;
  } catch (error) {
    return { ok: false, offline: true, reason: "Connection is required to broadcast a live linked test.", error };
  }
}

async function saveLinkedVerificationSide(schedule, definition, side, values = {}) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId || !definition || !side) return { ok: false, invalid: true };
  if (!linkedVerificationTechnicianMatches(side)) {
    return { ok: false, forbidden: true, reason: "This side is assigned to another technician." };
  }
  const current = getLinkedVerificationSideRecord(schedule, definition.linkedVerificationId, side.sideId);
  const existingDraft = getLinkedVerificationDraft(scheduleId, definition.linkedVerificationId, side.sideId);
  const localCompletedAt = values.localCompletedAt || existingDraft?.localCompletedAt || new Date().toISOString();
  const record = {
    recordId: getLinkedVerificationSideRecordId(scheduleId, definition.linkedVerificationId, side.sideId),
    linkedVerificationId: definition.linkedVerificationId,
    jobId: definition.jobId || state.activeJob?.jobId || `JOB-${scheduleId}`,
    scheduleId,
    clientId: definition.clientId || schedule.companyName || "",
    siteId: definition.siteId || schedule.siteName || "",
    systemId: definition.systemId || "",
    verificationType: definition.verificationType,
    definitionVersion: definition.definitionVersion || "1",
    sideId: side.sideId,
    sideName: side.sideName,
    sideLocation: side.location,
    assignedTechnicianId: side.assignedTechnicianId,
    assignedTechnicianName: side.assignedTechnicianName,
    technicianId: getCurrentUserId(),
    technicianName: getCurrentUserName(),
    technicianRole: getCurrentUserRole(),
    result: values.result || existingDraft?.result || "",
    notes: values.notes || existingDraft?.notes || "",
    evidenceRefs: Array.isArray(values.evidenceRefs) && values.evidenceRefs.length ? values.evidenceRefs : (existingDraft?.evidenceRefs || current?.evidenceRefs || []),
    localCompletedAt,
    timestamp: localCompletedAt,
    submissionId: values.submissionId || existingDraft?.submissionId || `LV-SIDE-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
  };
  if (!record.result) return { ok: false, invalid: true, reason: "Select a result before saving." };
  if ((definition.evidenceRequired || side.evidenceRequired) && !record.evidenceRefs.length) {
    return { ok: false, invalid: true, reason: "Photo evidence is required for this side." };
  }
  const expectedRevision = Number(existingDraft?.expectedRevision ?? current?.revision ?? 0);
  try {
    const payload = await postLinkedVerificationSide(schedule, record, expectedRevision);
    if (!payload.ok && payload.conflict) {
      const draft = storeLinkedVerificationDraft({ ...record, expectedRevision, syncStatus: "CONFLICT", conflict: payload.payload });
      draft.syncStatus = "CONFLICT";
      persistLinkedVerificationDrafts();
      return { ok: false, conflict: true, draft, payload: payload.payload };
    }
    if (!payload.ok) return payload;
    removeLinkedVerificationDraft(record);
    updateLinkedVerificationCache(schedule, payload);
    return { ok: true, record: payload.record, linkedVerification: payload.linkedVerification, idempotent: Boolean(payload.idempotent) };
  } catch (error) {
    const draft = storeLinkedVerificationDraft({ ...record, expectedRevision });
    return { ok: true, offline: true, draft, error };
  }
}

async function syncLinkedVerificationDrafts() {
  const drafts = Object.values(state.linkedVerificationDrafts || {}).filter((draft) => draft.syncStatus !== "CONFLICT");
  if (!drafts.length) return { synced: 0, conflicts: 0, remaining: 0 };
  let synced = 0;
  let conflicts = 0;
  for (const draft of drafts) {
    const schedule = state.schedules.find((item) => item.scheduleId === draft.scheduleId);
    if (!schedule) continue;
    try {
      const payload = await postLinkedVerificationSide(schedule, draft, Number(draft.expectedRevision || 0));
      if (!payload.ok && payload.conflict) {
        draft.syncStatus = "CONFLICT";
        draft.conflict = payload.payload;
        conflicts += 1;
        persistLinkedVerificationDrafts();
        continue;
      }
      if (!payload.ok) {
        draft.syncStatus = payload.forbidden ? "ASSIGNMENT_REVIEW_REQUIRED" : "INVALID";
        draft.syncError = payload.reason || "Unable to sync linked verification draft.";
        persistLinkedVerificationDrafts();
        continue;
      }
      removeLinkedVerificationDraft(draft);
      updateLinkedVerificationCache(schedule, payload);
      synced += 1;
    } catch (error) {
      break;
    }
  }
  if (synced) await loadLinkedVerificationIndex();
  if (synced && state.activeCriticalSopId === "fire-alarm-tripping-sop" && !criticalSopPanel?.classList.contains("hidden")) {
    renderCriticalSopPreservingScroll();
  }
  return { synced, conflicts, remaining: Object.keys(state.linkedVerificationDrafts || {}).length };
}

function resetRequestForm() {
  const form = document.querySelector("#requestForm");
  form?.reset();
  const submitButton = form?.querySelector("button[type='submit']");
  if (submitButton) submitButton.textContent = "Send To Admin Review";
  state.editingRequestId = null;
}

function openRequestModal(requestId = "") {
  const request = requestId ? state.requests.find((item) => item.id === requestId) : null;
  if (getCurrentUserRole() === "Technician" && !state.pendingRequestPin && !request) {
    if (state.requestPinMode) {
      clearMissingDevicePinMode();
      document.querySelector("#syncState").textContent = "Missing point pin cancelled";
      return;
    }
    startMissingDevicePinMode();
    return;
  }
  resetRequestForm();
  if (request) {
    state.editingRequestId = request.id;
    state.pendingRequestPin = {
      floor: request.floor,
      floorId: request.floorId,
      companyName: request.companyName,
      siteName: request.siteName,
      xPercent: request.xPercent,
      yPercent: request.yPercent
    };
    setSelectValue(document.querySelector("#requestType"), request.type || "", request.type || "");
    document.querySelector("#requestLabel").value = request.label || "";
    document.querySelector("#requestLocation").value = request.location || "";
    document.querySelector("#requestReason").value = request.reason || request.note || "";
    const submitButton = document.querySelector("#requestForm")?.querySelector("button[type='submit']");
    if (submitButton) submitButton.textContent = "Save Request Adjustment";
  }
  updateRequestPinField();
  document.querySelector("#requestModal").classList.remove("hidden");
}

function closeRequestModal() {
  document.querySelector("#requestModal").classList.add("hidden");
  state.editingRequestId = null;
  if (getCurrentUserRole() === "Technician") {
    clearMissingDevicePinMode();
  }
}

function startMissingDevicePinMode() {
  state.requestPinMode = true;
  state.pendingRequestPin = null;
  workspace.classList.add("request-pin-mode");
  if (showRequestBtn) showRequestBtn.textContent = "Cancel Pin";
  if (techSuggestMissingBtn) techSuggestMissingBtn.textContent = "Cancel Missing Pin";
  renderMarkers();
  mapStage.scrollIntoView({ behavior: "smooth", block: "center" });
  document.querySelector("#syncState").textContent = "Tap the mimic where the missing device is located";
}

function captureMissingDevicePin(xPercent, yPercent) {
  const floor = getFloorAsset(floorSelect.value);
  const profile = getCurrentSiteIdentity();
  state.pendingRequestPin = {
    floor: floor.title,
    floorId: floorSelect.value,
    companyName: floor.companyName || profile.companyName,
    siteName: floor.siteName || profile.siteName,
    xPercent: roundPercent(xPercent),
    yPercent: roundPercent(yPercent)
  };
  state.requestPinMode = false;
  workspace.classList.remove("request-pin-mode");
  if (showRequestBtn) showRequestBtn.textContent = getCurrentUserRole() === "Technician" ? "Pin Missing Point" : "Suggest Device";
  if (techSuggestMissingBtn) techSuggestMissingBtn.textContent = "+ Missing Device / Suggest Pin";
  renderMarkers();
  updateRequestPinField();
  document.querySelector("#requestModal").classList.remove("hidden");
  document.querySelector("#syncState").textContent = "Missing point pinned. Fill details and send to admin.";
}

function clearMissingDevicePinMode() {
  state.requestPinMode = false;
  state.pendingRequestPin = null;
  workspace.classList.remove("request-pin-mode");
  if (showRequestBtn) showRequestBtn.textContent = getCurrentUserRole() === "Technician" ? "Pin Missing Point" : "Suggest Device";
  if (techSuggestMissingBtn) techSuggestMissingBtn.textContent = "+ Missing Device / Suggest Pin";
  updateRequestPinField();
  renderMarkers();
}

function updateRequestPinField() {
  const input = document.querySelector("#requestPinText");
  if (!input) return;
  input.value = formatRequestPin(state.pendingRequestPin);
}

function formatRequestPin(pin) {
  if (!pin || !Number.isFinite(Number(pin.xPercent)) || !Number.isFinite(Number(pin.yPercent))) {
    return "";
  }
  return `${pin.floor || "Selected floor"} @ X ${roundPercent(pin.xPercent)}%, Y ${roundPercent(pin.yPercent)}%`;
}

function isRequestRejected(request) {
  const status = String(request?.status || "").toUpperCase();
  return status.includes("REJECTED");
}

function getRequestStatusLabel(request) {
  const status = String(request?.status || "PENDING_ADMIN_REVIEW").toUpperCase();
  if (status.includes("APPROVED")) return "Approved to Master";
  if (status.includes("REJECTED")) return "Rejected";
  if (request?.unsynced) return "Local Draft";
  return "Pending Admin Review";
}

function getRequestPhotoLabel(request) {
  const count = Array.isArray(request?.photoEvidence) ? request.photoEvidence.length : 0;
  if (count) return `${count} photo(s) attached`;
  return request?.photo || "No photo attached";
}

function renderReportReviews() {
  if (!reportReviewList) return;
  const reportFilter = state.adminReportFilter || "awaiting";
  const reviewSchedules = state.schedules.filter((schedule) => {
    const submissionStatus = String(getScheduleReportSubmission(schedule)?.status || schedule.reportStatus || "").toUpperCase();
    const isSent = submissionStatus.includes("SENT");
    if (reportFilter === "awaiting") return isScheduleAwaitingAdminReview(schedule);
    if (reportFilter === "returned") return isScheduleReturnedForCorrection(schedule);
    if (reportFilter === "approved") return isScheduleAdminApproved(schedule) && !isSent;
    if (reportFilter === "sent") return isSent;
    return isScheduleAwaitingAdminReview(schedule)
      || isScheduleReturnedForCorrection(schedule)
      || isScheduleAdminApproved(schedule)
      || isSent;
  });
  if (!reviewSchedules.length) {
    reportReviewList.innerHTML = `<p class="hint">No reports match this review status.</p>`;
    return;
  }

  reportReviewList.innerHTML = reviewSchedules.map((schedule) => {
    const summary = getLightTechnicianScheduleSummary(schedule);
    const submission = getScheduleReportSubmission(schedule) || {};
    const status = getTechnicianScheduleStatus(schedule);
    const pendingRequests = getPendingMissingRequestsForSchedule(schedule);
    const canAdminReview = canEditMasterData() && isScheduleAwaitingAdminReview(schedule);
    return `
      <article class="request-card report-review-card">
        <div>
          <strong>${escapeHtml(schedule.companyName || "-")} / ${escapeHtml(schedule.siteName || "-")}</strong>
          <p><b>Job:</b> ${escapeHtml(schedule.scheduleId || "-")} | <b>Status:</b> ${escapeHtml(status)}</p>
          <p><b>Submitted by:</b> ${escapeHtml(submission.submittedBy || schedule.reportSubmittedBy || "-")} ${submission.submittedAt ? `on ${escapeHtml(formatShortDateTime(submission.submittedAt))}` : ""}</p>
          <p><b>Progress:</b> ${summary.done}/${summary.total} completed | PASS ${summary.pass} | FAULT ${summary.fail} | Pending ${summary.pending + summary.partial + Number(summary.blocked || 0)}</p>
          <p><b>Pending missing-device suggestions:</b> ${pendingRequests.length}</p>
        </div>
        <div class="request-actions">
          <span class="status-pill">${escapeHtml(status)}</span>
          <button type="button" class="mini-button secondary open-report-btn" data-schedule-id="${escapeHtml(schedule.scheduleId)}">Open Report</button>
          ${canAdminReview ? `
            <button type="button" class="mini-button approve-report-btn" data-schedule-id="${escapeHtml(schedule.scheduleId)}">Approve</button>
            <button type="button" class="mini-button danger return-report-btn" data-schedule-id="${escapeHtml(schedule.scheduleId)}">Return for Correction</button>
          ` : ""}
        </div>
      </article>
    `;
  }).join("");

  reportReviewList.querySelectorAll(".approve-report-btn").forEach((button) => {
    button.addEventListener("click", () => approveSubmittedReport(button.dataset.scheduleId));
  });
  reportReviewList.querySelectorAll(".open-report-btn").forEach((button) => {
    button.addEventListener("click", () => showReport(button.dataset.scheduleId));
  });
  reportReviewList.querySelectorAll(".return-report-btn").forEach((button) => {
    button.addEventListener("click", () => returnSubmittedReportForCorrection(button.dataset.scheduleId));
  });
}

async function approveSubmittedReport(scheduleId) {
  if (!canEditMasterData()) return;
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (!schedule) return;
  const latest = await requestSharedJobState(schedule, { migrate: false });
  if (!latest?.online) {
    document.querySelector("#syncState").textContent = "Approval blocked: authoritative shared job records are unavailable.";
    return;
  }
  const reportSnapshot = buildReportSnapshot(schedule, { forceLive: true, snapshotStatus: "APPROVED_SNAPSHOT" });
  if (reportSnapshot.dataIntegrity.unsyncedCount > 0) {
    document.querySelector("#syncState").textContent = `Approval blocked: ${reportSnapshot.dataIntegrity.unsyncedCount} unsynced report record(s) remain.`;
    return;
  }
  const approvedAt = new Date().toISOString();
  reportSnapshot.status = "APPROVED_BY_ADMIN";
  reportSnapshot.approvedAt = approvedAt;
  reportSnapshot.review = {
    ...reportSnapshot.review,
    status: "APPROVED_BY_ADMIN",
    reviewedBy: getCurrentUserName(),
    reviewedAt: approvedAt,
    reviewNote: "Admin approved technician submission."
  };
  const result = await submitReportReviewAction(schedule, "APPROVED_BY_ADMIN", "Admin approved technician submission.", { reportSnapshot });
  if (!result.ok) {
    document.querySelector("#syncState").textContent = result.conflict
      ? "Report review changed elsewhere. Reload before approving."
      : "Unable to approve report review.";
    return;
  }
  schedule.status = "Completed";
  schedule.reportSubmissionStatus = "APPROVED_BY_ADMIN";
  schedule.reportSubmission = result.submission;
  schedule.reviewedAt = result.submission?.reviewedAt || new Date().toISOString();
  schedule.reviewedBy = getCurrentUserName();
  schedule.completedAt = schedule.reviewedAt;
  schedule.completedBy = getCurrentUserName();
  if (state.activeJob?.scheduleId === schedule.scheduleId) {
    state.activeJob.status = "Completed";
    state.activeJob.reportSubmission = result.submission;
    persistActiveJob();
  }
  completeScopeCycleSchedule(schedule);
  persistSchedules();
  await saveSchedulesToPc(false);
  renderRequests();
  renderSchedulePanel();
  renderTechWorkPanel();
  document.querySelector("#syncState").textContent = `${schedule.scheduleId} approved by Admin.`;
}

async function returnSubmittedReportForCorrection(scheduleId) {
  if (!canEditMasterData()) return;
  const schedule = state.schedules.find((item) => item.scheduleId === scheduleId);
  if (!schedule) return;
  const result = await submitReportReviewAction(schedule, "RETURNED_FOR_CORRECTION", "Admin returned this job for correction.");
  if (!result.ok) {
    document.querySelector("#syncState").textContent = result.conflict
      ? "Report review changed elsewhere. Reload before returning."
      : "Unable to return report for correction.";
    return;
  }
  schedule.status = "RETURNED_FOR_CORRECTION";
  schedule.reportSubmissionStatus = "RETURNED_FOR_CORRECTION";
  schedule.reportSubmission = result.submission;
  schedule.returnedForCorrectionAt = result.submission?.reviewedAt || new Date().toISOString();
  schedule.returnedForCorrectionBy = getCurrentUserName();
  if (state.activeJob?.scheduleId === schedule.scheduleId) {
    state.activeJob.status = "RETURNED_FOR_CORRECTION";
    state.activeJob.reportSubmission = result.submission;
    persistActiveJob();
  }
  persistSchedules();
  await saveSchedulesToPc(false);
  renderRequests();
  renderSchedulePanel();
  renderTechWorkPanel();
  document.querySelector("#syncState").textContent = `${schedule.scheduleId} returned for correction. Technician editing is enabled again.`;
}

function renderRequests() {
  const requestList = document.querySelector("#requestList");
  renderReportReviews();
  if (!requestList) return;
  if (!state.requests.length) {
    requestList.innerHTML = `<p class="hint">No missing device requests yet.</p>`;
    renderFrontDeskPanel();
    updateAdminReportWorkspaceFilter();
    return;
  }

  requestList.innerHTML = state.requests.map((request) => `
    <article class="request-card ${escapeHtml(String(request.status || "pending").toLowerCase())}">
      <div>
        <strong>${escapeHtml(request.label)} - ${escapeHtml(request.type)}</strong>
        <p>${escapeHtml(request.companyName || "-")} / ${escapeHtml(request.siteName || "-")} | ${escapeHtml(request.floor)}</p>
        ${request.scheduleId ? `<p><b>Job:</b> ${escapeHtml(request.scheduleId)} | <b>System:</b> ${escapeHtml(request.system || request.systemKey || "-")}</p>` : ""}
        <p><b>Location:</b> ${escapeHtml(request.location)}</p>
        ${request.pinText ? `<p><b>Pin:</b> ${escapeHtml(request.pinText)}</p>` : ""}
        <p><b>Reason:</b> ${escapeHtml(request.reason)}</p>
        <p><b>Photo:</b> ${escapeHtml(getRequestPhotoLabel(request))}</p>
        <p><b>Requested by:</b> ${escapeHtml(request.requestedBy || "-")} ${request.requestedAt ? `on ${escapeHtml(formatShortDateTime(request.requestedAt))}` : ""}</p>
        ${request.approvedTag ? `<p><b>Approved tag:</b> ${escapeHtml(request.approvedTag)}</p>` : ""}
      </div>
      <div class="request-actions">
        <span class="status-pill">${escapeHtml(getRequestStatusLabel(request))}</span>
        ${!isRequestApproved(request) && !isRequestRejected(request) && !isExtinguisherAdminRequest(request) ? `
          <button type="button" class="mini-button adjust-request-btn" data-request-id="${escapeHtml(request.id)}">Adjust</button>
          <button type="button" class="mini-button approve-request-btn" data-request-id="${escapeHtml(request.id)}">Approve To Master</button>
          <button type="button" class="mini-button danger reject-request-btn" data-request-id="${escapeHtml(request.id)}">Reject</button>
        ` : ""}
      </div>
    </article>
  `).join("");

  requestList.querySelectorAll(".adjust-request-btn").forEach((button) => {
    button.addEventListener("click", () => openRequestModal(button.dataset.requestId));
  });
  requestList.querySelectorAll(".approve-request-btn").forEach((button) => {
    button.addEventListener("click", () => approveMissingDeviceRequest(button.dataset.requestId));
  });
  requestList.querySelectorAll(".reject-request-btn").forEach((button) => {
    button.addEventListener("click", () => rejectMissingDeviceRequest(button.dataset.requestId));
  });
  renderFrontDeskPanel();
  updateAdminReportWorkspaceFilter();
}

async function approveMissingDeviceRequest(requestId) {
  if (!canEditMasterData()) {
    document.querySelector("#syncState").textContent = "Only admin can approve missing device requests";
    return;
  }
  const request = state.requests.find((item) => item.id === requestId);
  if (!request || isRequestApproved(request) || isRequestRejected(request)) return;

  if (request.floorId && floorExists(request.floorId)) {
    renderFloorOptions(request.floorId, {
      companyName: request.companyName,
      siteName: request.siteName
    });
    refreshSelectedFloorView();
  }

  const tag = normalizeApprovedRequestTag(request);
  addSetupDevice({
    tag,
    type: request.type || "Other",
    floor: request.floor || getFloorAsset(floorSelect.value).title,
    location: request.location || "Admin approved missing point",
    status: "Pending Review",
    remarks: `Approved from ${request.id}. ${request.reason || ""}`.trim(),
    xPercent: Number(request.xPercent),
    yPercent: Number(request.yPercent),
    companyName: request.companyName || document.querySelector("#mimicCompany").value.trim(),
    siteName: request.siteName || document.querySelector("#mimicSite").value.trim(),
    capturedBy: getCurrentUserName(),
    capturedAt: new Date().toISOString()
  });

  request.status = "APPROVED_TO_MASTER";
  request.approvedTag = tag;
  request.approvedAt = new Date().toISOString();
  request.approvedBy = getCurrentUserName();
  request.reviewHistory = [
    ...(request.reviewHistory || []),
    { action: "APPROVED_TO_MASTER", by: getCurrentUserName(), at: request.approvedAt, approvedTag: tag }
  ];
  await saveMissingDeviceRequestRecord(request);
  renderRequests();
  renderMarkers();
  updateSummary();
  document.querySelector("#syncState").textContent = `${tag} added to device master for admin review`;
}

async function rejectMissingDeviceRequest(requestId) {
  if (!canEditMasterData()) {
    document.querySelector("#syncState").textContent = "Only admin can reject missing device requests";
    return;
  }
  const request = state.requests.find((item) => item.id === requestId);
  if (!request || isRequestApproved(request) || isRequestRejected(request)) return;
  const rejectedAt = new Date().toISOString();
  request.status = "REJECTED";
  request.rejectedAt = rejectedAt;
  request.rejectedBy = getCurrentUserName();
  request.reviewHistory = [
    ...(request.reviewHistory || []),
    { action: "REJECTED", by: getCurrentUserName(), at: rejectedAt }
  ];
  await saveMissingDeviceRequestRecord(request);
  renderRequests();
  renderMarkers();
  updateSummary();
  document.querySelector("#syncState").textContent = `${request.label || request.id} rejected. Request history retained.`;
}

function normalizeApprovedRequestTag(request) {
  const label = String(request.label || "").trim();
  if (label && label.toLowerCase() !== "admin to assign") return label;
  const floorCode = getFloorCode(request.floorId || floorSelect.value);
  const short = getShortCode({ type: request.type, tag: "" }) || "REQ";
  return `${floorCode}.${short}.${String(Date.now()).slice(-4)}`;
}

function addSetupDevice(device) {
  const x = getSetupDeviceX(device);
  const y = getSetupDeviceY(device);
  const draft = {
    tag: device.tag || `UNKNOWN-${Date.now()}`,
    type: device.type || "Other",
    floor: device.floor || getFloorAsset(floorSelect.value).title,
    floorId: device.floorId || "",
    location: cleanDeviceLocation(device.location),
    brandModel: device.brandModel || "",
    serialBarcode: device.serialBarcode || "",
    expiryDate: device.expiryDate || "",
    status: device.status || "Pending Review",
    remarks: device.remarks || "",
    xPercent: Number.isFinite(x) ? roundPercent(x) : null,
    yPercent: Number.isFinite(y) ? roundPercent(y) : null,
    companyName: device.companyName || document.querySelector("#mimicCompany").value.trim(),
    siteName: device.siteName || document.querySelector("#mimicSite").value.trim(),
    capturedBy: device.capturedBy || "Demo Inspector",
    capturedAt: device.capturedAt || new Date().toISOString()
  };
  normalizeSetupDevicePinFields(draft);

  const draftKey = getSetupDeviceIdentityKey(draft);
  const existingIndex = state.setupDevices.findIndex((item) => getSetupDeviceIdentityKey(item) === draftKey);
  if (existingIndex >= 0) {
    state.setupDevices[existingIndex] = draft;
  } else {
    state.setupDevices.unshift(draft);
  }

  removeSupersededStandardTags();
  writeStoredJson("tmFireSetupDevices", state.setupDevices);
  renderSetupDevices();
  renderMarkers();
  updateSummary();
  updateTagPaletteHint();
  saveDeviceMasterToPc();
}

function removeSupersededStandardTags() {
  const editedPins = new Set(
    state.setupDevices
      .filter((device) => !isStandardPageTag(device.tag))
      .map((device) => getDuplicatePinKey(device))
      .filter(Boolean)
  );
  const cleaned = state.setupDevices.filter((device) => {
    return !isStandardPageTag(device.tag) || !editedPins.has(getDuplicatePinKey(device));
  });
  if (cleaned.length !== state.setupDevices.length) {
    state.setupDevices = cleaned;
    writeStoredJson("tmFireSetupDevices", state.setupDevices);
  }
}

function normalizeSetupDevices() {
  let changed = false;
  state.setupDevices = state.setupDevices.map((device) => {
    const next = { ...device };
    changed = normalizeSetupDevicePinFields(next) || changed;
    if (next.companyName === "WETEX" && next.siteName === "WETEX" && next.floor === "WETEX - Floor 02" && /^G\./i.test(next.tag || "")) {
      next.tag = String(next.tag).replace(/^G\./i, "W2.");
      changed = true;
    }
    if (isAutoPinLocation(next.location)) {
      next.location = "";
      changed = true;
    }
    return next;
  });
  changed = dedupeSetupDevices() || changed;
  removeSupersededStandardTags();
  if (changed) {
    writeStoredJson("tmFireSetupDevices", state.setupDevices);
  }
}

function normalizeSetupDevicePinFields(device) {
  let changed = false;
  const x = getFirstFiniteNumber(device.xPercent, device.pinX, device.x, device.mapX, device.map_x);
  const y = getFirstFiniteNumber(device.yPercent, device.pinY, device.y, device.mapY, device.map_y);
  if (Number.isFinite(x) && Number(device.xPercent) !== roundPercent(x)) {
    device.xPercent = roundPercent(x);
    changed = true;
  }
  if (Number.isFinite(y) && Number(device.yPercent) !== roundPercent(y)) {
    device.yPercent = roundPercent(y);
    changed = true;
  }
  if (!device.floor && device.floorTitle) {
    device.floor = device.floorTitle;
    changed = true;
  }
  const inferredFloorId = inferSetupDeviceFloorId(device);
  if (!device.floorId && inferredFloorId) {
    device.floorId = inferredFloorId;
    changed = true;
  }
  return changed;
}

function getFirstFiniteNumber(...values) {
  for (const value of values) {
    const number = Number(value);
    if (Number.isFinite(number)) return number;
  }
  return NaN;
}

function getSetupDeviceX(device) {
  return getFirstFiniteNumber(device?.xPercent, device?.pinX, device?.x, device?.mapX, device?.map_x);
}

function getSetupDeviceY(device) {
  return getFirstFiniteNumber(device?.yPercent, device?.pinY, device?.y, device?.mapY, device?.map_y);
}

function inferSetupDeviceFloorId(device) {
  if (device?.floorId && floorExists(device.floorId)) return device.floorId;
  const companyName = normalizeScopeText(device?.companyName);
  const siteName = normalizeScopeText(device?.siteName);
  const deviceFloor = normalizeFloorForCompare(device?.floor || device?.floorTitle || device?.floorName || device?.floorCode, companyName, siteName);
  if (!deviceFloor) return "";
  return [...state.mimicFloors, ...state.libraryFloors]
    .find((floor) => {
      if (companyName && normalizeScopeText(floor.companyName) && normalizeScopeText(floor.companyName) !== companyName) return false;
      if (siteName && normalizeScopeText(floor.siteName) && normalizeScopeText(floor.siteName) !== siteName) return false;
      const candidates = uniqueValues([
        floor.id,
        floor.floorId,
        floor.title,
        floor.floorName,
        floor.floorCode
      ]).map((value) => normalizeFloorForCompare(value, companyName, siteName)).filter(Boolean);
      return candidates.some((candidate) => candidate === deviceFloor);
    })?.floorId || "";
}

function dedupeSetupDevices() {
  const seen = new Map();
  const deduped = [];
  state.setupDevices.forEach((device) => {
    const key = getSetupDeviceIdentityKey(device);
    if (!key) {
      deduped.push(device);
      return;
    }
    const existingIndex = seen.get(key);
    if (existingIndex === undefined) {
      seen.set(key, deduped.length);
      deduped.push(device);
      return;
    }
    deduped[existingIndex] = preferSetupDeviceRecord(deduped[existingIndex], device);
  });

  if (deduped.length === state.setupDevices.length) return false;
  state.setupDevices = deduped;
  return true;
}

function getSetupDeviceIdentityKey(device) {
  const tag = normalizeScopeText(device?.tag);
  if (!tag) return "";
  return [
    device.companyName,
    device.siteName,
    device.floor,
    tag
  ].map(normalizeScopeText).join("|");
}

function preferSetupDeviceRecord(current, incoming) {
  const currentScore = getSetupDeviceCompletenessScore(current);
  const incomingScore = getSetupDeviceCompletenessScore(incoming);
  if (incomingScore > currentScore) return incoming;
  if (incomingScore < currentScore) return current;
  const currentTime = new Date(current?.capturedAt || 0).getTime() || 0;
  const incomingTime = new Date(incoming?.capturedAt || 0).getTime() || 0;
  return incomingTime >= currentTime ? incoming : current;
}

function getSetupDeviceCompletenessScore(device) {
  return [
    device?.status === "Confirmed",
    Boolean(cleanDeviceLocation(device?.location)),
    Boolean(device?.brandModel),
    Boolean(device?.serialBarcode),
    Boolean(device?.expiryDate),
    Number.isFinite(getSetupDeviceX(device)) && Number.isFinite(getSetupDeviceY(device)),
    Boolean(device?.remarks)
  ].reduce((score, value) => score + (value ? 1 : 0), 0);
}

function isStandardPageTag(tag) {
  return /^P\d+\./i.test(String(tag || ""));
}

function getDuplicatePinKey(device) {
  const x = getSetupDeviceX(device);
  const y = getSetupDeviceY(device);
  if (!device || !Number.isFinite(x) || !Number.isFinite(y)) {
    return "";
  }
  return [
    device.companyName || "",
    device.siteName || "",
    device.floor || "",
    device.type || "",
    Number(x).toFixed(1),
    Number(y).toFixed(1)
  ].join("|").toLowerCase();
}

function renderSetupDevices() {
  const setupRows = document.querySelector("#setupDeviceRows");
  if (!setupRows) return;
  const visibleDevices = getVisibleSetupDevices();

  if (!visibleDevices.length) {
    setupRows.innerHTML = `
      <tr>
        <td colspan="8">No devices captured for this company/site yet. Add one manually, import CSV, or pin ready tags on the selected mimic.</td>
      </tr>
    `;
    updateSummary();
    return;
  }

  setupRows.innerHTML = visibleDevices.map((device) => `
    <tr data-setup-tag="${escapeHtml(device.tag)}">
      <td><strong>${escapeHtml(device.tag)}</strong></td>
      <td>${escapeHtml(device.type)}</td>
        <td>${escapeHtml(device.floor)}</td>
        <td>${escapeHtml(displayDeviceLocation(device.location))}</td>
        <td>${escapeHtml(device.serialBarcode || device.brandModel || "-")}</td>
        <td>${formatPin(device)}</td>
        <td><span class="status-pill">${escapeHtml(device.status)}</span></td>
        <td>
          <div class="row-actions">
            <button type="button" class="mini-button edit-setup-btn" data-tag="${escapeHtml(device.tag)}">Edit</button>
            <button type="button" class="mini-button danger delete-setup-btn" data-tag="${escapeHtml(device.tag)}">Delete</button>
          </div>
        </td>
      </tr>
  `).join("");

  setupRows.querySelectorAll(".edit-setup-btn").forEach((button) => {
    button.addEventListener("click", () => {
      const device = state.setupDevices.find((item) => item.tag === button.dataset.tag);
      if (device) {
        state.selectedSetupTag = device.tag;
        renderMarkers();
        updateTagPaletteHint();
        fillSetupFormFromDevice(device);
      }
    });
  });
  setupRows.querySelectorAll(".delete-setup-btn").forEach((button) => {
    button.addEventListener("click", () => deleteSetupDevice(button.dataset.tag));
  });
}

function getVisibleSetupDevices() {
  const companyName = document.querySelector("#mimicCompany")?.value.trim().toLowerCase() || "";
  const siteName = document.querySelector("#mimicSite")?.value.trim().toLowerCase() || "";
  return state.setupDevices.filter((device) => {
    return String(device.companyName || "").trim().toLowerCase() === companyName
      && String(device.siteName || "").trim().toLowerCase() === siteName;
  });
}

function deleteSetupDevice(tag) {
  const device = state.setupDevices.find((item) => item.tag === tag);
  if (!device) return;

  const confirmed = window.confirm(`Delete unused pin ${tag}? This will remove it from the mimic and device master draft.`);
  if (!confirmed) return;

  state.setupDevices = state.setupDevices.filter((item) => item.tag !== tag);
  state.pinHistory = state.pinHistory.filter((item) => item !== tag);
  if (state.selectedSetupTag === tag) {
    state.selectedSetupTag = null;
  }
  writeStoredJson("tmFireSetupDevices", state.setupDevices);
  writeStoredJson("tmFirePinHistory", state.pinHistory);

  if (document.querySelector("#setupTag").value === tag) {
    document.querySelector("#setupForm").reset();
    delete document.querySelector("#setupTag").dataset.xPercent;
    delete document.querySelector("#setupTag").dataset.yPercent;
    document.querySelector("#setupPin").value = "";
    document.querySelector("#setupFloor").value = getFloorAsset(floorSelect.value).title;
  }

  renderSetupDevices();
  renderMarkers();
  updateSummary();
  updateTagPaletteHint();
  saveDeviceMasterToPc();
  document.querySelector("#syncState").textContent = `${tag} deleted`;
}

function editSelectedPin() {
  const tag = state.selectedSetupTag || state.pinHistory[state.pinHistory.length - 1];
  if (!tag) {
    document.querySelector("#syncState").textContent = "Select a draft pin first";
    return;
  }

  const device = state.setupDevices.find((item) => item.tag === tag);
  if (!device) {
    document.querySelector("#syncState").textContent = "Selected pin not found";
    state.selectedSetupTag = null;
    renderMarkers();
    updateTagPaletteHint();
    return;
  }

  state.selectedSetupTag = device.tag;
  renderMarkers();
  updateTagPaletteHint();
  fillSetupFormFromDevice(device);
  document.querySelector("#syncState").textContent = `${device.tag} ready to edit`;
}

function deleteSelectedPin() {
  if (!state.selectedSetupTag) {
    document.querySelector("#syncState").textContent = "Select a draft pin first";
    return;
  }
  deleteSetupDevice(state.selectedSetupTag);
}

async function importSetupCsv(event) {
  const file = event.target.files[0];
  if (!file) return;

  const text = await file.text();
  const rows = parseCsv(text);
  const imported = rows.map((row) => ({
    tag: row.device_tag || row.tag,
    type: row.device_type || row.type,
    floor: row.floor_area || row.floor,
    location: row.location,
    brandModel: row.brand_model || row.brand || row.model,
    serialBarcode: row.serial_barcode || row.serial || row.barcode,
    expiryDate: row.expiry_date || row.expiry,
    status: row.status || "Pending Review",
    remarks: row.remarks || row.remark,
    xPercent: Number(row.x_percent || row.x || row.map_x),
    yPercent: Number(row.y_percent || row.y || row.map_y),
    companyName: row.company_name || row.company || row.client_name,
    siteName: row.site_name || row.site,
    capturedBy: row.captured_by || "CSV Import",
    capturedAt: row.captured_at || new Date().toISOString()
  })).filter((row) => row.tag || row.location);

  imported.forEach(addSetupDevice);
  saveDeviceMasterToPc();
  event.target.value = "";
  document.querySelector("#syncState").textContent = `${imported.length} setup rows imported`;
}

function exportSetupCsv() {
  const rows = state.setupDevices.length ? state.setupDevices : [{
    tag: "L1.MCP.1",
    type: "Manual Call Point",
    floor: "Level 1",
    location: "Lift lobby",
    brandModel: "",
    serialBarcode: "",
    expiryDate: "",
    status: "Pending Review",
    remarks: "Sample row",
    capturedBy: "Demo Inspector",
    capturedAt: new Date().toISOString()
  }];
  const headers = ["company_name", "site_name", "device_tag", "device_type", "floor_area", "location", "brand_model", "serial_barcode", "expiry_date", "status", "remarks", "x_percent", "y_percent", "captured_by", "captured_at"];
  const csvRows = [headers.join(",")].concat(rows.map((row) => [
    row.companyName,
    row.siteName,
    row.tag,
    row.type,
    row.floor,
    row.location,
    row.brandModel,
    row.serialBarcode,
    row.expiryDate,
    row.status,
    row.remarks,
    row.xPercent,
    row.yPercent,
    row.capturedBy,
    row.capturedAt
  ].map(formatCsvCell).join(",")));

  downloadTextFile("first-time-site-setup-export.csv", csvRows.join("\n"));
}

function addReadyTagAtPoint(xPercent, yPercent) {
  const floorAsset = getFloorAsset(floorSelect.value);
  const floor = floorAsset.title;
  const tag = nextTagForActiveType();
  const roundedX = roundPercent(xPercent);
  const roundedY = roundPercent(yPercent);
  addSetupDevice({
    tag,
    type: state.activeTag.type,
    floor,
    location: "",
    status: "Pending Review",
    remarks: "Pinned from ready tag palette. Admin to confirm exact location and device details.",
    xPercent: roundedX,
    yPercent: roundedY,
    companyName: floorAsset.companyName || document.querySelector("#mimicCompany").value.trim(),
    siteName: floorAsset.siteName || document.querySelector("#mimicSite").value.trim(),
    capturedBy: "Demo Inspector",
    capturedAt: new Date().toISOString()
  });
  state.selectedSetupTag = tag;
  renderMarkers();
  updateTagPaletteHint();
  state.pinHistory.push(tag);
  writeStoredJson("tmFirePinHistory", state.pinHistory);
  document.querySelector("#syncState").textContent = `${tag} pinned to mimic`;
}

function clearActiveTag() {
  state.activeTag = null;
  document.querySelectorAll("#tagPalette button").forEach((item) => item.classList.remove("active"));
  updateTagPaletteHint();
  document.querySelector("#syncState").textContent = "Pinning stopped";
}

function undoLastPin() {
  while (state.pinHistory.length) {
    const tag = state.pinHistory.pop();
    const index = state.setupDevices.findIndex((device) => device.tag === tag);
    if (index >= 0) {
      state.setupDevices.splice(index, 1);
      writeStoredJson("tmFireSetupDevices", state.setupDevices);
      writeStoredJson("tmFirePinHistory", state.pinHistory);
      renderSetupDevices();
      renderMarkers();
      updateSummary();
      updateTagPaletteHint();
      document.querySelector("#syncState").textContent = `${tag} removed`;
      return;
    }
  }

  writeStoredJson("tmFirePinHistory", state.pinHistory);
  document.querySelector("#syncState").textContent = "No pinned tag to undo";
}

function nextTagForActiveType() {
  const floorAsset = getFloorAsset(floorSelect.value);
  const floorCode = getFloorCode(floorSelect.value);
  const prefix = state.activeTag?.prefix || "DEV";
  const pattern = new RegExp(`^${escapeRegExp(floorCode)}\\.${escapeRegExp(prefix)}\\.(\\d+)$`, "i");
  const startNumber = getTagStartNumber(floorAsset, floorCode, prefix);
  const highest = state.setupDevices.reduce((max, device) => {
    if (!isSameTagNumberScope(device, floorAsset)) return max;
    const match = String(device.tag || "").match(pattern);
    return match ? Math.max(max, Number(match[1])) : max;
  }, startNumber - 1);
  return `${floorCode}.${prefix}.${highest + 1}`;
}

function migrateConfiguredTagStarts() {
  let changed = false;

  tagStartProfiles.forEach((profile) => {
    const groups = new Map();
    state.setupDevices.forEach((device) => {
      const tag = String(device.tag || "").trim().toUpperCase();
      const match = tag.match(/^([A-Z0-9]+)\.([A-Z0-9]+)\.(\d+)$/);
      if (!match) return;

      const [, floorCode, prefix, numberText] = match;
      const siteText = normalizeScopeText([device.companyName, device.siteName].join(" "));
      const floorText = normalizeScopeText([device.floor, floorCode].join(" "));
      if (!tagStartProfileMatches(profile, siteText, floorText, floorCode)) return;
      if (!Object.prototype.hasOwnProperty.call(profile.starts, prefix)) return;

      const key = `${floorCode}.${prefix}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push({ device, floorCode, prefix, number: Number(numberText) });
    });

    groups.forEach((items) => {
      const sorted = items.sort((a, b) => {
        return a.number - b.number
          || Number(getSetupDeviceX(a.device) || 0) - Number(getSetupDeviceX(b.device) || 0)
          || Number(getSetupDeviceY(a.device) || 0) - Number(getSetupDeviceY(b.device) || 0);
      });
      const startNumber = profile.starts[sorted[0].prefix] || 1;
      if (profile.compact) {
        sorted.forEach((item, index) => {
          const nextTag = `${item.floorCode}.${item.prefix}.${startNumber + index}`;
          if (item.device.tag !== nextTag) {
            renameSetupDeviceTag(item.device.tag, nextTag);
            item.device.tag = nextTag;
            changed = true;
          }
        });
        return;
      }

      const offset = startNumber - sorted[0].number;
      if (!offset) return;

      sorted.forEach((item) => {
        const nextTag = `${item.floorCode}.${item.prefix}.${item.number + offset}`;
        if (item.device.tag !== nextTag) {
          renameSetupDeviceTag(item.device.tag, nextTag);
          item.device.tag = nextTag;
          changed = true;
        }
      });
    });
  });

  if (changed) {
    writeStoredJson("tmFireSetupDevices", state.setupDevices);
    writeStoredJson("tmFireInspections", state.inspections);
    writeStoredJson("tmFireHistory", state.history);
    writeStoredJson("tmFirePinHistory", state.pinHistory);
  }
  return changed;
}

function renameSetupDeviceTag(oldTag, newTag) {
  if (!oldTag || !newTag || oldTag === newTag) return;
  if (state.inspections[oldTag] && !state.inspections[newTag]) {
    state.inspections[newTag] = state.inspections[oldTag];
  }
  delete state.inspections[oldTag];

  if (state.history[oldTag] && !state.history[newTag]) {
    state.history[newTag] = state.history[oldTag];
  }
  delete state.history[oldTag];

  state.pinHistory = state.pinHistory.map((tag) => tag === oldTag ? newTag : tag);
  if (state.selectedSetupTag === oldTag) state.selectedSetupTag = newTag;
  if (state.selectedId === oldTag) state.selectedId = newTag;
}

function isSameTagNumberScope(device, floorAsset) {
  return setupDeviceMatchesFloorAsset(device, floorAsset);
}

function setupDeviceMatchesFloorAsset(device, floorAsset, profile = null) {
  const currentCompany = normalizeScopeText(profile?.companyName || floorAsset.companyName || document.querySelector("#mimicCompany")?.value);
  const currentSite = normalizeScopeText(profile?.siteName || floorAsset.siteName || document.querySelector("#mimicSite")?.value);
  const deviceCompany = normalizeScopeText(device.companyName);
  const deviceSite = normalizeScopeText(device.siteName);
  if (currentCompany && deviceCompany && currentCompany !== deviceCompany) return false;
  if (currentSite && deviceSite && currentSite !== deviceSite) return false;

  const floorId = floorAsset.floorId || floorAsset.id;
  if (device.floorId && floorId) {
    return normalizeScopeText(device.floorId) === normalizeScopeText(floorId);
  }

  const deviceFloor = normalizeFloorForCompare(device.floor, currentCompany, currentSite);
  const floorCandidates = uniqueValues([
    floorAsset.title,
    floorAsset.floorName,
    floorAsset.floorCode
  ]).map((value) => normalizeFloorForCompare(value, currentCompany, currentSite)).filter(Boolean);

  if (!deviceFloor || !floorCandidates.length) return true;
  return floorCandidates.some((candidate) => {
    return deviceFloor === candidate
      || deviceFloor.endsWith(` - ${candidate}`)
      || candidate.endsWith(` - ${deviceFloor}`);
  });
}

function normalizeFloorForCompare(value, companyName = "", siteName = "") {
  let text = normalizeScopeText(value).replace(/\s+/g, " ");
  [companyName, siteName].filter(Boolean).forEach((prefix) => {
    const normalizedPrefix = normalizeScopeText(prefix).replace(/\s+/g, " ");
    if (text.startsWith(`${normalizedPrefix} - `)) {
      text = text.slice(normalizedPrefix.length + 3).trim();
    }
    if (text.startsWith(`${normalizedPrefix}: `)) {
      text = text.slice(normalizedPrefix.length + 2).trim();
    }
  });
  return text;
}

function getTagStartNumber(floorAsset, floorCode, prefix) {
  const siteText = normalizeScopeText([
    floorAsset.companyName,
    floorAsset.siteName,
    document.querySelector("#mimicCompany")?.value,
    document.querySelector("#mimicSite")?.value
  ].join(" "));
  const floorText = normalizeScopeText([
    floorCode,
    floorAsset.floorCode,
    floorAsset.floorName,
    floorAsset.title
  ].join(" "));

  const profile = tagStartProfiles.find((item) => tagStartProfileMatches(item, siteText, floorText, floorCode));
  const startNumber = profile?.starts?.[prefix.toUpperCase()];
  return Number.isFinite(startNumber) ? startNumber : 1;
}

function tagStartProfileMatches(profile, siteText, floorText, floorCode) {
  const companyMatch = !profile.companyKeywords?.length
    || profile.companyKeywords.some((keyword) => siteText.includes(keyword));
  const floorCodeMatch = !profile.floorCodes?.length
    || profile.floorCodes.includes(String(floorCode || "").toUpperCase());
  const floorKeywordMatch = !profile.floorKeywords?.length
    || profile.floorKeywords.some((keyword) => floorText.includes(keyword));
  return Boolean(companyMatch && (floorCodeMatch || floorKeywordMatch));
}

function normalizeScopeText(value) {
  return String(value || "").trim().toLowerCase();
}

function renderFloorOptions(selectedValue = floorSelect.value || "lv1", preferredProfile = null, options = {}) {
  const selectedFloor = floorExists(selectedValue) ? getFloorAsset(selectedValue) : null;
  const selectedFloorProfile = getFloorClientProfile(selectedFloor);
  renderClientSiteSelectors(preferredProfile || selectedFloorProfile || state.siteProfile);
  const activeProfile = getSelectedClientProfile();
  const customFloors = [...state.mimicFloors, ...state.runtimeMimicAssets]
    .filter((floor) => profileMatchesClient(floor, activeProfile));
  const libraryCompanies = state.libraryCompanies.filter((company) => profileMatchesClient(company, activeProfile));
  const customOptions = customFloors.map((floor) => {
    return `<option value="${escapeHtml(floor.id)}">${escapeHtml(floor.title)}</option>`;
  }).join("");
  const libraryGroups = libraryCompanies.map((company) => {
    const options = company.pages.map((page) => {
      return `<option value="${escapeHtml(page.floorId)}">${escapeHtml(page.title)}</option>`;
    }).join("");
    return `<optgroup label="${escapeHtml(company.companyName)}">${options}</optgroup>`;
  }).join("");
  const hasClientFloors = Boolean(customOptions || libraryGroups);
  const demoGroup = !hasClientFloors ? `
    <optgroup label="Demo Floors">
      <option value="lv1">LV-1 First Floor</option>
      <option value="ground">Ground Floor Reference</option>
      <option value="production">Production Map Reference</option>
    </optgroup>
  ` : "";

  floorSelect.innerHTML = `
    ${demoGroup}
    ${customOptions ? `<optgroup label="Uploaded Floors">${customOptions}</optgroup>` : ""}
    ${libraryGroups}
  `;

  const validValues = [...floorSelect.options].map((option) => option.value);
  floorSelect.value = validValues.includes(selectedValue)
    ? selectedValue
    : validValues[0] || "lv1";
  const floor = getFloorAsset(floorSelect.value);
  updateMapImage(floor);
  syncMimicInputsFromFloor(floor);
  renderLibraryPageTabs();
  if (scheduleFloor && options.renderSchedule !== false) {
    renderSchedulePanel();
  }
}

function getMimicImageSrc(floor) {
  if (state.mimicViewMode === "original") {
    return floor.originalSrc || floor.cleanSourceOriginalSrc || floor.src || floor.cleanSrc;
  }
  return floor.cleanSrc || floor.src || floor.originalSrc || floor.cleanSourceOriginalSrc;
}

function updateMapImage(floor = getFloorAsset(floorSelect.value)) {
  mapImage.src = getMimicImageSrc(floor);
  mapTitle.textContent = floor.title;
  originalMimicBtn.classList.toggle("active", state.mimicViewMode === "original");
  cleanMimicBtn.classList.toggle("active", state.mimicViewMode === "clean");
  cleanMimicBtn.disabled = !floor.cleanSrc;
  cleanMimicBtn.title = floor.cleanSrc ? "Show simplified clean outline" : "Clean outline not available for this floor yet";
}

function setMimicViewMode(mode) {
  const floor = getFloorAsset(floorSelect.value);
  state.mimicViewMode = mode === "original" ? "original" : "clean";
  if (state.mimicViewMode === "clean" && !floor.cleanSrc) {
    state.mimicViewMode = "original";
  }
  localStorage.setItem("rmtMimicViewMode", state.mimicViewMode);
  updateMapImage(floor);
  document.querySelector("#syncState").textContent = `${state.mimicViewMode === "clean" ? "Clean" : "Original"} mimic view enabled`;
}

function renderClientSiteSelectors(preferredProfile = state.siteProfile) {
  const profiles = collectClientSiteOptions(preferredProfile);
  const selectedProfile = findClosestClientProfile(preferredProfile, profiles) || profiles[0] || normalizeClientProfile(preferredProfile);
  const companyCounts = profiles.reduce((counts, profile) => {
    const key = normalizeScopeText(profile.companyName);
    counts.set(key, (counts.get(key) || 0) + 1);
    return counts;
  }, new Map());

  clientSelect.innerHTML = profiles.map((profile) => {
    const value = makeScheduleSiteValue(profile.companyName, profile.siteName);
    const duplicateCompany = (companyCounts.get(normalizeScopeText(profile.companyName)) || 0) > 1;
    const label = duplicateCompany ? `${profile.companyName} / ${profile.siteName}` : profile.companyName;
    return `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`;
  }).join("");

  const selectedValue = makeScheduleSiteValue(selectedProfile.companyName, selectedProfile.siteName);
  clientSelect.value = [...clientSelect.options].some((option) => option.value === selectedValue)
    ? selectedValue
    : clientSelect.options[0]?.value || "";

  const selectedCompany = getSelectedClientProfile().companyName;
  const siteNames = profiles
    .filter((profile) => normalizeScopeText(profile.companyName) === normalizeScopeText(selectedCompany))
    .map((profile) => profile.siteName);
  siteSelect.innerHTML = uniqueValues(siteNames)
    .map((name) => `<option>${escapeHtml(name)}</option>`)
    .join("");
  siteSelect.value = selectedProfile.siteName;
}

function collectClientSiteOptions(extraProfile = null) {
  const map = new Map();
  const add = (companyName, siteName) => {
    const profile = normalizeClientProfile({ companyName, siteName });
    if (!profile.companyName && !profile.siteName) return;
    map.set(makeScheduleSiteValue(profile.companyName, profile.siteName), profile);
  };

  if (extraProfile) add(extraProfile.companyName, extraProfile.siteName);
  add(state.siteProfile?.companyName, state.siteProfile?.siteName);
  state.mimicFloors.forEach((floor) => add(floor.companyName, floor.siteName));
  state.runtimeMimicAssets.forEach((floor) => add(floor.companyName, floor.siteName));
  state.libraryCompanies.forEach((company) => add(company.companyName, company.siteName));
  state.setupDevices.forEach((device) => add(device.companyName, device.siteName));
  state.schedules.forEach((schedule) => add(schedule.companyName, schedule.siteName));

  return [...map.values()].sort((a, b) => {
    return a.companyName.localeCompare(b.companyName) || a.siteName.localeCompare(b.siteName);
  });
}

function getSelectedClientProfile() {
  if (clientSelect?.value) {
    const profile = String(clientSelect.value).includes("|")
      ? readScheduleSiteValue(clientSelect.value)
      : { companyName: clientSelect.value, siteName: siteSelect?.value || state.siteProfile?.siteName };
    if (profile.companyName || profile.siteName) return normalizeClientProfile(profile);
  }
  return normalizeClientProfile({
    companyName: state.siteProfile?.companyName || "RMT",
    siteName: siteSelect?.value || state.siteProfile?.siteName || "Site"
  });
}

function normalizeClientProfile(profile = {}) {
  const companyName = String(profile.companyName || "").trim();
  const siteName = String(profile.siteName || "").trim();
  return {
    companyName: companyName || siteName || "RMT",
    siteName: siteName || companyName || "Site"
  };
}

function findClosestClientProfile(profile, profiles) {
  const desired = normalizeClientProfile(profile);
  return profiles.find((item) => {
    return normalizeScopeText(item.companyName) === normalizeScopeText(desired.companyName)
      && normalizeScopeText(item.siteName) === normalizeScopeText(desired.siteName);
  }) || profiles.find((item) => normalizeScopeText(item.companyName) === normalizeScopeText(desired.companyName));
}

function getFloorClientProfile(floor) {
  if (!floor || (!floor.companyName && !floor.siteName)) return null;
  return normalizeClientProfile({
    companyName: floor.companyName,
    siteName: floor.siteName
  });
}

function profileMatchesClient(item, profile) {
  const selected = normalizeClientProfile(profile);
  const company = normalizeScopeText(item?.companyName);
  const site = normalizeScopeText(item?.siteName);
  if (!company && !site) return false;
  return company === normalizeScopeText(selected.companyName)
    && site === normalizeScopeText(selected.siteName);
}

function getFirstFloorIdForProfile(profile) {
  const selected = normalizeClientProfile(profile);
  const customFloor = state.mimicFloors.find((floor) => profileMatchesClient(floor, selected));
  if (customFloor) return customFloor.id;
  const runtimeAsset = state.runtimeMimicAssets.find((floor) => profileMatchesClient(floor, selected));
  if (runtimeAsset) return runtimeAsset.id;
  const libraryCompany = state.libraryCompanies.find((company) => profileMatchesClient(company, selected));
  if (libraryCompany?.pages?.length) return libraryCompany.pages[0].floorId;
  return scheduleGeneralFloorAsset.id;
}

function getFloorAsset(floorId) {
  if (isGeneralScheduleFloorId(floorId)) return scheduleGeneralFloorAsset;
  return defaultFloorAssets[floorId]
    || state.mimicFloors.find((floor) => floor.id === floorId)
    || state.runtimeMimicAssets.find((floor) => floor.id === floorId || floor.floorId === floorId)
    || state.libraryFloors.find((floor) => floor.id === floorId || floor.floorId === floorId)
    || defaultFloorAssets.lv1;
}

function floorExists(floorId) {
  return Boolean(isGeneralScheduleFloorId(floorId) || defaultFloorAssets[floorId] || state.mimicFloors.some((floor) => floor.id === floorId) || state.runtimeMimicAssets.some((floor) => floor.id === floorId || floor.floorId === floorId) || state.libraryFloors.some((floor) => floor.id === floorId || floor.floorId === floorId));
}

function getFloorCode(floorId) {
  if (isGeneralScheduleFloorId(floorId)) return scheduleGeneralFloorAsset.floorCode;
  const customFloor = state.mimicFloors.find((floor) => floor.id === floorId);
  const libraryFloor = state.libraryFloors.find((floor) => floor.id === floorId || floor.floorId === floorId);
  const visibleFloorCode = document.querySelector("#mimicFloorCode")?.value.trim().toUpperCase();
  if (floorId === floorSelect.value && visibleFloorCode) {
    const staleCodes = ["G", "1ST", "2ND", "P1", "P2", "P3"];
    if (libraryFloor?.companyName === "WETEX" && staleCodes.includes(visibleFloorCode) && visibleFloorCode !== libraryFloor.floorCode) {
      return libraryFloor.floorCode;
    }
    return visibleFloorCode;
  }
  return customFloor?.floorCode || libraryFloor?.floorCode || floorCodes[floorId] || "UNK";
}

function getProfileCacheKey(profile = {}) {
  return normalizeScopeText(`${profile.companyName || ""}::${profile.siteName || ""}`);
}

function masterFileMatchesProfile(file = {}, profile = null) {
  if (!profile) return true;
  const text = normalizeScopeText(`${file.name || ""} ${file.url || ""}`);
  const companySlug = slugify(profile.companyName || "");
  const siteSlug = slugify(profile.siteName || "");
  const combinedSlug = slugify(`${profile.companyName || ""}-${profile.siteName || ""}`);
  return Boolean(
    (combinedSlug && text.includes(combinedSlug))
      || (companySlug && siteSlug && text.includes(companySlug) && text.includes(siteSlug))
      || (companySlug && text.includes(companySlug))
  );
}

async function loadMimicLibrary(options = {}) {
  const { profile = null, render = true } = options;
  if (browserDataState.mimicLibraryLoaded && !profile) return state.libraryFloors;
  try {
    const response = await fetch("/local-data/mimic-library/mimic-library-app-data.json", { cache: "no-store" });
    if (!response.ok) return state.libraryFloors;
    const manifest = await response.json();
    const companies = manifest.companies || [];
    const floors = manifest.floors || [];
    if (profile && getCurrentUserRole() === "Technician") {
      state.libraryCompanies = companies.filter((company) => profileMatchesClient(company, profile));
      state.libraryFloors = floors.filter((floor) => profileMatchesClient(floor, profile));
    } else {
      state.libraryCompanies = companies;
      state.libraryFloors = floors;
      browserDataState.mimicLibraryLoaded = true;
    }
    normalizeSetupDevices();
    invalidateRuntimeCaches();
    if (render) {
      renderFloorOptions(floorSelect.value);
      renderMarkers();
      renderSchedulePanel();
      renderTechWorkPanel();
      refreshTechnicianAssignedPins({ scrollToMap: false });
      document.querySelector("#syncState").textContent = `${state.libraryFloors.length} mimic pages loaded`;
    }
  } catch (error) {
    console.warn("Unable to load mimic library", error);
  }
  return state.libraryFloors;
}

async function loadRuntimeMimicAssets() {
  if (browserDataState.runtimeMimicAssetsLoaded) return state.runtimeMimicAssets;
  try {
    const response = await fetch("assets/mimics/index.json", { cache: "no-store" });
    if (!response.ok) return state.runtimeMimicAssets;
    const index = await response.json();
    const manifests = Array.isArray(index.manifests) ? index.manifests : [];
    state.runtimeMimicAssets = manifests
      .filter((manifest) => manifest && manifest.clientId && manifest.siteId && manifest.floorId && manifest.background)
      .map((manifest) => ({
        id: `asset-${manifest.clientId}-${manifest.siteId}-${manifest.floorId}`,
        floorId: `asset-${manifest.clientId}-${manifest.siteId}-${manifest.floorId}`,
        companyName: manifest.clientName || manifest.clientId,
        siteName: manifest.siteName || manifest.siteId,
        floorCode: manifest.floorCode || manifest.floorId,
        floorName: manifest.displayName || manifest.floorId,
        title: manifest.displayName || manifest.floorId,
        src: `assets/mimics/${manifest.clientId}/${manifest.siteId}/${manifest.floorId}/${manifest.background}`,
        cleanSrc: `assets/mimics/${manifest.clientId}/${manifest.siteId}/${manifest.floorId}/${manifest.background}`,
        fileName: manifest.background,
        backgroundVersion: manifest.backgroundVersion || "",
        manifestSource: "runtime-asset"
      }));
    browserDataState.runtimeMimicAssetsLoaded = true;
  } catch (error) {
    console.warn("Unable to load runtime mimic asset index", error);
  }
  return state.runtimeMimicAssets;
}

async function loadSavedDeviceMasters(options = {}) {
  const { profile = null, render = true } = options;
  const profileKey = profile ? getProfileCacheKey(profile) : "";
  if (profileKey && browserDataState.loadedDeviceMasterProfiles.has(profileKey)) return state.setupDevices;
  if (!profile && browserDataState.deviceMastersLoaded) return state.setupDevices;
  let masterFiles = [
    { name: "uob-uob-device-master.json", url: "/local-data/device-master/uob-uob-device-master.json" },
    { name: "wetex-wetex-device-master.json", url: "/local-data/device-master/wetex-wetex-device-master.json" }
  ];

  try {
    const indexResponse = await fetch("/api/device-masters", { cache: "no-store" });
    if (indexResponse.ok) {
      const index = await indexResponse.json();
      const discovered = (index.files || []).filter((file) => file.url);
      if (discovered.length) {
        masterFiles = discovered;
      }
    }
  } catch (error) {
    console.warn("Unable to list device masters; using known demo files", error);
  }

  if (profile) {
    const matching = masterFiles.filter((file) => masterFileMatchesProfile(file, profile));
    if (matching.length) masterFiles = matching;
  }

  let loadedCount = 0;
  for (const fileInfo of masterFiles) {
    const file = fileInfo.url || fileInfo;
    try {
      const response = await fetch(file, { cache: "no-store" });
      if (!response.ok) continue;
      const master = await response.json();
      if (profile && !profileMatchesClient(master, profile)) continue;
      const devicesFromFile = (master.devices || []).map((device) => ({
        ...device,
        companyName: device.companyName || master.companyName,
        siteName: device.siteName || master.siteName
      }));
      if (!devicesFromFile.length) continue;

      state.setupDevices = [
        ...state.setupDevices,
        ...devicesFromFile
      ];
      normalizeSetupDevices();
      migrateConfiguredTagStarts();
      writeStoredJson("tmFireSetupDevices", state.setupDevices);
      invalidateRuntimeCaches();
      if (render) {
        renderSetupDevices();
        renderMarkers();
        updateSummary();
        renderSystemChecklist();
        renderSchedulePanel();
        renderTechWorkPanel();
      }
      loadedCount += 1;
      if (render) {
        document.querySelector("#syncState").textContent = `${devicesFromFile.length} ${master.companyName || "site"} master devices loaded for checklist`;
      }
    } catch (error) {
      console.warn("Unable to load saved device master", file, error);
    }
  }
  if (profileKey) browserDataState.loadedDeviceMasterProfiles.add(profileKey);
  if (!profile) browserDataState.deviceMastersLoaded = true;
  if (render && loadedCount > 1) {
    document.querySelector("#syncState").textContent = `${loadedCount} saved device masters loaded`;
  }
  if (render) refreshTechnicianAssignedPins({ scrollToMap: false });
  return state.setupDevices;
}

async function ensureTechnicianFieldDataLoaded(scheduleOrProfile = null) {
  loadStoredFieldState();
  const profile = scheduleOrProfile
    ? {
        companyName: scheduleOrProfile.companyName || state.siteProfile.companyName,
        siteName: scheduleOrProfile.siteName || state.siteProfile.siteName
      }
    : state.siteProfile;
  await loadMimicLibrary({ profile, render: false });
  await loadSavedDeviceMasters({ profile, render: false });
  invalidateRuntimeCaches();
  return true;
}

async function loadStaffTrackingDemo() {
  try {
    const response = await fetch("/local-data/inspection-runs/wetex-demo-inspection-run.json", { cache: "no-store" });
    if (!response.ok) {
      renderStaffTrackingUnavailable();
      return;
    }
    state.staffRun = await response.json();
    renderStaffTracking();
  } catch (error) {
    console.warn("Unable to load WETEX staff tracking demo", error);
    renderStaffTrackingUnavailable();
  }
}

function renderStaffTrackingUnavailable() {
  const intro = document.querySelector("#staffTrackingIntro");
  const summary = document.querySelector("#staffTrackingSummary");
  const flags = document.querySelector("#staffFlagList");
  const timeline = document.querySelector("#staffTimelineRows");
  const critical = document.querySelector("#criticalSystemList");
  if (intro) intro.textContent = "WETEX demo run has not been generated yet.";
  if (summary) summary.innerHTML = "";
  if (flags) flags.innerHTML = `<p class="hint">No staff tracking run loaded.</p>`;
  if (timeline) timeline.innerHTML = "";
  if (critical) critical.innerHTML = "";
}

function renderStaffTracking() {
  const run = state.staffRun;
  const intro = document.querySelector("#staffTrackingIntro");
  const summary = document.querySelector("#staffTrackingSummary");
  const flags = document.querySelector("#staffFlagList");
  const timeline = document.querySelector("#staffTimelineRows");
  const critical = document.querySelector("#criticalSystemList");
  if (!intro || !summary || !flags || !timeline || !critical) return;
  if (!run) {
    renderStaffTrackingUnavailable();
    return;
  }

  const redFlagCount = Object.values(run.redFlags || {}).reduce((sum, items) => sum + (items?.length || 0), 0);
  const criticalItems = run.criticalTracking?.summary || [];
  const criticalHoldCount = criticalItems.filter((item) => item.priority === "Critical").length;
  intro.textContent =
    `${run.serviceType}. This demo shows check-in/out, GPS, device start/end time, checklist ticks, photo evidence, SOP holds, and supervisor red flags.`;

  summary.innerHTML = `
    <div><strong>${escapeHtml(run.installedDeviceCount)}</strong><span>Installed devices</span></div>
    <div><strong>${escapeHtml(run.scopeDeviceCount)}</strong><span>Checked in demo</span></div>
    <div><strong>${escapeHtml(run.totalMinutes)} min</strong><span>Check-in to check-out</span></div>
    <div><strong>${escapeHtml(redFlagCount)}</strong><span>Backend red flags</span></div>
  `;

  critical.innerHTML = criticalItems.length ? criticalItems.map((item) => `
    <article class="critical-system-item ${item.priority === "Critical" ? "critical" : ""}">
      <div>
        <strong>${escapeHtml(item.system)} <span>${escapeHtml(item.priority)}</span></strong>
        <p>${escapeHtml(item.tag)} | ${escapeHtml(item.floor)}</p>
        <p>${escapeHtml(item.status)}</p>
      </div>
      <small>${escapeHtml(formatShortDateTime(item.startTime))} - ${escapeHtml(formatShortDateTime(item.endTime))}</small>
    </article>
  `).join("") : `<p class="hint">No critical system captured in this run.</p>`;

  if (criticalHoldCount) {
    intro.textContent += ` Critical hold found: ${criticalHoldCount} item(s) need supervisor closure.`;
  }

  const flagGroups = [
    ["MOS / Sequence", run.redFlags?.mosSequence || []],
    ["Missing Evidence", run.redFlags?.missingEvidence || []],
    ["Staff Speed Review", run.redFlags?.speedReview || []],
    ["Faulty / Malfunction", run.redFlags?.faults || []]
  ];
  flags.innerHTML = flagGroups.map(([label, items]) => `
    <div class="staff-flag-group">
      <strong>${escapeHtml(label)} <span>${items.length}</span></strong>
      ${items.length ? items.slice(0, 4).map((item) => `
        <p><b>${escapeHtml(item.priority || "Review")}</b> ${escapeHtml(item.tag || item.system || "-")} - ${escapeHtml(item.issue || item.required || item.action || "-")}</p>
      `).join("") : `<p>No red flag captured.</p>`}
    </div>
  `).join("");

  const importantKinds = new Set(["Check-in", "Briefing", "App scope", "Floor start", "SOP hold", "Supervisor review", "Check-out"]);
  const timelineRows = (run.activity || [])
    .filter((event) => importantKinds.has(event.kind) || (event.flag && event.flag !== "-"))
    .slice(0, 28);
  timeline.innerHTML = timelineRows.map((event) => `
    <tr>
      <td>${escapeHtml(formatShortDateTime(event.time))}</td>
      <td>${escapeHtml(event.actor || event.staff || event.inspector || "-")}</td>
      <td>${escapeHtml(event.kind)}</td>
      <td>${escapeHtml(event.floor || "-")}</td>
      <td>${escapeHtml(event.tag || "-")}</td>
      <td>${escapeHtml(event.flag || "-")}</td>
    </tr>
  `).join("");
}

function formatShortDateTime(value) {
  const text = String(value || "");
  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) {
    return parsed.toLocaleString([], {
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit"
    });
  }
  return text.includes(" ") ? text.split(" ")[1]?.slice(0, 5) || text : text;
}

function renderLibraryPageTabs() {
  const floor = getFloorAsset(floorSelect.value);
  if (!floor.library) {
    libraryPageTabs.classList.add("hidden");
    libraryPageTabs.innerHTML = "";
    return;
  }

  const company = state.libraryCompanies.find((item) => item.id === floor.companyId);
  if (!company || company.pages.length <= 1) {
    libraryPageTabs.classList.add("hidden");
    libraryPageTabs.innerHTML = "";
    return;
  }

  libraryPageTabs.classList.remove("hidden");
  libraryPageTabs.innerHTML = `
    <strong>${escapeHtml(company.companyName)}</strong>
    <div class="page-tab-buttons">
      ${company.pages.map((page) => `
        <button type="button" class="${page.floorId === floorSelect.value ? "active" : ""}" data-floor-id="${escapeHtml(page.floorId)}">
          ${escapeHtml(page.title)}
        </button>
      `).join("")}
    </div>
  `;

  libraryPageTabs.querySelectorAll("button").forEach((button) => {
    button.addEventListener("click", () => {
      floorSelect.value = button.dataset.floorId;
      floorSelect.dispatchEvent(new Event("change"));
    });
  });
}

async function saveMimicFloor() {
  const companyName = document.querySelector("#mimicCompany").value.trim();
  const siteName = document.querySelector("#mimicSite").value.trim();
  const floorCode = document.querySelector("#mimicFloorCode").value.trim().toUpperCase();
  const floorName = document.querySelector("#mimicFloorName").value.trim();

  if (!companyName || !siteName || !floorCode || !floorName || !state.pendingMimicImage) {
    document.querySelector("#syncState").textContent = "Fill company, site, floor code, floor name, and upload mimic image";
    return;
  }

  const id = `${slugify(companyName)}-${slugify(siteName)}-${slugify(floorCode)}-${Date.now()}`;
  const title = `${floorCode} - ${floorName}`;
  state.siteProfile = { companyName, siteName };
  writeStoredJson("rmtSiteProfile", state.siteProfile);
  const floor = {
    id,
    companyName,
    siteName,
    floorCode,
    floorName,
    title,
    src: state.pendingMimicImage.dataUrl,
    fileName: state.pendingMimicImage.name,
    createdAt: new Date().toISOString()
  };

  state.mimicFloors.unshift(floor);
  const pcSave = await saveMimicFloorToPc(floor);
  if (pcSave?.ok && pcSave.imageUrl) {
    floor.src = pcSave.imageUrl;
    floor.savedImageUrl = pcSave.imageUrl;
  }
  writeStoredJson("rmtMimicFloors", state.mimicFloors);
  state.pendingMimicImage = null;
  document.querySelector("#mimicUpload").value = "";
  document.querySelector("#mimicSavedName").value = floor.fileName;
  renderFloorOptions(id);
  renderMarkers();
  updateTagPaletteHint();
  document.querySelector("#syncState").textContent = pcSave?.ok ? `${title} mimic saved to PC folder` : `${title} mimic saved in browser`;
  saveDeviceMasterToPc();
}

function updateCurrentMimicInfo() {
  const companyName = document.querySelector("#mimicCompany").value.trim();
  const siteName = document.querySelector("#mimicSite").value.trim();
  const floorCode = document.querySelector("#mimicFloorCode").value.trim().toUpperCase();
  const floorName = document.querySelector("#mimicFloorName").value.trim();

  if (!companyName || !siteName) {
    document.querySelector("#syncState").textContent = "Company and site name cannot be blank";
    return;
  }

  state.siteProfile = { companyName, siteName };
  writeStoredJson("rmtSiteProfile", state.siteProfile);

  const customFloor = state.mimicFloors.find((floor) => floor.id === floorSelect.value);
  if (customFloor) {
    const oldFloorTitle = customFloor.title;
    customFloor.companyName = companyName;
    customFloor.siteName = siteName;
    if (floorCode) customFloor.floorCode = floorCode;
    if (floorName) customFloor.floorName = floorName;
    customFloor.title = `${customFloor.floorCode} - ${customFloor.floorName}`;
    customFloor.updatedAt = new Date().toISOString();
    writeStoredJson("rmtMimicFloors", state.mimicFloors);

    state.setupDevices = state.setupDevices.map((device) => {
      if (device.floor !== oldFloorTitle && device.floor !== customFloor.title) return device;
      return {
        ...device,
        companyName,
        siteName,
        floor: customFloor.title
      };
    });
    writeStoredJson("tmFireSetupDevices", state.setupDevices);
    renderFloorOptions(customFloor.id);
  } else {
    renderClientSiteSelectors();
  }

  renderSetupDevices();
  renderMarkers();
  saveDeviceMasterToPc();
  document.querySelector("#syncState").textContent = "Company / site updated";
}

function syncMimicInputsFromFloor(floor) {
  document.querySelector("#mimicCompany").value = floor.companyName || state.siteProfile.companyName;
  document.querySelector("#mimicSite").value = floor.siteName || state.siteProfile.siteName;
  document.querySelector("#mimicFloorCode").value = floor.floorCode || getFloorCode(floorSelect.value);
  document.querySelector("#mimicFloorName").value = floor.floorName || floor.title;
  document.querySelector("#mimicSavedName").value = floor.fileName || "Demo floor plan";
  state.siteProfile = {
    companyName: document.querySelector("#mimicCompany").value,
    siteName: document.querySelector("#mimicSite").value
  };
  writeStoredJson("rmtSiteProfile", state.siteProfile);
  renderClientSiteSelectors();
}

function uniqueValues(values) {
  return [...new Set(values.map((value) => String(value || "").trim()).filter(Boolean))];
}

function slugify(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40) || "floor";
}

function escapeRegExp(value) {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function getMapPercentFromEvent(event) {
  const rect = mapImage.getBoundingClientRect();
  const point = getReliableTapPoint(event);
  const xPercent = ((point.x - rect.left) / rect.width) * 100;
  const yPercent = ((point.y - rect.top) / rect.height) * 100;
  return {
    xPercent: Math.max(0, Math.min(100, xPercent)),
    yPercent: Math.max(0, Math.min(100, yPercent))
  };
}

function updateSetupDevicePosition(tag, xPercent, yPercent, persistToPc = true) {
  const device = state.setupDevices.find((item) => item.tag === tag);
  if (!device) return;
  device.xPercent = roundPercent(xPercent);
  device.yPercent = roundPercent(yPercent);
  writeStoredJson("tmFireSetupDevices", state.setupDevices);
  renderMarkers();
  renderSetupDevices();
  if (persistToPc) {
    saveDeviceMasterToPc();
  }
  if (document.querySelector("#setupTag").value === tag) {
    document.querySelector("#setupTag").dataset.xPercent = device.xPercent;
    document.querySelector("#setupTag").dataset.yPercent = device.yPercent;
    document.querySelector("#setupPin").value = formatPin(device);
  }
}

function updateExistingDevicePosition(deviceId, xPercent, yPercent, persistToPc = true) {
  state.devicePins[deviceId] = {
    xPercent: roundPercent(xPercent),
    yPercent: roundPercent(yPercent),
    updatedAt: new Date().toISOString()
  };
  state.dragMoved = true;
  writeStoredJson("tmFireDevicePins", state.devicePins);
  renderMarkers();
  if (persistToPc) {
    saveDeviceMasterToPc();
  }
}

async function saveMimicFloorToPc(floor) {
  try {
    const response = await fetch("/api/save-mimic-floor", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(floor)
    });
    return await response.json();
  } catch (error) {
    console.warn("Unable to save mimic floor to PC folder", error);
    return { ok: false, error: error.message };
  }
}

async function saveDeviceMasterToPc() {
  try {
    const companyName = document.querySelector("#mimicCompany").value.trim();
    const siteName = document.querySelector("#mimicSite").value.trim();
    const scopedDevices = state.setupDevices.filter((device) => {
      return String(device.companyName || "").trim().toLowerCase() === companyName.toLowerCase()
        && String(device.siteName || "").trim().toLowerCase() === siteName.toLowerCase();
    });
    const payload = {
      companyName,
      siteName,
      floors: state.mimicFloors.filter((floor) => {
        return String(floor.companyName || "").trim().toLowerCase() === companyName.toLowerCase()
          && String(floor.siteName || "").trim().toLowerCase() === siteName.toLowerCase();
      }).map((floor) => ({
        id: floor.id,
        companyName: floor.companyName,
        siteName: floor.siteName,
        floorCode: floor.floorCode,
        floorName: floor.floorName,
        title: floor.title,
        fileName: floor.fileName,
        createdAt: floor.createdAt
      })),
      devices: scopedDevices,
      adjustedExistingPins: state.devicePins,
      savedAt: new Date().toISOString()
    };
    const response = await fetch("/api/save-device-master", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    if (result.ok) {
      document.querySelector("#syncState").textContent = "Device master saved to PC folder";
    }
    return result;
  } catch (error) {
    console.warn("Unable to save device master to PC folder", error);
    return { ok: false, error: error.message };
  }
}

function fillSetupFormFromDevice(device) {
  state.selectedSetupTag = device.tag;
  document.querySelector("#setupPanel").scrollIntoView({ behavior: "smooth", block: "start" });
  document.querySelector("#setupTag").value = device.tag;
  document.querySelector("#setupTag").dataset.xPercent = device.xPercent;
  document.querySelector("#setupTag").dataset.yPercent = device.yPercent;
  document.querySelector("#setupType").value = device.type;
  document.querySelector("#setupFloor").value = device.floor;
  document.querySelector("#setupLocation").value = cleanDeviceLocation(device.location);
  document.querySelector("#setupBrand").value = device.brandModel || "";
  document.querySelector("#setupSerial").value = device.serialBarcode || "";
  document.querySelector("#setupExpiry").value = device.expiryDate || "";
  document.querySelector("#setupStatus").value = device.status || "Pending Review";
  document.querySelector("#setupPin").value = formatPin(device);
  document.querySelector("#setupRemarks").value = device.remarks || "";
}

function updateTagPaletteHint() {
  const hint = document.querySelector("#tagPaletteHint");
  if (!hint) return;
  hint.textContent = state.activeTag
    ? `${state.activeTag.short} selected. Tap the mimic to add ${nextTagForActiveType()}.`
    : state.selectedSetupTag
      ? `${state.selectedSetupTag} selected. Use Edit Selected Pin or Delete Selected Pin.`
    : "Pick a tag, then tap the mimic to pin it. Drag color-coded tags to adjust.";
}

function getShortCode(device) {
  const parts = String(device.tag || "").split(".");
  if (parts.length >= 2) return parts[1].slice(0, 3).toUpperCase();
  return String(device.type || "DEV").slice(0, 3).toUpperCase();
}

function getDeviceTypeClass(type) {
  const value = String(type || "").toLowerCase();
  if (value.includes("smoke")) return "type-smoke";
  if (value.includes("heat")) return "type-heat";
  if (value.includes("manual") || value.includes("call point") || value.includes("break glass")) return "type-mcp";
  if (value.includes("emergency light")) return "type-emergency-light";
  if (value.includes("exit")) return "type-exit";
  if (value.includes("main fire alarm panel")) return "type-mfap";
  if (value.includes("hose reel panel")) return "type-hrp";
  if (value.includes("sprinkler panel")) return "type-spp";
  if (value.includes("wet riser panel")) return "type-wrp";
  if (value.includes("pressurized hydrant panel")) return "type-php";
  if (value.includes("flow switch")) return "type-flow-switch";
  if (value.includes("fm200")) return "type-fm200";
  if (value.includes("hose reel")) return "type-hose-reel";
  if (value.includes("wet riser")) return "type-wet-riser";
  if (value.includes("2kg") && value.includes("co2") && value.includes("extinguisher")) return "type-co2-extinguisher";
  if (value.includes("extinguisher")) return "type-extinguisher";
  if (value.includes("co2")) return "type-co2";
  if (value.includes("wet chemical")) return "type-wet-chemical";
  if (value.includes("pump")) return "type-pump";
  if (value.includes("intercom")) return "type-intercom";
  if (value.includes("gas")) return "type-gas";
  return "type-other";
}

function roundPercent(value) {
  return Math.round(value * 10) / 10;
}

function formatPin(device) {
  const x = getSetupDeviceX(device);
  const y = getSetupDeviceY(device);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return "-";
  return `${roundPercent(x)}%, ${roundPercent(y)}%`;
}

function isAutoPinLocation(location) {
  return /^Pinned on .+ mimic at X \d+(\.\d+)?%, Y \d+(\.\d+)?%$/i.test(String(location || "").trim());
}

function cleanDeviceLocation(location) {
  const value = String(location || "").trim();
  return isAutoPinLocation(value) ? "" : value;
}

function displayDeviceLocation(location) {
  return cleanDeviceLocation(location) || "Add location";
}

function parseCsv(text) {
  const lines = text.replace(/\r/g, "").split("\n").filter((line) => line.trim());
  if (lines.length < 2) return [];

  const headers = splitCsvLine(lines[0]).map((header) => normalizeHeader(header));
  return lines.slice(1).map((line) => {
    const values = splitCsvLine(line);
    return headers.reduce((row, header, index) => {
      row[header] = values[index] || "";
      return row;
    }, {});
  });
}

function splitCsvLine(line) {
  const result = [];
  let current = "";
  let inQuotes = false;

  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    const next = line[index + 1];
    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      index += 1;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      result.push(current);
      current = "";
    } else {
      current += char;
    }
  }

  result.push(current);
  return result.map((value) => value.trim());
}

function normalizeHeader(header) {
  return header.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
}

function formatCsvCell(value) {
  const text = String(value || "");
  return `"${text.replace(/"/g, '""')}"`;
}

function downloadTextFile(filename, text) {
  const blob = new Blob([text], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

function escapeHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function getReportSchedule(scheduleId = "") {
  const requestedId = typeof scheduleId === "string" ? scheduleId : "";
  const activeId = requestedId
    || state.activeReportScheduleId
    || state.editingScheduleId
    || state.activeJob?.scheduleId
    || state.activeJob?.schedule?.scheduleId
    || "";
  return (activeId && state.schedules.find((item) => item.scheduleId === activeId))
    || (activeId && state.activeJob?.schedule?.scheduleId === activeId ? state.activeJob.schedule : null)
    || getActiveTechnicianMaintenanceSchedule()
    || getTechMarkerScopeSchedule()
    || null;
}

function getReportSuggestedPinsForSchedule(schedule) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return [];
  const company = normalizeScopeText(schedule.companyName);
  const site = normalizeScopeText(schedule.siteName);
  const floorNames = new Set(getScheduledAssignedDevices(schedule).flatMap((device) => [
    device.floorId,
    device.floor,
    device.floorTitle
  ]).map(normalizeScopeText).filter(Boolean));
  [schedule.floorId, schedule.floorTitle, schedule.startFloorId, schedule.startFloorTitle]
    .map(normalizeScopeText)
    .filter(Boolean)
    .forEach((value) => floorNames.add(value));
  return state.requests.filter((request) => {
    if (String(request.scheduleId || "") !== scheduleId) return false;
    if (company && normalizeScopeText(request.companyName) !== company) return false;
    if (site && normalizeScopeText(request.siteName) !== site) return false;
    const floor = normalizeScopeText(request.floor || request.floorTitle || request.floorId);
    return !floor || !floorNames.size || floorNames.has(floor);
  });
}

function getReportEvidenceRefs(record = {}) {
  const refs = Array.isArray(record.evidenceRefs) ? record.evidenceRefs : [];
  const named = [
    record.beforePhoto ? { type: "before", name: record.beforePhoto } : null,
    record.afterPhoto ? { type: "after", name: record.afterPhoto } : null,
    record.photo ? { type: "photo", name: record.photo } : null
  ].filter(Boolean);
  const seen = new Set();
  return [...refs, ...named].map((item) => {
    const displayPhotoUrl = String(item?.stampedPhotoUrl || item?.photoUrl || "");
    const ref = {
      type: String(item?.type || "evidence"),
      name: String(item?.name || item?.filename || "Evidence"),
      evidenceId: String(item?.evidenceId || ""),
      originalEvidenceId: String(item?.originalEvidenceId || ""),
      stampedEvidenceId: String(item?.stampedEvidenceId || ""),
      originalPhotoUrl: String(item?.originalPhotoUrl || ""),
      stampedPhotoUrl: String(item?.stampedPhotoUrl || ""),
      photoUrl: displayPhotoUrl,
      capturedAtUtc: String(item?.capturedAtUtc || item?.capturedAt || ""),
      technicianName: String(item?.technicianName || item?.capturedBy || ""),
      stampVersion: String(item?.stampVersion || ""),
      savedToPc: Boolean(item?.savedToPc)
    };
    const key = ref.evidenceId || `${ref.type}::${ref.name}::${ref.photoUrl}`;
    if (seen.has(key)) return null;
    seen.add(key);
    return ref;
  }).filter(Boolean);
}

function getReportResult(record = {}) {
  const value = String(record.status || record.result || "pending").trim().toUpperCase();
  if (["PASS", "PASSED", "VERIFIED", "CONFIRMED", "COMPLETE", "COMPLETED"].includes(value)) return "PASS";
  if (["FAIL", "FAILED", "FAULT", "MISSING", "MISMATCH_REVIEW_REQUIRED"].includes(value)) return "FAULT";
  if (["PARTIAL", "IN_PROGRESS", "STARTED"].includes(value)) return "IN PROGRESS";
  return value || "PENDING";
}

function getReportSystemForDevice(device, groups) {
  return groups.find((group) => group.devices.some((item) => (item.id || item.tag) === (device.id || device.tag)))
    || { id: "other", label: "Other Configured Systems" };
}

function getReportUnsyncedRecords(schedule, plannedIds) {
  const scheduleId = getScheduleKey(schedule);
  const planned = new Set(plannedIds);
  const isDraft = (record) => {
    const sync = String(record?.syncStatus || "").toUpperCase();
    return Boolean(record?.unsynced || sync === "DRAFT" || sync === "CONFLICT" || sync.includes("AWAITING_SYNC"));
  };
  const inspections = Object.entries(state.inspections || {}).filter(([id, record]) => planned.has(id) && isDraft(record));
  const sops = Object.values(state.criticalSops || {}).filter((record) => String(record.scheduleId || "") === scheduleId && isDraft(record));
  const linked = Object.entries(state.linkedVerificationDrafts || {}).filter(([key]) => key.startsWith(`${scheduleId}::`));
  const extinguishers = Object.entries(state.extinguisherAssetDrafts || {}).filter(([key]) => key.startsWith(`${scheduleId}::`));
  return [...inspections, ...sops, ...linked, ...extinguishers].map(([id]) => String(id));
}

function buildReportCriticalSnapshot(schedule, store, assignedDevices, groups) {
  const records = Object.values(store?.criticalSopRecords || {});
  const fallback = Object.values(state.criticalSops || {}).filter((record) => String(record.scheduleId || "") === getScheduleKey(schedule));
  const source = records.length ? records : fallback;
  const byDevice = new Map(source.map((record) => [String(record.parentDeviceId || record.deviceId || record.deviceTag || ""), record]));
  return assignedDevices.filter((device) => isCriticalSopDevice(device)).map((device) => {
    const deviceId = device.id || device.tag;
    const record = byDevice.get(deviceId) || {};
    const template = criticalSopTemplates.find((item) => item.id === record.templateId || item.id === getCriticalSopTemplateIdForDevice(device));
    const savedSteps = record.steps || {};
    const steps = (template?.steps || Object.values(savedSteps)).map((step, index) => {
      const saved = savedSteps[index] || savedSteps[String(index)] || {};
      return {
        number: index + 1,
        title: String(step.title || saved.title || `Checklist step ${index + 1}`),
        critical: Boolean(step.critical),
        confirmed: Boolean(saved.confirmed),
        choice: String(saved.choice || ""),
        reading: String(saved.reading || ""),
        remark: String(saved.remark || ""),
        supervisor: String(saved.supervisor || ""),
        evidenceRefs: getReportEvidenceRefs(saved)
      };
    });
    const group = getReportSystemForDevice(device, groups);
    return {
      deviceId,
      deviceType: device.type || record.deviceType || "Critical System",
      title: record.title || template?.title || device.type || "Critical System Check",
      systemKey: group.id,
      systemLabel: group.label,
      floor: device.floorTitle || device.floor || record.floor || "-",
      location: displayDeviceLocation(device.location || record.location || ""),
      status: getReportResult(record),
      workflowStatus: String(record.workflowStatus || ""),
      finalRestorationComplete: Boolean(record.finalRestorationComplete),
      sopVersion: String(record.sopVersion || record.definitionVersion || record.templateVersion || "configured"),
      technicianId: String(record.technicianId || record.filledById || ""),
      technicianName: String(record.technicianName || record.filledBy || record.savedBy || ""),
      completedAt: String(record.updatedAt || record.savedAt || ""),
      generalRemarks: String(record.generalRemarks || ""),
      evidenceRefs: getReportEvidenceRefs(record),
      steps
    };
  });
}

function buildReportLinkedVerificationSnapshot(schedule) {
  return getScheduleLinkedVerificationDefinitions(schedule).map((definition) => {
    const linked = calculateClientLinkedVerificationState(schedule, definition);
    return {
      linkedVerificationId: definition.linkedVerificationId,
      verificationType: definition.verificationType,
      title: definition.title,
      systemId: definition.systemId,
      definitionVersion: definition.definitionVersion,
      status: linked.status,
      sides: linked.sides.map((side) => ({
        sideId: side.sideId,
        sideName: side.sideName,
        location: side.location || side.sideLocation || "",
        assignedTechnicianId: side.assignedTechnicianId || "",
        assignedTechnicianName: side.assignedTechnicianName || "",
        technicianId: side.record?.technicianId || "",
        technicianName: side.record?.technicianName || "",
        result: side.record?.result || "PENDING",
        timestamp: side.record?.timestamp || side.record?.localCompletedAt || "",
        syncStatus: side.record?.syncStatus || (side.draft ? "LOCAL_COMPLETE_AWAITING_SYNC" : "PENDING"),
        evidenceRefs: getReportEvidenceRefs(side.record || side.draft || {})
      }))
    };
  });
}

function buildReportExtinguisherSnapshot(store, schedule) {
  const snapshot = store?.extinguisherAssetSnapshot;
  if (!snapshot) return null;
  const records = Object.values(store.extinguisherVerificationRecords || {});
  const proposals = Object.values(store.extinguisherChangeProposals || {});
  const byAsset = new Map(records.map((record) => [record.assetId, record]));
  const counts = { expected: snapshot.assets?.length || 0, verified: 0, missing: 0, moved: 0, newUnitFound: 0, fault: 0, replaced: 0, pending: 0, pendingMasterChanges: 0 };
  const assets = (snapshot.assets || []).map((asset) => {
    const record = byAsset.get(asset.assetId) || {};
    const result = String(record.result || "PENDING").toUpperCase();
    const countKey = { VERIFIED: "verified", MISSING: "missing", MOVED: "moved", FAULT: "fault", REPLACED: "replaced" }[result] || "pending";
    counts[countKey] += 1;
    return {
      assetId: asset.assetId,
      serialNumber: asset.serialNumber,
      agentType: asset.agentType || "",
      sizeKg: asset.sizeKg || "",
      floor: asset.floor || "",
      expectedLocation: asset.location || "",
      result,
      currentLocation: record.currentLocation || "",
      replacementSerial: record.replacementSerial || "",
      notes: record.notes || "",
      technicianId: record.technicianId || "",
      technicianName: record.technicianName || "",
      timestamp: record.timestamp || record.updatedAt || "",
      evidenceRefs: getReportEvidenceRefs(record)
    };
  });
  const found = records.filter((record) => record.result === "NEW_UNIT_FOUND").map((record) => ({
    assetId: record.assetId,
    serialNumber: record.serialNumber,
    result: "NEW_UNIT_FOUND",
    currentLocation: record.currentLocation || "",
    notes: record.notes || "",
    technicianName: record.technicianName || "",
    timestamp: record.timestamp || record.updatedAt || "",
    evidenceRefs: getReportEvidenceRefs(record)
  }));
  counts.newUnitFound = found.length;
  counts.pendingMasterChanges = proposals.filter((proposal) => proposal.status === "PENDING_ADMIN_REVIEW").length;
  return {
    snapshotId: snapshot.snapshotId || "",
    masterRevision: Number(snapshot.masterRevision || 0),
    sourceDocuments: (snapshot.sourceDocuments || []).map((source) => ({ name: source.name || "", reference: source.reference || "" })),
    counts,
    assets,
    newUnitsFound: found,
    collectionReturn: {
      tracking: { ...(schedule?.tracking || {}) },
      extinguisherDetails: schedule?.extinguisherDetails || "",
      unitDetails: { ...(schedule?.extinguisherUnitDetails || schedule?.unitDetails || {}) },
      photoEvidenceRefs: Object.entries(schedule?.photoProof || {}).flatMap(([type, photos]) => (photos || []).map((photo) => ({
        type,
        name: typeof photo === "string" ? photo : photo?.name || "Evidence",
        photoUrl: typeof photo === "object" ? photo?.photoUrl || "" : ""
      })))
    }
  };
}

function buildReportSnapshot(schedule, options = {}) {
  const submission = getScheduleReportSubmission(schedule) || {};
  if (!options.forceLive && submission.reportSnapshot && isScheduleAdminApproved(schedule)) {
    return submission.reportSnapshot;
  }
  const scheduleId = getScheduleKey(schedule);
  const cache = getSharedJobCache(schedule);
  const store = cache?.store || {};
  const assignedDevices = getScheduledAssignedDevices(schedule);
  const plannedIds = assignedDevices.map((device) => device.id || device.tag).filter(Boolean);
  const groups = getTechnicianFireSystemGroups(schedule);
  const criticalItems = buildReportCriticalSnapshot(schedule, store, assignedDevices, groups);
  const criticalIds = new Set(criticalItems.map((item) => item.deviceId));
  const devices = assignedDevices.filter((device) => !criticalIds.has(device.id || device.tag)).map((device) => {
    const record = getStoredInspectionForDevice(device, schedule) || {};
    const group = getReportSystemForDevice(device, groups);
    return {
      deviceId: device.id || device.tag,
      deviceType: device.type || "Device",
      systemKey: group.id,
      systemLabel: group.label,
      floor: device.floorTitle || device.floor || "-",
      location: displayDeviceLocation(device.location || ""),
      result: getReportResult(record),
      notes: String(record.notes || ""),
      correctiveAction: String(record.action || record.correctiveAction || ""),
      technicianId: String(record.technicianId || record.inspectedById || ""),
      technicianName: String(record.technicianName || record.inspectedBy || ""),
      inspectedAt: String(record.inspectedAt || record.updatedAt || ""),
      durationMs: Number(record.checklistTotalDurationMs || record.checklistDurationMs || 0),
      evidenceRefs: getReportEvidenceRefs(record),
      revision: Number(record.revision || record.sharedRevision || 0)
    };
  });
  const resultByDevice = new Map([...devices, ...criticalItems].map((item) => [item.deviceId, item]));
  const systemTotals = groups.map((group) => {
    const results = [...new Set(group.devices.map((device) => device.id || device.tag))].map((id) => resultByDevice.get(id)).filter(Boolean);
    const pass = results.filter((item) => item.status === "PASS" || item.result === "PASS").length;
    const fault = results.filter((item) => item.status === "FAULT" || item.result === "FAULT").length;
    const completed = pass + fault;
    return {
      systemKey: group.id,
      label: group.label,
      assigned: results.length,
      pass,
      fault,
      pending: Math.max(0, results.length - pass - fault),
      completed,
      completionPercent: results.length ? Math.round((completed / results.length) * 100) : 0,
      criticalAssigned: results.filter((item) => criticalIds.has(item.deviceId)).length
    };
  });
  const passCount = [...devices, ...criticalItems].filter((item) => item.result === "PASS" || item.status === "PASS").length;
  const faultCount = [...devices, ...criticalItems].filter((item) => item.result === "FAULT" || item.status === "FAULT").length;
  const pendingCount = Math.max(0, assignedDevices.length - passCount - faultCount);
  const suggestedPins = getReportSuggestedPinsForSchedule(schedule).map((request) => ({
    requestId: request.id,
    scheduleId: request.scheduleId,
    label: request.label || "Suggested device",
    deviceType: request.type || request.system || "",
    floor: request.floor || request.floorTitle || "",
    location: request.location || "",
    status: request.status || "PENDING_ADMIN_REVIEW",
    requestedBy: request.requestedBy || request.createdBy || "",
    requestedAt: request.requestedAt || request.createdAt || "",
    note: request.reason || request.note || "",
    evidenceRefs: getReportEvidenceRefs({ evidenceRefs: request.photoEvidence, photo: request.photo })
  }));
  const unsyncedRecordIds = getReportUnsyncedRecords(schedule, plannedIds);
  const profile = { companyName: schedule.companyName || "", siteName: schedule.siteName || "" };
  const coverage = getAnnualCoverageSummary(profile, {
    frequencyPercent: schedule.contractFrequencyPercent || schedule.serviceFrequencyPercent,
    annualCycleId: schedule.annualCycleId || schedule.contractCycleId,
    date: schedule.date
  });
  const nextSchedule = state.schedules
    .filter((item) => item.scheduleId !== scheduleId && item.companyName === schedule.companyName && item.siteName === schedule.siteName && item.date && item.date > schedule.date)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)))[0];
  const linkedVerifications = buildReportLinkedVerificationSnapshot(schedule);
  const extinguisher = buildReportExtinguisherSnapshot(store, schedule);
  const linkedReviewCount = linkedVerifications.filter((item) => item.status === "MISMATCH_REVIEW_REQUIRED").length;
  const overallStatus = faultCount || linkedReviewCount
    ? "DEFECTS / REVIEW REQUIRED"
    : pendingCount
      ? "IN PROGRESS"
      : isScheduleAdminApproved(schedule) ? "APPROVED" : "COMPLETED - AWAITING REVIEW";
  const faults = devices.filter((item) => item.result === "FAULT").map((item) => ({
    deviceId: item.deviceId,
    systemLabel: item.systemLabel,
    floor: item.floor,
    location: item.location,
    finding: item.notes,
    correctiveAction: item.correctiveAction,
    evidenceRefs: item.evidenceRefs
  }));
  const generatedAt = new Date().toISOString();
  const evidence = [
    ...devices.flatMap((item) => item.evidenceRefs.map((ref) => ({ ...ref, sourceType: "device", sourceId: item.deviceId }))),
    ...criticalItems.flatMap((item) => item.evidenceRefs.map((ref) => ({ ...ref, sourceType: "critical", sourceId: item.deviceId }))),
    ...suggestedPins.flatMap((item) => item.evidenceRefs.map((ref) => ({ ...ref, sourceType: "suggested-pin", sourceId: item.requestId }))),
    ...linkedVerifications.flatMap((item) => item.sides.flatMap((side) => side.evidenceRefs.map((ref) => ({ ...ref, sourceType: "linked-verification", sourceId: `${item.linkedVerificationId}::${side.sideId}` })))),
    ...(extinguisher ? [...extinguisher.assets, ...extinguisher.newUnitsFound].flatMap((item) => item.evidenceRefs.map((ref) => ({ ...ref, sourceType: "extinguisher", sourceId: item.assetId }))) : [])
  ];
  const createdAt = schedule.reportCreatedAt || submission.submittedAt || generatedAt;
  return {
    schemaVersion: "rmt-report-snapshot-v1",
    reportId: `REPORT-${scheduleId}`,
    scheduleId,
    jobId: schedule.jobId || `JOB-${scheduleId}`,
    clientId: schedule.clientId || schedule.companyName || "",
    siteId: schedule.siteId || schedule.siteName || "",
    createdAt,
    submittedAt: submission.submittedAt || schedule.reportSubmittedAt || "",
    reviewedAt: submission.reviewedAt || schedule.reviewedAt || "",
    approvedAt: submission.status === "APPROVED_BY_ADMIN" ? submission.reviewedAt || schedule.reviewedAt || "" : "",
    status: options.snapshotStatus === "APPROVED_SNAPSHOT" ? "APPROVED_BY_ADMIN" : submission.status || schedule.reportSubmissionStatus || schedule.status || "",
    snapshotStatus: options.snapshotStatus || "LIVE_PREVIEW",
    generatedAt,
    generatedBy: getCurrentUserName(),
    source: {
      mode: cache?.online ? "AUTHORITATIVE_SHARED_RECORDS" : "CACHED_FALLBACK",
      sharedStoreSchemaVersion: store.schemaVersion || "",
      reportSubmissionRevision: Number(submission.revision || 0)
    },
    header: {
      clientName: schedule.companyName || "-",
      siteName: schedule.siteName || "-",
      serviceDate: schedule.date || "",
      serviceTime: schedule.time || "",
      reportReference: schedule.reportReference || scheduleId,
      serviceType: schedule.serviceType || schedule.scopeLabel || "Maintenance Inspection",
      frequencyPercent: Number(schedule.contractFrequencyPercent || schedule.serviceFrequencyPercent || 0),
      nextServiceDate: nextSchedule?.date || "",
      technicianName: submission.submittedBy || schedule.reportSubmittedBy || state.activeJob?.inspector || "-"
    },
    summary: {
      overallStatus,
      assignedCount: assignedDevices.length,
      completedCount: passCount + faultCount,
      passCount,
      faultCount,
      pendingCount,
      suggestedPinCount: suggestedPins.length,
      linkedReviewCount,
      systemTotals
    },
    systems: systemTotals,
    coverage: {
      annualCycleId: coverage.annualCycleId,
      eligibleCount: coverage.eligibleCount,
      uniqueCoveredCount: coverage.uniqueCoveredCount,
      uniqueCoveragePercent: coverage.uniqueCoveragePercent,
      totalInspections: coverage.totalInspections,
      repeatInspections: coverage.repeatInspections,
      faultRecheckRepeatCount: coverage.faultRecheckRepeatCount
    },
    devices,
    deviceResults: devices,
    criticalItems,
    faults,
    suggestedPins,
    linkedVerifications,
    extinguisher,
    extinguisherSummary: extinguisher?.counts || null,
    extinguisherAssets: extinguisher?.assets || [],
    evidence,
    acknowledgement: {
      ...(submission.clientAcknowledgement || {}),
      signedBy: store.signOff?.supervisorName || store.signOff?.clientName || "",
      signedAt: store.signOff?.signedAt || submission.clientAcknowledgement?.signedAt || "",
      signatureCaptured: Boolean(store.signOff?.signatureData || store.signOff?.supervisorSignatureData || submission.clientAcknowledgement?.signatureCaptured)
    },
    review: {
      status: submission.status || schedule.reportSubmissionStatus || schedule.status || "",
      submittedBy: submission.submittedBy || schedule.reportSubmittedBy || "",
      submittedAt: submission.submittedAt || schedule.reportSubmittedAt || "",
      reviewedBy: submission.reviewedBy || schedule.reviewedBy || "",
      reviewedAt: submission.reviewedAt || schedule.reviewedAt || "",
      reviewNote: submission.reviewNote || ""
    },
    dataIntegrity: {
      serverOnline: Boolean(cache?.online),
      unsyncedCount: unsyncedRecordIds.length,
      unsyncedRecordIds
    }
  };
}

function renderReportEvidenceReferences(refs = []) {
  if (!refs.length) return `<span class="report-muted">No evidence reference</span>`;
  return `<ul class="report-evidence-list">${refs.map((ref) => `<li>${ref.photoUrl ? `<img src="${escapeHtml(ref.photoUrl)}" alt="${escapeHtml(ref.type)} evidence">` : ""}<span><b>${escapeHtml(ref.type)}:</b> ${escapeHtml(ref.name)}${ref.stampedEvidenceId ? " (stamped display)" : ""}</span></li>`).join("")}</ul>`;
}

function renderReportSnapshot(snapshot) {
  state.activeReportSnapshot = snapshot;
  const title = `${snapshot.header.clientName} / ${snapshot.header.siteName}`;
  document.querySelector("#reportDocumentTitle").textContent = title;
  document.querySelector("#reportDetailTitle").textContent = title;
  document.querySelector("#reportDetailReference").textContent = snapshot.header.reportReference;
  document.querySelector("#reportDate").textContent = snapshot.header.serviceDate || "-";
  document.querySelector("#reportReference").textContent = snapshot.header.reportReference;
  document.querySelector("#reportFrequency").textContent = snapshot.header.frequencyPercent ? `${snapshot.header.frequencyPercent}% maintenance` : snapshot.header.serviceType;
  document.querySelector("#reportInspectorName").textContent = snapshot.header.technicianName || "-";
  const status = document.querySelector("#reportStatus");
  status.textContent = snapshot.summary.overallStatus;
  status.dataset.status = snapshot.summary.overallStatus.toLowerCase().replace(/[^a-z]+/g, "-").replace(/^-|-$/g, "");
  document.querySelector("#reportSummaryText").textContent = `${snapshot.summary.completedCount} of ${snapshot.summary.assignedCount} assigned items were completed. ${snapshot.summary.passCount} passed and ${snapshot.summary.faultCount} fault item(s) were recorded.${snapshot.header.nextServiceDate ? ` Next scheduled service: ${snapshot.header.nextServiceDate}.` : ""}`;
  document.querySelector("#reportSummaryMetrics").innerHTML = [
    ["Assigned", snapshot.summary.assignedCount],
    ["Completed", snapshot.summary.completedCount],
    ["Pass", snapshot.summary.passCount],
    ["Fault", snapshot.summary.faultCount],
    ["Pending", snapshot.summary.pendingCount],
    ["Suggested pins", snapshot.summary.suggestedPinCount]
  ].map(([label, value]) => `<div><strong>${value}</strong><span>${label}</span></div>`).join("");
  document.querySelector("#reportSystemSummaryRows").innerHTML = snapshot.summary.systemTotals.map((system) => `
    <tr><td>${escapeHtml(system.label)}</td><td>${system.assigned}</td><td>${system.completed}</td><td>${system.pass}</td><td>${system.fault}</td><td>${system.completionPercent}%</td></tr>
  `).join("") || `<tr><td colspan="6">No configured system results.</td></tr>`;
  document.querySelector("#reportCoverageSummary").innerHTML = `
    <p><strong>${snapshot.coverage.uniqueCoveragePercent}% unique coverage</strong></p>
    <p>${snapshot.coverage.uniqueCoveredCount} of ${snapshot.coverage.eligibleCount} eligible devices | ${escapeHtml(snapshot.coverage.annualCycleId || "No cycle")}</p>
    <p>${snapshot.summary.assignedCount} planned | ${snapshot.summary.completedCount} completed | ${snapshot.summary.passCount} pass | ${snapshot.summary.faultCount} fault</p>
    <p>${snapshot.coverage.totalInspections} total annual inspections | ${snapshot.coverage.repeatInspections} repeats | ${snapshot.coverage.faultRecheckRepeatCount} fault/recheck repeats</p>`;
  document.querySelector("#reportCriticalSummary").innerHTML = snapshot.criticalItems.length
    ? snapshot.criticalItems.map((item) => `<p><strong>${escapeHtml(item.deviceId)}</strong> ${escapeHtml(item.title)} <span class="report-result ${item.status === "PASS" ? "pass" : "pending"}">${escapeHtml(item.status)}</span></p>`).join("")
    : `<p class="report-muted">No critical system record in this job scope.</p>`;
  document.querySelector("#reportKeyFindings").innerHTML = snapshot.faults.length
    ? snapshot.faults.map((fault) => `<p><strong>${escapeHtml(fault.deviceId)}</strong> ${escapeHtml(fault.finding || "Fault recorded")}</p>`).join("")
    : `<p class="report-muted">No fault findings recorded.</p>`;
  const recommendations = snapshot.faults.filter((fault) => fault.correctiveAction);
  document.querySelector("#reportRecommendations").innerHTML = recommendations.length
    ? recommendations.map((fault) => `<p><strong>${escapeHtml(fault.deviceId)}</strong> ${escapeHtml(fault.correctiveAction)}</p>`).join("")
    : `<p class="report-muted">No corrective recommendation was recorded.</p>`;

  renderReportCriticalSystems(snapshot);
  const grouped = new Map();
  snapshot.devices.forEach((device) => {
    const key = `${device.systemLabel}::${device.floor}`;
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(device);
  });
  document.querySelector("#reportRows").innerHTML = [...grouped.entries()].map(([key, items]) => {
    const [system, floor] = key.split("::");
    return items.map((item, index) => `
      <tr class="${item.result === "FAULT" ? "report-fault-row" : ""}">
        <td>${index === 0 ? `<strong>${escapeHtml(system)}</strong><br><span>${escapeHtml(floor)}</span>` : ""}</td>
        <td><strong>${escapeHtml(item.deviceId)}</strong><br>${escapeHtml(item.deviceType)}<br><span>${escapeHtml(item.location)}</span></td>
        <td><span class="report-result ${item.result === "PASS" ? "pass" : item.result === "FAULT" ? "fault" : "pending"}">${escapeHtml(item.result)}</span></td>
        <td>${escapeHtml(item.technicianName || "-")}<br><span>${escapeHtml(formatReportDateTime(item.inspectedAt))}</span></td>
        <td>${renderReportEvidenceReferences(item.evidenceRefs)}${item.result === "FAULT" ? `<p><b>Finding:</b> ${escapeHtml(item.notes || "-")}</p><p><b>Corrective:</b> ${escapeHtml(item.correctiveAction || "-")}</p>` : item.notes ? `<p>${escapeHtml(item.notes)}</p>` : ""}</td>
      </tr>`).join("");
  }).join("") || `<tr><td colspan="5">No field-device records in this job.</td></tr>`;
  document.querySelector("#reportDefectList").innerHTML = snapshot.faults.length
    ? snapshot.faults.map((fault) => `<article class="report-note fail-note"><strong>${escapeHtml(fault.deviceId)} - ${escapeHtml(fault.systemLabel)}</strong><p>${escapeHtml(fault.finding || "Fault recorded")}</p><p><b>Recorded corrective action:</b> ${escapeHtml(fault.correctiveAction || "-")}</p>${renderReportEvidenceReferences(fault.evidenceRefs)}</article>`).join("")
    : `<p class="report-muted">No faults recorded.</p>`;
  document.querySelector("#reportSetupList").innerHTML = snapshot.suggestedPins.length
    ? snapshot.suggestedPins.map((request) => `<article class="report-note"><strong>${escapeHtml(request.label)} - ${escapeHtml(request.deviceType)}</strong><p>${escapeHtml(request.floor)} | ${escapeHtml(request.location)}</p><p>${escapeHtml(request.note || "-")}</p><p>${escapeHtml(request.status)} | ${escapeHtml(request.requestedBy)} | ${escapeHtml(formatReportDateTime(request.requestedAt))}</p>${renderReportEvidenceReferences(request.evidenceRefs)}</article>`).join("")
    : `<p class="report-muted">No suggested pin recorded for this job context.</p>`;
  renderReportExtinguisherSnapshot(snapshot.extinguisher);
  renderReportLinkedVerificationSnapshot(snapshot.linkedVerifications);
  document.querySelector("#reportAcknowledgement").innerHTML = `
    <div class="report-ack-grid">
      <p><strong>Client / witness</strong>${escapeHtml(snapshot.acknowledgement.witnessName || snapshot.acknowledgement.signedBy || "-")}</p>
      <p><strong>Technician</strong>${escapeHtml(snapshot.acknowledgement.technicianName || snapshot.review.submittedBy || "-")}</p>
      <p><strong>Signature</strong>${snapshot.acknowledgement.signatureCaptured ? "Captured" : "Not captured"}</p>
      <p><strong>Signed</strong>${escapeHtml(formatReportDateTime(snapshot.acknowledgement.signedAt))}</p>
      <p><strong>Admin review</strong>${escapeHtml(snapshot.review.status || "Not reviewed")}</p>
      <p><strong>Reviewed by</strong>${escapeHtml(snapshot.review.reviewedBy || "-")}</p>
    </div>`;
  document.querySelector("#reportFooter").textContent = `${snapshot.reportId} | Snapshot ${snapshot.schemaVersion} | Generated ${formatReportDateTime(snapshot.generatedAt)}`;
}

function renderReportExtinguisherSnapshot(extinguisher) {
  const section = document.querySelector("#reportExtinguisherSection");
  const container = document.querySelector("#reportExtinguisherDetails");
  section.classList.toggle("hidden", !extinguisher);
  if (!extinguisher) {
    container.innerHTML = "";
    return;
  }
  const counts = extinguisher.counts;
  const collection = extinguisher.collectionReturn || {};
  const tracking = collection.tracking || {};
  const hasCollectionData = Object.values(tracking).some((value) => String(value || "").trim())
    || collection.extinguisherDetails
    || Object.values(collection.unitDetails || {}).some((value) => String(value || "").trim());
  container.innerHTML = `
    <div class="report-summary-metrics">${[["Expected", counts.expected], ["Verified", counts.verified], ["Missing", counts.missing], ["Moved", counts.moved], ["Fault", counts.fault], ["Replaced", counts.replaced], ["New found", counts.newUnitFound], ["Master changes", counts.pendingMasterChanges]].map(([label, value]) => `<div><strong>${value}</strong><span>${label}</span></div>`).join("")}</div>
    ${hasCollectionData ? `<div class="report-ext-collection"><p><strong>Collection / return:</strong> Total ${Number(tracking.totalUnits || 0)}, collected ${Number(tracking.collectedUnits || 0)}, returned ${Number(tracking.returnedUnits || 0)}, loan issued ${Number(tracking.loanUnits || 0)}, loan returned ${Number(tracking.loanReturnedUnits || 0)}.</p>${collection.extinguisherDetails ? `<p>${escapeHtml(collection.extinguisherDetails)}</p>` : ""}${collection.unitDetails?.loanUnitDetails ? `<p><strong>Loan unit:</strong> ${escapeHtml(collection.unitDetails.loanUnitDetails)}</p>` : ""}${collection.photoEvidenceRefs?.length ? renderReportEvidenceReferences(collection.photoEvidenceRefs) : ""}</div>` : ""}
    <div class="report-table-wrap"><table><thead><tr><th>Serial / Type</th><th>Expected / Current Location</th><th>Result</th><th>Technician / Time</th><th>Evidence / Notes</th></tr></thead><tbody>
      ${[...extinguisher.assets, ...extinguisher.newUnitsFound].map((asset) => `<tr><td><strong>${escapeHtml(asset.serialNumber)}</strong><br>${escapeHtml([asset.agentType, asset.sizeKg].filter(Boolean).join(" "))}</td><td>${escapeHtml(asset.expectedLocation || "-")}<br>${asset.currentLocation ? `<b>Current:</b> ${escapeHtml(asset.currentLocation)}` : ""}</td><td>${escapeHtml(asset.result)}</td><td>${escapeHtml(asset.technicianName || "-")}<br>${escapeHtml(formatReportDateTime(asset.timestamp))}</td><td>${renderReportEvidenceReferences(asset.evidenceRefs)}${asset.notes ? `<p>${escapeHtml(asset.notes)}</p>` : ""}${asset.replacementSerial ? `<p><b>Replacement:</b> ${escapeHtml(asset.replacementSerial)}</p>` : ""}</td></tr>`).join("")}
    </tbody></table></div>`;
}

function renderReportLinkedVerificationSnapshot(items) {
  const section = document.querySelector("#reportLinkedVerificationSection");
  const container = document.querySelector("#reportLinkedVerificationDetails");
  section.classList.toggle("hidden", !items.length);
  container.innerHTML = items.map((item) => `
    <article class="report-linked-card">
      <div><strong>${escapeHtml(item.title)}</strong><span class="report-result ${item.status === "VERIFIED" ? "pass" : item.status === "MISMATCH_REVIEW_REQUIRED" ? "fault" : "pending"}">${escapeHtml(item.status.replaceAll("_", " "))}</span></div>
      <div class="report-table-wrap"><table><thead><tr><th>Side / Location</th><th>Technician</th><th>Result / Time</th><th>Sync / Evidence</th></tr></thead><tbody>${item.sides.map((side) => `<tr><td><strong>${escapeHtml(side.sideName)}</strong><br>${escapeHtml(side.location)}</td><td>${escapeHtml(side.technicianName || side.assignedTechnicianName || "-")}</td><td>${escapeHtml(side.result)}<br>${escapeHtml(formatReportDateTime(side.timestamp))}</td><td>${escapeHtml(side.syncStatus)}${renderReportEvidenceReferences(side.evidenceRefs)}</td></tr>`).join("")}</tbody></table></div>
    </article>`).join("");
}

async function showReport(scheduleId = "") {
  if (state.scheduleStartInProgressId) {
    document.querySelector("#syncState").textContent = "Please wait until the scheduled job finishes loading before generating the report.";
    return;
  }
  const reportSchedule = getReportSchedule(scheduleId);
  if (!reportSchedule) {
    document.querySelector("#syncState").textContent = "Select a scheduled job before opening its report.";
    return;
  }
  state.activeReportScheduleId = reportSchedule.scheduleId;
  if (reportSchedule) {
    await requestSharedJobState(reportSchedule, { migrate: false });
  }
  const snapshot = buildReportSnapshot(reportSchedule);
  applyCompanyBranding();
  workspace.classList.add("hidden");
  document.querySelector("#reportView").classList.remove("hidden");
  const reportTitle = document.querySelector("#reportView .report-header h1");
  if (reportTitle) {
    reportTitle.textContent = `${snapshot.header.clientName} / ${snapshot.header.siteName}`;
  }
  renderReportSnapshot(snapshot);
  document.querySelector("#reportSaveStatus").textContent = snapshot.snapshotStatus === "APPROVED_SNAPSHOT"
    ? "Approved snapshot"
    : snapshot.dataIntegrity.serverOnline ? "Live authoritative preview" : "Cached preview - approval blocked";
}

async function saveInspectionRunToPc() {
  const button = document.querySelector("#saveRunBtn");
  const status = document.querySelector("#reportSaveStatus");
  const originalText = button.textContent;
  button.disabled = true;
  button.textContent = "Saving...";
  status.textContent = "Saving run data...";

  try {
    const payload = buildInspectionRunPayload();
    const result = await postInspectionRun(payload);

    writeStoredJson("rmtLastInspectionRunSave", result);
    status.textContent = `Saved to PC folder: ${result.runKey}`;
    document.querySelector("#syncState").textContent = "Inspection run saved to PC folder";
  } catch (error) {
    console.warn("Unable to save inspection run", error);
    status.textContent = "Unable to save run. Keep this page open and try again.";
  } finally {
    button.disabled = false;
    button.textContent = originalText;
  }
}

async function postInspectionRun(payload) {
  const response = await fetch("/api/save-inspection-run", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  const result = await response.json();
  if (!response.ok || !result.ok) {
    throw new Error(result.error || "Unable to save inspection run");
  }
  return result;
}

function createClientSharedStore(schedule) {
  const scheduleId = getScheduleKey(schedule);
  return {
    schemaVersion: "shared-records-v1",
    scheduleId,
    scheduleSnapshot: getScheduleSnapshotForSharedApi(schedule),
    inspectionRecords: {},
    criticalSopRecords: {},
    systemCheckRecords: {},
    itemClaims: {},
    linkedVerificationDefinitions: {},
    linkedVerificationSideRecords: {},
    linkedVerificationConflicts: {},
    linkedVerificationAudit: [],
    signOff: null
  };
}

function ensureSharedCacheForSchedule(schedule) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return null;
  const cache = getSharedJobCache(scheduleId);
  if (cache?.store) return cache;
  return setSharedJobCache(scheduleId, createClientSharedStore(schedule), { online: false });
}

function updateSharedCacheWithRecord(schedule, collectionName, record, progress = null) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId || !record?.recordId) return;
  const cache = ensureSharedCacheForSchedule(schedule);
  const store = {
    ...cache.store,
    [collectionName]: {
      ...(cache.store?.[collectionName] || {}),
      [record.recordId]: record
    }
  };
  setSharedJobCache(scheduleId, {
    store,
    progress: progress || calculateLocalSharedProgress(store)
  }, { online: true });
}

function getExpectedInspectionRevision(deviceId, schedule) {
  const shared = getSharedInspectionRecord(deviceId, schedule);
  if (shared) return Number(shared.revision || 0);
  return Number(state.inspections?.[deviceId]?.sharedRevision || 0);
}

function getExpectedCriticalSopRevision(record, schedule) {
  const shared = getSharedCriticalSopRecordByDevice(record.parentDeviceId || record.deviceId || record.deviceTag, record.templateId, schedule);
  if (shared) return Number(shared.revision || 0);
  return Number(record.sharedRevision || 0);
}

function enqueueSharedSave(queueKey, task) {
  if (!queueKey) return task();
  const previous = state.sharedSaveQueues[queueKey] || Promise.resolve();
  const run = previous.catch(() => {}).then(task);
  const guard = run.catch(() => {});
  state.sharedSaveQueues[queueKey] = guard;
  return run.finally(() => {
    if (state.sharedSaveQueues[queueKey] === guard) {
      delete state.sharedSaveQueues[queueKey];
    }
  });
}

function buildSharedInspectionRecord(device, inspection, schedule) {
  const scheduleId = getScheduleKey(schedule);
  const deviceId = device.id || device.tag;
  const checklistQuestions = device.questions || getChecklistQuestions(device.type);
  const systemId = inspection.systemId || getActiveTechnicianSystemKey(schedule) || "";
  const systemDefinition = getTechnicianFireSystemDefinition(systemId);
  return {
    recordId: getInspectionRecordId(scheduleId, deviceId),
    jobId: state.activeJob?.jobId || `JOB-${scheduleId}`,
    scheduleId,
    deviceId,
    checklistItemId: deviceId,
    checklistTemplateId: device.type || "Device Checklist",
    checklistQuestionCount: checklistQuestions.length,
    clientId: inspection.clientId || schedule?.clientId || schedule?.companyName || "",
    companyName: state.activeJob?.companyName || schedule?.companyName || "",
    siteId: inspection.siteId || schedule?.siteId || schedule?.siteName || "",
    siteName: state.activeJob?.siteName || schedule?.siteName || "",
    systemId,
    systemName: inspection.systemName || systemDefinition?.label || "",
    floorId: inspection.floorId || device.floorId || "",
    floor: device.floor || device.floorTitle || "",
    location: displayDeviceLocation(device.location || ""),
    deviceType: device.type || "",
    technicianId: getCurrentUserId(),
    technicianName: getCurrentUserName(),
    technicianRole: getCurrentUserRole(),
    status: inspection.status || "pending",
    answers: inspection.answers || [],
    notes: inspection.notes || "",
    action: inspection.action || "",
    beforePhoto: inspection.beforePhoto || "",
    afterPhoto: inspection.afterPhoto || "",
    evidenceRefs: [
      inspection.beforePhotoEvidence ? { ...inspection.beforePhotoEvidence, type: "before" } : inspection.beforePhoto ? { type: "before", name: inspection.beforePhoto } : null,
      inspection.afterPhotoEvidence ? { ...inspection.afterPhotoEvidence, type: "after" } : inspection.afterPhoto ? { type: "after", name: inspection.afterPhoto } : null
    ].filter(Boolean),
    inspectedAt: inspection.inspectedAt || new Date().toISOString(),
    checklistStartedAt: inspection.checklistStartedAt || "",
    checklistDurationMs: inspection.checklistDurationMs || 0,
    checklistTotalDurationMs: inspection.checklistTotalDurationMs || 0
  };
}

async function saveSharedInspectionRecord(device, inspection, schedule) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return { ok: false, localOnly: true, reason: "No scheduled job" };
  const queueKey = `inspection::${scheduleId}::${device.id || device.tag}`;
  return enqueueSharedSave(queueKey, async () => {
    const record = buildSharedInspectionRecord(device, inspection, schedule);
    const expectedRevision = getExpectedInspectionRevision(record.deviceId, schedule);
    try {
      const response = await fetch(`/api/jobs/${encodeURIComponent(scheduleId)}/inspection-records`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          expectedRevision,
          schedule: getScheduleSnapshotForSharedApi(schedule),
          record
        })
      });
      const payload = await response.json();
      if (response.status === 409 && payload.conflict) {
        const current = payload.current;
        if (current?.deviceId) {
          updateSharedCacheWithRecord(schedule, "inspectionRecords", current);
          state.inspections[current.deviceId] = {
            ...(state.inspections[current.deviceId] || {}),
            ...inspectionRecordToLocal(current)
          };
        }
        return { ok: false, conflict: true, current, payload };
      }
      if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to save shared inspection record");
      updateSharedCacheWithRecord(schedule, "inspectionRecords", payload.record, payload.progress);
      state.inspections[payload.record.deviceId] = {
        ...(state.inspections[payload.record.deviceId] || {}),
        ...inspectionRecordToLocal(payload.record)
      };
      return { ok: true, record: payload.record, progress: payload.progress };
    } catch (error) {
      console.warn("Shared inspection record unavailable", error);
      markSharedJobUnavailable(scheduleId, error);
      return { ok: false, offline: true, error };
    }
  });
}

function buildSharedCriticalSopRecord(record, schedule) {
  const scheduleId = getScheduleKey(schedule);
  const parentDeviceId = record.deviceTag || record.parentDeviceId || record.deviceId || record.templateId;
  return {
    ...record,
    recordId: getCriticalSopSharedRecordId(scheduleId, record.templateId, parentDeviceId),
    jobId: state.activeJob?.jobId || `JOB-${scheduleId}`,
    scheduleId,
    parentDeviceId,
    deviceId: parentDeviceId,
    technicianId: getCurrentUserId(),
    technicianName: getCurrentUserName(),
    technicianRole: getCurrentUserRole(),
    status: record.workflowStatus === "complete" || record.finalRestorationComplete ? "pass" : getCriticalSopCompleteCount(getCriticalSopTemplate(record.templateId), record) > 0 ? "partial" : "pending",
    evidenceRefs: [
      record.beforePhotoEvidence ? { ...record.beforePhotoEvidence, type: "before", name: record.beforePhoto || record.beforePhotoEvidence.originalFileName || "Before photo" } : null,
      record.afterPhotoEvidence ? { ...record.afterPhotoEvidence, type: "after", name: record.afterPhoto || record.afterPhotoEvidence.originalFileName || "After photo" } : null,
      ...Object.entries(record.steps || {}).map(([index, step]) => step?.photoEvidence
        ? { ...step.photoEvidence, type: "step", stepIndex: Number(index), name: step.photo || step.photoEvidence.originalFileName || `Step ${Number(index) + 1} photo` }
        : null)
    ].filter(Boolean)
  };
}

async function saveSharedCriticalSopRecord(record, schedule) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return { ok: false, localOnly: true, reason: "No scheduled job" };
  const parentDeviceId = record.deviceTag || record.parentDeviceId || record.deviceId || record.templateId;
  const queueKey = `critical-sop::${scheduleId}::${record.templateId}::${parentDeviceId}`;
  return enqueueSharedSave(queueKey, async () => {
    const sharedRecord = buildSharedCriticalSopRecord(record, schedule);
    const expectedRevision = getExpectedCriticalSopRevision(sharedRecord, schedule);
    try {
      const response = await fetch(`/api/jobs/${encodeURIComponent(scheduleId)}/critical-sop-records`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          expectedRevision,
          schedule: getScheduleSnapshotForSharedApi(schedule),
          record: sharedRecord
        })
      });
      const payload = await response.json();
      if (response.status === 409 && payload.conflict) {
        const current = payload.current;
        if (current?.recordId) {
          updateSharedCacheWithRecord(schedule, "criticalSopRecords", current);
          const key = getCriticalSopStorageKey(current.templateId, current.parentDeviceId || current.deviceId || current.deviceTag);
          state.criticalSops[key] = {
            ...(state.criticalSops[key] || {}),
            ...current,
            sharedRevision: Number(current.revision || 0),
            syncStatus: "synced"
          };
        }
        return { ok: false, conflict: true, current, payload };
      }
      if (response.status === 403) {
        return { ok: false, forbidden: true, reason: payload.reason || payload.error || "This technician is not assigned to this critical item." };
      }
      if (response.status === 400 || response.status === 422) {
        return { ok: false, invalid: true, reason: payload.reason || payload.error || "The server rejected this critical checklist record." };
      }
      if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to save shared critical SOP record");
      updateSharedCacheWithRecord(schedule, "criticalSopRecords", payload.record, payload.progress);
      const key = getCriticalSopStorageKey(payload.record.templateId, payload.record.parentDeviceId || payload.record.deviceId || payload.record.deviceTag);
      state.criticalSops[key] = {
        ...(state.criticalSops[key] || {}),
        ...payload.record,
        sharedRevision: Number(payload.record.revision || 0),
        syncStatus: "synced"
      };
      return { ok: true, record: payload.record, progress: payload.progress };
    } catch (error) {
      console.warn("Shared critical SOP record unavailable", error);
      markSharedJobUnavailable(scheduleId, error);
      return { ok: false, offline: true, error };
    }
  });
}

function getActiveSharedClaim(deviceId, schedule = getActiveTechnicianMaintenanceSchedule() || getTechMarkerScopeSchedule()) {
  const scheduleId = getScheduleKey(schedule);
  const store = getSharedStore(scheduleId);
  if (!scheduleId || !store?.itemClaims) return null;
  const recordId = `claim::${scheduleId}::${deviceId}`;
  const claim = store.itemClaims[recordId] || Object.values(store.itemClaims).find((item) => item.itemId === deviceId || item.deviceId === deviceId);
  if (!claim || claim.claimedBy === getCurrentUserId()) return null;
  const expiresAt = claim.expiresAt ? new Date(claim.expiresAt).getTime() : 0;
  if (expiresAt && expiresAt < Date.now()) return null;
  return claim;
}

function updateSharedCacheWithClaim(schedule, claim) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId || !claim?.recordId) return;
  const cache = ensureSharedCacheForSchedule(schedule);
  const store = {
    ...cache.store,
    itemClaims: {
      ...(cache.store?.itemClaims || {}),
      [claim.recordId]: claim
    }
  };
  setSharedJobCache(scheduleId, { store, progress: cache.progress || calculateLocalSharedProgress(store) }, { online: true });
}

async function claimSharedInspectionItem(device, schedule = getActiveTechnicianMaintenanceSchedule()) {
  const scheduleId = getScheduleKey(schedule);
  const itemId = getDeviceSessionKey(device);
  if (!scheduleId || !itemId || getCurrentUserRole() !== "Technician") return null;
  const otherClaim = getActiveSharedClaim(itemId, schedule);
  if (otherClaim) {
    document.querySelector("#syncState").textContent = `${itemId} is currently opened by ${otherClaim.claimedByName || otherClaim.claimedBy}. You can view it, but stale saves may be rejected.`;
  }
  try {
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();
    const response = await fetch(`/api/jobs/${encodeURIComponent(scheduleId)}/item-claims`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        schedule: getScheduleSnapshotForSharedApi(schedule),
        itemId,
        deviceId: itemId,
        claimedBy: getCurrentUserId(),
        claimedByName: getCurrentUserName(),
        expiresAt,
        status: "active"
      })
    });
    const payload = await response.json();
    if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to claim item");
    updateSharedCacheWithClaim(schedule, payload.claim);
    return payload.claim;
  } catch (error) {
    console.warn("Unable to update shared item claim", error);
    markSharedJobUnavailable(scheduleId, error);
    return null;
  }
}

async function submitSharedJobSignOff(signOff, schedule) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return { ok: false, localOnly: true };
  const latest = await requestSharedJobState(schedule, { migrate: false });
  if (!latest?.online) {
    return { ok: false, offline: true, reason: "Shared server is unavailable. Completion is blocked until sync is restored." };
  }
  const expectedRevision = Number(latest.store?.signOff?.revision || 0);
  try {
    const response = await fetch(`/api/jobs/${encodeURIComponent(scheduleId)}/signoff`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        expectedRevision,
        schedule: getScheduleSnapshotForSharedApi(schedule),
        signOff: {
          ...signOff,
          jobId: state.activeJob?.jobId || `JOB-${scheduleId}`,
          scheduleId,
          signedBy: getCurrentUserName(),
          signedById: getCurrentUserId(),
          signedRole: getCurrentUserRole()
        }
      })
    });
    const payload = await response.json();
    if (response.status === 409) {
      return { ok: false, conflict: Boolean(payload.conflict), blocked: Boolean(payload.blocked), payload };
    }
    if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to complete shared job");
    const cache = ensureSharedCacheForSchedule(schedule);
    const store = {
      ...cache.store,
      signOff: payload.signOff,
      status: "Completed",
      completedAt: payload.signOff?.signedAt || new Date().toISOString()
    };
    setSharedJobCache(scheduleId, { store, progress: payload.progress }, { online: true });
    return { ok: true, signOff: payload.signOff, progress: payload.progress };
  } catch (error) {
    console.warn("Shared sign-off unavailable", error);
    markSharedJobUnavailable(scheduleId, error);
    return { ok: false, offline: true, error };
  }
}

function getPendingMissingRequestsForSchedule(schedule) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return [];
  return state.requests.filter((request) => {
    return request.scheduleId === scheduleId
      && !isRequestApproved(request)
      && !isRequestRejected(request);
  });
}

function buildReportSubmissionRecord(schedule, signOff, summary) {
  const groups = getTechnicianFireSystemGroups(schedule);
  const pendingRequests = getPendingMissingRequestsForSchedule(schedule);
  return {
    recordId: `report-submission::${schedule.scheduleId}`,
    jobId: state.activeJob?.jobId || `JOB-${schedule.scheduleId}`,
    scheduleId: schedule.scheduleId,
    status: "AWAITING_ADMIN_REVIEW",
    submittedById: getCurrentUserId(),
    submittedBy: getCurrentUserName(),
    submittedRole: getCurrentUserRole(),
    submittedAt: new Date().toISOString(),
    completedSystems: groups.map((group) => ({
      systemKey: group.id,
      label: group.label,
      total: group.summary?.total || group.devices.length || 0,
      done: group.summary?.done || 0,
      pass: group.summary?.pass || 0,
      fail: group.summary?.fail || 0
    })),
    plannedCount: summary.total,
    completedCount: summary.done,
    passCount: summary.pass,
    faultCount: summary.fail,
    pendingCount: summary.pending + summary.partial + Number(summary.blocked || 0),
    pendingMissingDeviceSuggestionCount: pendingRequests.length,
    pendingMissingDeviceRequestIds: pendingRequests.map((request) => request.id),
    clientAcknowledgement: {
      technicianName: signOff.technicianName || "",
      witnessName: signOff.supervisorName || "",
      clientName: signOff.clientName || "",
      signatureCaptured: Boolean(signOff.signatureData),
      signedAt: signOff.signedAt || new Date().toISOString()
    }
  };
}

async function submitSharedReportSubmission(schedule, submission) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return { ok: false, localOnly: true };
  const latest = await requestSharedJobState(schedule, { migrate: false });
  if (!latest?.online) {
    return { ok: false, offline: true, reason: "Shared server is unavailable. Report submission is blocked until sync is restored." };
  }
  const expectedRevision = Number(latest.store?.reportSubmission?.revision || 0);
  try {
    const response = await fetch(`/api/jobs/${encodeURIComponent(scheduleId)}/report-submission`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        expectedRevision,
        schedule: getScheduleSnapshotForSharedApi(schedule),
        submission
      })
    });
    const payload = await response.json();
    if (response.status === 409) {
      return {
        ok: false,
        conflict: Boolean(payload.conflict),
        blocked: Boolean(payload.blocked),
        payload
      };
    }
    if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to submit report for review");
    const cache = ensureSharedCacheForSchedule(schedule);
    const store = {
      ...cache.store,
      reportSubmission: payload.submission,
      status: payload.submission?.status || "AWAITING_ADMIN_REVIEW"
    };
    setSharedJobCache(scheduleId, { store, progress: payload.progress }, { online: true });
    return { ok: true, submission: payload.submission, progress: payload.progress };
  } catch (error) {
    console.warn("Shared report submission unavailable", error);
    markSharedJobUnavailable(scheduleId, error);
    return { ok: false, offline: true, error };
  }
}

async function submitReportReviewAction(schedule, status, reviewNote = "", additions = {}) {
  const scheduleId = getScheduleKey(schedule);
  if (!scheduleId) return { ok: false, localOnly: true };
  const latest = await requestSharedJobState(schedule, { migrate: false });
  if (!latest?.online) return { ok: false, offline: true };
  const expectedRevision = Number(latest.store?.reportSubmission?.revision || 0);
  try {
    const response = await fetch(`/api/jobs/${encodeURIComponent(scheduleId)}/report-submission`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        expectedRevision,
        schedule: getScheduleSnapshotForSharedApi(schedule),
        submission: {
          ...(latest.store?.reportSubmission || {}),
          ...additions,
          status,
          reviewedById: getCurrentUserId(),
          reviewedBy: getCurrentUserName(),
          reviewedAt: new Date().toISOString(),
          reviewNote,
          reviewHistory: [
            ...(latest.store?.reportSubmission?.reviewHistory || []),
            { status, by: getCurrentUserName(), at: new Date().toISOString(), note: reviewNote }
          ]
        }
      })
    });
    const payload = await response.json();
    if (response.status === 409) {
      return { ok: false, conflict: Boolean(payload.conflict), blocked: Boolean(payload.blocked), payload };
    }
    if (!response.ok || !payload.ok) throw new Error(payload.error || "Unable to update report review");
    const cache = ensureSharedCacheForSchedule(schedule);
    setSharedJobCache(scheduleId, {
      store: {
        ...cache.store,
        reportSubmission: payload.submission,
        status: payload.submission?.status || status
      },
      progress: payload.progress
    }, { online: true });
    return { ok: true, submission: payload.submission, progress: payload.progress };
  } catch (error) {
    console.warn("Shared report review unavailable", error);
    markSharedJobUnavailable(scheduleId, error);
    return { ok: false, offline: true, error };
  }
}

function buildInspectionRunPayload() {
  const now = new Date();
  const reportSnapshot = state.activeReportSnapshot;
  if (reportSnapshot) {
    return {
      runId: reportSnapshot.jobId || reportSnapshot.reportId,
      reportId: reportSnapshot.reportId,
      scheduleId: reportSnapshot.scheduleId,
      serviceProvider: companyProfile,
      companyName: reportSnapshot.header.clientName,
      siteName: reportSnapshot.header.siteName,
      inspector: reportSnapshot.header.technicianName,
      serviceType: reportSnapshot.header.serviceType,
      serviceFrequencyPercent: reportSnapshot.header.frequencyPercent,
      createdAt: reportSnapshot.createdAt,
      jobStatus: reportSnapshot.status,
      summary: reportSnapshot.summary,
      devices: reportSnapshot.deviceResults,
      requests: reportSnapshot.suggestedPins,
      criticalSops: reportSnapshot.criticalItems,
      linkedVerifications: reportSnapshot.linkedVerifications,
      extinguisher: reportSnapshot.extinguisher,
      evidence: reportSnapshot.evidence,
      reportSnapshot
    };
  }
  const profile = getCurrentSiteIdentity();
  const activeJob = state.activeJob;
  const reportSchedule = getReportSchedule();
  const inspectionDevices = getInspectionDevicesForRun();
  const inspections = {};
  inspectionDevices.forEach((device) => {
    if (state.inspections[device.id]) {
      inspections[device.id] = state.inspections[device.id];
    }
  });

  const systemChecks = getScopedSystemChecks(profile);
  const criticalSops = getScopedCriticalSops(profile);
  const summary = buildInspectionRunSummary(inspectionDevices, inspections, systemChecks, criticalSops);
  const activity = buildInspectionRunActivity(inspectionDevices, inspections, systemChecks, criticalSops);
  const jobActivity = buildJobActivityEvents(activeJob);
  const redFlags = buildInspectionRunRedFlags(inspectionDevices, inspections, criticalSops);
  const completedTimes = Object.values(inspections).map((item) => item.inspectedAt).filter(Boolean).sort();
  const startedAt = activeJob?.startedAt || completedTimes[0] || now.toISOString();
  const completedAt = activeJob?.checkedOutAt || completedTimes[completedTimes.length - 1] || "";

  return {
    runId: activeJob?.jobId || `RUN-${formatRunStamp(now)}`,
    serviceProvider: companyProfile,
    companyName: activeJob?.companyName || profile.companyName,
    siteName: activeJob?.siteName || profile.siteName,
    inspector: activeJob?.inspector || jobInspector?.value.trim() || "Demo Inspector",
    serviceType: activeJob?.serviceType || jobServiceType?.value || "Maintenance",
    serviceFrequencyPercent: activeJob?.serviceFrequencyPercent || Number(document.querySelector("#serviceFrequency").value),
    createdAt: activeJob?.createdAt || now.toISOString(),
    startedAt,
    completedAt,
    durationMinutes: completedAt ? Math.max(0, Math.round((new Date(completedAt) - new Date(startedAt)) / 60000)) : 0,
    jobStatus: activeJob?.status || "Report Generated",
    job: activeJob,
    summary,
    devices: inspectionDevices.map(serializeDeviceForRun),
    inspections,
    requests: getReportSuggestedPinsForSchedule(reportSchedule),
    setupDevices: getVisibleSetupDevices(),
    systemChecks,
    criticalSops,
    staffActivity: [...jobActivity, ...activity].sort((a, b) => new Date(a.time || 0) - new Date(b.time || 0)),
    redFlags,
    reportSummary: document.querySelector("#reportSummaryText")?.textContent || ""
  };
}

function getCurrentSiteIdentity() {
  return {
    companyName: document.querySelector("#mimicCompany")?.value.trim() || state.siteProfile?.companyName || "RMT",
    siteName: document.querySelector("#mimicSite")?.value.trim() || state.siteProfile?.siteName || "Site"
  };
}

function getScopedSystemChecks(profile) {
  return Object.values(state.systemChecks).filter((check) => {
    return String(check.companyName || "").trim().toLowerCase() === profile.companyName.toLowerCase()
      && String(check.siteName || "").trim().toLowerCase() === profile.siteName.toLowerCase();
  });
}

function getScopedCriticalSops(profile) {
  return Object.values(state.criticalSops).filter((check) => {
    return String(check.companyName || "").trim().toLowerCase() === profile.companyName.toLowerCase()
      && String(check.siteName || "").trim().toLowerCase() === profile.siteName.toLowerCase();
  });
}

function serializeDeviceForRun(device) {
  return {
    id: device.id,
    type: device.type,
    floor: device.floor || "",
    location: displayDeviceLocation(device.location),
    xPercent: Number.isFinite(device.x) ? roundPercent(device.x) : "",
    yPercent: Number.isFinite(device.y) ? roundPercent(device.y) : "",
    source: device.source || "seed"
  };
}

function buildInspectionRunSummary(devicesForRun, inspections, systemChecks, criticalSops) {
  const counts = devicesForRun.reduce((acc, device) => {
    const status = inspections[device.id]?.status || "pending";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, { pass: 0, fail: 0, pending: 0 });

  return {
    totalDevices: devicesForRun.length,
    pass: counts.pass || 0,
    fail: counts.fail || 0,
    pending: counts.pending || 0,
    missingDeviceRequests: getReportSuggestedPinsForSchedule(getReportSchedule()).length,
    setupDevices: getVisibleSetupDevices().length,
    confirmedSetupDevices: getVisibleSetupDevices().filter((device) => device.status === "Confirmed").length,
    systemChecklistsSaved: systemChecks.length,
    criticalSopsSaved: criticalSops.length
  };
}

function buildInspectionRunActivity(devicesForRun, inspections, systemChecks, criticalSops) {
  const deviceEvents = devicesForRun
    .map((device) => {
      const inspection = inspections[device.id];
      if (!inspection?.inspectedAt) return null;
      return {
        time: inspection.inspectedAt,
        kind: "Device inspected",
        floor: device.floor || "-",
        tag: device.id,
        status: inspection.status || "pending",
        actor: inspection.inspectedBy || "-",
        role: inspection.inspectedRole || "",
        durationMinutes: Math.round(Number(inspection.checklistTotalDurationMs || inspection.checklistDurationMs || 0) / 60000),
        flag: inspection.status === "fail" ? "Fault / quotation review" : "-"
      };
    })
    .filter(Boolean);

  const systemEvents = systemChecks.map((check) => ({
    time: check.savedAt,
    kind: "System checklist saved",
    floor: "System",
    tag: check.title || check.templateId || "-",
    status: "saved",
    flag: "-"
  }));

  const sopEvents = criticalSops.map((sop) => ({
    time: sop.savedAt,
    kind: "Critical SOP saved",
    floor: "Critical System",
    tag: sop.title || sop.templateId || "-",
    status: "saved",
    actor: sop.savedBy || sop.filledBy || "-",
    role: sop.filledRole || "",
    durationMinutes: Math.round(Number(sop.checklistTotalDurationMs || sop.checklistDurationMs || 0) / 60000),
    flag: hasIncompleteCriticalSop(sop) ? "SOP incomplete" : "-"
  }));

  return [...deviceEvents, ...systemEvents, ...sopEvents].sort((a, b) => {
    return new Date(a.time || 0) - new Date(b.time || 0);
  });
}

function buildJobActivityEvents(job) {
  if (!job?.events?.length) return [];
  return job.events.map((event) => ({
    time: event.time,
    kind: event.kind,
    floor: "Job",
    tag: job.jobId,
    status: job.status,
    actor: event.actor || "-",
    role: event.role || "",
    flag: event.detail || "-"
  }));
}

function buildInspectionRunRedFlags(devicesForRun, inspections, criticalSops) {
  const faults = devicesForRun
    .filter((device) => inspections[device.id]?.status === "fail")
    .map((device) => ({
      priority: "Fault",
      tag: device.id,
      issue: inspections[device.id]?.notes || "Failed item requires quotation / corrective action",
      action: inspections[device.id]?.action || "Prepare follow-up"
    }));

  const missingEvidence = devicesForRun
    .filter((device) => {
      const inspection = inspections[device.id];
      return inspection?.status === "fail" && !inspection.beforePhoto && !inspection.beforePhotoData && !inspection.beforePhotoEvidence && !inspection.afterPhoto && !inspection.afterPhotoData && !inspection.afterPhotoEvidence;
    })
    .map((device) => ({
      priority: "Evidence",
      tag: device.id,
      required: "Failed item should include photo evidence"
    }));

  const mosSequence = criticalSops.flatMap((sop) => getCriticalSopFlags(sop));

  return {
    faults,
    missingEvidence,
    mosSequence,
    speedReview: []
  };
}

function hasIncompleteCriticalSop(sop) {
  return getCriticalSopFlags(sop).length > 0;
}

function getCriticalSopFlags(sop) {
  const template = criticalSopTemplates.find((item) => item.id === sop.templateId);
  if (!template) return [];
  const evidenceFlags = getMissingCriticalSopEvidence(template, sop).map((required) => ({
    priority: "Critical Hold",
    system: sop.title,
    issue: `Missing ${required}`,
    required: "Before and after photo evidence"
  }));
  const stepFlags = template.steps
    .map((step, index) => {
      const savedStep = sop.steps?.[index] || {};
      const missing = getMissingSopRequirements(step, savedStep);
      if (savedStep.confirmed && !missing.length) return null;
      return {
        priority: step.critical ? "Critical Hold" : "Review",
        system: sop.title,
        issue: `Step ${index + 1} not confirmed${missing.length ? ` (${missing.join(", ")})` : ""}`,
        required: step.title
      };
    })
    .filter(Boolean);
  return [...evidenceFlags, ...stepFlags];
}

function formatRunStamp(date) {
  const pad = (value) => String(value).padStart(2, "0");
  return [
    date.getFullYear(),
    pad(date.getMonth() + 1),
    pad(date.getDate()),
    "-",
    pad(date.getHours()),
    pad(date.getMinutes()),
    pad(date.getSeconds())
  ].join("");
}

function renderReportSummary() {
  const inspectionDevices = getInspectionDevicesForRun();
  const completed = inspectionDevices.filter((device) => deviceStatus(device.id) !== "pending").length;
  const failedDevices = inspectionDevices.filter((device) => deviceStatus(device.id) === "fail");
  const pendingDevices = inspectionDevices.filter((device) => deviceStatus(device.id) === "pending");
  const confirmedSetup = state.setupDevices.filter((item) => item.status === "Confirmed").length;
  const savedSystemChecks = Object.values(state.systemChecks).filter((check) => {
    return check.companyName === document.querySelector("#mimicCompany").value.trim()
      && check.siteName === document.querySelector("#mimicSite").value.trim();
  }).length;
  const savedCriticalSops = Object.values(state.criticalSops).filter((check) => {
    return check.companyName === document.querySelector("#mimicCompany").value.trim()
      && check.siteName === document.querySelector("#mimicSite").value.trim();
  }).length;

  const reportRequests = getReportSuggestedPinsForSchedule(getReportSchedule());
  document.querySelector("#reportSummaryText").textContent =
    `${completed} of ${inspectionDevices.length} planned devices have been inspected. ` +
    `${failedDevices.length} defect item(s) require follow-up. ` +
    `${reportRequests.length} missing device request(s) were raised. ` +
    `${state.setupDevices.length} first-time setup device(s) captured, with ${confirmedSetup} confirmed. ` +
    `${savedSystemChecks} system checklist(s) saved. ` +
    `${savedCriticalSops} critical SOP workflow(s) saved.`;

  const defectList = document.querySelector("#reportDefectList");
  if (!failedDevices.length && !reportRequests.length) {
    defectList.innerHTML = `<p class="hint">No defect or quotation follow-up items recorded in this demo report.</p>`;
  } else {
    const defects = failedDevices.map((device) => {
      const inspection = state.inspections[device.id] || {};
      return `
        <article class="report-note fail-note">
          <strong>${device.id} - ${device.type}</strong>
          <p>${escapeHtml(inspection.notes || "Failed item. Technician to confirm quotation requirement.")}</p>
          <p><b>Suggested follow-up:</b> ${escapeHtml(inspection.action || "Prepare quotation / corrective action.")}</p>
        </article>
      `;
    }).join("");
    const requests = reportRequests.map((request) => `
      <article class="report-note">
        <strong>${escapeHtml(request.label)} - ${escapeHtml(request.type)}</strong>
        <p>${escapeHtml(request.reason)}</p>
        <p><b>Suggested follow-up:</b> Admin to add device to mimic and next service scope.</p>
      </article>
    `).join("");
    defectList.innerHTML = defects + requests;
  }

  const setupList = document.querySelector("#reportSetupList");
  if (!state.setupDevices.length) {
    setupList.innerHTML = `<p class="hint">No first-time setup data captured yet.</p>`;
  } else {
    setupList.innerHTML = state.setupDevices.slice(0, 6).map((device) => `
      <article class="report-note">
        <strong>${escapeHtml(device.tag)} - ${escapeHtml(device.type)}</strong>
        <p>${escapeHtml(device.floor)} | ${escapeHtml(displayDeviceLocation(device.location))}</p>
        <p><b>Serial / barcode:</b> ${escapeHtml(device.serialBarcode || "-")} | <b>Status:</b> ${escapeHtml(device.status)}</p>
      </article>
    `).join("");
  }

  if (pendingDevices.length) {
    document.querySelector("#reportSummaryText").textContent += ` Pending items: ${pendingDevices.map((device) => device.id).join(", ")}.`;
  }
}

function generateServiceScope({ commitHistory = false } = {}) {
  const profile = getCurrentSiteIdentity();
  const percentage = Number(document.querySelector("#serviceFrequency")?.value || getContractFrequencyForProfile(profile));
  const inspectionDevices = getDevicesForScheduleSite(profile);
  const selectedScope = getMaintenanceScopeDevices(inspectionDevices, {
    profile,
    floorId: "site-wide",
    frequencyPercent: percentage,
    commitHistory
  });
  const selectedActive = selectedScope.filter((device) => isActiveSystem(device.type));
  const selectedPassive = selectedScope.filter((device) => isPassiveScopeDevice(device));
  const totalSelected = selectedPassive.length + selectedActive.length;
  const floorCounts = getScheduleFloorCounts(selectedScope);

  document.querySelector("#scopeSummary").innerHTML = `
    <div><strong>${percentage}%</strong><span>Site-wide passive sample</span></div>
    <div><strong>${selectedPassive.length}</strong><span>Passive checkpoints</span></div>
    <div><strong>${selectedActive.length}</strong><span>Active systems, 100%</span></div>
    <div><strong>${totalSelected}</strong><span>${floorCounts.length} floor(s) this visit</span></div>
  `;

  const passiveCards = selectedPassive.map((device) => `
    <article class="scope-card">
      <div>
        <strong>${device.id}</strong>
        <p>${escapeHtml(device.type)} - ${escapeHtml(device.floorTitle || device.floor || "Floor")} - ${escapeHtml(displayDeviceLocation(device.location))}</p>
      </div>
      <span class="scope-badge">Rotated</span>
    </article>
  `).join("");

  const activeCards = selectedActive.map((system) => `
    <article class="scope-card">
      <div>
        <strong>${system.id}</strong>
        <p>${escapeHtml(system.type)} - ${escapeHtml(system.floorTitle || system.floor || "Floor")} - ${escapeHtml(displayDeviceLocation(system.location))}</p>
      </div>
      <span class="scope-badge active">100%</span>
    </article>
  `).join("");

  document.querySelector("#scopeList").innerHTML = activeCards + passiveCards;
}

function isPassiveDevice(type) {
  const value = String(type || "").toLowerCase();
  return [
    "smoke",
    "heat",
    "manual",
    "call point",
    "break glass",
    "emergency light",
    "exit",
    "hose reel",
    "extinguisher",
    "flow switch",
    "fireman intercom"
  ].some((keyword) => value.includes(keyword));
}

function isPassiveScopeDevice(device) {
  return isPassiveDevice(device?.type) && !isActiveSystem(device?.type);
}

function isActiveSystem(type) {
  const value = String(type || "").toLowerCase();
  if (value.includes("extinguisher")) return false;
  return [
    "main fire alarm panel",
    "fire alarm panel",
    "pump",
    "gas release",
    "fm200",
    "hose reel panel",
    "sprinkler panel",
    "wet riser panel",
    "pressurized hydrant panel",
    "co2",
    "wet chemical"
  ].some((keyword) => value.includes(keyword));
}

function renderSystemChecklist() {
  const tabs = document.querySelector("#systemCheckTabs");
  const form = document.querySelector("#systemCheckForm");
  const summary = document.querySelector("#systemCheckSummary");
  if (!tabs || !form || !summary) return;

  const devicesForSite = getVisibleSetupDevices();
  const activeTemplate = systemChecklistTemplates.find((template) => template.id === state.activeSystemCheckId) || systemChecklistTemplates[0];
  state.activeSystemCheckId = activeTemplate.id;

  const totalQuestions = systemChecklistTemplates.reduce((sum, template) => {
    return sum + template.sections.reduce((sectionSum, section) => sectionSum + section.questions.length, 0);
  }, 0);
  const savedAnswers = state.systemChecks[state.activeSystemCheckId]?.answers || {};
  const activeAnswered = Object.keys(savedAnswers).length;

  summary.innerHTML = `
    <div><strong>${devicesForSite.length}</strong><span>Master devices</span></div>
    <div><strong>${countDevicesByTypes(devicesForSite, ["Smoke Detector", "Heat Detector", "Manual Call Point"])}</strong><span>Alarm points</span></div>
    <div><strong>${countDevicesByTypes(devicesForSite, ["Emergency Light", "Exit Sign"])}</strong><span>Lighting points</span></div>
    <div><strong>${activeAnswered}</strong><span>${totalQuestions} checklist answers</span></div>
  `;

  tabs.innerHTML = systemChecklistTemplates.map((template) => {
    const check = state.systemChecks[template.id] || {};
    const answered = Object.keys(check.answers || {}).length;
    const count = countDevicesByTypes(devicesForSite, template.appliesTo);
    return `
      <button type="button" class="${template.id === state.activeSystemCheckId ? "active" : ""}" data-template-id="${template.id}">
        <strong>${escapeHtml(template.title)}</strong>
        <span>${count} related device(s) | ${answered} saved answer(s)</span>
      </button>
    `;
  }).join("");

  tabs.querySelectorAll("button").forEach((button) => {
    button.addEventListener("click", () => {
      state.activeSystemCheckId = button.dataset.templateId;
      renderSystemChecklist();
    });
  });

  const currentCheck = state.systemChecks[activeTemplate.id] || { answers: {}, remarks: "" };
  form.innerHTML = `
    <div class="system-check-title">
      <div>
        <p class="eyebrow">Active Template</p>
        <h3>${escapeHtml(activeTemplate.title)}</h3>
      </div>
      <span>${countDevicesByTypes(devicesForSite, activeTemplate.appliesTo)} related device(s)</span>
    </div>
    ${activeTemplate.sections.map((section, sectionIndex) => `
      <fieldset class="system-section">
        <legend>${escapeHtml(section.title)}</legend>
        ${section.questions.map((question, questionIndex) => {
          const key = `${sectionIndex}-${questionIndex}`;
          const value = currentCheck.answers?.[key] || "N/A";
          return `
            <div class="system-question">
              <p>${questionIndex + 1}. ${escapeHtml(question)}</p>
              <div class="choice-row">
                ${["Pass", "Fail", "N/A"].map((choice) => `
                  <label>
                    <input type="radio" name="system-${key}" value="${choice}" ${value === choice ? "checked" : ""}>
                    ${choice}
                  </label>
                `).join("")}
              </div>
            </div>
          `;
        }).join("")}
      </fieldset>
    `).join("")}
    <label>
      System Remarks / Reading
      <textarea id="systemCheckRemarks" rows="4" placeholder="Example: Battery 26.8V, charger normal, panel reset normal.">${escapeHtml(currentCheck.remarks || "")}</textarea>
    </label>
    <div class="form-bottom-actions">
      <button id="saveSystemCheckBottomBtn" type="button">Save System Checklist</button>
    </div>
  `;

  document.querySelector("#saveSystemCheckBottomBtn")?.addEventListener("click", saveSystemChecklist);
}

function saveSystemChecklist() {
  const template = systemChecklistTemplates.find((item) => item.id === state.activeSystemCheckId) || systemChecklistTemplates[0];
  const answers = {};
  template.sections.forEach((section, sectionIndex) => {
    section.questions.forEach((_, questionIndex) => {
      const key = `${sectionIndex}-${questionIndex}`;
      answers[key] = document.querySelector(`input[name="system-${key}"]:checked`)?.value || "N/A";
    });
  });

  state.systemChecks[template.id] = {
    templateId: template.id,
    title: template.title,
    companyName: document.querySelector("#mimicCompany").value.trim(),
    siteName: document.querySelector("#mimicSite").value.trim(),
    answers,
    remarks: document.querySelector("#systemCheckRemarks")?.value.trim() || "",
    savedAt: new Date().toISOString(),
    savedBy: "Demo Inspector"
  };
  writeStoredJson("rmtSystemChecks", state.systemChecks);
  addJobEvent("System checklist saved", template.title);
  persistActiveJob();
  renderSystemChecklist();
  renderJobPanel();
  document.querySelector("#syncState").textContent = `${template.title} checklist saved`;
}

function countDevicesByTypes(deviceList, types) {
  const normalized = types.map((type) => type.toLowerCase());
  return deviceList.filter((device) => normalized.includes(String(device.type || "").toLowerCase())).length;
}

function sopStepNeedsRemark(step) {
  if (step.noRemark) return Boolean(step.requiresRemark);
  return Boolean(step.requiresRemark || (step.critical && !step.tickOnly));
}

function getCriticalSopEvidenceKey(templateId = state.activeCriticalSopId, index = "overall") {
  return `${getCriticalSopStorageKey(templateId)}::${index}`;
}

function hasRetainedPhotoEvidence(evidence = null) {
  if (!evidence?.evidenceId) return false;
  if (evidence.evidenceMode === "DEMO_TEST" && !isCriticalDemoEvidenceMode()) return false;
  return Boolean(
    evidence.originalDataUrl
    || evidence.stampedDataUrl
    || evidence.dataUrl
    || evidence.originalPhotoUrl
    || evidence.stampedPhotoUrl
    || evidence.photoUrl
  );
}

function isCriticalDemoEvidenceMode() {
  try {
    return new URLSearchParams(window.location.search).get("demoEvidence") === "1";
  } catch (_error) {
    return false;
  }
}

function createCriticalDemoEvidence(category, contextOverrides = {}) {
  const capturedDate = new Date();
  const context = getPhotoEvidenceContext(contextOverrides);
  const evidenceId = createEvidenceId("DEMO-EVD");
  return {
    schemaVersion: "photo-evidence-v1",
    evidenceId,
    originalEvidenceId: `${evidenceId}::original`,
    stampedEvidenceId: `${evidenceId}::stamped`,
    name: `DEMO-${category}.png`,
    originalFileName: `DEMO-${category}.png`,
    type: "image/png",
    size: 0,
    category,
    evidenceMode: "DEMO_TEST",
    isDemoEvidence: true,
    testOnly: true,
    jobId: context.jobId,
    scheduleId: context.scheduleId,
    clientId: context.clientId,
    clientName: context.clientName,
    siteId: context.siteId,
    siteName: context.siteName,
    floorId: context.floorId,
    floorLabel: context.floorLabel,
    deviceId: context.deviceId,
    technicianId: context.technicianId,
    technicianName: context.technicianName,
    capturedAt: capturedDate.toISOString(),
    capturedAtLocal: formatLocalCaptureTimestamp(capturedDate),
    capturedAtUtc: capturedDate.toISOString(),
    timezoneOffset: formatTimezoneOffset(capturedDate),
    locationLabel: context.locationLabel || context.floorLabel || "",
    syncState: "LOCAL",
    stampVersion: PHOTO_EVIDENCE_STAMP_VERSION,
    stampStatus: "DEMO_TEST",
    originalDataUrl: DEMO_CRITICAL_EVIDENCE_DATA_URL,
    stampedDataUrl: DEMO_CRITICAL_EVIDENCE_DATA_URL,
    dataUrl: DEMO_CRITICAL_EVIDENCE_DATA_URL
  };
}

function criticalEvidenceDisplayName(name, evidence) {
  if (evidence?.evidenceMode === "DEMO_TEST") return `${name || evidence.name || "Demo picture"} · DEMO / TEST EVIDENCE`;
  return name || evidence?.originalFileName || evidence?.name || "";
}

function isCriticalSopEvidenceProcessing(templateId = state.activeCriticalSopId) {
  const keyPrefix = `${getCriticalSopEvidenceKey(templateId)}::`;
  return [...criticalSopEvidenceProcessingKeys].some((key) => key.startsWith(keyPrefix));
}

function sopStepShowsRemark(step, stepState = {}, templateId = state.activeCriticalSopId, index = -1) {
  if (sopStepNeedsRemark(step) || sopStepChoiceNeedsRemark(step, stepState)) return true;
  if (step.phaseSupplyValidation && getPumpPhaseSupplyState(stepState).abnormal) return true;
  if (String(stepState.remark || "").trim()) return true;
  return Boolean(state.sopRemarkVisibility?.[getCriticalSopEvidenceKey(templateId, index)]);
}

function isFinalSopStep(template, index) {
  return Boolean(template?.steps?.length && index === template.steps.length - 1);
}

function getCriticalSopEvidenceDomState(saved = {}) {
  const beforePhotoInput = document.querySelector("#criticalBeforePhoto");
  const afterPhotoInput = document.querySelector("#criticalAfterPhoto");
  const key = getCriticalSopEvidenceKey();
  const pending = pendingCriticalSopPhotoEvidence.overall[key] || {};
  const beforePhotoEvidence = pending.before || saved.beforePhotoEvidence || null;
  const afterPhotoEvidence = pending.after || saved.afterPhotoEvidence || null;
  return {
    beforePhoto: criticalEvidenceDisplayName(beforePhotoInput?.files?.[0]?.name || saved.beforePhoto || "", beforePhotoEvidence),
    afterPhoto: criticalEvidenceDisplayName(afterPhotoInput?.files?.[0]?.name || saved.afterPhoto || "", afterPhotoEvidence),
    beforePhotoEvidence,
    afterPhotoEvidence,
    filledBy: saved.filledBy || saved.savedBy || getCurrentUserName(),
    filledRole: saved.filledRole || getCurrentUserRole(),
    evidenceAt: saved.evidenceAt || saved.savedAt || ""
  };
}

function getMissingCriticalSopEvidence(template, record = {}) {
  const missing = [];
  if (template?.requiresBeforeAfterPhotos && !hasRetainedPhotoEvidence(record.beforePhotoEvidence)) missing.push("before photo");
  if (template?.requiresBeforeAfterPhotos && !hasRetainedPhotoEvidence(record.afterPhotoEvidence)) missing.push("after photo");
  return missing;
}

function getCriticalSopCompleteCount(template, saved = {}) {
  if (!template) return 0;
  return template.steps.filter((step, index) => {
    return isSopStepComplete(step, saved.steps?.[index] || {}, template, index, saved);
  }).length;
}

function isCriticalSopRecordComplete(template, saved = {}) {
  if (!template) return false;
  if (Array.isArray(saved.linkedVerificationStatuses) && saved.linkedVerificationStatuses.some((status) => normalizeScopeText(status) !== "verified")) {
    return false;
  }
  return getCriticalSopCompleteCount(template, saved) === template.steps.length
    && getMissingCriticalSopEvidence(template, saved).length === 0;
}

function getSopStepExisting(templateId, index) {
  const storageKey = getCriticalSopStorageKey(templateId);
  return state.criticalSops[storageKey]?.steps?.[index] || state.criticalSops[templateId]?.steps?.[index] || {};
}

function getPumpConfigurationKey(schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  if (!schedule || !device) return "";
  return [schedule.companyName || schedule.clientId, schedule.siteName || schedule.siteId, device.id || device.tag]
    .map((value) => normalizeScopeText(value).replace(/[^a-z0-9]+/g, "-"))
    .filter(Boolean)
    .join("::");
}

function getPumpConfiguration(schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  const key = getPumpConfigurationKey(schedule, device);
  return key ? state.pumpConfigurations[key] || null : null;
}

function persistPumpConfigurations() {
  writeStoredJson("rmtPumpConfigurations", state.pumpConfigurations || {});
}

async function loadPumpConfiguration(schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  const key = getPumpConfigurationKey(schedule, device);
  if (!key || state.pumpConfigurationLoadingKey === key) return getPumpConfiguration(schedule, device);
  state.pumpConfigurationLoadingKey = key;
  try {
    const query = new URLSearchParams({
      companyName: schedule.companyName || schedule.clientId || "",
      siteName: schedule.siteName || schedule.siteId || "",
      pumpDeviceId: device.id || device.tag || ""
    });
    const response = await fetch(`/api/pump-configurations?${query}`, { cache: "no-store" });
    const payload = await response.json();
    if (response.ok && payload.ok && payload.configuration) {
      state.pumpConfigurations[key] = payload.configuration;
      persistPumpConfigurations();
    }
  } catch (error) {
    console.warn("Pump configuration server unavailable", error);
  } finally {
    state.pumpConfigurationLoadingKey = "";
  }
  return getPumpConfiguration(schedule, device);
}

async function savePumpConfigurationRecord(configuration, schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  const key = getPumpConfigurationKey(schedule, device);
  if (!key) return { ok: false, invalid: true, reason: "Pump configuration identity is unavailable." };
  const current = state.pumpConfigurations[key] || null;
  try {
    const response = await fetch("/api/pump-configurations", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        expectedRevision: Number(current?.revision || 0),
        configuration: {
          ...(current || {}),
          ...configuration,
          configurationKey: key,
          companyName: schedule.companyName || schedule.clientId || "",
          siteName: schedule.siteName || schedule.siteId || "",
          pumpDeviceId: device.id || device.tag || "",
          updatedBy: getCurrentUserName(),
          technicianId: getCurrentUserId()
        }
      })
    });
    const payload = await response.json();
    if (response.status === 409 && payload.conflict) return { ok: false, conflict: true, current: payload.current };
    if (!response.ok || !payload.ok) return { ok: false, invalid: true, reason: payload.reason || payload.error || "Unable to save pump configuration." };
    state.pumpConfigurations[key] = payload.configuration;
    state.pumpConfigurationEditKey = "";
    persistPumpConfigurations();
    return { ok: true, configuration: payload.configuration };
  } catch (error) {
    state.pumpConfigurations[key] = {
      ...(current || {}),
      ...configuration,
      configurationKey: key,
      syncStatus: "LOCAL_DRAFT",
      unsynced: true,
      updatedBy: getCurrentUserName(),
      updatedAt: new Date().toISOString()
    };
    persistPumpConfigurations();
    return { ok: true, offline: true, configuration: state.pumpConfigurations[key] };
  }
}

function getPumpConfigurationValues(step, schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  const configuration = getPumpConfiguration(schedule, device) || {};
  if (step?.configurationKey === "waterStorage") return configuration.waterStorage || {};
  if (step?.configurationKey === "standbyPump") return { standbyType: configuration.standbyType || "" };
  return {};
}

function isSprinklerPumpDevice(device = state.activeCriticalDevice) {
  const text = normalizeScopeText(`${device?.id || device?.tag || ""} ${device?.type || ""}`);
  return text.includes("sprinkler") || text.includes("spp");
}

function calculateTankStorageCapacity(fieldValues = {}) {
  const lengthFt = Number(fieldValues.tankLengthFt);
  const widthFt = Number(fieldValues.tankWidthFt);
  const heightFt = Number(fieldValues.tankHeightFt);
  if (![lengthFt, widthFt, heightFt].every((value) => Number.isFinite(value) && value > 0)) return null;
  const cubicFeet = lengthFt * widthFt * heightFt;
  return {
    lengthFt,
    widthFt,
    heightFt,
    cubicFeet: Number(cubicFeet.toFixed(3)),
    capacityGallons: Number((cubicFeet * 6.25).toFixed(2))
  };
}

function applySopDerivedFieldValues(step, fieldValues = {}) {
  const values = { ...fieldValues };
  if (!step?.tankCapacityCalculation || values.capacityMethod !== "Calculate from dimensions") return values;
  const calculation = calculateTankStorageCapacity(values);
  if (!calculation) {
    delete values.capacity;
    delete values.capacityUnit;
    delete values.capacityGallons;
    return values;
  }
  values.capacity = String(calculation.capacityGallons);
  values.capacityUnit = "gal";
  values.capacityGallons = String(calculation.capacityGallons);
  return values;
}

function isSopFieldVisible(field, fieldValues = {}) {
  if (!field?.when) return true;
  return (field.when.values || []).includes(fieldValues[field.when.fieldId]);
}

function getEffectiveSopFields(step, saved = {}, device = state.activeCriticalDevice, fieldValues = {}) {
  let fields = Array.isArray(step?.fields) ? step.fields : [];
  if (step?.variants) {
    const standby = getSavedSopStandbyConfiguration({ steps: [] }, saved) || getPumpConfiguration()?.standbyType || "";
    fields = step.variants[standby] || [];
  }
  if (step?.manualStopForSprinkler && isSprinklerPumpDevice(device)) {
    fields = fields.filter((field) => field.id !== "cutOutPsi").concat({
      id: "manualStop",
      label: "Cut-Out",
      kind: "display",
      value: "MANUAL STOP"
    });
  }
  return fields.filter((field) => isSopFieldVisible(field, fieldValues));
}

function getSopFieldDomValue(index, field, existingValues = {}) {
  if (field.kind === "single-choice") {
    return document.querySelector(`[name="sop-field-${index}-${field.id}"]:checked`)?.value?.trim?.()
      ?? existingValues[field.id]
      ?? field.value
      ?? "";
  }
  const input = document.querySelector(`[name="sop-field-${index}-${field.id}"]`);
  return input?.value?.trim?.() ?? existingValues[field.id] ?? field.value ?? "";
}

function getSopFieldRemarkDomValue(index, field, existingRemarks = {}) {
  const input = document.querySelector(`[name="sop-field-remark-${index}-${field.id}"]`);
  return input?.value?.trim?.() ?? existingRemarks[field.id] ?? "";
}

function getSopFieldValues(step, index, existingStep = {}, saved = {}) {
  const configurationValues = getPumpConfigurationValues(step);
  const seedValues = { ...configurationValues, ...(existingStep.fieldValues || {}) };
  if (step?.variants && !seedValues.coolingType && getPumpConfiguration()?.dieselCoolingType) {
    seedValues.coolingType = getPumpConfiguration().dieselCoolingType;
  }
  if (step?.configurationKey === "standbyPump" && configurationValues.standbyType) {
    seedValues.standbyType = configurationValues.standbyType;
  }
  const allFields = [
    ...(Array.isArray(step?.fields) ? step.fields : []),
    ...Object.values(step?.variants || {}).flat()
  ];
  const values = { ...seedValues };
  allFields.forEach((field) => {
    values[field.id] = getSopFieldDomValue(index, field, values);
  });
  return applySopDerivedFieldValues(step, values);
}

function getSopFieldRemarks(step, index, existingStep = {}) {
  const allFields = [
    ...(Array.isArray(step?.fields) ? step.fields : []),
    ...Object.values(step?.variants || {}).flat()
  ];
  return Object.fromEntries(allFields.map((field) => [field.id, getSopFieldRemarkDomValue(index, field, existingStep.fieldRemarks || {})]));
}

function getSopLinkedVerificationAutoState(step, schedule = getActiveTechnicianMaintenanceSchedule()) {
  const verificationTypes = Array.isArray(step?.autoResultFromLinkedVerifications)
    ? step.autoResultFromLinkedVerifications
    : [];
  if (!schedule || !verificationTypes.length) return { applicable: false, choice: "", message: "" };
  const definitions = getScheduleLinkedVerificationDefinitions(schedule)
    .filter((definition) => verificationTypes.includes(definition.verificationType));
  const states = definitions.map((definition) => calculateClientLinkedVerificationState(schedule, definition));
  const details = verificationTypes.map((verificationType) => {
    const typeStates = states.filter((state) => state.definition.verificationType === verificationType);
    const label = verificationType === "FIRE_PUMP_INDICATION" ? "Pump" : "CO2";
    const results = typeStates.flatMap((state) => state.sides.map((side) => String(side.record?.result || "").trim().toUpperCase()));
    const failed = typeStates.some((state) => state.status === "MISMATCH_REVIEW_REQUIRED")
      || results.some((result) => ["FAIL", "FAILED", "FAULT", "NOT_CONFIRMED"].includes(result));
    if (failed) return { verificationType, label, status: "FAIL" };
    if (!typeStates.length || typeStates.some((state) => state.status !== "VERIFIED")) {
      return { verificationType, label, status: "PENDING" };
    }
    return { verificationType, label, status: "PASS" };
  });
  const overall = details.some((item) => item.status === "FAIL")
    ? "FAIL"
    : details.every((item) => item.status === "PASS")
      ? "PASS"
      : "PENDING";
  const message = overall === "PASS"
    ? "Authoritative Pump and CO2 linked verifications are complete."
    : overall === "FAIL"
      ? "A linked verification failed or requires mismatch review."
      : "Awaiting required linked verification and sync.";
  return {
    applicable: true,
    choice: overall === "PASS" ? "Pass" : overall === "FAIL" ? "Fail" : "",
    overall,
    details,
    message,
    source: "Linked Verification"
  };
}

function getSopStepDomState(step, index, templateId) {
  const existingStep = getSopStepExisting(templateId, index);
  const photoInput = document.querySelector(`input[name="sop-photo-${index}"]`);
  const pendingPhotoEvidence = pendingCriticalSopPhotoEvidence.steps[getCriticalSopEvidenceKey(templateId, index)] || null;
  const linkedAutoResult = getSopLinkedVerificationAutoState(step);
  const configurationValues = getPumpConfigurationValues(step);
  const fieldValues = getSopFieldValues(step, index, existingStep);
  const fieldRemarks = getSopFieldRemarks(step, index, existingStep);
  return {
    confirmed: Boolean(document.querySelector(`input[name="sop-confirm-${index}"]`)?.checked),
    title: step.title,
    critical: Boolean(step.critical),
    choice: linkedAutoResult.applicable
      ? linkedAutoResult.choice
      : document.querySelector(`input[name="sop-choice-${index}"]:checked`)?.value
        || document.querySelector(`select[name="sop-choice-${index}"]`)?.value
        || (step.configurationKey === "standbyPump" ? configurationValues.standbyType : "")
        || existingStep.choice
        || "",
    reading: document.querySelector(`input[name="sop-reading-${index}"]`)?.value.trim() || existingStep.reading || "",
    remark: document.querySelector(`input[name="sop-remark-${index}"]`)?.value.trim() || existingStep.remark || "",
    photo: photoInput?.files?.[0]?.name || pendingPhotoEvidence?.originalFileName || existingStep.photo || "",
    photoEvidence: pendingPhotoEvidence || existingStep.photoEvidence || null,
    supervisor: document.querySelector(`input[name="sop-supervisor-${index}"]`)?.value.trim() || existingStep.supervisor || "",
    recordedBy: existingStep.recordedBy || (step.captureTechnician ? getCurrentUserName() : ""),
    fieldValues,
    fieldRemarks,
    autoResult: linkedAutoResult.applicable ? linkedAutoResult : null
  };
}

function getSopStepRenderState(step, index, templateId, saved = {}) {
  const existingStep = saved.steps?.[index] || getSopStepExisting(templateId, index) || {};
  const linkedAutoResult = getSopLinkedVerificationAutoState(step);
  const configurationValues = getPumpConfigurationValues(step);
  return {
    ...existingStep,
    photoEvidence: pendingCriticalSopPhotoEvidence.steps[getCriticalSopEvidenceKey(templateId, index)] || existingStep.photoEvidence || null,
    choice: linkedAutoResult.applicable
      ? linkedAutoResult.choice
      : (step.configurationKey === "standbyPump" ? configurationValues.standbyType : "") || existingStep.choice || "",
    fieldValues: applySopDerivedFieldValues(step, {
      ...configurationValues,
      ...(step?.variants && getPumpConfiguration()?.dieselCoolingType ? { coolingType: getPumpConfiguration().dieselCoolingType } : {}),
      ...(existingStep.fieldValues || {})
    }),
    autoResult: linkedAutoResult.applicable ? linkedAutoResult : null
  };
}

function getSavedSopStandbyConfiguration(template, saved = {}) {
  const steps = template?.steps?.length ? template.steps : criticalSopTemplates.find((item) => item.id === "sprinkler-hydrant-pump-sop")?.steps || [];
  const configIndex = steps.findIndex((step) => step.configurationKey === "standbyPump" || step.lockChoiceAfterSave);
  return getPumpConfiguration()?.standbyType || (configIndex >= 0 ? saved.steps?.[configIndex]?.choice || "" : "");
}

function sopValueMatches(value, options = []) {
  const normalized = normalizeScopeText(value);
  return options.some((option) => normalizeScopeText(option) === normalized);
}

function sopStepChoiceNeedsRemark(step, stepState = {}) {
  return Array.isArray(step?.remarkOnChoices) && sopValueMatches(stepState.choice, step.remarkOnChoices);
}

function sopStepChoiceNeedsPhoto(step, stepState = {}) {
  return Array.isArray(step?.photoOnChoices) && sopValueMatches(stepState.choice, step.photoOnChoices);
}

function sopStepFieldFailureNeedsPhoto(step, stepState = {}) {
  if (!step?.requiresPhotoOnFieldFailure) return false;
  const fields = getEffectiveSopFields(step, { steps: {} }, state.activeCriticalDevice, stepState.fieldValues || {});
  return fields.some((field) => Array.isArray(field.requiresRemarkOn) && sopValueMatches(stepState.fieldValues?.[field.id], field.requiresRemarkOn));
}

function sopStepRequiresPhoto(step, stepState = {}) {
  return Boolean(step?.requiresPhoto || sopStepChoiceNeedsPhoto(step, stepState) || sopStepFieldFailureNeedsPhoto(step, stepState));
}

function getGasLinkedStepRequirement(step) {
  if (!step?.linkedGasTestKey) return null;
  if (getCurrentUserRole() !== "Technician") return null;
  const linked = getSopStepLinkedVerificationState(step);
  if (!linked) {
    return { complete: false, mismatch: false, message: "configured MFAP linked verification" };
  }
  if (linked.linkedState.status === "VERIFIED") return { complete: true, mismatch: false, message: "" };
  if (linked.linkedState.status === "MISMATCH_REVIEW_REQUIRED") {
    return { complete: false, mismatch: true, message: "MFAP indication mismatch / fault" };
  }
  return { complete: false, mismatch: false, message: "MFAP linked verification" };
}

function getMissingSopRequirements(step, stepState, template = null, index = -1, saved = {}, options = {}) {
  const missing = [];
  if (step.requiresChoice && !stepState.choice) missing.push(step.choiceLabel || "choice");
  if (step.requiresReading && !stepState.reading) missing.push(step.readingLabel || "reading");
  if (step.requiresReading && step.readingType === "number" && stepState.reading && !Number.isFinite(Number(stepState.reading))) {
    missing.push(`valid ${step.readingLabel || "number"}`);
  }
  if ((sopStepNeedsRemark(step) || sopStepChoiceNeedsRemark(step, stepState)) && !stepState.remark) missing.push("remark");
  const fieldValues = stepState.fieldValues || {};
  const fieldRemarks = stepState.fieldRemarks || {};
  const effectiveFields = getEffectiveSopFields(step, saved, state.activeCriticalDevice, fieldValues);
  if (step.variants && !effectiveFields.length) missing.push("standby pump type configuration");
  effectiveFields.forEach((field) => {
    const value = field.kind === "display" ? field.value : fieldValues[field.id];
    if (field.required && !String(value ?? "").trim()) missing.push(field.label || field.id);
    if (field.kind === "number" && String(value ?? "").trim() && !Number.isFinite(Number(value))) {
      missing.push(`valid ${field.label || field.id}`);
    }
    if (Array.isArray(field.requiresRemarkOn) && sopValueMatches(value, field.requiresRemarkOn) && !String(fieldRemarks[field.id] || "").trim()) {
      missing.push(`${field.label || field.id} remark`);
    }
  });
  if (step.phaseSupplyValidation) {
    const phaseState = getPumpPhaseSupplyState(stepState);
    if (phaseState.hasReadings && phaseState.abnormal) {
      missing.push("R-Y / Y-B / B-R readings within 376-440 V");
      if (!String(stepState.remark || "").trim()) missing.push("phase supply acknowledgement remark");
    }
  }
  if (sopStepHasFault(step, stepState)) missing.push("safe / normal result before progression");
  if (sopStepRequiresPhoto(step, stepState) && !hasRetainedPhotoEvidence(stepState.photoEvidence)) missing.push("photo");
  if (step.requiresSupervisor && !stepState.supervisor) missing.push("supervisor");
  const linkedRequirement = options.ignoreLinkedVerification ? null : getGasLinkedStepRequirement(step);
  if (linkedRequirement && !linkedRequirement.complete) missing.push(linkedRequirement.message);
  if (template && isFinalSopStep(template, index)) {
    const evidence = options.useDomEvidence ? getCriticalSopEvidenceDomState(saved) : saved;
    missing.push(...getMissingCriticalSopEvidence(template, evidence));
  }
  return missing;
}

function isSopStepComplete(step, stepState, template = null, index = -1, saved = {}, options = {}) {
  const missing = getMissingSopRequirements(step, stepState, template, index, saved, options);
  if (sopStepHasFault(step, stepState)) return false;
  if (step.noConfirm) return missing.length === 0;
  return Boolean(stepState?.confirmed) && missing.length === 0;
}

function sopRequirementBadges(step) {
  const badges = [];
  if (step.requiresChoice) badges.push(step.choiceLabel || "Choice");
  if (step.requiresReading) badges.push(step.readingLabel || "Reading");
  if (sopStepNeedsRemark(step)) badges.push("Remark");
  if (step.requiresPhoto || step.requiresPhotoOnFieldFailure || step.photoOnChoices?.length) badges.push(step.requiresPhoto ? "Photo" : "Photo on fail");
  if (step.fields?.length || step.variants) badges.push("Structured readings");
  if (step.requiresSupervisor) badges.push("Supervisor");
  if (step.captureTechnician) badges.push("Recorded by technician");
  if (!badges.length) badges.push("Confirm");
  return badges.map((badge) => `<span>${escapeHtml(badge)}</span>`).join("");
}

function getCriticalSopStepStageBlock(template, activeDevice, index, saved = {}) {
  const schedule = getActiveTechnicianMaintenanceSchedule();
  const run = activeDevice ? getCriticalWorkflowRunForParentDevice(activeDevice, schedule) : null;
  if (!run || !run.finalStepIndexes?.includes(index)) return { blocked: false };
  const stage = getCriticalWorkflowRunState(run, schedule);
  if (stage.childrenComplete) return { blocked: false };
  return {
    blocked: true,
    reason: `Finish linked device checks first (${stage.childCompleteCount}/${stage.childTotal} completed), then return for final restoration.`
  };
}

function renderCriticalWorkflowStageBanner(run, stage) {
  if (!run || !stage) return "";
  const className = stage.status === "final_restored"
    ? "complete"
    : stage.prerequisiteFailed
      ? "blocked"
      : stage.status === "final_required"
        ? "warning"
        : "";
  return `
    <div class="critical-workflow-stage ${className}">
      <strong>${escapeHtml(run.label)} Sequence</strong>
      <span>${escapeHtml(stage.stageLabel)}</span>
      <small>Test readiness: ${stage.testReady ? "READY" : "NOT READY"} | MFAP checklist: ${stage.checklistComplete ? "Complete" : "In progress"} | Linked devices: ${stage.childCompleteCount}/${stage.childTotal} | Final restoration: ${stage.finalComplete ? "Complete" : "Pending"}</small>
    </div>
  `;
}

function getPumpConfigurationEditToken(step, schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  return `${getPumpConfigurationKey(schedule, device)}::${step?.configurationKey || ""}`;
}

function isPumpConfigurationEditing(step) {
  return Boolean(step?.configurationKey && state.pumpConfigurationEditKey === getPumpConfigurationEditToken(step));
}

function pumpConfigurationNeedsSetupUpgrade(step, configuration = getPumpConfiguration()) {
  if (step?.configurationKey !== "waterStorage" || !configuration?.waterStorage) return false;
  const water = configuration.waterStorage;
  return !water.capacityMethod || (water.capacityMethod === "Calculate from dimensions" && !water.capacityGallons);
}

function renderPumpConfigurationSummary(step, stepState) {
  if (!step?.configurationKey) return "";
  const configuration = getPumpConfiguration();
  if (!configuration || isPumpConfigurationEditing(step)) return "";
  const needsSetupUpgrade = pumpConfigurationNeedsSetupUpgrade(step, configuration);
  const values = step.configurationKey === "waterStorage"
    ? configuration.waterStorage || {}
    : { standbyType: configuration.standbyType || "" };
  const dimensionSummary = values.tankLengthFt && values.tankWidthFt && values.tankHeightFt
    ? `${values.tankLengthFt} × ${values.tankWidthFt} × ${values.tankHeightFt} ft | `
    : "";
  const summary = step.configurationKey === "waterStorage"
    ? `${values.tankType || "Not configured"}${values.tankTypeOther ? ` - ${values.tankTypeOther}` : ""} | ${dimensionSummary}${values.capacity || "-"} ${values.capacityUnit || ""}`
    : values.standbyType || "Not configured";
  return `
    <div class="sop-configuration-summary">
      <div><span>Saved site / pump configuration</span><strong>${escapeHtml(summary)}</strong></div>
      <button type="button" class="secondary" data-change-pump-config="${escapeHtml(step.configurationKey)}">${needsSetupUpgrade ? "Complete Tank Setup" : "Change"}</button>
      ${needsSetupUpgrade ? `<small>Existing capacity is preserved. Complete the new dimension or known-capacity setup to create the next revision.</small>` : ""}
      ${configuration.unsynced ? `<small>Local draft - server sync required before this becomes authoritative.</small>` : ""}
    </div>
  `;
}

function renderSopStructuredField(field, index, stepState, disabled, configurationLocked) {
  if (field.configuration && configurationLocked) return "";
  const value = stepState.fieldValues?.[field.id] ?? field.value ?? "";
  const remark = stepState.fieldRemarks?.[field.id] || "";
  const needsRemark = Array.isArray(field.requiresRemarkOn) && sopValueMatches(value, field.requiresRemarkOn);
  if (field.kind === "display") {
    return `<div class="sop-auto-result complete"><span>${escapeHtml(field.label)}</span><strong>${escapeHtml(field.value || "")}</strong></div>`;
  }
  if (field.kind === "single-choice") {
    return `
      <fieldset class="sop-single-choice">
        <legend>${escapeHtml(field.label)}${field.required ? " *" : ""}</legend>
        <div>
          ${(field.choices || []).map((choice) => `
            <label><input type="radio" name="sop-field-${index}-${escapeHtml(field.id)}" value="${escapeHtml(choice)}" ${value === choice ? "checked" : ""} ${disabled ? "disabled" : ""}><span>${escapeHtml(choice)}</span></label>
          `).join("")}
        </div>
      </fieldset>`;
  }
  const control = field.kind === "choice"
    ? `<select name="sop-field-${index}-${escapeHtml(field.id)}" ${disabled ? "disabled" : ""}>
        <option value="">Select</option>
        ${(field.choices || []).map((choice) => `<option value="${escapeHtml(choice)}" ${value === choice ? "selected" : ""}>${escapeHtml(choice)}</option>`).join("")}
      </select>`
    : `<span class="sop-reading-control"><input name="sop-field-${index}-${escapeHtml(field.id)}" type="${field.kind === "number" ? "number" : "text"}" ${field.kind === "number" ? `inputmode="decimal" step="${escapeHtml(field.step || "any")}"` : ""} value="${escapeHtml(value)}" ${disabled ? "disabled" : ""}>${field.unit ? `<strong>${escapeHtml(field.unit)}</strong>` : ""}</span>`;
  return `
    <label class="sop-structured-field">
      ${escapeHtml(field.label)}${field.required ? " *" : ""}
      ${control}
    </label>
    ${needsRemark ? `<label class="sop-field-failure">${escapeHtml(field.label)} Remark *<input name="sop-field-remark-${index}-${escapeHtml(field.id)}" value="${escapeHtml(remark)}" placeholder="Describe the failed condition" ${disabled ? "disabled" : ""}></label>` : ""}
  `;
}

function renderSopDerivedFieldSummary(step, stepState) {
  if (!step?.tankCapacityCalculation || stepState.fieldValues?.capacityMethod !== "Calculate from dimensions") return "";
  const calculation = calculateTankStorageCapacity(stepState.fieldValues);
  if (!calculation) {
    return `<div class="sop-auto-result waiting"><span>Calculated Capacity</span><strong>Enter all three positive dimensions</strong></div>`;
  }
  return `<div class="sop-auto-result complete"><span>Tank Size · Read-only</span><strong>${escapeHtml(calculation.lengthFt)} × ${escapeHtml(calculation.widthFt)} × ${escapeHtml(calculation.heightFt)} ft</strong><small>Calculated Storage: ${escapeHtml(calculation.capacityGallons.toLocaleString("en-US", { maximumFractionDigits: 2 }))} gal</small></div>`;
}

function renderSopValidationNotice(step, stepState) {
  if (!step?.phaseSupplyValidation) return "";
  const phaseState = getPumpPhaseSupplyState(stepState);
  if (!phaseState.hasReadings || !phaseState.abnormal) return "";
  const readings = Object.entries(phaseState.readings).map(([key, value]) => `${key}: ${value || "missing"} V`).join(" | ");
  return `<div class="sop-auto-result fault"><span>PHASE SUPPLY ABNORMAL</span><strong>${escapeHtml(readings)}</strong><small>Each phase-to-phase reading must be within 376-440 V. Raw readings are retained; acknowledge the condition in remarks before saving. Step 6 and later pump tests remain locked.</small></div>`;
}

function renderSopLinkedSummary(autoResult) {
  if (!autoResult?.applicable) return "";
  return `
    <div class="sop-linked-summary">
      ${(autoResult.details || []).map((item) => `<div class="${escapeHtml(item.status.toLowerCase())}"><span>${escapeHtml(item.label)}</span><strong>${escapeHtml(item.status)}</strong></div>`).join("")}
      <div class="overall ${escapeHtml(String(autoResult.overall || "PENDING").toLowerCase())}"><span>Overall</span><strong>${escapeHtml(autoResult.overall || "PENDING")}</strong></div>
      <small>Source: ${escapeHtml(autoResult.source || "Linked Verification")}</small>
    </div>
  `;
}

function isPumpStagedSop(template) {
  return template?.id === "sprinkler-hydrant-pump-sop" && getCurrentUserRole() === "Technician";
}

function getTechnicianSopStageDefinitions(template) {
  if (getCurrentUserRole() !== "Technician") return [];
  return TECHNICIAN_SOP_STAGE_DEFINITIONS[template?.id] || [];
}

function isTechnicianStagedSop(template) {
  return getTechnicianSopStageDefinitions(template).length > 0;
}

function getTechnicianSopStageForStep(template, index) {
  return getTechnicianSopStageDefinitions(template).find((stage) => stage.stepIndexes.includes(index)) || null;
}

function getPumpSopStageForStep(index) {
  return PUMP_SOP_STAGE_DEFINITIONS.find((stage) => stage.stepIndexes.includes(index)) || null;
}

function sopStepHasFault(step, stepState = {}) {
  const negativeChoices = new Set([
    "fail", "failed", "fault", "insufficient", "partially open", "closed", "some closed",
    "weak", "low", "abnormal", "need attention", "needs attention", "not confirmed",
    "no indication", "not received", "mismatch"
  ]);
  if (negativeChoices.has(normalizeScopeText(stepState.choice))) return true;
  const fields = getEffectiveSopFields(step, { steps: {} }, state.activeCriticalDevice, stepState.fieldValues || {});
  if (fields.some((field) => Array.isArray(field.requiresRemarkOn) && sopValueMatches(stepState.fieldValues?.[field.id], field.requiresRemarkOn))) return true;
  if (Object.values(stepState.fieldValues || {}).some((value) => negativeChoices.has(normalizeScopeText(value)))) return true;
  if (step.phaseSupplyValidation && getPumpPhaseSupplyState(stepState).abnormal) return true;
  if (step.linkedGasTestKey && getGasLinkedStepRequirement(step)?.mismatch) return true;
  return normalizeScopeText(stepState.autoResult?.overall) === "fail";
}

function getPumpSopStageStates(template, saved, device = state.activeCriticalDevice) {
  let previousComplete = true;
  const definitions = getTechnicianSopStageDefinitions(template);
  return definitions.map((definition, stageIndex) => {
    const stepStates = definition.stepIndexes.map((index) => {
      const step = template.steps[index];
      const stepState = getSopStepRenderState(step, index, template.id, saved);
      const stageBlock = getCriticalSopStepStageBlock(template, device, index, saved);
      return {
        index,
        step,
        stepState,
        complete: isSopStepComplete(step, stepState, template, index, saved) && !stageBlock.blocked,
        fault: sopStepHasFault(step, stepState)
      };
    });
    const completeCount = stepStates.filter((item) => item.complete).length;
    const faultCount = stepStates.filter((item) => item.fault).length;
    const complete = completeCount === stepStates.length;
    const accessible = previousComplete;
    const result = {
      ...definition,
      stageIndex,
      completeCount,
      totalCount: stepStates.length,
      faultCount,
      complete,
      accessible,
      stepStates
    };
    previousComplete = previousComplete && complete && faultCount === 0;
    return result;
  });
}

function getActivePumpSopStage(storageKey, stages) {
  if (state.pumpSopStageSelection && state.pumpSopStageSelection !== state.sopStageSelection) {
    state.sopStageSelection = state.pumpSopStageSelection;
  }
  state.sopStageSelection = state.sopStageSelection || {};
  state.pumpSopStageSelection = state.sopStageSelection;
  const selectedId = state.sopStageSelection?.[storageKey] || "";
  const selected = stages.find((stage) => stage.id === selectedId && stage.accessible);
  if (selected) return selected;
  return stages.find((stage) => stage.accessible && !stage.complete)
    || [...stages].reverse().find((stage) => stage.accessible)
    || stages[0];
}

function getPumpSopStageStatus(stage, activeStage) {
  if (stage.id === activeStage?.id) return "active";
  if (!stage.accessible) return "locked";
  if (stage.faultCount) return "fault";
  if (stage.complete) return "complete";
  return "ready";
}

function renderPumpSopStageNavigator(stages, activeStage, saved = {}) {
  const completedStages = stages.filter((stage) => stage.complete).length;
  const totalFaults = stages.reduce((sum, stage) => sum + stage.faultCount, 0);
  const syncStatus = saved.syncStatus === "synced"
    ? "Synced"
    : saved.syncStatus === "draft" || saved.unsynced
      ? "Pending sync"
      : saved.syncStatus === "conflict"
        ? "Sync problem"
        : "Not saved";
  return `
    <section class="pump-sop-stage-shell" data-active-pump-stage="${escapeHtml(activeStage?.id || "")}">
      <header class="pump-sop-context">
        <div>
          <span>${escapeHtml(state.activeCriticalDevice?.siteName || state.siteProfile?.siteName || "Current site")}</span>
          <strong>${escapeHtml(state.activeCriticalDevice?.type || "System")} · Stage ${(activeStage?.stageIndex ?? 0) + 1} of ${stages.length}</strong>
          <small>${escapeHtml(activeStage?.label || "System checklist")} · ${completedStages}/${stages.length} complete</small>
        </div>
        <span class="pump-sop-sync ${escapeHtml(normalizeScopeText(syncStatus))}">${escapeHtml(syncStatus)}</span>
      </header>
      <div class="pump-sop-stage-progress" aria-label="${completedStages} of ${stages.length} Pump stages complete"><span style="width:${Math.round((completedStages / Math.max(stages.length, 1)) * 100)}%"></span></div>
      <button type="button" class="secondary pump-sop-open-drawer" data-pump-open-stage-drawer>Stages</button>
      ${totalFaults ? `<div class="pump-sop-fault-summary"><strong>${totalFaults} fault${totalFaults === 1 ? "" : "s"} recorded</strong><span>Open the marked stage to review the saved result.</span></div>` : ""}
      <div class="pump-sop-stage-content">
  `;
}

function renderSopChoiceControl(step, index, stepState, disabled, usePumpChoiceButtons) {
  if (!step.requiresChoice) return "";
  if (usePumpChoiceButtons && !step.changeableConfiguration && !step.autoResult?.applicable) {
    return `
      <fieldset class="sop-choice-buttons">
        <legend>${escapeHtml(step.choiceLabel || "Result")}</legend>
        <div>
          ${(step.choices || ["Pass", "Fail", "N/A"]).map((choice) => `
            <label class="choice-${escapeHtml(normalizeScopeText(choice))}">
              <input type="radio" name="sop-choice-${index}" value="${escapeHtml(choice)}" ${stepState.choice === choice ? "checked" : ""} ${disabled ? "disabled" : ""}>
              <span>${escapeHtml(choice.toUpperCase())}</span>
            </label>
          `).join("")}
        </div>
      </fieldset>
    `;
  }
  return `
    <label>
      ${escapeHtml(step.choiceLabel || "Result")}
      <select name="sop-choice-${index}" ${(disabled || (step.lockChoiceAfterSave && Boolean(stepState.choice))) ? "disabled" : ""}>
        <option value="">Select before confirming</option>
        ${(step.choices || ["Pass", "Fail", "N/A"]).map((choice) => `
          <option value="${escapeHtml(choice)}" ${stepState.choice === choice ? "selected" : ""}>${escapeHtml(choice)}</option>
        `).join("")}
      </select>
      ${step.lockChoiceAfterSave && stepState.choice ? `<small class="auto-fill-note">Locked for this job/system · ${escapeHtml(stepState.choice)}</small>` : ""}
    </label>
  `;
}

function renderCriticalSop() {
  const tabs = document.querySelector("#criticalSopTabs");
  const form = document.querySelector("#criticalSopForm");
  if (!tabs || !form) return;

  const activeTemplate = criticalSopTemplates.find((template) => template.id === state.activeCriticalSopId) || criticalSopTemplates[0];
  state.activeCriticalSopId = activeTemplate.id;
  const storageKey = getCriticalSopStorageKey(activeTemplate.id);
  const rawSaved = state.criticalSops[storageKey] || state.criticalSops[activeTemplate.id] || { templateId: activeTemplate.id, steps: {}, generalRemarks: "" };
  const saved = normalizeCriticalSopRecordForTemplate(rawSaved, activeTemplate);
  if (saved !== rawSaved) state.criticalSops[storageKey] = saved;
  const evidence = getCriticalSopEvidenceDomState(saved);
  const evidenceMissing = getMissingCriticalSopEvidence(activeTemplate, evidence);
  const activeDevice = state.activeCriticalDevice;
  const activeSchedule = getActiveTechnicianMaintenanceSchedule();
  const workflowRun = activeDevice ? getCriticalWorkflowRunForParentDevice(activeDevice, activeSchedule) : null;
  const workflowStage = workflowRun ? getCriticalWorkflowRunState(workflowRun, activeSchedule) : null;
  const isMfapWorkspace = activeTemplate.id === "fire-alarm-tripping-sop" && getCurrentUserRole() === "Technician";
  const isStagedWorkspace = isTechnicianStagedSop(activeTemplate);
  const sopStages = isStagedWorkspace ? getPumpSopStageStates(activeTemplate, saved, activeDevice) : [];
  const activeSopStage = isStagedWorkspace ? getActivePumpSopStage(storageKey, sopStages) : null;
  criticalSopPanel?.classList.toggle("pump-staged-active", isStagedWorkspace);
  criticalSopPanel?.classList.toggle("technician-staged-active", isStagedWorkspace);
  document.querySelector("#saveCriticalSopBtn")?.classList.toggle("hidden", getCurrentUserRole() === "Technician");
  if (isMfapWorkspace) initializeMfapPendingUiState(activeSchedule);
  const heading = document.querySelector("#criticalSopPanel h2");
  if (heading) {
    heading.textContent = activeDevice
      ? `${activeDevice.tag} - ${activeTemplate.title}`
      : "Step-By-Step MOS Workflow";
  }

  const visibleTemplates = getCurrentUserRole() === "Technician" && activeDevice
    ? [activeTemplate]
    : criticalSopTemplates;
  tabs.innerHTML = visibleTemplates.map((template) => {
    const checkKey = getCriticalSopStorageKey(template.id);
    const check = state.criticalSops[checkKey] || state.criticalSops[template.id] || { steps: {} };
    const completed = getCriticalSopCompleteCount(template, check);
    return `
      <button type="button" class="${template.id === state.activeCriticalSopId ? "active" : ""}" data-sop-id="${template.id}">
        <strong>${escapeHtml(template.title)}</strong>
        <span>${completed} of ${template.steps.length} step(s) confirmed</span>
      </button>
    `;
  }).join("");

  tabs.querySelectorAll("button").forEach((button) => {
    button.addEventListener("click", () => {
      state.activeCriticalSopId = button.dataset.sopId;
      renderCriticalSop();
    });
  });

  let locked = false;
  form.innerHTML = `
    ${activeDevice ? `
      <div class="critical-device-summary">
        <span><strong>Device</strong>${escapeHtml(activeDevice.tag)}</span>
        <span><strong>Type</strong>${escapeHtml(activeDevice.type || "-")}</span>
        <span><strong>Floor</strong>${escapeHtml(activeDevice.floor || "-")}</span>
        <span><strong>Location</strong>${escapeHtml(displayDeviceLocation(activeDevice.location || ""))}</span>
      </div>
    ` : ""}
    ${getCurrentUserRole() === "Technician" && activeSchedule && state.activeTechSystemKey ? `
      <div class="tech-critical-actions">
        <button type="button" class="secondary" data-tech-critical-dashboard>Back to Dashboard</button>
        <button type="button" class="secondary" data-tech-critical-system-list>Back to System List</button>
        <button type="button" class="secondary" data-tech-critical-view-mimic>View Mimic</button>
        <span>Open the current system mimic for location reference. Locked pins still require this System Check.</span>
      </div>
    ` : ""}
    ${isMfapWorkspace ? `
      <div data-critical-job-alerts>${renderTechnicianJobAlerts(activeSchedule)}</div>
      <div class="mfap-workspace-navigation" data-mfap-workspace-navigation>
        <div class="mfap-workspace-tabs" role="tablist" aria-label="MFAP workspace views">
          <button type="button" role="tab" data-mfap-workspace-tab="checklist">CHECKLIST</button>
          <button type="button" role="tab" data-mfap-workspace-tab="live">LIVE INDICATIONS (<span data-mfap-pending-count>${getMfapActiveLiveEvents(activeSchedule).length}</span>)</button>
        </div>
        <div class="mfap-new-indication-alert hidden" data-mfap-new-indication-alert role="status">
          <div><strong>NEW INDICATION TEST</strong><span data-mfap-new-indication-title></span></div>
          <button type="button" data-mfap-view-new-indication>VIEW</button>
        </div>
      </div>
      <section class="mfap-live-indications-view ${state.activeMfapWorkspaceTab === "live" ? "" : "hidden"}" data-mfap-live-view role="tabpanel">
        <div data-critical-linked-prompt>${renderCriticalSopLiveLinkedPrompt(activeSchedule)}</div>
      </section>
      <section class="mfap-checklist-view ${state.activeMfapWorkspaceTab === "live" ? "hidden" : ""}" data-mfap-checklist-view role="tabpanel">
    ` : `<div data-critical-linked-prompt>${renderCriticalSopLiveLinkedPrompt(activeSchedule)}</div>`}
    <div class="critical-warning danger">
      <strong>${escapeHtml(activeTemplate.title)}</strong>
      <span>${escapeHtml(activeTemplate.danger)}</span>
    </div>
    ${renderCriticalWorkflowStageBanner(workflowRun, workflowStage)}
    ${activeTemplate.requiresBeforeAfterPhotos ? `
      <div class="critical-evidence-card">
        <div class="sop-evidence-head">
          <div>
            <strong>Required Critical Evidence</strong>
            <span>One before photo and one after photo for the full ${escapeHtml(activeTemplate.title)} record.</span>
          </div>
          <div class="sop-filled-by">
            <span>Filled by</span>
            <strong>${escapeHtml(evidence.filledBy || getCurrentUserName())}</strong>
          </div>
        </div>
        <div class="sop-evidence-grid">
          <label>
            Before Photo
            <input id="criticalBeforePhoto" type="file" accept="image/*">
            <span id="criticalBeforePhotoName">${escapeHtml(evidence.beforePhoto || "No before photo saved")}</span>
          </label>
          <label>
            After Photo
            <input id="criticalAfterPhoto" type="file" accept="image/*">
            <span id="criticalAfterPhotoName">${escapeHtml(evidence.afterPhoto || "No after photo saved")}</span>
          </label>
        </div>
        ${isCriticalDemoEvidenceMode() ? `
          <div class="sop-demo-evidence-actions" role="group" aria-label="Development evidence controls">
            <strong>TEST / DEVELOPMENT MODE</strong>
            <button type="button" class="secondary sop-demo-photo" data-critical-demo-photo="before">Demo Before Picture</button>
            <button type="button" class="secondary sop-demo-photo" data-critical-demo-photo="after">Demo After Picture</button>
          </div>
        ` : ""}
        ${evidenceMissing.length ? `<p class="locked-note">Required before final confirmation: ${escapeHtml(evidenceMissing.join(", "))}.</p>` : ""}
      </div>
    ` : ""}
    ${isStagedWorkspace ? renderPumpSopStageNavigator(sopStages, activeSopStage, saved) : `
      <div class="sop-progress">
        <strong>${getCriticalSopCompleteCount(activeTemplate, saved)}/${activeTemplate.steps.length}</strong>
        <span>${activeTemplate.fastTickMode ? "Tick each step in order. Final confirmation needs the photos above and supervisor name." : "completed in order. Next step stays locked until required evidence is recorded."}</span>
      </div>
    `}
    ${activeTemplate.steps.map((step, index) => {
      const stepState = getSopStepRenderState(step, index, activeTemplate.id, saved);
      const stageBlock = getCriticalSopStepStageBlock(activeTemplate, activeDevice, index, saved);
      const isComplete = isSopStepComplete(step, stepState, activeTemplate, index, saved) && !stageBlock.blocked;
      const disabled = locked || stageBlock.blocked;
      const missing = getMissingSopRequirements(step, stepState, activeTemplate, index, saved);
      const pumpConfiguration = step.configurationKey ? getPumpConfiguration(activeSchedule, activeDevice) : null;
      const configurationLocked = Boolean(pumpConfiguration && !pumpConfigurationNeedsSetupUpgrade(step, pumpConfiguration) && !isPumpConfigurationEditing(step));
      const effectiveFields = getEffectiveSopFields(step, saved, activeDevice, stepState.fieldValues || {});
      const statusText = stageBlock.blocked ? "Final restoration locked" : disabled ? "Locked" : isComplete ? "Completed" : (missing.length ? `Need ${missing.join(", ")}` : "Ready to confirm");
      const pumpStage = isStagedWorkspace ? getTechnicianSopStageForStep(activeTemplate, index) : null;
      const pumpStepHidden = Boolean(pumpStage && pumpStage.id !== activeSopStage?.id);
      const pumpStepExpansionKey = `${storageKey}::${index}`;
      const pumpStepExpanded = state.pumpSopExpandedStepKey === pumpStepExpansionKey;
      const pumpStepCollapsed = Boolean(pumpStage && (isComplete || disabled) && !pumpStepExpanded);
      const remarkRequired = sopStepNeedsRemark(step) || sopStepChoiceNeedsRemark(step, stepState) || Boolean(step.phaseSupplyValidation && getPumpPhaseSupplyState(stepState).abnormal);
      const remarkVisible = sopStepShowsRemark(activeTemplate.steps[index], stepState, activeTemplate.id, index);
      if (!isComplete) locked = true;
      return `
        <fieldset class="sop-step ${step.critical ? "critical" : ""} ${disabled ? "locked" : ""} ${isComplete ? "complete" : ""} ${pumpStepHidden ? "pump-sop-step-hidden" : ""} ${pumpStepCollapsed ? "pump-sop-step-collapsed" : ""}" data-sop-step-index="${index}" ${pumpStage ? `data-pump-sop-step-stage="${escapeHtml(pumpStage.id)}"` : ""}>
          <legend>Step ${index + 1}</legend>
          <div class="sop-step-head">
            <span class="sop-status ${isComplete ? "complete" : ""}">${escapeHtml(statusText)}</span>
            <div class="sop-requirements">${sopRequirementBadges(step)}</div>
            ${pumpStage && isComplete ? `<button type="button" class="secondary pump-sop-step-toggle" data-pump-sop-step-toggle="${index}">${pumpStepExpanded ? "Close" : "Review"}</button>` : ""}
          </div>
          ${step.noConfirm ? `
            <div class="sop-confirm no-checkbox">
              <strong>${escapeHtml(step.title)}</strong>
              <span>${step.optionalRemark && !step.requiresChoice && !step.requiresReading ? "Optional entry. You can continue without filling it." : "Complete the required value below to continue."}</span>
            </div>
          ` : `
            <label class="sop-confirm">
              <input type="checkbox" name="sop-confirm-${index}" ${isComplete || (step.linkedGasTestKey && stepState.confirmed) ? "checked" : ""} ${disabled ? "disabled" : ""}>
              <strong>${escapeHtml(step.title)}</strong>
            </label>
          `}
          ${isStagedWorkspace ? `
            <details class="sop-how-to">
              <summary>How to check</summary>
              <p>${escapeHtml(step.detail)}</p>
            </details>
          ` : `<p>${escapeHtml(step.detail)}</p>`}
          <div class="sop-grid">
            ${step.readOnlyLinkedSummary && stepState.autoResult?.applicable ? renderSopLinkedSummary(stepState.autoResult) : step.requiresChoice && stepState.autoResult?.applicable ? `
              <div class="sop-auto-result ${stepState.choice ? "complete" : "waiting"}">
                <span>${escapeHtml(step.choiceLabel || "Result")} · Read-only</span>
                <strong>${escapeHtml(stepState.choice || "Awaiting linked verification")}</strong>
                <small>${escapeHtml(stepState.autoResult.message)}</small>
              </div>
            ` : step.requiresChoice && !(step.configurationKey === "standbyPump" && configurationLocked)
              ? renderSopChoiceControl(step, index, stepState, disabled, isStagedWorkspace)
              : ""}
            ${renderPumpConfigurationSummary(step, stepState)}
            ${effectiveFields.map((field) => renderSopStructuredField(field, index, stepState, disabled, configurationLocked)).join("")}
            ${renderSopDerivedFieldSummary(step, stepState)}
            ${renderSopValidationNotice(step, stepState)}
            ${step.linkedPumpTestKey || step.linkedGasTestKey ? `<div data-sop-inline-linked-step="${index}">${renderSopStepLinkedVerification(step, activeSchedule, activeDevice)}</div>` : ""}
            ${step.requiresReading ? `
              <label>
                ${escapeHtml(step.readingLabel || "Reading / Value")}
                <span class="sop-reading-control">
                  <input name="sop-reading-${index}" type="${step.readingType === "number" ? "number" : "text"}" ${step.readingType === "number" ? `inputmode="decimal" step="${escapeHtml(step.readingStep || "any")}"` : ""} value="${escapeHtml(stepState.reading || "")}" placeholder="${escapeHtml(step.readingPlaceholder || "Example: 26.8V / 120 PSI / 28 sec")}" ${disabled ? "disabled" : ""}>
                  ${step.readingUnit ? `<strong>${escapeHtml(step.readingUnit)}</strong>` : ""}
                </span>
              </label>
            ` : ""}
            ${step.usesStandbyConfiguration ? `<div class="sop-auto-result complete"><span>Configured standby · Read-only</span><strong>${escapeHtml(getSavedSopStandbyConfiguration(activeTemplate, saved) || "Not configured")}</strong><small>Auto-filled from the saved standby setup for this job/system.</small></div>` : ""}
            ${!remarkVisible ? `<button type="button" class="secondary sop-remark-toggle" data-sop-remark-toggle="${index}" ${disabled ? "disabled" : ""}>+ Add Remarks</button>` : ""}
            ${remarkVisible ? `
              <label data-sop-remark-field="${index}">
                ${remarkRequired ? "Remarks *" : "Optional Remark"}
                <input name="sop-remark-${index}" value="${escapeHtml(stepState.remark || "")}" placeholder="${remarkRequired ? "Describe the observation or failed condition" : "Optional additional observation"}" ${disabled ? "disabled" : ""}>
              </label>
            ` : ""}
            ${sopStepRequiresPhoto(step, stepState) ? `
              <label>
                Required Photo
                <input name="sop-photo-${index}" type="file" accept="image/*" ${disabled ? "disabled" : ""}>
                <span id="sop-photo-name-${index}">${escapeHtml(stepState.photo || "No saved photo name")}</span>
              </label>
            ` : ""}
            ${step.requiresSupervisor ? `
              <label>
                Supervisor Confirmation
                <input name="sop-supervisor-${index}" value="${escapeHtml(stepState.supervisor || "")}" placeholder="Supervisor name / PIN" ${disabled ? "disabled" : ""}>
              </label>
            ` : ""}
            ${step.captureTechnician ? `
              <label>
                Confirmed By
                <input value="${escapeHtml(stepState.recordedBy || getCurrentUserName())}" readonly aria-readonly="true">
                <small class="auto-fill-note">Read-only · Auto-filled from logged-in Technician</small>
              </label>
            ` : ""}
          </div>
          ${stageBlock.blocked ? `<p class="locked-note">${escapeHtml(stageBlock.reason)}</p>` : disabled ? `<p class="locked-note">Complete previous step first.</p>` : ""}
          ${!disabled && !isComplete && missing.length ? `<p class="locked-note">Required before confirm: ${escapeHtml(missing.join(", "))}.</p>` : ""}
        </fieldset>
      `;
    }).join("")}
    ${isStagedWorkspace ? "</div></section>" : ""}
    ${!isStagedWorkspace || activeSopStage?.stageIndex === sopStages.length - 1 ? `
      <label>
        Overall SOP Remarks
        <textarea id="criticalSopRemarks" rows="4" placeholder="Final safety note, abnormal condition, client instruction.">${escapeHtml(saved.generalRemarks || "")}</textarea>
      </label>
    ` : ""}
    ${getCurrentUserRole() === "Technician" ? `
      <div class="pump-sop-sticky-actions">
        <button type="button" class="secondary" data-pump-sop-back>BACK</button>
        <span>${saved.syncStatus === "synced" ? "Saved and synced" : saved.unsynced ? "Saved locally · pending sync" : "Complete the current stage"}</span>
        <button id="saveCriticalSopBottomBtn" type="button">SAVE & NEXT</button>
      </div>
    ` : `
      <div class="form-bottom-actions">
        <button id="saveCriticalSopBottomBtn" type="button">Save Critical SOP</button>
        <button id="saveCriticalSopNextBtn" type="button">Save Critical SOP & Next Item</button>
      </div>
    `}
    ${isMfapWorkspace ? "</section>" : ""}
  `;

  if (isStagedWorkspace) {
    form.dataset.activePumpStage = activeSopStage?.id || "";
  } else {
    delete form.dataset.activePumpStage;
  }
  const primarySaveButton = document.querySelector("#saveCriticalSopBottomBtn");
  if (primarySaveButton) {
    bindReliableTap(primarySaveButton, () => runCriticalSopPrimaryAction(primarySaveButton, isStagedWorkspace ? savePumpSopStageAndAdvance : saveCriticalSopAndOpenNext));
  }
  document.querySelector("#saveCriticalSopNextBtn")?.addEventListener("click", saveCriticalSopAndOpenNext);
  form.querySelectorAll("[data-pump-sop-stage]").forEach((button) => {
    bindReliableTap(button, () => {
      if (button.disabled) return;
      state.sopStageSelection = state.sopStageSelection || state.pumpSopStageSelection || {};
      state.pumpSopStageSelection = state.sopStageSelection;
      state.sopStageSelection[storageKey] = button.dataset.pumpSopStage;
      renderCriticalSopPreservingScroll();
      requestAnimationFrame(() => document.querySelector(".pump-sop-stage-content")?.scrollIntoView({ block: "start", behavior: "smooth" }));
    });
  });
  form.querySelectorAll("[data-pump-open-stage-drawer]").forEach((button) => {
    bindReliableTap(button, () => setTechSystemDrawerOpen(true));
  });
  form.querySelectorAll("[data-pump-sop-step-toggle]").forEach((button) => {
    button.addEventListener("click", () => {
      const expansionKey = `${storageKey}::${button.dataset.pumpSopStepToggle}`;
      state.pumpSopExpandedStepKey = state.pumpSopExpandedStepKey === expansionKey ? "" : expansionKey;
      renderCriticalSopPreservingScroll();
    });
  });
  form.querySelector("[data-pump-sop-back]")?.addEventListener("click", () => openPreviousPumpSopStage(storageKey, sopStages, activeSopStage));
  form.querySelectorAll("[data-tech-critical-view-mimic]").forEach((button) => {
    bindReliableTap(button, () => openCurrentTechnicianMimic({ scroll: true }));
  });
  form.querySelectorAll("[data-tech-critical-system-list]").forEach((button) => {
    bindReliableTap(button, showTechnicianSystemList);
  });
  form.querySelectorAll("[data-tech-critical-dashboard]").forEach((button) => {
    bindReliableTap(button, () => {
      if (!confirmTechnicianNavigation()) return;
      clearTechnicianInspectionDirty();
      setTechScreen("jobs", { scroll: true, skipDirtyCheck: true });
    });
  });

  form.querySelectorAll("input[type='checkbox']").forEach((checkbox) => {
    checkbox.addEventListener("change", async () => {
      const index = Number(checkbox.name.replace("sop-confirm-", ""));
      const step = activeTemplate.steps[index];
      const stepState = getSopStepDomState(step, index, activeTemplate.id);
      const explicitGasSave = activeTemplate.id === "gas-discharge-sop" && getCurrentUserRole() === "Technician";
      const missing = getMissingSopRequirements(step, stepState, activeTemplate, index, saved, {
        useDomEvidence: true,
        ignoreLinkedVerification: explicitGasSave
      });
      if (checkbox.checked && missing.length) {
        checkbox.checked = false;
        document.querySelector("#syncState").textContent = `Cannot confirm Step ${index + 1}: missing ${missing.join(", ")}`;
        return;
      }
      if (explicitGasSave) {
        document.querySelector("#syncState").textContent = `Step ${index + 1} ready. Press SAVE & NEXT once.`;
        return;
      }
      await saveCriticalSop(false);
      renderCriticalSopPreservingScroll();
    });
  });

  form.querySelectorAll("select[name^='sop-choice-']").forEach((select) => {
    select.addEventListener("change", async () => {
      if (activeTemplate.id === "gas-discharge-sop" && getCurrentUserRole() === "Technician") return;
      await saveCriticalSop(false);
      renderCriticalSopPreservingScroll();
    });
  });

  form.querySelectorAll("input[type='radio'][name^='sop-choice-']").forEach((radio) => {
    radio.addEventListener("change", async () => {
      if (activeTemplate.id === "gas-discharge-sop" && getCurrentUserRole() === "Technician") return;
      await saveCriticalSop(false);
      renderCriticalSopPreservingScroll();
    });
  });

  form.querySelectorAll("[data-change-pump-config]").forEach((button) => {
    button.addEventListener("click", () => {
      const step = activeTemplate.steps.find((item) => item.configurationKey === button.dataset.changePumpConfig);
      if (!step) return;
      state.pumpConfigurationEditKey = getPumpConfigurationEditToken(step, activeSchedule, activeDevice);
      renderCriticalSopPreservingScroll();
      document.querySelector("#syncState").textContent = "Configuration change opened. Saving will create a revisioned update.";
    });
  });

  form.querySelectorAll("[data-sop-remark-toggle]").forEach((button) => {
    button.addEventListener("click", () => {
      const index = button.dataset.sopRemarkToggle;
      state.sopRemarkVisibility = state.sopRemarkVisibility || {};
      state.sopRemarkVisibility[getCriticalSopEvidenceKey(activeTemplate.id, index)] = true;
      const field = document.createElement("label");
      field.dataset.sopRemarkField = index;
      field.innerHTML = `Optional Remark<input name="sop-remark-${escapeHtml(index)}" placeholder="Optional additional observation">`;
      button.replaceWith(field);
      field.querySelector("input")?.focus();
    });
  });

  bindCriticalSopLinkedPromptControls(form.querySelector("[data-critical-linked-prompt]"), activeSchedule);
  form.querySelectorAll("[data-linked-live-toggle]").forEach((button) => {
    bindReliableTap(button, () => handleLinkedLiveToggle(button, activeSchedule));
  });
  form.querySelectorAll("[data-gas-live-start]").forEach((button) => {
    bindReliableTap(button, () => handleGasLiveStart(button, activeSchedule));
  });
  if (isMfapWorkspace) bindMfapWorkspaceNavigation(activeSchedule);

  form.querySelectorAll("input[name^='sop-reading-'], input[name^='sop-remark-'], input[name^='sop-field-'], select[name^='sop-field-']").forEach((input) => {
    input.addEventListener("change", async () => {
      if (activeTemplate.id === "gas-discharge-sop" && getCurrentUserRole() === "Technician") {
        document.querySelector("#syncState").textContent = "Entry ready. Press SAVE & NEXT once.";
        return;
      }
      await saveCriticalSop(false);
      renderCriticalSopPreservingScroll();
    });
  });

  form.querySelectorAll("#criticalBeforePhoto, #criticalAfterPhoto").forEach((input) => {
    input.addEventListener("change", async () => {
      const file = input.files?.[0];
      const fileName = file?.name || "";
      if (!file) return;
      const type = input.id === "criticalBeforePhoto" ? "before" : "after";
      const key = getCriticalSopEvidenceKey(activeTemplate.id);
      const label = document.querySelector(input.id === "criticalBeforePhoto" ? "#criticalBeforePhotoName" : "#criticalAfterPhotoName");
      const processingKey = `${key}::${type}`;
      criticalSopEvidenceProcessingKeys.add(processingKey);
      input.disabled = true;
      if (label) label.textContent = `Processing ${fileName || `${type} photo`}...`;
      document.querySelector("#syncState").textContent = `${input.id === "criticalBeforePhoto" ? "Before" : "After"} photo is being processed. Please wait.`;
      try {
        const retainedEvidence = await createPhotoEvidenceFromFile(file, `critical-${type}`, {
          deviceId: activeDevice?.id || activeDevice?.tag || activeTemplate.id,
          locationLabel: activeDevice?.location || activeDevice?.floor || "",
          allowUnstampedFallback: true
        });
        if (!hasRetainedPhotoEvidence(retainedEvidence)) throw new Error("The selected photo could not be retained.");
        pendingCriticalSopPhotoEvidence.overall[key] = pendingCriticalSopPhotoEvidence.overall[key] || {};
        pendingCriticalSopPhotoEvidence.overall[key][type] = retainedEvidence;
        criticalSopEvidenceProcessingKeys.delete(processingKey);
        if (label) label.textContent = criticalEvidenceDisplayName(fileName, retainedEvidence);
        const saveResult = await saveCriticalSop(false);
        if (!saveResult?.ok) throw new Error(saveResult?.reason || "The retained photo could not be saved.");
        renderCriticalSopPreservingScroll();
        document.querySelector("#syncState").textContent = `${input.id === "criticalBeforePhoto" ? "Before" : "After"} photo saved and ready`;
      } catch (error) {
        criticalSopEvidenceProcessingKeys.delete(processingKey);
        input.disabled = false;
        if (label) label.textContent = `Photo not saved · ${error?.message || "processing failed"}`;
        document.querySelector("#syncState").textContent = `${input.id === "criticalBeforePhoto" ? "Before" : "After"} photo was not saved. Choose the photo again.`;
      }
    });
  });
  form.querySelectorAll("[data-critical-demo-photo]").forEach((button) => {
    bindReliableTap(button, async (event) => {
      event.preventDefault();
      if (!isCriticalDemoEvidenceMode()) return;
      const type = button.dataset.criticalDemoPhoto;
      const key = getCriticalSopEvidenceKey(activeTemplate.id);
      pendingCriticalSopPhotoEvidence.overall[key] = pendingCriticalSopPhotoEvidence.overall[key] || {};
      pendingCriticalSopPhotoEvidence.overall[key][type] = createCriticalDemoEvidence(`critical-${type}`, {
        deviceId: activeDevice?.id || activeDevice?.tag || activeTemplate.id,
        locationLabel: activeDevice?.location || activeDevice?.floor || ""
      });
      const saveResult = await saveCriticalSop(false);
      if (!saveResult?.ok) return;
      renderCriticalSopPreservingScroll();
      document.querySelector("#syncState").textContent = `${type === "before" ? "Before" : "After"} DEMO / TEST EVIDENCE saved`;
    });
  });
  form.querySelectorAll("input[name^='sop-photo-']").forEach((input) => {
    input.addEventListener("change", async () => {
      const file = input.files?.[0];
      if (!file) return;
      const index = Number(input.name.replace("sop-photo-", ""));
      const key = getCriticalSopEvidenceKey(activeTemplate.id, index);
      pendingCriticalSopPhotoEvidence.steps[key] = await createPhotoEvidenceFromFile(file, `critical-step-${index + 1}`, {
        deviceId: activeDevice?.id || activeDevice?.tag || activeTemplate.id,
        locationLabel: activeDevice?.location || activeDevice?.floor || "",
        allowUnstampedFallback: true
      });
      const label = document.querySelector(`#sop-photo-name-${index}`);
      if (label) label.textContent = file.name;
      await saveCriticalSop(false);
      renderCriticalSopPreservingScroll();
      document.querySelector("#syncState").textContent = `Photo recorded for Step ${index + 1}`;
    });
  });
  if (activeTemplate.id === "fire-alarm-tripping-sop") {
    form.dataset.linkedAutoSignature = getFapLinkedAutoResultSignature(activeSchedule);
  } else {
    delete form.dataset.linkedAutoSignature;
  }
  if (activeTemplate.id === "gas-discharge-sop") {
    form.dataset.gasLinkedSignature = getGasLinkedProgressSignature(activeSchedule);
  } else {
    delete form.dataset.gasLinkedSignature;
  }
  renderTechDesktopNavigation(activeSchedule);
}

async function runCriticalSopPrimaryAction(button, action) {
  if (criticalSopPrimaryActionInFlight) return { ok: false, busy: true };
  criticalSopPrimaryActionInFlight = true;
  const originalText = button?.textContent || "SAVE & NEXT";
  if (button) {
    button.disabled = true;
    button.textContent = "SAVING...";
  }
  document.querySelector("#syncState").textContent = "Saving critical checklist...";
  try {
    return await action();
  } finally {
    criticalSopPrimaryActionInFlight = false;
    if (button?.isConnected) {
      button.disabled = false;
      button.textContent = originalText;
    }
  }
}

function openPreviousPumpSopStage(storageKey, stages, activeStage) {
  const currentIndex = stages.findIndex((stage) => stage.id === activeStage?.id);
  if (currentIndex <= 0) {
    openCurrentTechnicianMimic({ scroll: true });
    return;
  }
  state.sopStageSelection = state.sopStageSelection || state.pumpSopStageSelection || {};
  state.pumpSopStageSelection = state.sopStageSelection;
  state.sopStageSelection[storageKey] = stages[currentIndex - 1].id;
  renderCriticalSopPreservingScroll();
  requestAnimationFrame(() => document.querySelector(".pump-sop-stage-content")?.scrollIntoView({ block: "start", behavior: "smooth" }));
}

async function savePumpSopStageAndAdvance() {
  const template = criticalSopTemplates.find((item) => item.id === state.activeCriticalSopId);
  if (!isTechnicianStagedSop(template)) return saveCriticalSop(true);
  const storageKey = getCriticalSopStorageKey(template.id);
  const form = document.querySelector("#criticalSopForm");
  const currentStageId = form?.dataset.activePumpStage || "";
  const result = await saveCriticalSop(false);
  if (!result?.ok) return result;
  const saved = state.criticalSops[storageKey] || { steps: {} };
  const stages = getPumpSopStageStates(template, saved, state.activeCriticalDevice);
  const currentStage = stages.find((stage) => stage.id === currentStageId) || stages[0];
  if (!currentStage?.complete) {
    const isGasSop = template.id === "gas-discharge-sop";
    const nextIncomplete = isGasSop ? currentStage?.stepStates.find((item) => !item.complete) : null;
    state.sopStageSelection = state.sopStageSelection || state.pumpSopStageSelection || {};
    state.pumpSopStageSelection = state.sopStageSelection;
    state.sopStageSelection[storageKey] = currentStage?.id || "";
    renderCriticalSopPreservingScroll();
    if (nextIncomplete) {
      requestAnimationFrame(() => document.querySelector(`[data-sop-step-index="${nextIncomplete.index}"]`)?.scrollIntoView({ block: "center", behavior: "auto" }));
    }
    document.querySelector("#syncState").textContent = nextIncomplete
      ? `Saved. Continue with Step ${nextIncomplete.index + 1}: ${nextIncomplete.step.title}.`
      : `${currentStage?.label || "Current stage"} saved. Complete its required checks before continuing.`;
    return { ...result, stageComplete: false };
  }
  const nextStage = stages.find((stage) => stage.stageIndex > currentStage.stageIndex && stage.accessible && !stage.complete);
  state.sopStageSelection = state.sopStageSelection || state.pumpSopStageSelection || {};
  state.pumpSopStageSelection = state.sopStageSelection;
  if (nextStage) {
    state.sopStageSelection[storageKey] = nextStage.id;
  } else {
    delete state.sopStageSelection[storageKey];
    if (isCriticalSopRecordComplete(template, saved)) {
      return saveCriticalSopAndOpenNext();
    }
  }
  renderCriticalSop();
  requestAnimationFrame(() => document.querySelector(".pump-sop-stage-content")?.scrollIntoView({ block: "start", behavior: "smooth" }));
  document.querySelector("#syncState").textContent = nextStage
    ? `${currentStage.label} saved. Continue with ${nextStage.label}.`
    : `${template.title} stages complete. Review restoration and complete the item.`;
  return { ...result, stageComplete: true, nextStageId: nextStage?.id || "" };
}

function getPumpPhaseSupplyState(stepRecord = {}) {
  const values = stepRecord.fieldValues || {};
  const readings = {
    "R-Y": String(values.phaseRy ?? "").trim(),
    "Y-B": String(values.phaseYb ?? "").trim(),
    "B-R": String(values.phaseBr ?? "").trim()
  };
  const hasReadings = Object.values(readings).some(Boolean);
  const numericValues = Object.values(readings).map((value) => Number(value));
  const abnormal = hasReadings && Object.values(readings).some((value, index) => {
    const numeric = numericValues[index];
    return !value || !Number.isFinite(numeric) || numeric < 376 || numeric > 440;
  });
  return { readings, values: numericValues, hasReadings, abnormal, minimumVoltage: 376, maximumVoltage: 440 };
}

function buildPumpPhaseSupplyAlert(stepRecord = {}, schedule = getActiveTechnicianMaintenanceSchedule(), device = state.activeCriticalDevice) {
  const phaseState = getPumpPhaseSupplyState(stepRecord);
  if (!phaseState.hasReadings || !phaseState.abnormal) return null;
  const scheduleId = getScheduleKey(schedule);
  const pumpId = device?.id || device?.tag || "pump";
  return {
    alertId: `phase-supply::${scheduleId}::${pumpId}`,
    type: "PHASE_SUPPLY_ABNORMAL",
    severity: "critical",
    status: "ACTIVE",
    title: "PUMP ROOM - PHASE SUPPLY ABNORMAL",
    source: "Shared same-job Pump Step 5 alert",
    location: device?.location || device?.floor || "Pump Room",
    readings: phaseState.readings,
    scheduleId,
    deviceId: pumpId,
    detectedBy: getCurrentUserName(),
    detectedAt: new Date().toISOString()
  };
}

function getSharedJobAlerts(schedule = getActiveTechnicianMaintenanceSchedule()) {
  if (!schedule) return [];
  const store = getSharedStore(schedule) || {};
  const shared = Object.values(store.criticalSopRecords || {}).flatMap((record) => record.jobAlerts || []);
  const local = Object.values(state.criticalSops || {}).flatMap((record) => record.jobAlerts || []);
  const alerts = new Map();
  [...shared, ...local].forEach((alert) => {
    if (alert?.alertId && alert.status === "ACTIVE") alerts.set(alert.alertId, alert);
  });
  return [...alerts.values()];
}

function renderTechnicianJobAlerts(schedule) {
  const alerts = getSharedJobAlerts(schedule);
  if (!alerts.length) return "";
  return `<section class="tech-job-alerts" aria-label="Same job alerts">
    ${alerts.map((alert) => `<article>
      <strong>${escapeHtml(alert.title)}</strong>
      <span>${escapeHtml(alert.location)}</span>
      <small>${Object.entries(alert.readings || {}).map(([key, value]) => `${escapeHtml(key)}: ${escapeHtml(value || "missing")} V`).join(" | ")}</small>
      <em>${escapeHtml(alert.source)}</em>
    </article>`).join("")}
  </section>`;
}

function getPumpConfigurationCandidate(saved = {}) {
  const waterStep = saved.steps?.[2] || {};
  const standbyStep = saved.steps?.[7] || {};
  const standbyManualStep = saved.steps?.[10] || {};
  const water = waterStep.fieldValues || {};
  return {
    waterStorage: water.tankType && water.capacity && water.capacityUnit ? {
      tankType: water.tankType,
      tankTypeOther: water.tankTypeOther || "",
      capacityMethod: water.capacityMethod || "Use known capacity",
      tankLengthFt: water.tankLengthFt || "",
      tankWidthFt: water.tankWidthFt || "",
      tankHeightFt: water.tankHeightFt || "",
      capacity: water.capacity,
      capacityUnit: water.capacityUnit,
      capacityGallons: water.capacityGallons || ""
    } : null,
    standbyType: standbyStep.choice || "",
    dieselCoolingType: standbyManualStep.fieldValues?.coolingType || ""
  };
}

async function savePumpConfigurationFromSop(template, saved, schedule, device) {
  if (template?.id !== "sprinkler-hydrant-pump-sop") return { ok: true, skipped: true };
  const current = getPumpConfiguration(schedule, device) || {};
  const candidate = getPumpConfigurationCandidate(saved);
  const waterStep = template.steps.find((step) => step.configurationKey === "waterStorage");
  const standbyStep = template.steps.find((step) => step.configurationKey === "standbyPump");
  const waterEditable = !current.waterStorage || !current.waterStorage.capacityMethod || state.pumpConfigurationEditKey === getPumpConfigurationEditToken(waterStep, schedule, device);
  const standbyEditable = !current.standbyType || state.pumpConfigurationEditKey === getPumpConfigurationEditToken(standbyStep, schedule, device);
  const next = {
    ...current,
    waterStorage: waterEditable && candidate.waterStorage ? candidate.waterStorage : current.waterStorage || null,
    standbyType: standbyEditable && candidate.standbyType ? candidate.standbyType : current.standbyType || "",
    dieselCoolingType: candidate.dieselCoolingType || current.dieselCoolingType || ""
  };
  const comparable = (value) => JSON.stringify({
    waterStorage: value?.waterStorage || null,
    standbyType: value?.standbyType || "",
    dieselCoolingType: value?.dieselCoolingType || ""
  });
  if (comparable(current) === comparable(next)) return { ok: true, unchanged: true, configuration: current };
  return savePumpConfigurationRecord(next, schedule, device);
}

async function syncPumpManualLinkedVerifications(template, saved, schedule, device) {
  if (template?.id !== "sprinkler-hydrant-pump-sop" || !schedule || !device) return [];
  const definitions = getScheduleLinkedVerificationDefinitions(schedule);
  const results = [];
  for (const [index, step] of template.steps.entries()) {
    if (!step.linkedPumpTestKey) continue;
    const stepRecord = saved.steps?.[index] || {};
    const localResult = stepRecord.choice || stepRecord.fieldValues?.manualResult || "";
    if (!localResult) continue;
    const definition = definitions.find((item) => item.pumpTestKey === step.linkedPumpTestKey && item.pumpDeviceId === (device.id || device.tag));
    const side = definition?.requiredSides.find((item) => item.sideId === "PUMP_ROOM");
    if (!definition || !side || !linkedVerificationTechnicianMatches(side)) continue;
    const normalizedResult = normalizeScopeText(localResult) === "pass" ? "CONFIRMED" : "NOT_CONFIRMED";
    const result = await saveLinkedVerificationSide(schedule, definition, side, {
      result: normalizedResult,
      notes: stepRecord.remark || stepRecord.fieldRemarks?.manualResult || "",
      submissionId: `${getScheduleKey(schedule)}::${definition.linkedVerificationId}::PUMP_ROOM::${normalizedResult}`
    });
    results.push(result);
    if (result.ok && isLinkedVerificationLiveActive(getLinkedVerificationLiveState(schedule, definition.linkedVerificationId))) {
      await saveLinkedVerificationLiveState(schedule, definition, side, "ENDED");
    }
  }
  return results;
}

async function syncGasReleaseLinkedVerification(template, saved, schedule, device) {
  if (template?.id !== "gas-discharge-sop" || !schedule || !device) return [];
  const definitions = getScheduleLinkedVerificationDefinitions(schedule);
  const results = [];
  for (const [index, step] of template.steps.entries()) {
    if (!step.linkedGasTestKey) continue;
    const stepRecord = saved.steps?.[index] || {};
    const localResult = stepRecord.choice || stepRecord.fieldValues?.result || (stepRecord.confirmed ? "Pass" : "");
    if (!localResult) continue;
    const definition = definitions.find((item) => item.gasTestKey === step.linkedGasTestKey && item.gasDeviceId === (device.id || device.tag));
    const side = definition?.requiredSides.find((item) => item.sideId === "SUPPRESSION_SYSTEM_LOCATION");
    if (!definition || !side || !linkedVerificationTechnicianMatches(side)) continue;
    const normalizedResult = ["pass", "confirmed"].includes(normalizeScopeText(localResult)) ? "CONFIRMED" : "NOT_CONFIRMED";
    const result = await saveLinkedVerificationSide(schedule, definition, side, {
      result: normalizedResult,
      notes: stepRecord.remark || "",
      submissionId: `${getScheduleKey(schedule)}::${definition.linkedVerificationId}::SUPPRESSION_SYSTEM_LOCATION::${normalizedResult}`
    });
    results.push(result);
    if (result.ok
      && ["VERIFIED", "MISMATCH_REVIEW_REQUIRED"].includes(result.linkedVerification?.status)
      && isLinkedVerificationLiveActive(getLinkedVerificationLiveState(schedule, definition.linkedVerificationId))) {
      await saveLinkedVerificationLiveState(schedule, definition, side, "ENDED");
    }
  }
  return results;
}

async function saveCriticalSop(showMessage = true) {
  const template = criticalSopTemplates.find((item) => item.id === state.activeCriticalSopId) || criticalSopTemplates[0];
  if (isCriticalSopEvidenceProcessing(template.id)) {
    document.querySelector("#syncState").textContent = "Wait for the selected critical photo to finish processing before saving.";
    return { ok: false, evidenceProcessing: true };
  }
  const storageKey = getCriticalSopStorageKey(template.id);
  const previous = state.criticalSops[storageKey] || state.criticalSops[template.id] || {};
  const evidence = getCriticalSopEvidenceDomState(previous);
  const activeSchedule = getActiveTechnicianMaintenanceSchedule();
  if (isTechnicianReportReadOnly(activeSchedule)) {
    if (showMessage) {
      document.querySelector("#syncState").textContent = "This report is awaiting Admin Review. Admin must return it before technician edits are allowed.";
    }
    return { ok: false, readOnly: true };
  }
  const workflowRun = state.activeCriticalDevice ? getCriticalWorkflowRunForParentDevice(state.activeCriticalDevice, activeSchedule) : null;
  const now = new Date().toISOString();
  const steps = {};

  template.steps.forEach((step, index) => {
    const stepState = getSopStepDomState(step, index, template.id);
    const missing = getMissingSopRequirements(step, stepState, template, index, evidence);
    const storageMissing = step.linkedGasTestKey
      ? getMissingSopRequirements(step, stepState, template, index, evidence, { ignoreLinkedVerification: true })
      : missing;
    const stageBlock = getCriticalSopStepStageBlock(template, state.activeCriticalDevice, index, evidence);
    steps[index] = {
      ...stepState,
      confirmed: stageBlock.blocked
        ? false
        : step.noConfirm
          ? !storageMissing.length
          : Boolean(stepState.confirmed && !storageMissing.length)
    };
  });

  state.criticalSops[storageKey] = {
    templateId: template.id,
    templateVersion: getCriticalSopTemplateVersion(template),
    templateSnapshot: createCriticalSopTemplateSnapshot(template),
    legacySopMigration: previous.legacySopMigration || null,
    legacySteps: previous.legacySteps || {},
    workflowId: workflowRun?.workflowId || "",
    dependencyDefinitionId: workflowRun?.definitionId || "",
    title: template.title,
    deviceTag: state.activeCriticalDevice?.tag || "",
    deviceType: state.activeCriticalDevice?.type || "",
    floor: state.activeCriticalDevice?.floor || getFloorAsset(floorSelect.value).title,
    location: state.activeCriticalDevice?.location || "",
    companyName: document.querySelector("#mimicCompany").value.trim(),
    siteName: document.querySelector("#mimicSite").value.trim(),
    steps,
    beforePhoto: evidence.beforePhoto,
    afterPhoto: evidence.afterPhoto,
    beforePhotoEvidence: evidence.beforePhotoEvidence || null,
    afterPhotoEvidence: evidence.afterPhotoEvidence || null,
    filledBy: getCurrentUserName(),
    filledRole: getCurrentUserRole(),
    evidenceAt: evidence.beforePhoto || evidence.afterPhoto ? now : evidence.evidenceAt,
    generalRemarks: document.querySelector("#criticalSopRemarks")?.value.trim() ?? previous.generalRemarks ?? "",
    savedAt: now,
    savedBy: getCurrentUserName()
  };
  const savedRecord = state.criticalSops[storageKey];
  if (template.id === "sprinkler-hydrant-pump-sop") {
    const phaseAlert = buildPumpPhaseSupplyAlert(savedRecord.steps?.[4], activeSchedule, state.activeCriticalDevice);
    savedRecord.jobAlerts = phaseAlert ? [phaseAlert] : [];
    const configurationSave = await savePumpConfigurationFromSop(template, savedRecord, activeSchedule, state.activeCriticalDevice);
    if (configurationSave.conflict) {
      document.querySelector("#syncState").textContent = "Pump configuration changed on another device. Reload before changing it.";
      return { ok: false, conflict: true, configurationConflict: true };
    }
    savedRecord.pumpConfiguration = configurationSave.configuration || getPumpConfiguration(activeSchedule, state.activeCriticalDevice) || null;
    savedRecord.pumpConfigurationSyncStatus = configurationSave.offline ? "LOCAL_DRAFT" : "SYNCED";
  }
  if (template.id === "sprinkler-hydrant-pump-sop") {
    const linkedResults = await syncPumpManualLinkedVerifications(template, savedRecord, activeSchedule, state.activeCriticalDevice);
    if (linkedResults.some((result) => result && !result.ok && !result.offline)) {
      state.criticalSops[storageKey] = previous;
      document.querySelector("#syncState").textContent = "Linked pump verification was rejected. The critical checklist was not completed.";
      return { ok: false, linkedVerificationRejected: true };
    }
    savedRecord.linkedVerificationStatuses = linkedResults.map((result) => result.linkedVerification?.status || (result.offline ? "LOCAL_COMPLETE_AWAITING_SYNC" : "AWAITING_COUNTERPART"));
  }
  if (template.id === "gas-discharge-sop") {
    const linkedResults = await syncGasReleaseLinkedVerification(template, savedRecord, activeSchedule, state.activeCriticalDevice);
    if (linkedResults.some((result) => result && !result.ok && !result.offline)) {
      state.criticalSops[storageKey] = previous;
      document.querySelector("#syncState").textContent = "Linked gas verification was rejected. The critical checklist was not completed.";
      return { ok: false, linkedVerificationRejected: true };
    }
    savedRecord.linkedVerificationStatuses = linkedResults.map((result) => result.linkedVerification?.status || (result.offline ? "LOCAL_COMPLETE_AWAITING_SYNC" : "AWAITING_COUNTERPART"));
  }
  const complete = getCriticalSopCompleteCount(template, savedRecord);
  const criticalComplete = isCriticalSopRecordComplete(template, savedRecord);
  if (workflowRun) {
    updateCriticalWorkflowRunProgress(workflowRun, activeSchedule);
    savedRecord.workflowStatus = workflowRun.status;
    savedRecord.workflowStageLabel = workflowRun.stageLabel;
    savedRecord.prerequisiteComplete = Boolean(workflowRun.prerequisiteComplete);
    savedRecord.finalRestorationComplete = Boolean(workflowRun.finalComplete);
    savedRecord.linkedDeviceCount = Number(workflowRun.childTotal || 0);
    savedRecord.linkedDeviceCompleteCount = Number(workflowRun.childCompleteCount || 0);
  }
  const auditDevice = {
    id: savedRecord.deviceTag || template.id,
    tag: savedRecord.deviceTag || template.id,
    type: savedRecord.deviceType || template.title,
    floor: savedRecord.floor,
    location: savedRecord.location
  };
  const auditSession = completeAssignedItemSession(auditDevice, {
    status: criticalComplete ? "pass" : complete > 0 ? "partial" : "pending",
    critical: true,
    criticalTemplateTitle: template.title,
    criticalStepProgress: `${complete}/${template.steps.length}`
  });
  savedRecord.checklistStartedAt = auditSession?.lastStartedAt || auditSession?.firstOpenedAt || "";
  savedRecord.checklistDurationMs = auditSession?.lastDurationMs || 0;
  savedRecord.checklistTotalDurationMs = auditSession?.durationMs || 0;
  const sharedSave = getCurrentUserRole() === "Technician"
    ? await saveSharedCriticalSopRecord(savedRecord, activeSchedule)
    : { ok: true, localOnly: true };
  if (sharedSave.conflict) {
    savedRecord.syncStatus = "conflict";
    savedRecord.unsynced = true;
    invalidateRuntimeCaches();
    writeStoredJson("rmtCriticalSops", state.criticalSops);
    renderTechAssignedItemList();
    renderTechFaultPanel();
    renderDiagnosticsPanel();
    if (showMessage) {
      document.querySelector("#syncState").textContent = `${template.title} was updated by another phone. Reload the SOP before saving.`;
    }
    return { ok: false, conflict: true };
  }
  if (sharedSave.forbidden || sharedSave.invalid) {
    state.criticalSops[storageKey] = previous;
    if (showMessage) document.querySelector("#syncState").textContent = sharedSave.reason || "The server rejected this critical checklist save.";
    return { ok: false, forbidden: Boolean(sharedSave.forbidden), invalid: Boolean(sharedSave.invalid) };
  }
  if (sharedSave.offline) {
    savedRecord.syncStatus = "draft";
    savedRecord.unsynced = true;
  } else if (!sharedSave.localOnly) {
    savedRecord.syncStatus = "synced";
    savedRecord.sharedRevision = Number(sharedSave.record?.revision || savedRecord.sharedRevision || 0);
  }
  invalidateRuntimeCaches();
  writeStoredJson("rmtCriticalSops", state.criticalSops);
  addJobEvent("Critical SOP saved", template.title);
  if (workflowRun) {
    addJobEvent("Critical workflow stage", `${workflowRun.parentDeviceTag}: ${workflowRun.stageLabel}`, {
      tag: workflowRun.parentDeviceTag,
      workflowId: workflowRun.workflowId,
      workflowStatus: workflowRun.status
    });
  }
  syncActiveJobProgressToSchedule();
  persistActiveJob();
  clearTechnicianInspectionDirty();
  renderTechAssignedItemList();
  renderTechFaultPanel();
  if (showMessage) {
    renderCriticalSop();
    renderJobPanel();
    const missingEvidence = getMissingCriticalSopEvidence(template, state.criticalSops[storageKey]);
    const syncNote = sharedSave.offline ? ", local draft only - server unavailable" : "";
    document.querySelector("#syncState").textContent = `${template.title} SOP saved (${complete}/${template.steps.length}${missingEvidence.length ? `, missing ${missingEvidence.join(", ")}` : ""}${syncNote})`;
  }
  return { ok: true, offline: Boolean(sharedSave.offline), record: sharedSave.record || savedRecord };
}

async function saveCriticalSopAndOpenNext() {
  const template = criticalSopTemplates.find((item) => item.id === state.activeCriticalSopId) || criticalSopTemplates[0];
  const currentDeviceTag = state.activeCriticalDevice?.tag || "";
  const storageKey = getCriticalSopStorageKey(template.id);
  const saveResult = await saveCriticalSop(true);
  if (!saveResult?.ok) return;
  const saved = state.criticalSops[storageKey];
  const activeSchedule = getActiveTechnicianMaintenanceSchedule();
  const workflowRun = state.activeCriticalDevice ? getCriticalWorkflowRunForParentDevice(state.activeCriticalDevice, activeSchedule) : null;
  const workflowStage = workflowRun ? getCriticalWorkflowRunState(workflowRun, activeSchedule) : null;
  if (workflowStage?.prerequisiteFailed || (!workflowStage?.prerequisiteComplete && !isCriticalSopRecordComplete(template, saved))) {
    document.querySelector("#syncState").textContent = `${template.title} saved, but prerequisite is not complete/safe yet. Complete it before moving next.`;
    return;
  }
  if (getCurrentUserRole() === "Technician") {
    if (activeSchedule && state.activeTechSystemKey) {
      const route = getTechnicianSystemStageRoute(activeSchedule, state.activeTechSystemKey);
      if (route?.stage === "field-devices") {
        await routeTechnicianSystemStage(activeSchedule, state.activeTechSystemKey, { scroll: true });
        document.querySelector("#syncState").textContent = `${template.title} saved. Continue with field devices on the mimic.`;
        return;
      }
    }
    await openNextAssignedItemAfter(currentDeviceTag);
  }
}

function resetCriticalSop() {
  const template = criticalSopTemplates.find((item) => item.id === state.activeCriticalSopId) || criticalSopTemplates[0];
  delete state.criticalSops[getCriticalSopStorageKey(template.id)];
  writeStoredJson("rmtCriticalSops", state.criticalSops);
  renderCriticalSop();
  renderTechAssignedItemList();
  document.querySelector("#syncState").textContent = `${template.title} reset`;
}

function getBalancedRotatingDevices(deviceList, targetCount, previousIds = []) {
  const groups = new Map();
  deviceList.forEach((device) => {
    const key = device.floorId || normalizeScopeText(device.floorTitle || device.floor || "unknown-floor");
    const group = groups.get(key) || {
      key,
      title: device.floorTitle || device.floor || key,
      devices: []
    };
    group.devices.push(device);
    groups.set(key, group);
  });

  const queuedGroups = [...groups.values()]
    .map((group) => {
      const devicesByOldest = [...group.devices].sort((a, b) => getRotationRank(a.id, previousIds) - getRotationRank(b.id, previousIds));
      return {
        ...group,
        devices: devicesByOldest,
        groupRank: Math.min(...devicesByOldest.map((device) => getRotationRank(device.id, previousIds)))
      };
    })
    .sort((a, b) => a.groupRank - b.groupRank || String(a.title).localeCompare(String(b.title)));

  const selected = [];
  while (selected.length < targetCount && queuedGroups.some((group) => group.devices.length)) {
    for (const group of queuedGroups) {
      if (selected.length >= targetCount) break;
      const next = group.devices.shift();
      if (next) selected.push(next);
    }
  }
  return selected;
}

function getRotationRank(id, previousIds = []) {
  const index = previousIds.indexOf(id);
  return index === -1 ? -999 : index;
}

function selectRotatingDevices(deviceList, targetCount, percentage, historyKey = getScopeHistoryKey(percentage), balancedByFloor = false) {
  return selectCycleAwareRotatingDevices(deviceList, targetCount, historyKey, balancedByFloor, true);
}

function selectCycleAwareRotatingDevices(deviceList, targetCount, historyKey, balancedByFloor = false, commitHistory = false) {
  const validDevices = getUniqueScheduleDevices(deviceList).filter((device) => device.id);
  const safeTarget = Math.max(0, Math.min(validDevices.length, Number(targetCount) || 0));
  if (!safeTarget || !validDevices.length) return [];

  const cycle = getScopeCycleRecord(historyKey, validDevices);
  const coveredSet = new Set(cycle.coveredIds);
  const reservedSet = new Set(cycle.reservedIds || []);
  const unvisitedDevices = validDevices.filter((device) => !coveredSet.has(device.id) && !reservedSet.has(device.id));
  const selected = [];

  if (unvisitedDevices.length) {
    selected.push(...pickRotatingDevices(unvisitedDevices, Math.min(safeTarget, unvisitedDevices.length), cycle.lastSelectedIds, balancedByFloor));
    if (selected.length < safeTarget) {
      selected.push(...pickPriorityRecheckDevices(validDevices, safeTarget - selected.length, selected, cycle.lastSelectedIds));
    }
  } else {
    selected.push(...pickPriorityRecheckDevices(validDevices, safeTarget, selected, cycle.lastSelectedIds));
  }

  if (selected.length < safeTarget) {
    selected.push(...pickRotatingDevices(
      validDevices.filter((device) => !selected.some((item) => item.id === device.id) && !cycle.lastSelectedIds.includes(device.id)),
      safeTarget - selected.length,
      cycle.lastSelectedIds,
      balancedByFloor
    ));
  }

  if (selected.length < safeTarget) {
    selected.push(...pickRotatingDevices(
      validDevices.filter((device) => !selected.some((item) => item.id === device.id)),
      safeTarget - selected.length,
      cycle.lastSelectedIds,
      balancedByFloor
    ));
  }

  const finalSelected = selected.slice(0, safeTarget);
  if (commitHistory) {
    reserveScopeCycleSelection(historyKey, validDevices, cycle, finalSelected, {});
  }
  return finalSelected;
}

function getScopeCycleRecord(historyKey, deviceList, options = {}) {
  const validIds = new Set(deviceList.map((device) => device.id));
  const stored = state.scopeCycle[historyKey] || {};
  const legacyKey = getLegacyKeyFromCycleHistoryKey(historyKey);
  const legacyHistory = Array.isArray(state.scopeHistory[historyKey])
    ? state.scopeHistory[historyKey]
    : Array.isArray(state.scopeHistory[legacyKey])
      ? state.scopeHistory[legacyKey]
      : [];
  const coveredIds = uniqueValues([...(stored.coveredIds || []), ...legacyHistory]).filter((id) => validIds.has(id));
  const lastSelectedIds = uniqueValues(stored.lastSelectedIds || []).filter((id) => validIds.has(id));
  const reservations = sanitizeScopeReservations(stored.reservations || {}, validIds, options.excludeScheduleId);
  addExistingScheduleReservations(historyKey, reservations, validIds, options.excludeScheduleId);
  const reservedIds = uniqueValues(Object.values(reservations).flatMap((reservation) => reservation.deviceIds || [])).filter((id) => validIds.has(id));
  const completionRecords = sanitizeScopeCompletionRecords(stored.completionRecords || {}, validIds);
  const completedInspectionCount = Object.values(completionRecords).reduce((sum, record) => sum + (record.deviceIds || []).length, 0)
    || Number(stored.completedInspectionCount || coveredIds.length || 0);
  const repeatInspectionCount = Object.values(completionRecords).reduce((sum, record) => sum + (record.repeatIds || []).length, 0)
    || Number(stored.repeatInspectionCount || Math.max(0, completedInspectionCount - coveredIds.length) || 0);
  const faultRecheckRepeatCount = Object.values(completionRecords).reduce((sum, record) => sum + (record.recheckIds || []).length, 0)
    || Number(stored.faultRecheckRepeatCount || 0);
  return {
    schemaVersion: stored.schemaVersion || "scope-cycle-v2",
    annualCycleId: stored.annualCycleId || options.annualCycleId || historyKey.match(/::(annual-\d{4})$/)?.[1] || getContractCycleIdForDate(),
    contractCycleId: stored.contractCycleId || stored.annualCycleId || options.annualCycleId || historyKey.match(/::(annual-\d{4})$/)?.[1] || getContractCycleIdForDate(),
    eligibleIds: [...validIds],
    coveredIds,
    reservations,
    reservedIds,
    completionRecords,
    completedInspectionCount,
    repeatInspectionCount,
    faultRecheckRepeatCount,
    lastSelectedIds,
    cycleStartedAt: stored.cycleStartedAt || "",
    completedAt: coveredIds.length >= validIds.size ? stored.completedAt || new Date().toISOString() : stored.completedAt || "",
    updatedAt: stored.updatedAt || ""
  };
}

function getLegacyKeyFromCycleHistoryKey(historyKey = "") {
  return String(historyKey || "").replace(/::annual-\d{4}$/, "");
}

function sanitizeScopeReservations(reservations = {}, validIds = new Set(), excludeScheduleId = "") {
  return Object.fromEntries(Object.entries(reservations || {})
    .filter(([scheduleId]) => scheduleId !== excludeScheduleId)
    .map(([scheduleId, reservation]) => {
      const deviceIds = uniqueValues(reservation?.deviceIds || []).filter((id) => validIds.has(id));
      return [scheduleId, { ...reservation, scheduleId, deviceIds }];
    })
    .filter(([, reservation]) => reservation.deviceIds.length));
}

function sanitizeScopeCompletionRecords(records = {}, validIds = new Set()) {
  return Object.fromEntries(Object.entries(records || {}).map(([scheduleId, record]) => [
    scheduleId,
    {
      ...record,
      scheduleId,
      deviceIds: uniqueValues(record?.deviceIds || []).filter((id) => validIds.has(id)),
      newCoveredIds: uniqueValues(record?.newCoveredIds || []).filter((id) => validIds.has(id)),
      repeatIds: uniqueValues(record?.repeatIds || []).filter((id) => validIds.has(id)),
      recheckIds: uniqueValues(record?.recheckIds || []).filter((id) => validIds.has(id))
    }
  ]).filter(([, record]) => record.deviceIds.length));
}

function addExistingScheduleReservations(historyKey, reservations, validIds, excludeScheduleId = "") {
  state.schedules
    .filter((schedule) => schedule.rotationHistoryKey === historyKey)
    .filter((schedule) => schedule.scheduleId !== excludeScheduleId)
    .filter((schedule) => schedule.status !== "Completed" && schedule.status !== "Cancelled")
    .forEach((schedule) => {
      if (reservations[schedule.scheduleId]) return;
      const reservationIds = Array.isArray(schedule.plannedDeviceIds) && schedule.plannedDeviceIds.length
        ? schedule.plannedDeviceIds
        : (schedule.sampledDeviceIds || []);
      const deviceIds = uniqueValues(reservationIds).filter((id) => validIds.has(id));
      if (!deviceIds.length) return;
      reservations[schedule.scheduleId] = {
        scheduleId: schedule.scheduleId,
        deviceIds,
        mandatoryRecheckIds: uniqueValues(schedule.mandatoryRecheckDeviceIds || []).filter((id) => validIds.has(id)),
        date: schedule.date || "",
        status: "reserved-from-schedule",
        createdAt: schedule.createdAt || schedule.updatedAt || new Date().toISOString()
      };
    });
}

function commitScopeCycleSelection(historyKey, deviceList, cycle, selectedDevices) {
  reserveScopeCycleSelection(historyKey, deviceList, cycle, selectedDevices, {});
}

function reserveScopeCycleSelection(historyKey, deviceList, cycle, selectedDevices, options = {}) {
  const validIds = new Set(deviceList.map((device) => device.id));
  const selectedIds = selectedDevices.map((device) => device.id).filter((id) => validIds.has(id));
  const mandatoryIds = new Set((options.mandatoryRecheckDevices || []).map((device) => device.id).filter((id) => validIds.has(id)));
  const rotationSelectedIds = selectedIds.filter((id) => !mandatoryIds.has(id));
  const now = new Date().toISOString();
  const scheduleId = options.scheduleId || `scope-preview-${now}`;
  const reservations = sanitizeScopeReservations(cycle.reservations || {}, validIds);
  if (selectedIds.length) {
    reservations[scheduleId] = {
      scheduleId,
      deviceIds: selectedIds,
      mandatoryRecheckIds: [...mandatoryIds],
      date: options.date || "",
      status: "reserved",
      createdAt: now
    };
  }
  const reservedIds = uniqueValues(Object.values(reservations).flatMap((reservation) => reservation.deviceIds || [])).filter((id) => validIds.has(id));
  const coveredIds = uniqueValues(cycle.coveredIds || []).filter((id) => validIds.has(id));
  const completedAt = coveredIds.length >= validIds.size ? cycle.completedAt || now : "";
  state.scopeCycle[historyKey] = {
    schemaVersion: "scope-cycle-v2",
    annualCycleId: options.annualCycleId || cycle.annualCycleId || historyKey.match(/::(annual-\d{4})$/)?.[1] || getContractCycleIdForDate(),
    contractCycleId: options.annualCycleId || cycle.contractCycleId || cycle.annualCycleId || historyKey.match(/::(annual-\d{4})$/)?.[1] || getContractCycleIdForDate(),
    eligibleIds: [...validIds],
    coveredIds,
    reservations,
    reservedIds,
    completionRecords: cycle.completionRecords || {},
    completedInspectionCount: cycle.completedInspectionCount || coveredIds.length,
    repeatInspectionCount: cycle.repeatInspectionCount || 0,
    faultRecheckRepeatCount: cycle.faultRecheckRepeatCount || 0,
    lastSelectedIds: rotationSelectedIds.length ? rotationSelectedIds : selectedIds,
    cycleStartedAt: cycle.cycleStartedAt || now,
    completedAt,
    updatedAt: now
  };
  state.scopeHistory[historyKey] = coveredIds;
  writeStoredJson("rmtScopeCycle", state.scopeCycle);
  writeStoredJson("tmFireScopeHistory", state.scopeHistory);
}

function pickRotatingDevices(deviceList, targetCount, previousIds = [], balancedByFloor = false) {
  if (!targetCount || !deviceList.length) return [];
  if (balancedByFloor) {
    return getBalancedRotatingDevices(deviceList, targetCount, previousIds);
  }
  return [...deviceList]
    .sort((a, b) => getRotationRank(a.id, previousIds) - getRotationRank(b.id, previousIds))
    .slice(0, targetCount);
}

function pickPriorityRecheckDevices(deviceList, targetCount, alreadySelected = [], previousIds = []) {
  const selectedIds = new Set(alreadySelected.map((device) => device.id));
  return deviceList
    .filter((device) => !selectedIds.has(device.id))
    .map((device) => ({ device, priority: getRecheckPriorityScore(device) }))
    .filter((item) => item.priority > 0)
    .sort((a, b) => b.priority - a.priority || getRotationRank(a.device.id, previousIds) - getRotationRank(b.device.id, previousIds))
    .slice(0, targetCount)
    .map((item) => item.device);
}

function getRecheckPriorityScore(device) {
  return getScopeRecheckPriority(device).score;
}

function renderReportPhotos(inspection) {
  if (!inspection) return "No photos";

  const photoBlocks = [
    { label: "Before", name: inspection.beforePhoto, data: inspection.beforePhotoData },
    { label: "After", name: inspection.afterPhoto, data: inspection.afterPhotoData }
  ].map((photo) => {
    if (!photo.data) {
      return `
        <div class="photo-thumb">
          <div class="photo-placeholder">${photo.label}</div>
          <span>No photo</span>
        </div>
      `;
    }
    return `
      <div class="photo-thumb">
        <img src="${escapeHtml(photo.data)}" alt="${escapeHtml(photo.label)} photo for ${escapeHtml(inspection.status)} inspection">
        <span>${escapeHtml(photo.label)}: ${escapeHtml(photo.name)}</span>
      </div>
    `;
  }).join("");

  return `<div class="photo-report">${photoBlocks}</div>`;
}

function formatReportDateTime(value) {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString();
}

function renderReportCriticalSystems(snapshot = state.activeReportSnapshot) {
  const container = document.querySelector("#reportCriticalSystemDetails");
  if (!container) return;
  const records = [...(snapshot?.criticalItems || [])]
    .sort((a, b) => String(a.floor || "").localeCompare(String(b.floor || "")) || String(a.deviceId || a.title || "").localeCompare(String(b.deviceId || b.title || "")));

  if (!records.length) {
    container.innerHTML = `<p class="report-muted">No critical system record is part of this scheduled job.</p>`;
    return;
  }

  container.innerHTML = records.map(renderCriticalSopReportCard).join("");
}

function renderCriticalSopReportCard(record) {
  const steps = record.steps || [];
  const completed = steps.filter((step) => step.confirmed).length;
  const total = steps.length;
  const complete = record.status === "PASS" && Boolean(record.finalRestorationComplete || !total || completed === total);
  const title = `${record.deviceId || "Critical System"} - ${record.title || "Critical SOP"}`;

  const rows = steps.map((step, index) => {
    const result = step.confirmed ? "Confirmed" : "Not confirmed";
    const detailParts = [
      step.remark,
      step.supervisor ? `Supervisor: ${step.supervisor}` : "",
      step.evidenceRefs?.length ? `${step.evidenceRefs.length} evidence reference(s)` : ""
    ].filter(Boolean);
    return `
      <tr>
        <td class="step-no">${step.number || index + 1}</td>
        <td class="step-title">
          ${escapeHtml(step.title || "Checklist step")}
          ${step.critical ? `<span class="scope-badge active">Critical</span>` : ""}
        </td>
        <td class="${step.confirmed ? "critical-report-ok" : "critical-report-missing"}">${escapeHtml(result)}</td>
        <td>${escapeHtml(step.choice || "-")}</td>
        <td>${escapeHtml(step.reading || "-")}</td>
        <td>${escapeHtml(detailParts.join(" | ") || "-")}</td>
      </tr>
    `;
  }).join("");

  return `
    <article class="critical-report-card">
      <div class="critical-report-head">
        <div>
          <h3>${escapeHtml(title)}</h3>
          <p>${escapeHtml(record.systemLabel || record.deviceType || "Critical system")} - ${escapeHtml(record.floor || "-")} - ${escapeHtml(record.location || "-")}</p>
        </div>
        <span class="critical-report-status ${complete ? "" : "incomplete"}">${complete ? "Completed" : "Needs Review"}</span>
      </div>
      <div class="critical-report-meta">
        <p><strong>Step Completion</strong>${completed} of ${total || 0}</p>
        <p><strong>Filled By</strong>${escapeHtml(record.technicianName || "-")}</p>
        <p><strong>Saved Time</strong>${escapeHtml(formatReportDateTime(record.completedAt))}</p>
        <p><strong>SOP Version</strong>${escapeHtml(record.sopVersion || "configured")}</p>
        <p><strong>Evidence</strong>${record.evidenceRefs?.length || 0} reference(s)</p>
      </div>
      <table class="critical-report-table">
        <thead>
          <tr>
            <th>No.</th>
            <th>Test / Safety Point</th>
            <th>Status</th>
            <th>Result</th>
            <th>Reading / Value</th>
            <th>Remarks / Proof</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
      ${record.generalRemarks ? `<p class="critical-report-remarks"><strong>Overall remarks:</strong> ${escapeHtml(record.generalRemarks)}</p>` : ""}
      ${renderReportEvidenceReferences(record.evidenceRefs)}
    </article>
  `;
}
